-- ── mommy_daily_messages → kk (1460 sətir) ──
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кешкі уақытта бөпенің себепсіз жылауы, аяқтарын ішіне қарай бүгіп, қызаруы іштің желден шаншуы (колик) басталғанын көрсетуі мүмкін; бұл оның ас қорыту жүйесінің әлі толық қалыптаспағанын білдіреді. Алаңдамаңыз, бұл ауырсынулар бөпенің денсаулығында мәселе барын білдірмейді, оған аздап көмектесу қажет; ішін сағат тілі бағытымен ақырын уқалау немесе аяқтарымен «велосипед» қимылдарын жасау жеңілдеуіне көмектеседі. Бөпені етпетінен білегіңіздің үстіне жатқызып алып жүру («жолбарыс» қалпы) де шаншуды жеңілдетуі мүмкін. Сабырлы болыңыз, бұл «бітпейтін түндер» секілді көрінуі мүмкін, бірақ 3-4 айдан кейін бұл шаншулар толығымен басылады.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, бөпеңізге бүгін тура 2 апта толды! Бұл кезеңде дәрігерлер әдетте бөпелерге D дәруменінің тамшысын тағайындайды, өйткені ана сүті мінсіз тағам болғанымен, ондағы D дәруменінің мөлшері көбіне жеткіліксіз, ал күн сәулесі де әрдайым жеткілікті бола бермейді. Сүйектерінің дұрыс дамуы және мешелдің алдын алу үшін дәруменді дәрігеріңіз тағайындаған мөлшерде беруді ұмытпаңыз. Сондай-ақ бұл дәрігердің алғашқы тексеруінен өтуге қолайлы уақыт; бөпенің салмақ қосуын тексертіп, дамуы туралы сұрақтарыңызды қою үшін педиатрға баруды жоспарлай аласыз. Сіз бәрін тамаша атқарып жүрсіз, ең қиын алғашқы кезеңді артта қалдырдыңыз!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бүгін назарыңызды қайтадан өз денеңізге аздап аударайық; босанғаннан кейінгі бөлінділердің (лохияның) түсі өзгеріп, ашығырақ, сарғыш немесе ақ түске ауыса бастауы керек. Егер кенеттен қан кету күшейсе немесе жағымсыз иіс пайда болса, бұл денеңіздің Сізге «тым қатты шаршап жүрсіз» немесе «инфекция бар» деген белгісі болуы мүмкін; сондықтан ауыр заттарды көтермеңіз. Жеке гигиенаңызға ерекше көңіл бөліңіз, жиі душ қабылдау дене тазалығы үшін де, көңіл күйіңізді көтеру үшін де маңызды. Толық қалпыңызға келуге әлі бірнеше апта қажет екенін ұмытпаңыз, сондықтан өзіңізді әлі толық сергек сезінбесеңіз де, денеңізге уақыт беріп, жанашырлық танытыңыз.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіз ұйқы ережелері бөпенің өмірі үшін аса маңызды; бөпені әрдайым шалқасынан, қатты төсенішке жатқызып ұйықтату керек. Әжелер ұсынатын жұмсақ жастықтар, қалың көрпелер немесе төсектегі ойыншықтар бөпенің тұншығу қаупін тудыруы мүмкін, сондықтан бесікті барынша қарапайым әрі бос ұстаңыз. «Басы тегіс болсын» деп қолданылатын арнайы ортопедиялық жастықтар көбіне қажет емес, өйткені бөпе басын еркін қозғалта алуы керек. Бөлме температурасын бақылаңыз (20-22 градус — ең қолайлы), бөпені тым қалың киіндіруден аулақ болыңыз, өйткені шамадан тыс ыстықтау да ұйқы кезінде қауіп төндіреді.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпені ояу кезінде етпетінен жатқызудың (tummy time) маңызын естіген боларсыз, бірақ бөпеңізге бұл мүлде ұнамай, ол бірден жылап жіберуі мүмкін. Бұл қалыпты жағдай, дегенмен бас тартпаңыз; күніне бірнеше рет, әр жолы небәрі 1-2 минуттан жасау оның мойын, иық және қол бұлшықеттерін нығайту үшін өте маңызды. Сондай-ақ бұл желкесінің жалпаюының (плагиоцефалияның) алдын алудың ең табиғи тәсілі. Қызықтырақ болуы үшін алдына айна немесе ақ-қара карточкалар қоя аласыз, тіпті өзіңіз де қасына еденге жатып, көзіне қарай аласыз.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қырқынан шықпаған бала далаға шықпайды» деген сөз — ескірген аңыз ғана; ауа райы қолайлы әрі бөпе сау болса, таза ауа екеуіңізге де емдей әсер етеді. Үйдегі тұрып қалған ауа, шаң мен бактериялар сырттағы таза ауадан зияндырақ болуы мүмкін; тек адам көп жиналатын сауда орталықтары мен жабық орындарға бармаңыз. Бөпені киіндіргенде өзіңізден бір қабат артық киіндіру жеткілікті, оны «қырыққабаттай» қымтап тастау терлетіп, ауырып қалуына себеп болуы мүмкін. Қысқа серуен Сіздің көңіл күйіңізді көтеріп, бөпенің тереңірек ұйықтауына көмектеседі.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің тырнақтары қағаздай жұқа болғанымен, ұстарадай өткір болуы мүмкін. Ол еріксіз қимылдап, бетін тырнап алуы ықтимал. Тырнағын алу өте қорқынышты көрінуі мүмкін, мұны жасаудың ең оңай жолы — бөпе қатты ұйықтап жатқанда арнайы балалар қайшысымен абайлап қию. Кейбір аналар қолғап кигізгенді жөн көреді, алайда бөпе әлемді қолымен ұстап, сезіну арқылы танып-біледі. Қолын үнемі жауып қою оның дамуын баяулатып, өзін-өзі тыныштандыру қабілетіне кедергі келтіруі мүмкін. Қорықпаңыз, байқаусызда кішкентай жерін кесіп алсаңыз да, таза мақтамен басып ұстау жеткілікті — тез жазылып кетеді. Батыл болыңыз!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Босанғаннан кейінгі осы кезеңде кейде өзіңізді әлемнен оқшауланған, тек емізіп, жөргек ауыстыратын «робот» сияқты сезінуіңіз мүмкін. Бірақ Сіз тек ана ғана емес, сонымен қатар дос, жар және өз қызығушылықтары бар жеке тұлға екеніңізді ұмытпаңыз. Бүгін бөпе ұйықтағанда құрбыңызға қоңырау шалыңыз, әлеуметтік желіден қызықты бір нәрсе оқыңыз немесе жай ғана терезеге қарап: «Мен осындамын, бәрі жақсы», — деп айтыңыз. Психикалық саулығыңыз физикалық денсаулығыңыздан кем емес маңызды. Егер өзіңізді тұйықталып қалғандай сезінсеңіз, бұл сезімдеріңізді жақындарыңызбен бөлісіңіз — сөйлесу көңіліңіздегі жүкті жеңілдетеді.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы күндері бөпеңіз сүтке мүлде тоймайтындай болып, үнемі емшек сұрап, ұйқысы бұзылса, қорықпаңыз. Бұл, ең ықтимал, «3-аптадағы өсу секірісі» (growth spurt). Осы кезеңде бөпенің ағзасы тез өсетіндіктен, оған көбірек қуат қажет болады, ал Сіздің ағзаңыз осы сұранысқа бейімделу үшін сүтті көбірек өндіруге тырысады. Аналардың осы кезеңдегі ең үлкен қателігі — «сүтім азайып кетті» деп, жасанды қоспаға көшу. Керісінше, бұл уақытша дағдарыс, оны еңсерудің жалғыз жолы — сағатқа қарамай, бөпені қалағанынша емізу. Сабырлы болыңыз, бұл мазасыз кезең әдетте 24-48 сағат ішінде өтіп, сүт мөлшері қайта реттеледі.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің тегіс, жібектей бетінде кенеттен ұсақ қызыл бөртпелер немесе безеулер пайда болуы мүмкін. Бірден «баламның бұлай болуына менің жегенім себеп болды ма?» деп өзіңізді кінәламаңыз. Бұл «жаңа туған нәрестелердің акнесі» деп аталады және жүктілік кезінде бөпеге берілген Сіздің гормондарыңыздың оның ағзасынан шығарылу үдерісіне байланысты болады. Бұл бөртпелер аллергия емес, сондықтан оларды сығуға, спиртпен сүртуге немесе әртүрлі крем жағуға қатаң тыйым салынады — мұның бәрі теріні зақымдауы мүмкін. Бетін күн сайын жай ғана қайнатылып, жылы күйге дейін салқындатылған сумен сүрту жеткілікті. Бөртпелер бірнеше апта ішінде өздігінен жоғалады.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кешкі уақытта басталып, сағаттарға созылатын белгілі жылау ұстамалары (колик) осы кезеңде шегіне жетуі мүмкін. Мұндайда бөпені тыныштандыру үшін «ақ шуды» (white noise) қолданып көріңіз. Ана құрсағында бөпе қан айналымы мен ішкі ағзалардың дыбысын үнемі естіп жатқандықтан, феннің, шаңсорғыштың дауысы немесе телефоннан қосылған «ақ шу» қолданбалары оған таныс естіліп, өзін қауіпсіз сезінуге көмектеседі. Бөпені бауырыңызға қысып, ырғақпен тербетіп, осы дыбыстарды тыңдату оның жүйке жүйесін тыныштандыруы мүмкін. Бұл жылаудың Сіздің кінәңіз емес екенін ұмытпаңыз. Бұл — бөпенің әлі толық жетілмеген ас қорыту жүйесінің реакциясы ғана.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің көру қабілеті енді дами бастайды, бірақ ол түстерді әлі толық ажырата алмайды және айналасын көбіне бұлыңғыр көлеңкелер түрінде көреді. Оның назарын аударып, миының дамуын қолдау үшін ақ-қара түсті карточкаларды немесе контрастылығы жоғары ойыншықтарды пайдалануға болады. Оларды бөпенің бетінен шамамен 20-30 см қашықтықта ұстау керек. Бөпенің осы карточкаларға көзін қадап, мұқият бақылап тұрғанын көресіз. Бұл қарапайым ойын оның көз бұлшықеттерін жаттықтырып қана қоймай, ми жасушаларының (нейрондардың) арасында жаңа байланыстардың түзілуіне ықпал етеді.') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қоғамымызда кең тараған «қызанақ жеме, баланың іші күйеді», «жасымық жеме, бөпенің іші кебеді» деген сияқты тағамға қатысты тыйымдар Сізді шаршатқан болса, заманауи медицина бұл пікірлерді растамайтынын білгеніңіз жөн. Сіз жеген тағамнан пайда болған газ емшек сүтіне тікелей өтпейді: сүт асқазандағы газдан емес, қаннан түзіледі. Белгілі бір тағамды жегеннен кейін бөпеңізде шынымен жайсыздық байқалмаса (бұл өте сирек, мысалы, сиыр сүтінің ақуызына аллергия болғанда кездеседі), өзіңізді қажетсіз диетамен шектемеңіз. Дәрумендер мен ақуыздарға бай, әртүрлі тағамдармен қоректенуіңіз емшек сүтінің сапасы үшін де, психологиялық саулығыңыз үшін де аш жүруден әлдеқайда пайдалы.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді үнемі қолыңызға алып жүру беліңізді ауыртуы мүмкін, сондықтан дұрыс таңдалған слинг немесе эрго-рюкзак («кенгуру» емес!) Сіздің ең жақсы көмекшіңіз бола алады. «Бала қолға үйреніп кетеді», «омыртқасы қисаяды» деген сөздерге мән бермеңіз. Керісінше, бөпенің аяқтары «М» әрпі тәрізді (бақа сияқты) орналасатын эргономикалық тасымалдағыштар оның жамбас буындарының дұрыс дамуына өте пайдалы. Бұл қалып бөпеге ана құрсағындағы жайлы тығыздықты еске салып, оны тыныштандырады, ал Сіздің екі қолыңыз да бос болып, үй шаруаларымен айналыса аласыз немесе жай ғана асықпай шай іше аласыз. Жақындық сезімі екеуіңізге де серотонин (бақыт гормоны) сыйлайды.') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Үйге келген қонақтардың бөпеңізді сүйгісі немесе қолдан-қолға бергісі келуі Сізді алаңдатса, «жоқ» деуден және шекара қоюдан еш қысылмаңыз. Бөпенің иммундық жүйесі әлі өте әлсіз, ал ересектер үшін үйреншікті ұшық вирусы (герпес) бөпеге өмірлік қауіп төндіруі мүмкін. Қонақтардан қолдарын жууды, ауырып жүрсе келмеуді және бөпенің бетінен/қолынан сүймеуді сыпайы түрде сұрау — Сіздің табиғи құқығыңыз. Егер біреу бұған ренжісе, бұл — олардың мәселесі. Сіздің басты міндетіңіз — басқалардың көңіліне қарау емес, бөпеңізді қорғау.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, ғажайып Ана! Бүгін бөпеңізге тура 1 ай толды! Осы бір айда қаншама қиындықты еңсеріп, ұйқысыз түндерді өткізіп, соған қарамастан мықты болғаныңызды еске алып, өзіңізді мақтан тұтыңыз. Сондай-ақ бөпені ай сайынғы дәрігер бақылауына апаратын уақыт келді: оның салмағы мен бойы өлшенеді, ал қосқан әрбір грамы — Сіздің еңбегіңіздің жемісі. Бүгін бөпеңіздің бір айлық естелік суретін түсіріп, күнін белгілеп қойыңыз және осы шағын мерейтойды, тіпті бір тілім тортпен болса да, міндетті түрде атап өтіңіз. Уақыт өте жылдам өтеді, ал осы сәттерді есте сақтау болашақтағы ең әдемі естеліктердің біріне айналады.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді шомылдырғанда құлағына су кіріп кетеді деп қорықсаңыз, алаңдамаңыз. Құлақ жарғағы судың құлақтың ішкі бөлігіне өтуіне жол бермейді, сондықтан су кіруі, әдетте, елеулі мәселе туғызбайды (егер құлақ жарғағы зақымданбаған болса). Шомылу бөпе үшін тек тазалық емес, сонымен қатар көңіл көтеру мен босаңсудың бір тәсілі. Егер бөпеңіз суды ұнатса, оны күн сайын кешке бір уақытта, ұйықтар алдында шомылдыру керемет ұйқы рәсіміне айналуы мүмкін. Жылы су бұлшықеттерді босаңсытып, тыныштандырады және бөпеге «түн болды, ұйықтайтын уақыт келді» деген белгі береді. Шомылдырып болған соң оны жылы сүлгіге орап, жеңіл массаж жасау ұйқыға кетуін жеңілдетеді.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Босанғаннан кейінгі алғашқы айдан соң «Baby blues» деп аталатын мұңды әрі сезімтал кезең, әдетте, аяқталуы керек. Егер Сіз әлі де үнемі мұңайып, үмітсіз, шаршаңқы күйде жүрсеңіз немесе бөпеңізге немқұрайды қарай бастағаныңызды сезсеңіз, бұған назар аударыңыз. Бұл босанғаннан кейінгі депрессия (БКД) болуы мүмкін. Ол ешқандай да Сіздің кінәңіз, еркелігіңіз немесе әлсіздігіңіз емес, гормондық және химиялық тепе-теңдіктің бұзылуынан туындайтын жағдай. «Мен анамын, шыдауым керек» деп өзіңізді кінәламаңыз. Ішкі бос кеңістік сезімі басылмаса, міндетті түрде дәрігеріңізбен немесе психологпен сөйлесіңіз. Сіздің психикалық саулығыңыз бөпеңіздің физикалық денсаулығы сияқты, тіпті одан да маңызды болуы мүмкін.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қош келдіңіз, аяулы Ана! Өміріңіздің ең жаңа әрі, бәлкім, ең толқынысты кезеңі бүгін басталады. Қазір Сіз үшін ең маңыздысы — демалу және бөпеңізбен алғаш рет дене арқылы жақындық орнату; үй шаруасы, телефон қоңыраулары мен қонақтар күте тұрады. Алғашқы күндері бөлінетін қою, сарғыш сүттің (уыздың) мөлшері аз болғанымен, құрамы ғажайып екенін және бөпеңіз үшін алғашқы екпе іспетті қорғаныс беретінін біліңіз. Сүтім аз деп қорықпаңыз, өйткені бөпеңіздің асқазаны әзірге шиедей ғана, сондықтан сол бірнеше тамшы оған толық жетеді. Өзіңізді міндетті түрде қаһарманша ұстауға тырыспаңыз: ауырсыну мен шаршау — мүлде табиғи жағдай. Жай ғана жатыңыз, бөпеңіздің иісін сезіңіз, жылуын түйсініңіз және осы сәттен ләззат алыңыз, өйткені араларыңыздағы байланыстың іргетасы дәл қазір қаланып жатыр.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Денеңіз 9 ай бойы орасан зор жұмыс атқарды, енді ішкі ағзаларыңыз біртіндеп бұрынғы орнына келе бастайды. Әсіресе емізу кезінде ішіңіздің төменгі жағында түйіліп ауырғанын сезуіңіз мүмкін. Алаңдамаңыз, бұл — жатырдың жиырылып, бұрынғы көлеміне қайтып келе жатқанының жақсы белгісі. Қоғамда айтылатын "сүтім аз, бала тоймайды, сондықтан жылайды" деген сияқты қате пікірлерге ермеңіз. Бөпеңіз тек қарны ашқандықтан ғана емес, Сіздің иісіңізді сезу, жүрек соғысыңызды есту және өзін қауіпсіз сезіну үшін де емшекті жиі сұрауы мүмкін. Оған осы сенімділік сезімін сыйлаңыз: құшағыңызға алып, жиі емізіңіз. Есіңізде болсын, бөпеңіз емген сайын сүтіңіздің мөлшері арта түседі.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы күндері сүт бездеріңіз тола (сүт молынан келе) бастауы мүмкін, соның салдарынан кеудеңіз ауырлап, ысып тұрғандай сезіледі. Сонымен қатар ағзаңыздағы гормондар деңгейі күрт өзгеретіндіктен, еш себепсіз мұңайып, жылағыңыз келіп немесе ашуланшақ болып жүруіңіз мүмкін; медицинада бұл "Baby blues" деп аталады. Мұндай сезімдер Сіздің "жаман ана" немесе қолыңыздан ештеңе келмейтін адам екеніңізді білдірмейді. Бұл — жай ғана физиологиялық әрі уақытша үдеріс. Көз жасыңызды тыймаңыз: жылағыңыз келсе, ішіңіздегіні шығарып, бұл туралы жақындарыңызбен сөйлесуден тартынбаңыз. Сіз жалғыз емессіз, мыңдаған ана осы өтпелі кезеңді дәл Сіз сияқты өткеріп жатыр. Терең тыныс алып, уақыттың өз дегенін жасауына мүмкіндік беріңіз.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Күш-қуатыңызды қалпына келтіру үшін тамақтануыңызға ерекше мән бергеніңіз жөн, бірақ "денеңе суық өтеді", "жеміс жеме", "су ішпе" деген сияқты ескірген тыйымдарды ұмытыңыз. Түрлі түсті, дәруменге бай тағамдар жеу және сұйықтықты мол ішу сүтіңіздің сапасынан гөрі, өзіңіздің физикалық күш жинауыңыз бен психологиялық сергектігіңіз үшін маңызды. Бөпеңіздің кіндік қалдығына келсек, оны спиртпен күйдірудің немесе орап қоюдың қажеті жоқ. Тек құрғақ әрі таза болуын қадағалаңыз, жөргегін кигізгенде кіндік тұсын ашық қалдырып, ауа тиіп тұруына мүмкіндік беріңіз; ауамен жанасу — жазылуды жылдамдататын ең жақсы тәсіл.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Күн мен түн ауысып, ұйқысыздық сезіле бастайтын күндерге қош келдіңіз, қайратты ана! Айналаңыздағылар "баланы қолға үйретпе" деуі мүмкін, бірақ алғашқы айларда бөпені "еркелетіп жіберу" мүмкін емес екенін біліңіз. Оған Сіз керексіз, ал құшақта ұстау мен теріге-тері жанасу — оның миының дамуына да, сүтіңіздің көбеюіне де көмектесетін ең тиімді тәсілдердің бірі. Үй шаруасы ешқайда қашпайды, ыдыс жуылмай қалса да ештеңе етпейді, ал Сіздің ұйқыңыз бен демалысыңыз бәрінен маңызды. Бөпеңіз ұйықтаған бойда Сіз де көзіңізді жұмып, демалуға тырысыңыз. Тіпті 15 минуттық ұйқының өзі Сізге күш береді.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бәрін жалғыз істеуге және "супер ана" болуға міндетті емессіз; көмек сұрау әлсіздік емес, керісінше мықтылықтың белгісі. Жұбайыңыздан, анаңыздан немесе жақындарыңыздан нақты істер бойынша көмек сұраңыз: мысалы, тамақ әкелуін немесе Сіз душ қабылдап жатқанда бөпеге қарап тұруын өтініңіз. Өзіңізге күтім жасау, жуынып-шайыну және бір кесе ыстық шай ішу — өзімшілдік емес, аналық міндеттеріңізді жақсырақ атқаруыңыз үшін қажет нәрсе. Есіңізде болсын, бақытты әрі тыныққан ана — бақытты бөпе. Сондықтан жүгіңізді жақындарыңызбен бөлісуден тартынбаңыз.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, ана атанғаныңызға бір апта болды және барлық қиындыққа қарамастан, осы күндерден сәтті өттіңіз! Айнаға қарағанда ішіңіздің әлі толық тартылмағанын, шашыңыздың ретсіз екенін байқауыңыз мүмкін, бірақ Сіз бір ғажайыпты өсіріп келесіз және дәл осы қалпыңызда да өте сұлусыз. Бүгіннен бастап бөпеңіз ояу кезде оны бақылаумен қысқа уақытқа (1-2 минут) ішімен жатқыза (tummy time) аласыз. Бұл шағын жаттығу оның мойын және арқа бұлшықеттерін нығайтып, газ түйілуін жеңілдетуге көмектеседі әрі болашақтағы дене дамуына негіз қалайды.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің терісі немесе көзінің ағы сәл сарғайғанын байқауыңыз мүмкін; бұл физиологиялық сарғаю және көп жағдайда жиі емізудің арқасында ағзадан біртіндеп кетеді. Алайда сарғаю аяқтарына қарай тараса және бөпе қатты әлсіресе, міндетті түрде дәрігеріңізбен кеңесіңіз. Сонымен қатар бөлмені желдетуден қорықпаңыз; "қырқынан шыққанша таза ауаға шығаруға болмайды" деген түсінік — жай ғана аңыз, таза оттегі Сіздің де, бөпеңіздің де миы үшін маңызды. Терезені ашып, бөлмені желдетіңіз немесе мүмкіндік болса, бөпеңізді ауа райына сай киіндіріп, қысқа уақытқа таза ауаға алып шығыңыз (егер дәрігеріңіз рұқсат берсе).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әжелеріміз "бөпенің денесі түзу болсын" деп оны қатты құндақтағанды ұнатуы мүмкін, бірақ заманауи медицина бөпенің жамбас буындары дұрыс дамуы үшін аяқтары еркін қозғалуы керектігін дәлелдеді. Егер бөпе өз қолының қимылынан селк етіп оянса, тек қолдарын жеңіл ғана құндақтауға болады (жартылай құндақтау), бірақ аяқтарының "бақа" қалпында еркін жатуына міндетті түрде жағдай жасаңыз. Бөпені қатты қысып, қимылсыз ұстау оның қан айналымы мен бұлшықеттерінің дамуына кері әсер етуі мүмкін. Оны еркін қалдырыңыз, қолдары және аяқтарымен әлемді танып-біле берсін.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Міне, 10 күн бойы бар назарыңыз бен ойыңыз бөпеңізде, бірақ бүгін тым болмаса 15-20 минутты тек өзіңізге арнауға тырысыңыз. Жылы душ қабылдаңыз, сүйікті музыкаңызды тыңдаңыз, теріңізге күтім жасаңыз немесе жай ғана терезеден қарап, қиялға беріліңіз. Қалпына келу үдерісін жылдамдату үшін жамбас түбі бұлшықеттерін біртіндеп сезінуге тырысыңыз (Кегель жаттығуларының ең жеңіл түрі), алайда ауыр жаттығулар жасауға әлі тым ерте. Денеңізді тыңдап, оған құрметпен қараңыз және Сіз балаңыздың ең үлкен тірегі екеніңізді ұмытпаңыз: деніңіздің сау, рухыңыздың мықты болуы — оған берер ең үлкен сыйыңыз.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің кіндік қалдығы құрғап, түсіп қалған немесе түсуге жақын болуы мүмкін; бұл — толығымен табиғи үдеріс, сондықтан кіндік орнында аздаған қан дағын көрсеңіз, қорықпаңыз. Кіндік қалдығы түскеннен кейін де бұл аймақты құрғақ әрі таза ұстау маңызды, өйткені ылғалды орта бактериялардың көбеюіне қолайлы. Кейде аналар кіндіктің "сыртқа шығып" тұруына алаңдайды, бірақ құрсақ бұлшықеттері қатайған сайын ол көбіне өздігінен қалпына келеді; сондықтан ескі тәсілдермен кіндікке тиын байлаудан немесе оны қатты қысып қоюдан аулақ болыңыз. Егер кіндік айналасының қызарғанын, жағымсыз иіс немесе ірің байқасаңыз, дереу дәрігеріңізге хабарлаңыз, ал мұндай белгілер болмаса, табиғи үдерістің өздігінен жүруіне мүмкіндік беріңіз.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы күндері бөпеңіз тоймай жүргендей үздіксіз, кейде сағат сайын емгісі келетінін байқауыңыз мүмкін; медицинада бұл "қарқынды өсу кезеңі" (growth spurt) деп аталады. Аналар мұны жиі "сүтім азайды, бөпем аш қалды" деп түсініп, алаңдап, қоспаға көшуге асығады. Алайда шын мәнінде бұл — бөпенің артқан қажеттілігін өтеу үшін ағзаңызға "көбірек сүт өндір" деген белгі беру тәсілі. Сабыр сақтаңыз, бұл уақытша жағдай және әдетте бір-екі күнге созылады; бөпеңіздің сұранысына сай оны жиі емізіп, кеудеңізге басыңыз. Осы кезеңде мол су ішіп, демалу Сізге күш береді. Сүт мөлшері бөпеңіздің қажеттілігіне қарай табиғи түрде артатынын ұмытпаңыз.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Екінші айға қош келдіңіз! Бөпеңіз екеуіңіз бір-біріңізді жақсырақ тани бастадыңыздар және өмірлеріңізде белгілі бір "ырғақ" қалыптасып келеді. Назар аударыңыз, біз "режим" емес, "ырғақ" дейміз, өйткені бөпе әлі сағат бойынша өмір сүруге дайын емес, алайда ұйқы, тамақтану және сергек жүру реті біртіндеп қалыптасады. Бұл кезеңде қатаң кесте құруға тырыспаңыз, тек бөпеңіздің ұйқысы келгенін білдіретін белгілерді (есінеу, көзін уқалау) бақылап, қатты шаршап кетпей тұрып ұйықтатуға тырысыңыз. Егер бәрі әлі де бейберекет болып көрінсе, уайымдамаңыз: осы бейберекеттіктің өзінде үлкен бір тәртіп бар, ал Сіз бәрін керемет атқарып жүрсіз.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді ішімен жатқызғанда (tummy time), оның басын бірнеше секундқа болса да көтеруге тырысып жатқанын байқауыңыз мүмкін; бұл — мойын бұлшықеттерінің нығайып келе жатқанының алғашқы белгісі. Бұл жаттығуларды қызықтырақ ету үшін алдына түрлі түсті ойыншық қойыңыз немесе жай ғана қарама-қарсы жатып, онымен сөйлесіңіз. Егер ол басын әлі көтере алмаса, алаңдамаңыз, әр бала әртүрлі қарқынмен дамиды. Тек сабырмен жалғастыра беріңіз: бұл кішкентай талпыныстар болашақта оның еңбектеуі мен жүруіне негіз болады.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы уақытқа дейін бөпеңіздің ұйықтап жатып жымиғанын көрген боларсыз, халық арасында мұны "періштелермен ойнап жатыр" дейді (шын мәнінде, бұл — рефлекс), алайда енді "әлеуметтік жымию" кезеңі жақындап келеді. Бөпеңіз Сізге қарап, даусыңызға немесе бет әлпетіңізге жауап ретінде саналы түрде жымиюы мүмкін; бұл жай ғана мимика емес, оның Сізге "мен Сізді танимын және жақсы көремін" деуінің алғашқы тәсілі. Онымен сөйлескенде көзіне қарап, жымиыңыз, ол да Сізге жауап беруге тырысады. Мұндай өзара әрекеттесу — оның эмоциялық интеллектісінің дамуына ықпал ететін ең күшті ынталандыру.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кейде бөлмеге кіріп, "мен мұнда не үшін келіп едім?" деп ойланып қаласыз ба немесе ең қарапайым сөздер есіңізге түспей ме? Мұны әзілдеп "Ана миы" (Mom brain) деп атайды және бұл — шын мәнінде болатын физиологиялық жағдай. Ұйқының қанбауы мен гормондық өзгерістер мидың назарын басқа арнаға бұрып, оның барлық ресурсын бөпеге бағыттағандай болады да, өзге "маңызды емес" нәрселерді өшіріп тастайды. Өзіңізді "ақымақ болып қалғандай" сезінбеңіз, бұл — уақытша тұмандану. Маңызды істерді қойындәптерге немесе телефонға жазып жүру арқылы бұл кезеңді жеңілірек өткізе аласыз; миыңыз көп ұзамай бұрынғы сергектігіне қайта оралады.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің көру қабілеті дамып келеді және ол енді қозғалып тұрған заттарды көзімен қадағалай (tracking) бастауы мүмкін. Саусағыңызды немесе түрлі түсті ойыншықты оның бетінен 20-30 sm қашықтықта ұстап, оңға-солға баяу қозғалтыңыз; ол Сізді көзімен қадағалауға тырысады. Бұл қарапайым ойын оның көз бұлшықеттерін және ми мен көздің үйлесімді жұмысын дамытады. Егер ол бірден жауап бермесе, шаршаған болуы мүмкін, оны мәжбүрлемеңіз және басқа уақытта қайта байқап көріңіз.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз әлі сөйлей алмаса да, ол — тамаша тыңдаушы; онымен күні бойы істеп жатқан әр әрекетіңіз туралы сөйлесу ("қазір жөргегіңді ауыстырамыз", "қарашы, бұл — терезе") оның болашақта сөйлеуінің дамуы үшін өте маңызды. Зерттеулер ата-анасы өзімен көп сөйлесетін балалардың сөздік қоры кейінірек молырақ болатынын көрсетеді. Оған сұрақ қойып, жауап беретіндей сәл кідіріп күтіңіз (мысалы: "Сүтіңді іштің бе? Жарайсың!"). Мұндай "диалог" оған қарым-қатынас қағидаларын үйретіп, араларыңыздағы байланысты нығайтады.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеге массаж жасау – іш кебуінен болатын түйілуді азайтып, оны тыныштандырудың тамаша тәсілі. Қолыңызға аздап табиғи балалар майын жағып, бөлменің жылы екеніне көз жеткізіңіз де, бөпенің аяқтарынан бастап жоғары қарай жұмсақ қимылдармен массаж жасаңыз. Жанасу кезінде бөлінетін окситоцин гормоны Сізді де, бөпені де тыныштандырады. Бұл рәсімді күн сайын кешке шомылдырғаннан кейін қайталау оның түнгі ұйқыға жайлырақ кетуіне көмектесуі мүмкін.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бар назарыңыз бөпеде болғандықтан, жұбайыңызбен қарым-қатынасыңыз кейінгі орынға ысырылғандай көрінуі мүмкін және бұл – қалыпты жағдай. Дегенмен «ата-ана» бола жүріп, «жұп» екендеріңізді де ұмытпауға тырысыңыздар: бөпе ұйықтағанда бірге шай ішу, құшақтасу немесе жай ғана 10 минут бойы күннің қалай өткені туралы сөйлесу араларыңыздағы салқындықты жібіте алады. Әкесіне де бөпемен жақын байланыс орнатуға мүмкіндік беріңіз (мысалы, кекірту немесе шомылдыру оның міндеті болуы мүмкін). Бір команда екендеріңізді сезіну осы қиын күндері екеуіңізге де күш береді.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпе әлі еңбектемесе де, еріксіз қимылдармен аударылуға талпынуы мүмкін, сондықтан қауіпсіздік мәселесіне ерекше мән беру керек. Алтын қағида: бөпені биік жерде (диванда, төсекте, жөргек ауыстыратын үстелде) ешқашан, тіпті бір секундқа да жалғыз қалдырмаңыз. «Әлі қозғалмайды» деп алаңсыз болмаңыз, өйткені алғаш рет аударылу әдетте күтпеген сәтте болады. Оны тек еденге төселген кілемнің немесе арнайы ойын төсенішінің үстіне жатқыза аласыз (әрине, бақылауда ұстаңыз). Қауіпсіздік дағдыларын қазірден қалыптастыру алдағы жазатайым оқиғалардың алдын алады.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Міне, халық арасында ерекше мән берілетін күн де келді – «Баланың қырқынан шыққан» күні! Құттықтаймыз! Ежелгі дәстүр бойынша бұл күні арнайы шомылдыру рәсімі («қырық қасық су») өткізіліп, ана мен бала бұдан былай ел арасына еркін шыға алады. Ал медициналық тұрғыдан бұл 6 апталық қалпына келу кезеңінің (лохияның тоқтауы, жатырдың жиырылуы) аяқталғанын білдіреді. Бұл күнді мереке ретінде атап өтіңіз, сәнденіп, әрленіңіз және бөпеңізбен алғаш рет ұзақ «ресми» серуенге шығып көріңіз. «Қырық» – жай ғана сан емес, ол Сіздің «жаңа ана» мәртебесінен «тәжірибелі ана» мәртебесіне өтуіңіздің нышаны. Сіз мұны еңсердіңіз!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қырқынан шығу» қоғамымызда мәреге жеткендей қабылданады, бірақ шын мәнінде бұл – марафонның бастамасы ғана. «Енді бәрін істей алуым керек», «Үйім мінсіз таза болуы тиіс» деген қысымға берілмеңіз. Қалпына келу үдерісі әлі де жалғасып жатыр; әсіресе емізіп жүрсеңіз, гормондардың (пролактиннің) әсерінен буындарыңыздың босаңсуын немесе беліңіздің ауырғанын сезуіңіз мүмкін. Осы «жаңа еркіндік» кезеңінде өзіңізге бірден көп салмақ түсірмей, бұрынғы қарқыныңызға асықпай, біртіндеп оралыңыз.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді түстерді жақсырақ ажырата бастайды; қызыл және қызғылт сары оның назарын аударатын алғашқы ашық түстер болуы мүмкін. Бесігінің үстіне ілінген айналмалы ойыншықтың (мобильдің) енді тек әуені ғана емес, қозғалысы да оны қызықтырады. Егер әлі сатып алмасаңыз, қарапайым геометриялық пішіндерден тұратын және баяу қозғалатын мобиль оның зейінін шоғырландыру қабілетін дамытады. Бірақ ескеріңіз: ұйықтатар кезде ұйқысы қашып кетпеуі үшін бұл ойыншықтарды алып қойыңыз.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің көру әлемі барған сайын түрлі түске боялып келеді: енді ол қызыл және қызғылт сары түстермен қатар, жасыл мен сарыны да ажырата бастайды. Оның дамуын қолдау үшін үйдің әртүрлі бөлмелерін аралатып, айнадан өз бейнесін көрсетіңіз (бөпелер өз бейнесіне қарағанды қатты ұнатады, бірақ оның өзі екенін әлі түсінбейді). «Кәне, қарайықшы, мұнда кім бар?» деп онымен сөйлесіңіз. Мұндай әлеуметтік ойындар оның миындағы нейрондық байланыстардың жылдам дамуына ықпал етеді.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кейде аналар емізіп жүрсе де, салмағы азаймай, керісінше артады. Бұл ұйқының қанбауы мен күйзелістен кортизол гормонының көбеюіне байланысты болуы мүмкін: ағза өзін «қауіпте» сезініп, май қорын жинайды. «Сүт көбейсін» деп тәтті шай ішу, халуа немесе қамырдан жасалған тағамдар жеу керек деген түсінік — аңыз. Сүттің көбеюіне жеткілікті су ішу және бөпенің жиі емуі ықпал етеді. Қантты азайтып, көкөністі көбірек жеу қуатыңызды арттырып қана қоймай, салмағыңыздың біртіндеп қалыпқа келуіне де көмектеседі.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Етпетінен (tummy time) жатқызғанда, енді тек басын ғана емес, кеудесін де жерден көтеруге тырыса ма? Бұл — нағыз «шағын жаттығу»! Оның қолдары мен арқа бұлшықеттері нығайып келеді. Егер әлі жасай алмаса, көмектесіңіз: кішкентай сүлгіні орап, қолтықтарының астына қойыңыз, ол тірек болады. Алдына сүйікті ойыншығын қойып, соған жетуге талпынуына мүмкіндік беріңіз. Бұл қимылдар болашақта еңбектеуі мен отыруы үшін маңызды.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бұл кезеңде бөпелердің «қоректік емес ему» рефлексі күшті болады, яғни ол аш емес, тек тынышталу үшін бір нәрсе сорғысы келеді. Егер саусақтарын сорса және Сіз емізік бергіңіз келсе, «ортодонтиялық» пішіндегі түрін таңдауға тырысыңыз. Емізік жаман әдет емес, ол сәбидің кенеттен қайтыс болу синдромының (SIDS) қаупін азайтуға көмектесетін құрал болып саналады. Алайда бөпе жылаған сайын емізікті «тыныштандырғыш» ретінде қолданбаңыз, алдымен оны не мазалап тұрғанын түсінуге тырысыңыз.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің басының бір жағы жалпайып кеткенін байқадыңыз ба? Бұл «позициялық плагиоцефалия» деп аталады және бөпенің үнемі бір қырымен жатуынан пайда болады. Бас сүйектері әлі жұмсақ болғандықтан, мұны оңай түзетуге болады. Қарапайым шешімі: оны бесікке жатқызғанда, басының бағытын әр түн сайын ауыстырыңыз (бір күні оңға, бір күні солға). Ал ояу кезінде басының артына қысым түспеуі үшін мүмкіндігінше жиі етпетінен жатқызыңыз.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бүгін бөпеңіз 2 айға толды! Енді «жаңа туған нәресте» (newborn) кезеңін ресми түрде артқа тастап, «бөпе» (infant) кезеңіне өттіңіздер. Алғашқы күндердегі кішкентай әрі дәрменсіз сәбиді қазір Сізге күлімдеп, түрлі дыбыс шығаратын бөпеңізбен салыстырып көріңіз. Алда тіс жару, ұйқы регрессиясы және басқа да қиын кезеңдер кездеседі. Бірақ Сіз енді тәжірибелі анасыз және кез келген қиындықты еңсере аласыз. Өзіңізді құшақтаңыз, Сіз керемет іс атқарып жүрсіз!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6-8-апталар (яғни қазіргі кезең) бөпелердің ең көп жылайтын шағы болуы мүмкін. Кейде еш себепсіз, қарны тоқ, жөргегі таза болса да жылай береді. Бұл оның жүйке жүйесіне айналадағы дыбыстар, жарық және басқа да әсерлердің шамадан тыс жүктеме түсіруінен болады. Өзіңізді кінәламаңыз, мұның Сіздің «жаман ана» болуыңызға еш қатысы жоқ, бұл — дамудың табиғи бір бөлігі. Тек жанында болып, құшақтап, «бұл да өтеді» деңіз. Шынында да, бірнеше аптадан кейін мұндай жылау күрт азаяды.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз «агу» деп немесе тамағынан түрлі дыбыстар шығара бастады ма? Бұл — сөйлеу дамуының алғашқы кезеңі! Ол дыбыс шығарғанда, Сіз де дәл сондай дыбыспен жауап беріңіз, «әңгімелесіп отырғандай» болыңыз. Зерттеулер ата-ананың бөпе шығарған дыбыстарды қайталауы оған «мен сені естіп, түсініп тұрмын» деген белгі беретінін көрсетеді. Бұл қарапайым ойын оның өзіне деген сенімін арттырып, болашақта ертерек сөйлеуіне негіз қалайды.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Айнаға қарағанда жүктіліктен қалған артық салмақты немесе салбыраған ішіңізді көріп, әлі де көңіліңіз түсуі мүмкін. Есіңізде болсын, ішіңіз 9 ай бойы үлкейді, оның толық қалпына келуіне де кемінде сонша уақыт қажет. Қатаң диеталар (әсіресе емізетін аналар үшін) сүттің азаюына және шаштың түсуіне әкелуі мүмкін. Қазір арықтау туралы емес, дұрыс тамақтану туралы ойлаңыз. Мол су, көкөніс және ақуыз — Сіздің ең жақсы серіктеріңіз. Денеңізді жек көрмеңіз, ол Сізге дүниедегі ең әдемі сыйды тарту етті.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Етпетінен жату уақытын» (tummy time) қызықтырақ ету үшін «ұшақ» ойынын ойнап көріңіз. Шалқаңыздан жатып, тізеңізді бүгіңіз де, бөпеңізді сирақтарыңыздың үстіне етпетінен жатқызып, ақырын тербетіңіз (әрине, қолыңызбен ұстап тұрыңыз). Бұл оған айналасына басқа қырынан қарауға мүмкіндік береді, Сізбен көз түйістіруіне көмектеседі және вестибулярлық аппаратын (тепе-теңдік сезімін) дамытады. Бөпелер еденде жалғыз жатқаннан гөрі, анасының денесінің үстінде жаттығуды көбірек ұнатады.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқысы әлі толық реттелмесе де, күндізгі ұйқысы (nap) қысқара бастауы мүмкін. Егер бөпеңіз күндіз небәрі 20-30 минут ұйықтап оянса, «ұйқысы қанды» деп ойламаңыз. Кейде бөпелер ұйқы циклдерінің арасында (әр 40-45 минут сайын) оянады, бірақ шын мәнінде әлі ұйқысын толық қандырмаған болады. Оянған бойда жарықты бірден жағып, ойнауды бастамаңыз; жанына жатып, әлдилеңіз немесе емізіп, ұйқысын ұзартуға тырысыңыз.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жақында жасалатын 2 айлық екпелер (вакцинация) туралы дәрігеріңізбен сөйлесетін уақыт келді. Әзербайжанның Ұлттық екпе күнтізбесіне сәйкес, осы кезеңде көкжөтел, дифтерия, сіреспе, B гепатиті және т.б. қарсы (Hexaxim немесе соған ұқсас), сондай-ақ ротавирус пен пневмококқа қарсы екпелер қарастырылған. Айналадағы адамдардың «екпе зиян», «бала сөйлемей қалады» деген ғылыми негізі жоқ қорқынышты қауесеттеріне сенбеңіз. Екпе — бөпеңізді болашақта өлімге әкелуі мүмкін аурулардан қорғайтын ең мықты қалқан. Сұрақтарыңызды «көрші апайдан» емес, педиатрыңыздан сұраңыз.') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Босанғаннан кейінгі жыныстық өмір тақырыбы көбіне жабық тақырып саналады, бірақ бұл туралы хабардар болғаныңыз маңызды. Дәрігеріңіз рұқсат бергеннен кейін (әдетте 6 аптадан соң) жыныстық қатынасқа түсуге болады. Алайда жыныстық құлшыныстың болмауы (либидоның төмендеуі) немесе құрғақтық сезінуіңіз — қалыпты жағдай. Бұл емізуге байланысты гормондар мен шаршаудың әсерінен болады. Жұбайыңызбен бұл туралы ашық сөйлесіп, бір-біріңізге уақыт беріңіздер және асықпаңыздар. Жақындық тек жыныстық қатынас емес, осы кезеңде жай ғана құшақтасып, бір-біріңізге жанасудың өзі өте маңызды.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз қазір қолдарын зерттей бастайтын кезеңде: ол қолдарын аузына салып, саусақтарын соруы мүмкін. Бұл оның "қарны ашты" дегенді білдірмейді (дегенмен аштықтың белгісі де болуы мүмкін). Осылайша бөпе өзін тыныштандырады әрі қоршаған ортаны танып-біледі. Қолдарын аузынан шығаруға немесе оған қолғап кигізуге тырыспаңыз. Өз денесін зерттеуіне мүмкіндік беріңіз. Тек қолдарының таза, ал тырнақтарының алынғанына көз жеткізіңіз.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '2 айлық екпелерді салдыратын уақыт келді (егер әлі жасатпаған болсаңыз). Әзербайжанда қолданылатын екпе күнтізбесіне сәйкес, осы кезеңде бөпеге әдетте 5 немесе 6 компонентті біріктірілген вакцина (көкжөтел, дифтерия, сіреспе және т.б.) мен пневмококқа қарсы екпе салынады. Екпеден кейін бөпенің дене қызуы сәл көтерілуі немесе ол мазасыздануы мүмкін. Бұл қорқынышты емес, керісінше, иммундық жүйенің "іске қосылғанын" және ағзаның қорғаныс қалыптастырып жатқанын көрсетеді. Дәрігердің кеңесімен үйде бөпелерге арналған құрамында парацетамол бар суппозиторий немесе шәрбат міндетті түрде сақтаңыз, алайда дене қызуы 38 градустан аспай тұрып дәрі беруге асықпаңыз.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің аузынан сілекей ағып, қолдарын кеміре бастады ма? Әжелер бірден "тісі шығып жатыр" деуі мүмкін, бірақ 2 ай тіс шығу үшін әдетте ерте кезең саналады (ерекше жағдайлар кездескенімен). Осы кезеңде сілекей бездері белсенді жұмыс істей бастайды, алайда бөпе сілекейді толық жұтуды әлі үйренбегендіктен, ол сыртқа ағады. Сонымен қатар сілекейдегі ферменттер оның ас қорыту жүйесін болашақта қатты тағам қабылдауға дайындайды. Мойны ылғал болып, бөртіп кетпеуі үшін сілекей сіңіретін алжапқышын жиі ауыстырып тұрыңыз.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Душ қабылдаған кезде қолыңызға бір уыс шаш түссе, қорықпаңыз, таз болып қалмайсыз! Бұл "Босанғаннан кейінгі шаш түсуі" деп аталады және толығымен гормондарға байланысты үдеріс. Жүктілік кезінде жоғарылаған эстроген гормоны шашыңыздың түсуіне жол бермеген еді, ал қазір бұл гормондардың деңгейі төмендеп, кезінде түспеген шаштың бәрі бір мезгілде түсіп жатыр. Бұл уақытша құбылыс және шамамен 6-12 ай ішінде шашыңыз қалпына келеді. Қымбат сусабындарға ақша жұмсағаннан гөрі, тамақтануыңыз бен ағзаңыздағы темір деңгейіне мән беріңіз. Уақыт өте келе бәрі қалпына келеді.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз түн мен күнді біртіндеп ажырата бастады, сондықтан қазір "ұйқы рәсімін" қалыптастыруға таптырмас уақыт. Бұл қатаң режим емес, тек белгілі бір реттілік: Жылы ванна -> Пижама кигізу -> Бәсең жарық -> Бесік жыры немесе ақ шу -> Ұйқы. Күн сайын осы реттілікті қайталау бөпенің миына "ұйықтайтын уақыт келді" деген белгі береді. Бұл әдет бүгін бірден нәтиже бермесе де, бірнеше аптадан кейін Сізге үлкен көмек болады.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қош келдіңіз, 3-ай! Бөпеңіздің дамуындағы «Төртінші триместр» деп аталатын алғашқы 3 айлық бейімделу кезеңі аяқталуға жақын. Енді бөпеңіз тек тамақтанып, ұйықтайтын сәби емес, айналасын танып-біліп, дыбыстарға жауап беретін әлеуметтік тұлғаға айналып келеді. Осы айдан бастап оның сергек жүретін уақыты ұзарып, ұйқысы да (солай болады деп үміттенеміз!) біршама реттеле бастайды. Бұл жаңа кезеңде ол Сізбен көбірек «сөйлескісі» келеді, сондықтан онымен көп сөйлесіп, ән айтуға дайын болыңыз.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз қолдарын бетінің алдына ұстап, оларға таңдана қарап жүр ме? Бұл — оның алғашқы «ойыншығын» танып-білуі! Мұны «қол-көз үйлесімі» деп атайды. Ол қолдарының өзіне тиесілі екенін және оларды басқара алатынын түсіне бастайды. Бұл үдеріске кедергі жасамаңыз, қолдарын жасырмаңыз. Керісінше, білектеріне түрлі түсті немесе дыбыс шығаратын (сылдырмақты) білезіктер тағып, бұл жаңалықты қызықтырақ ете аласыз. Бұл — оның миының дамуына арналған тамаша жаттығу.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұйқы мәселесі әлі де қиындық туғызғанымен, жақсы жаңалық бар: бөпеңіздің миы «Мелатонин» (ұйқы гормоны) бөле бастады, циркадтық ырғағы (биологиялық сағаты) қалыптасып келеді. Енді оның күн мен түнді шатастыру ықтималдығы азаяды. Оған көмектесу үшін таңертең бөлмеге күн сәулесін молынан түсіріңіз, ал кешке жарықты ертерек өшіріп, тыныштық орнатыңыз. Осындай табиғи жарық тәртібі оның миына «қазір сергек болатын уақыт» және «қазір ұйықтайтын уақыт» деген белгілерді жеткізеді.') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің мойын бұлшықеттері едәуір нығайды, енді ол етпетінен жатқанда басын 45-90 градусқа көтеріп, айналасына қарай алады. Тіпті кейде «ұшақ» сияқты қолдары мен аяқтарын ауаға көтеріп, тербелуі мүмкін. Бұл оның арқа бұлшықеттерін алдағы еңбектеу және отыру кезеңдеріне дайындайды. Егер ол әлі де басын толық ұстай алмаса, алаңдамаңыз: әр баланың даму қарқыны әртүрлі. Тек етпетінен жату уақытын (tummy time) күнделікті тәртіптен алып тастамаңыз.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің басынан, әсіресе еңбегінің маңынан сарғыш, майлы қабыршақтарды (қайызғақ тәрізді) байқадыңыз ба? Мұны халық арасында «сүт қабыршағы», ал медицинада «Себореялық дерматит» деп атайды. Қорықпаңыз, бұл гигиенаның нашарлығынан болмайды және жұқпалы емес. Ол анадан берілетін гормондардың әсерінен май бездерінің шамадан тыс жұмыс істеуінен пайда болады. Қабыршақтарды жұлып алуға тырыспаңыз. Шомылдырмас бұрын зәйтүн немесе бадам майын жағып жұмсартыңыз, содан кейін жұмсақ щеткамен ақырын тарап, жуып тастаңыз. Уақыт өте келе ол өздігінен жоғалады.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді бөпеңіздің күлкісі рефлекстік емес, толықтай саналы! Сіз оған жымиғанда, қытықтағанда немесе «ку-ку» (жасырынбақ) ойынын ойнағанда, ол дауыстап күле бастауы мүмкін. Бұл дыбыс — әлемдегі ең әдемі әуен, солай емес пе? Оның әзіл сезімі қалыптасып келеді. Біртүрлі дыбыстар шығарып, бетіңізді әртүрлі құбылтуыңыз оған қатты ұнайды. Күлу оның өкпесін дамытуға да көмектесіп, стресс гормондарының деңгейін төмендетеді.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпені ішімен жатқызғанда (tummy time), оның бір қырына аунауға тырысып жатқанын байқауыңыз мүмкін. Кейбір ширақ бөпелер осы кезеңде ішінен арқасына қарай (кейде басының салмағымен кездейсоқ) аунап түсе алады. Бұл — үлкен қуаныш, бірақ сонымен қатар сақ болу керектігін білдіреді: енді оны жөргек ауыстыратын үстелде, диванда немесе биік жерде бір секундқа да қараусыз қалдыруға болмайды. Осы айдан бастап құлап кету қаупі күрт артады, сондықтан ең қауіпсіз орын — еден (кілем немесе ойын төсенішінің үсті).') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпе енді тек жылап қана қоймай, дауысты дыбыстарды ("а", "о", "у") созып айта немесе қуана шыңғыра алады. Осылайша оның дауыс желбезектері жаттығады. Сіз асүйде жұмыс істеп жүргенде, ол бөлмеде дыбыс шығарса, міндетті түрде дауыстап жауап беріңіз ("Иә, сені естіп тұрмын, қазір барамын"). Мұндай "қашықтан сөйлесу" оған қауіпсіздік сезімін береді: "Анамды көрмесем де, дауысын естіп тұрмын, демек, мен жалғыз емеспін". Бұл ажырау мазасыздығын (separation anxiety) азайтуға көмектеседі.') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің салмағы артқан сайын, беліңіз бен қолдарыңыз ауыруы мүмкін (әсіресе "ана білегі" синдромы). Оны қолыңызға алғанда немесе емізгенде дене қалпыңызға мән беріңіз: иықтарыңызды құлағыңызға қарай көтермеңіз, тік отырыңыз және міндетті түрде беліңізді тірейтін жастықтарды пайдаланыңыз. Бөпені еденнен көтергенде, беліңізді емес, тізеңізді бүгіңіз. Омыртқаңыз Сізге әлі талай жыл қызмет етуі керек, сондықтан оны қазірден қорғаңыз.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Айналаңыздағы адамдардан "бөпең 3 айға толды, енді тамақтың сорпасынан дәм татқыз", "аздап нанның жұмсағын бер, үйрене берсін" деген сияқты қысым естуіңіз мүмкін. Нық болыңыз және "ЖОҚ" деңіз. Дүниежүзілік денсаулық сақтау ұйымы (ДДСҰ) мұны анық айтады: алғашқы 6 айда ТЕК ана сүті (немесе сүт қоспасы) берілуі керек. Бөпенің асқазан-ішек жолы крахмалды немесе басқа тағамдарды қорытуға әлі дайын емес; қосымша тағамды ерте бастау аллергияға, іштің кебуіне және болашақта семіздікке әкелуі мүмкін. Асықпаңыз, бөпеңіздің тамақ жеуіне әлі бүкіл өмірі бар.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы кезеңдегі ең қызықты ойыншық — айна! Бөпенің алдына қауіпсіз (сынбайтын) айна қойыңыз. Ол айнадағы "басқа бөпеге" күлімсіреп, оған қолын тигізуге тырысады және таңырқай қарайды. Әзірге оның өзі екенін түсінбейді (бұл шамамен 18-ші айда болады), бірақ бет әлпеті мен қимылдарды бақылау оның әлеуметтік дамуы үшін өте пайдалы. Бұл ойын бөпені ішімен ұзағырақ жатқызудың да тамаша тәсілі.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің айналаға қызығушылығы артқан сайын, оны емізу қиындай түсуі мүмкін. Ол әр дыбыс пен әр қимылға басын бұрып қарағысы келіп, емшекті жібере салады. Мұны "әуесқой бөпе синдромы" деп атайды. Ашуланбаңыз, емізу үшін тыныш, қараңғы әрі алаңдататын нәрселері жоқ бөлмені таңдаңыз. Мойныңыздағы жарқыраған алқаны немесе назар аударатын заттарды шешіп қойыңыз. Оның түнде немесе ұйқылы кезінде жақсырақ еметінін байқауыңыз мүмкін, бұл қалыпты жағдай.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жастығы немесе киімі жиі сулана ма? 3-ші айда сілекейдің көбеюі — қалыпты жағдай. Бұл міндетті түрде тісі шығады дегенді білдірмейді (дегенмен қызыл иегі қышуы мүмкін). Бұл ас қорыту жүйесінің дамып, ауыз қуысындағы бактерияларға қарсы табиғи қорғаныс қалыптасып жатқанын көрсетеді. Бөртпе пайда болмас үшін мойнына сілекей сіңіретін алжапқыш тағып, ауыз айналасын құрғақ ұстаңыз.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Су беру керек пе?" деген сұрақ осы айларда аналарды жиі толғандырады. Әсіресе әжелер "обал ғой, шөлдеп қалды" деуі мүмкін. Алайда Дүниежүзілік денсаулық сақтау ұйымы (ДДСҰ) алғашқы 6 айда бөпеге ана сүтінен немесе сүт қоспасынан басқа ЕШТЕҢЕ (тіпті су да) бермеуді ұсынады. Ана сүтінің 88%-і судан тұрады және бұл бөпенің суға деген қажеттілігін толық өтейді. Оның асқазаны әлі өте кішкентай, сондықтан су ішкізу сүтті аз ішуіне және дамуының тежелуіне әкелуі мүмкін.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Күнделікті өміріңізге өзіңіз үшін "үзіліс" түймесін қосыңыз. Бөпе ұйықтағанда бірден үй жинауға асықпаңыз. Сіздің де "батареяңызды" қуаттау қажет. 20 минут көз шырымын алу, кітап оқу немесе жай ғана төбеге қарап жату — Сіздің де құқығыңыз. "Мінсіз үй иесі" болуға міндетті емессіз, бірақ "дені сау ана" болуыңыз керек. Шаң күте тұрады, ал Сіздің психологиялық саулығыңыз күтпейді.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы айдан бастап "Тамақтану - Белсенділік - Ұйқы" тәртібін қалыптастыра аласыз. Яғни: Бөпе оянады -> Сүт ішеді -> Ойнайды -> Ұйықтайды. Көп жағдайда аналар бөпесін емізіп ұйықтатады (бұл дұрыс емес деген сөз емес, бірақ әдетке айналуы мүмкін). Егер "ішіп-ойнап-ұйықтау" ретін қолдансаңыз, бөпе тамақтануды ұйқымен азырақ байланыстыратын болады және болашақта өздігінен ұйықтап кетуі жеңілдейді. Әрине, бұл қатаң қағида емес, тек қолданып көруге тұрарлық тәсіл.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің қолдары енді "өздігінен" қимылдамайды: ол заттарға саналы түрде қол созып, оларды ұстауға тырысады. Бұрын саусағыңызды алақанына салғанда рефлексті түрде қысып ұстаса, енді ойыншықты көріп, оған қарай қолын созады. Бұл — керемет даму, бірақ абай болыңыз: қолыңызда отырғанда ол шашыңыздан, алқаңыздан немесе көзілдірігіңізден тартуға тырысады. Сондай-ақ ыстық шай құйылған кеселерді одан алыс ұстаңыз, өйткені кенет қимылдап, үстіне төгіп алуы мүмкін. Енді қауіпсіз арақашықтықты сақтау өте маңызды.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқысыздық әлі де жалғасып жатса, "Ұйқыда тамақтандыру" (Dream Feed) тәсілін қолданып көріңіз. Бұл — бөпені толық оятпай, ұйқылы күйінде (мысалы, өзіңіз ұйықтар алдында сағат 23:00-да) емізіп, қайтадан орнына жатқызу. Бұл тәсіл кейде бөпенің түн ортасында оянуына жол бермей, Сізге сәл ұзағырақ әрі үзіліссіз ұйықтауға мүмкіндік береді. Егер бұл тәсіл көмектеспесе және бөпе оянып, жыласа, мәжбүрлемеңіз; әр баланың биологиялық ырғағы әртүрлі.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің өз қолдарын зерттей бастауы кейде тырнағымен бетін тырнап алуына әкеледі. Егер тырнағын алуға қорықсаңыз, мұны ол ұйықтап жатқанда жасаңыз немесе тырнақтары сәл жұмсаруы үшін шомылдырғаннан кейінге қалдырыңыз. Қолғап кигізу енді ұсынылмайды, өйткені бөпе қолымен ұстап, аузына апару арқылы әлемді танып-біледі. Кішкентай тырналған жер тез жазылады, ал қолдарының сезінуіне кедергі келтіру оның дамуын баяулатуы мүмкін.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, "Төртінші триместр" деп аталатын алғашқы 3 айлық бейімделу кезеңі аяқталуға жақын! Бөпеңіз енді "сыртқы әлемге" толық үйренді. Ояу кезінде оны тек төсекте жатқыза бермеңіз: үйді аралатыңыз, терезеден бірге қараңыз, әртүрлі бөлмелерге апарыңыз. Ол енді айналасын бақылап жүр. Осы кезеңде онымен неғұрлым көп көзбен және дыбыс арқылы байланыс орнатсаңыз, миындағы нейрондық байланыстар соғұрлым нығая түседі. Сіз — оның алғашқы әрі ең жақсы ұстазысыз.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің түнде ұзағырақ (мысалы, 4-5 сағат үзіліссіз) ұйықтай бастағанын байқадыңыз ба? Бұл оның асқазаны үлкейіп, түні бойы тоқ бола алатынын көрсетеді. Бірақ қуануға асықпаңыз, бұл "бал айы" кезеңі болуы мүмкін. Кейбір бөпелерде 3-4 ай шамасында "ұйқы регрессиясы" (sleep regression) басталады. Ұйқысы бұзылса, алаңдамаңыз: бұл оның ми дамуы жаңа кезеңге өткенін білдіреді. Өзіңіз қалыптастырған ұйқы рәсімін жалғастыра беріңіз, өйткені тұрақтылық — оның ең басты қажеттілігі.') WHERE id = '7478fbcd-b780-4677-b9cd-7d27602a29cc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді бөпеңіздің қолдары жұдырық болып түйілмей, көбіне ашық тұрады. Бұл оның бұлшықет тонусының (гипертонус) төмендеп, қалыпқа келе бастағанын көрсетеді. Ол екі қолын біріктіріп, саусақтарымен ойнай алады. Оған құрылымы әртүрлі (жұмсақ, бұдырлы, сыбдырлайтын) маталар немесе ойыншықтар беріп, сипап сезу қабілетін дамыта аласыз. Мидың дамуы саусақ ұштарынан басталады: ол әртүрлі беттерге неғұрлым көп жанасса, миы соғұрлым көп ақпарат өңдейді.') WHERE id = 'd9c1219d-f2eb-4189-a9f5-e0d58b033ef7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Көршінің баласы аунай бастады, ал менікі неге әлі қозғалмайды?" деген сияқты салыстырулар — аналардың ең үлкен жауы. Есіңізде болсын, әр бала — бірегей тұлға, ал даму кестесі математикалық формула емес, тек шамамен берілген аралық. Бір бөпе 3 айында, екіншісі 5 айында аунауы мүмкін; бұл екіншісі "артта қалды" дегенді білдірмейді. Салыстыру Сізді күйзеліске түсіреді, ал бөпе Сіздің мазасыздығыңызды сезеді. Оның өз қарқынымен дамуына құрметпен қарап, кішкентай жетістіктерін ғана атап өтіңіз (мысалы, басын бұрынғыдан тік ұстауын).') WHERE id = '3aa7065c-48aa-4e3c-a0fe-877781389808';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Денеңізді тексеріңіз: ішіңіздің ортасында, кіндік сызығының бойында саңылау немесе ойық сезіле ме? Бұл "Диастаз" (іш бұлшықеттерінің ажырауы) болуы мүмкін. Жүктілік кезінде созылған бұлшықеттер әлі бірігіп үлгермесе, классикалық "пресс" (денені көтеру) жаттығуларын жасауға қатаң тыйым салынады, өйткені олар жағдайды одан әрі нашарлатуы мүмкін. Алдымен қарапайым тыныс алу жаттығулары немесе вакуум (дәрігердің рұқсатымен) арқылы ішкі бұлшықеттерді нығайту керек. Жаттығуды бастамас бұрын диастаздың бар-жоғын тексеру маңызды.') WHERE id = '2926fb2b-5ad3-4daf-b451-2b21927c114c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізбен бірге «кітап оқуды» бастау ешқашан ерте емес! Ол сөздерді түсінбесе де, Сіздің дауыс ырғағыңызды, интонацияңыз бен сөйлеу мәнеріңізді тыңдағанды ұнатады. Қалың бетті, суреті көп әрі мәтіні аз кітаптарды таңдаңыз. Оған суреттерді көрсетіп: «Қарашы, мынау мысық, ол мияулайды», — деңіз. Бұл әдет оның тілінің дамуын жеделдетіп, болашақта кітапқа деген қызығушылығын оятады. Сондай-ақ бөпеңізді құшағыңызға алып кітап оқу ұйықтар алдындағы тыныштандыратын рәсімге айналуы мүмкін.') WHERE id = '7f0b6be9-2911-4a47-a448-53c0a1e9d9fe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді етпетінен жатқызғанда (tummy time), ол енді қолдарын алға созып, кеудесін еденнен едәуір көтере алуы керек. Бұл «кобра қалпы» оның арқа және мойын бұлшықеттерінің нығайып келе жатқанын көрсетеді. Егер ол әлі де етпетінен жатқанды ұнатпай, жылайтын болса, берілмеңіз. Күніне 5-10 минуттық қысқа жаттығуларды жалғастырыңыз. Немесе шалқаңыздан жатып, оны кеудеңіздің үстіне қойыңыз; Сіздің жүзіңізді көру үшін басын көтеруге ынтасы арта түседі.') WHERE id = 'd283274d-2a11-4684-91a8-ce7b016b2812';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала емізетін аналар арасында «ботокс жасатуға болмайды», «шаш бояуға болмайды» деген пікірлер кең таралған. Алайда заманауи зерттеулер шаш бояуының немесе жергілікті эстетикалық процедуралардың көпшілігі емшек сүтіне өтпейтінін және бөпе үшін қауіпсіз екенін көрсетеді (әрине, аммиаксыз бояуларды таңдап, сенімді мамандарға жүгінген жөн). Өзіңізге күтім жасап, әдемі көрінгіңіз келуі аналық міндеттеріңізге қайшы емес. Бақытты әрі өзіне сенімді ана баласына көбірек сүйіспеншілік сыйлай алады.') WHERE id = '989b1bed-bb91-418f-ba9c-66f04eee3377';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді бөпеңіздің жымиысы қытықтаған кезде сыңғырлаған күлкіге ұласуы мүмкін. Оның қолтығын, мойнын немесе табанын ақырын қытықтап, реакциясын бақылаңыз. Бұл қарапайым ойын оған өз денесін танып-білуге және сезіну қабілетін дамытуға көмектеседі. Күлу оның өкпе сыйымдылығын арттырып, қан айналымын жақсартады. Үйдегі күйзелісті азайтатын ең жақсы дәрі — бөпенің күлкісі.') WHERE id = '9800dfd4-1a12-46cd-be37-2d51f66e1ad7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің күндізгі ұйқысы қысқарып, бірақ жиілеп кетті ме? 3 айлық бөпелер әдетте күндіз 3-4 рет ұйықтайды (барлығы 4-5 сағат). Егер ол ұйықтағысы келмей, шамадан тыс шаршағандықтан жыласа, оны құшағыңызда тербетіп немесе арбамен серуендетіп ұйықтатудан тартынбаңыз. «Үйреніп кетеді» деп қорқып, оны ұйқысыз қалдыру әлдеқайда зиян. Ұйқысы қанбаған бөпенің ағзасында стресс гормоны (кортизол) бөлінеді, бұл оның дамуына кері әсер етеді. Басты мақсат: оның ұйықтауы, ал қалай ұйықтайтыны әзірге екінші орында.') WHERE id = '1a9dccd0-8134-416f-bb91-5bdf13fc777c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бүгін бөпеңіз 3 айға толды! Бұл — маңызды кезең. Енді «Төртінші триместр» толығымен аяқталды. Бөпеңіз басын тік ұстайды, қолдарын біріктіреді, Сізге жымияды және тіпті бір қырына аунауға тырысуы мүмкін. Ол енді өзіндік мінезі бар кішкентай тұлға. Бүгін оның дамуын бағалау үшін педиатрдың қабылдауын жоспарлауыңызға болады. Бірақ ең бастысы — өзіңізді құттықтаңыз. Сіз 90 күн бойы үзіліссіз, күндіз-түні еңбек етіп келе жатқан қаһармансыз. Бүгін өзіңізге шағын сыйлық жасауды ұмытпаңыз!') WHERE id = 'c4888a4d-c53f-4c06-9f8b-73bef82c950b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз қолына түскеннің бәрін аузына сала ма? Бұл — «оральды кезеңнің» белсенді басталғаны. Ол қоршаған ортаны аузына салып, «дәмін тату» арқылы танып-біледі. Бұл міндетті түрде тісі шығады дегенді білдірмейді (дегенмен қызыл иегі қышуы мүмкін). Оған құрылымы әртүрлі тіс қаситын ойыншықтар беріңіз. Бірақ ең бастысы — қауіпсіздік: еденде немесе үстел үстінде ұсақ заттарды (түйме, тиын, моншақ) қалдырмаңыз. Осы айларда қол қимылы икемді бола түсетіндіктен, қақалып қалу қаупі артады. Үйіңізді «бөпенің көзімен» қарап шығыңыз.') WHERE id = '3d44726d-b011-4c60-a3ce-d4d40cf54d8f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кешкі уақытта бөпеңіздің емуден бас тартып, емшекпен «арпалысатынын» немесе жылап отырып еметінін байқайсыз ба? Бұл «жалған емшектен бас тарту» деп аталады. Оның себебі сүттің аздығы емес, бөпенің шаршауы немесе шамадан тыс әсер алуы. Оны тыныштандыру үшін «ақ шуды» (white noise) қосыңыз, бөлмені қараңғылаңыз немесе жүріп емізіп көріңіз. Сонда да ембесе, мәжбүрлемеңіз: 15-20 минут үзіліс жасап, тыныштандырыңыз да, қайтадан ұсынып көріңіз.') WHERE id = '01937078-adcb-4cc4-9337-fd91b288734f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің күндізгі ұйқысы қысқарса (30-45 минут), бұл қалыпты жағдай. 4-ші айда ұйқы циклдері өзгереді және бөпе бір циклден екіншісіне ауысқанда (жеңіл ояну кезінде) өздігінен қайта ұйықтай алмауы мүмкін. Оған көмектесу үшін оянған бойда жарықты бірден жақпаңыз; жанына жатып, ақырын жұбатыңыз немесе қолыңызды кеудесіне қойып, сәл басып тұрыңыз. Бұл «ұйқыны ұзарту» әдісі (resettling) уақыт өте келе оған ұйқы циклдерін біріктіруді үйретеді.') WHERE id = '42ae96e6-578f-4958-b69b-9e931b862da2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бөпеңізбен бірге алғашқы 100 күнді артта қалдырдыңыз! Кейбір Азия мәдениеттерінде бұл күн ерекше атап өтіледі, өйткені бөпе өмірінің ең нәзік кезеңінен өтті деп есептеледі. Артыңызға бір қараңызшы: кішкентай әрі дәрменсіз бөпе енді Сізге күлімдейтін, Сізді танитын, қолдарымен ойнайтын жеке тұлғаға айналды. Сіз де өзгердіңіз, өстіңіз және күшейдіңіз. Бүгін өзіңізге бір шыны кофе құйып, галереядағы алғашқы күндердің суреттерін қарап, «Менің қолымнан келді!» деңіз. Сіз кереметсіз!') WHERE id = '000749db-379b-4eae-a0cc-18c3f43ee041';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз түнде жиі ояна бастады ма? «4-ші айдағы ұйқы регрессиясына» қош келдіңіз! Негізінде бұл кері кету емес, бөпе миының дамуындағы үлкен серпіліс. Оның ұйқы циклдері өзгеріп, ересектердікіндей «үстірт» және «терең» ұйқы кезеңдеріне бөлінеді. Бөпе бір кезеңнен екіншісіне ауысқанда (әр 45-60 минут сайын) сәл оянып, өздігінен қайта ұйықтай алмағандықтан жылайды. Бұл уақытша кезең (2-6 аптаға созылуы мүмкін). Сабырлы болыңыз, бұрынғы әдеттерін (тербету, емізу) күрт өзгертпеңіз, тек оған жаныңызда екеніңізді сездіріңіз.') WHERE id = '70ef5cd6-e529-4523-a7e3-dac3c50ee881';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді етпетінен жатқызғанда (tummy time), оның енді басын ғана емес, кеудесін де жерден көтеріп, қолдарын алға созып «жүзуге» тырысатынын байқайсыз ба? Бұл оның арқа бұлшықеттерінің нығайып келе жатқанын көрсетеді. Кейбір бөпелер осы кезеңде етпетінен шалқасына қарай (кездейсоқ, басының салмағымен) аунап түсуі мүмкін. Бұл — үлкен қуаныш, бірақ сонымен бірге қауіптің белгісі: енді оны диванда немесе төсекте жалғыз қалдыруға мүлде болмайды! Осы айдан бастап құлап кету қаупі күрт артады.') WHERE id = '71d4a5bb-ec66-43a8-8e47-cf600b05a37e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің емізу кезінде зейіні жиі бөлінетіні Сізді алаңдата ма? Ол бір-екі рет еміп, кейін басын бұрып, бөлмедегі дыбысқа немесе жарыққа қарайды. Мұны «Қызығушылығы жоғары бөпе синдромы» деп атайды. Ол айналасын зерттегісі келеді, ал емуді «қызықсыз» деп қабылдайды. Шешімі: емізу кезінде бөлмені барынша тыныш әрі күңгірт етіп, назарын аударатын заттарды (телефон, теледидар, жарқын ойыншықтар) алып қойыңыз. Түнде немесе ұйқылы кезінде оның жақсырақ еметінін байқайсыз.') WHERE id = 'bce582cc-6b95-467c-98a1-35d2509fd4d5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің сілекейі әлі де көп ағып, қолына түскеннің бәрін (ойыншықты, көрпені, Сіздің саусағыңызды) қатты кеміре ме? Бұл қызыл иегінің қышуына байланысты. Тісі әлі көрінбесе де, қызыл иектің астында қозғалып, оған жайсыздық тудырады. Салқындатылған (мұздатылған емес!) тіс қышытқыш немесе таза, дымқыл шүберек беріп, қызыл иегін уқалауына көмектесе аласыз. Бұл ауырсынуды азайтып қана қоймай, оны тыныштандырады.') WHERE id = 'c2f4aabf-8bc7-487e-b896-7f21d18143b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз Сіз бөлмеден шыққанда жылап, қайта кірген бойда тыныштала ма? Құттықтаймыз, бұл оның есте сақтау қабілеті дамып, Сізді басқа адамдардан ажырата бастағанын көрсетеді! Ол енді «объектінің тұрақтылығын» (бір нәрсе көзден таса болғанда жоғалып кетпей, тек орны өзгеретінін) түсіне бастайды, бірақ бұған әлі толық сенімді емес. Онымен «Ку-ку» (жасырынбақ) ойынын ойнап, осы қорқынышты жеңуге көмектесе аласыз. Бетіңізді қолыңызбен жауып, қайта ашыңыз – бұл қарапайым ойын оған «анам кетсе де, қайта оралады» дегенді ұғындырады.') WHERE id = '807256c5-09ac-42f8-a6ba-9c88ea7f39a0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Менің сүтім енді майлы емес», «Сүтім су сияқты» деген ойларға берілмеңіз. Ана сүтінің құрамы бөпенің қажеттіліктеріне қарай үнемі өзгеріп отырады. Алғашқы айлардағы қою, сарғыш сүт қазір сұйығырақ көрінуі мүмкін, бірақ бұл оның сапасыз екенін білдірмейді. Осы айда бөпенің суға деген қажеттілігін өтеу үшін сүт құрамындағы су мөлшері артады (сондықтан қосымша су берудің қажеті жоқ). Табиғат бәрін мінсіз реттеген, өз денеңізге сеніңіз.') WHERE id = 'd807fc3e-ee9d-408b-880a-d8041fef08ed';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің дыбыстар шығаруы («а-гу», «ба-ба», «ғы-ғы») жай ғана шу емес, бұл – сөйлеуді дамыту жаттығуы. Ол дыбыс шығарғанда, Сіз де дәл сондай дыбыспен немесе қарапайым сөздермен жауап беріңіз («Иә, солай ма? Рас па?»). Зерттеулер ата-анасымен «кезектесіп сөйлесетін» (turn-taking) бөпелердің болашақта IQ деңгейі мен тілдік қабілеті жоғарырақ болатынын көрсетеді. Онымен ересек адаммен сөйлескендей әңгімелесіңіз: ол Сізді түсінбесе де, дауыс ырғағы мен қарым-қатынас ережелерін үйренеді.') WHERE id = '8c9eeb48-f7d1-4cb1-abda-c8b5acd82625';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді қолыңызға алып жүруден беліңіз бен қолдарыңыз ауыра ма? Бұл «ана білезігі» (Де Кервен теносиновиті) немесе омыртқа мәселелеріне әкелуі мүмкін. Бөпені көтергенде беліңізді емес, тізеңізді бүгіп (отырып-тұрғандай) көтеріңіз. Емізгенде бөпенің салмағы қолыңызға түспеуі үшін міндетті түрде шынтағыңыздың астына жастық қойыңыз. Сондай-ақ эргономикалық тасымалдағыш-рюкзак немесе слинг қолдану салмақты біркелкі бөліп, Сізге жеңілдік береді. Өз денсаулығыңызды күтіңіз, бөпеңізге Сіздің деніңіз сау болғаныңыз қажет.') WHERE id = '43116043-105f-43ce-b935-0d355f71fac9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің түрлі түсті, дыбысты және жарық шығаратын ойыншықтарға қызығушылығы арта түседі. Бірақ мынаны ескеріңіз: «шамадан тыс ынталану» (overstimulation) деген шек бар. Егер бөпе кенеттен жылай бастаса, басын бұрса немесе көзін жұмса, бұл оның «Болды! Миым шаршады!» деп жеткізу тәсілі. Мұндайда барлық ойыншықты жинап, шуды тоқтатыңыз да, оны жай ғана құшағыңызға алыңыз. Кейде ең жақсы ойыншық – тыныштық пен ананың құшағы.') WHERE id = 'b4ee2099-bc1d-4919-b3ee-ba22dc951100';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Айнаға қарағанда жүктіліктен қалған созылу белгілерін (стрияларды) көріп, әлі де көңіліңіз түсе ме? Бұл іздер Сіздің ана атанғаныңыздың белгісі екенін ұмытпаңыз. Уақыт өте олардың түсі алтын түстен күміс түске ауысып, біртіндеп ағарады. Оларды толық кетіру қиын болғанымен, теріні ылғалдандыру және уқалау сыртқы көрінісін жақсарта алады. Бірақ ең бастысы – бұл дене жаңа адамды дүниеге әкеліп, өсірді. Өзіңізге тым қатал болмаңыз, Сіз қазіргі қалпыңызбен де өте сұлусыз.') WHERE id = 'c1675203-e86f-4f0e-b277-4834368fee01';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпені шалқасынан жатқызғанда, аяқтарын жоғары көтеріп ұстауға, тіпті аузына апаруға тырыса ма? Бұл жай ғана көңілді ойын емес, оның іш бұлшықеттерін (пресс) нығайтып, өз денесін танып-білуіне көмектесетін маңызды жаттығу. Оған кедергі жасамаңыз, шұлығын шешіп, аяқ саусақтарымен ойнауына мүмкіндік беріңіз. Бұл қимыл омыртқасының төменгі бөлігін созып, босаңсытады әрі іштің кебуінен болатын түйілуді азайтуға көмектесуі мүмкін.') WHERE id = '5348f17b-ff81-4e2c-b426-336c5630b994';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '4 айлық бөпелердің сергек жүру уақыты (wake window) әдетте 1.5 - 2 сағат аралығында болады. Егер бөпе осы уақыттан ұзақ сергек жүрсе, «шамадан тыс шаршау» (overtiredness) күйіне түсіп, ұйықтауы одан сайын қиындайды. Уақытқа қараңыз: егер соңғы ұйқысынан бері 1.5 сағат өтіп, көзін уқалай бастаса, бірден тыныштандыру рәсіміне кірісіңіз. Ұйықтайтын уақытын өткізіп алу түнде ояну санын арттыруы мүмкін.') WHERE id = '314c334b-e7f8-4072-b418-2d43d8366274';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кейде бөпеңіз емшек еміп немесе қоспа ішіп жатқанда кенеттен жылап, тамақтанудан бас тартып, арқасын садақша иіп жібере ме? Бұл «жасырын рефлюкстің» белгісі болуы мүмкін. Асқазан қышқылы өңешке көтеріліп, оны тітіркендіреді. Егер бұл жағдай жиі қайталанып, салмақ қосуына кедергі келтірсе, дәрігеріңізбен кеңесіңіз. Үйде тамақтандырғаннан кейін оны бірден жатқызбай, ас асқазанға жақсы орнығуы үшін 15-20 минут тік күйде (иығыңызға сүйеп) ұстаңыз.') WHERE id = '1f5459ab-1bd2-4191-b9fa-6cb6903bc60f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Менің балам неге әлі күлмейді/аунамайды?» деп алаңдамаңыз. Даму кестесі жарыс емес. Кейбір балалар «бақылаушы» болады – айналасын үнсіз бақылап жүріп, кейін кенеттен бәрін бірден жасай бастайды; ал кейбірі «қимылшыл» болады – үнемі қозғалып, талпынып жүреді. Екеуі де қалыпты. Бөпені басқа балалармен (тіпті бауырларымен де) салыстыру Сізге тек күйзеліс, ал оған қысым әкеледі. Оның қайталанбас мінезін сол қалпында қабылдап, жақсы көріңіз.') WHERE id = '6c7ebcbb-cb8d-440f-985f-f7721a4549c7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '4-айға қош келдіңіз! Енді "Төртінші триместр" толығымен артта қалды. Бөпеңіз енді тек тамақ ішіп, ұйықтайтын "түйіншек" емес, айналасын танып-біле бастаған кішкентай адам. Осы айдан бастап оның ұйқы циклдері ересектердікіне ұқсай бастайды (жеңіл және терең ұйқы кезеңдері қалыптасады). Бұл өзгеріс кейде ұйқының бұзылуына әкелуі мүмкін, бірақ қорықпаңыз; бұл кері кету емес, керісінше даму белгісі. Оның миы өсіп келеді, тек жаңа жүйеге бейімделуге тырысуда.') WHERE id = 'eb18b9d2-6fac-4a33-989e-ff8e3c156809';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді қолыңызға алғанда, оның денесін тік ұстап, басын еркін басқара алатынын байқадыңыз ба? Бұл омыртқасының нығайып келе жатқанын көрсетеді. Енді оны тасуға арналған эргономикалық рюкзактағы "жүзі әлемге қараған" (face out) қалыптарды байқап көруге болады (әрине, аяқтары "M" пішінінде болуы керек). Ол айналасын тамашалағанды ұнатады, бірақ абай болыңыз: тым көп көрнекі ақпарат оны тез шаршатуы мүмкін. Егер мазасызданса, бірден жүзін өзіңізге қаратып, тыныштандырыңыз.') WHERE id = '0ffeb288-283a-4150-a4f7-cffdb0482b4c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Менің бөпем әлі аунамайды, дамуы кешігіп жатқан жоқ па?" – деген сұрақ мазаңызды алса, терең тыныс алыңыз. Бөпелер әдетте 4-6 ай аралығында аунай бастайды. Кейбір бөпелер алдымен етпетінен шалқасына, ал басқалары керісінше аунайды. Егер бөпеңіз бір қырына бұрылуға талпынып жүрсе, бұл – керемет бастама. Оған көмектесу үшін сүйікті ойыншығын қолы жетпейтіндей қашықтықта, бір бүйіріне қойыңыз. Ойыншыққа жету үшін ол денесін бұруға тырысады. Бұл – ең жақсы жаттығу.') WHERE id = '7165cb2d-519b-4d93-9e14-3abc5973a1c2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Шашыңыз әлі де түсіп жүр ме? 4-ай әдетте "Босанғаннан кейінгі шаш түсуінің" шарықтау кезеңі болады. Жуынатын бөлмедегі бір уыс шашты көріп, жылағыңыз келуі мүмкін, бірақ уайымдамаңыз, таз болып қалмайсыз. Бұл – жүктілік кезінде уақытша "тоқтап қалған" шаш түсу үдерісінің енді басталуы. Қымбат дәрумендер немесе сусабындар бұл үдерісті тоқтата алмайды, оған тек уақыт қажет. Шашыңызды тым қатты буып-жинамауға және ыстық ауамен (фенмен) жиі кептірмеуге тырысыңыз. Жаңа қысқа шаштар ("baby hair") шамамен 6-айдан кейін өсе бастайды.') WHERE id = 'd0ba1bd8-2d07-4566-8111-997ecbf838c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бұл кезеңде бөпеңіздің жымиғаны енді сыңғырлаған күлкіге айналады! Оны күлдіру үшін "оғаш" дыбыстар шығарыңыз, ерніңізді бүлкілдетіңіз немесе ішін сүйіп, үрлеңіз. Күлу диафрагманы (тыныс алу бұлшықетін) нығайтып, ағзаға оттегінің мол түсуіне көмектеседі. Егер ол күлудің орнына қорқып жыласа (қатты дыбыстан), демек, жүйке жүйесі әлі өте сезімтал. Тыныш ойындарға ауысыңыз. Әр бөпенің әзілді қабылдауы әртүрлі.') WHERE id = '7f993160-1b52-4958-82c0-d5f0cf373852';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әжелер жиі кеңес беретін "Ходунокты" (жүріс арбасын) сатып алуды ойлап жүрсіз бе? Асықпаңыз! Қазіргі ортопедтер мен педиатрлар ходунокты пайдалануға үзілді-кесілді кеңес бермейді. Бұл құрал бөпенің аяқ ұшымен жүруіне, омыртқасына ерте күш түсуіне және өздігінен әрекет етуге құлықсыз болуына (тепе-теңдік сақтауды үйренбеуіне) әкелуі мүмкін. Даму үшін ең жақсы орын – еден (кілем, төсеніш). Бөпеңіз өзі еңбектеуге, қимылдауға талпынсын, өйткені бұл табиғи үдеріс бұлшықеттерді дұрыс қалыптастырады.') WHERE id = '58105ea4-3801-47f9-97cc-2478fe93cb03';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің өз атын танып үйренуі үшін жаттығуларды бастауға болады. Оған «жаным», «сұлуым» деумен қатар, өз атын жиі атап сөйлесіңіз. Бөлменің екінші бұрышынан атын шақырып, Сізге қарай бұрыла ма, соны бақылаңыз. Егер бұрылып қараса, қатты қуанып, мақтаңыз («Жарайсың!»). Бұл — оның әлеуметтік болмысы қалыптасуының алғашқы қадамы. Ол енді бұл әлемде өзінің жеке тұлға екенін түсіне бастайды.') WHERE id = 'e2e55b95-3a42-4c60-9aac-15653d87bc0a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бұл кезеңде аналардың ең үлкен жауы — «бәрін білетін туыстардың» «бала арық, тоймай жүр, оған ботқа бер» деген қысымы. Есіңізде болсын: Бөпенің томпақ болуы оның дені сау екенін білдірмейді. Негізгі көрсеткіштер — бойының өсуі, бас шеңбері және белсенділігі. 4-ші айда қосымша тағам бере бастау (медициналық көрсетілім болмаса) оның ішегіне салмақ түсіреді, аллергия қаупін арттырады және ана сүтін емуін азайтады. «Иә» деп қоя салыңыз, бірақ өзіңіз дұрыс деп білетінді (ДДСҰ ұсынымын) ұстаныңыз.') WHERE id = '79a1bd17-ef80-4f02-a1a6-cec0947ec9fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз етпетінен жатқанда (tummy time) қолдарын жерге тіреп, кеудесін толық көтере алса, алдына қызықты ойыншықты қолы жетпейтіндей қашықтыққа қойыңыз. Ол ойыншыққа жету үшін салмақ орталығын ауыстыруға, тіпті бір қолын жерден көтеруге тырысуы мүмкін. Бұл «тепе-теңдік жаттығуы» болашақта еңбектеуі үшін өте маңызды. Егер қолынан келмей, ашулана бастаса, ынтасы жоғалмауы үшін ойыншықты сәл жақындатыңыз.') WHERE id = '9069addc-9d36-4d58-8ceb-48b115881ebe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз шығаратын дыбыстар «а-у» дауыстыларынан «м-б-п» дауыссыздарына ауыса бастады ма? «Ма-ма», «Ба-ба» сияқты дыбыстарды кездейсоқ айтуы мүмкін. Бұл оның Сізді саналы түрде шақырып жатқанын білдірмейді (әзірге), ол жай ғана ерін бұлшықеттерін жаттықтырып жүр. Бірақ Сіз бұған ерекше қуанышпен жауап беріңіз: «Иә, мен Анаңмын!». Сіздің реакцияңыз оны осы дыбыстарды қайталауға және сөйлеу қабілетін дамытуға ынталандырады.') WHERE id = '124a08e0-8297-466a-ad92-5da9e2b40124';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Төртінші айда бөпеңіздің ұйқы тәртібін қалыптастыру үшін «Ұйқы ассоциацияларын» (Sleep Associations) жасай аласыз. Егер ол тек емшек еміп немесе тербеткенде ғана ұйықтауға үйренсе, мұны біртіндеп өзгерте бастаңыз. Мысалы, ұйқысы келе бастағанда (әлі толық ұйықтамай тұрып) төсегіне жатқызып, үстіне қолыңызды қойып, жай ғана «ш-ш-ш» деңіз. Алғашқы күндері ол қарсылық білдіреді, бірақ сабыр сақтасаңыз, біртіндеп өздігінен тынышталуды (self-soothing) үйрене бастайды. Бұл — ұзақ жол, асықпаңыз.') WHERE id = '440c73d7-8d87-4380-afc8-4a3037eff65e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бөпеңіз 4 айға толды! Бұл — «нәрестелік» кезеңнің алтын ортасы. Ол енді тым кішкентай әрі дәрменсіз де емес, тым қимылшыл әрі шаршататындай да емес. Осы айда дәрігердің тексеруі кезінде оның салмағы туғандағы салмағынан шамамен 2 есе артқанын байқауыңыз мүмкін (бұл орташа көрсеткіш). Ол енді түстерді көреді, дыбыстарды таниды және Сізді қатты жақсы көреді. Бұл кезеңнің әр сәтінен ләззат алыңыз, өйткені жақында тіс шығару мен еңбектеу қызықтары басталады! Сіз керемет еңбек етіп жүрсіз, Ана!') WHERE id = 'c7fd582a-aa6d-4d77-b362-3fa53514647a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Бөпе отыра ала ма?» деген сұрақтар басталса, асықпаңыз. Бөпені жастықтардың арасына отырғызып, өздігінен отыруға мәжбүрлеу (егер өзі әлі дайын болмаса) омыртқасына зиян келтіруі мүмкін. 5-айда бөпелер «тірекпен отыруға» (қолдарын алдына тіреп отыруға) талпынуы мүмкін, бірақ әлі тепе-теңдігін толық сақтай алмайды. Ең жақсы жаттығу – еденде етпетінен жатып ойнау. Арқа бұлшықеттері нығайған сайын, өзі көтеріліп отыратын болады.') WHERE id = 'e21494e3-d1b4-470c-8b69-91bdff0641cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әжелердің «дәмін білсін, аздап сорпаның суын бер» деген кеңесі қайтадан айтыла бастады ма? Бөпенің ішегі әлі де «сүзгі» сияқты екенін білуіңіз керек (ішек өткізгіштігі жоғары). Ана сүтінен немесе сүт қоспасынан басқа берілген кез келген тағам (тіпті су немесе шырын) осы тосқауылдан өтіп, аллергия мен ас қорыту мәселелеріне әкелуі мүмкін. «Дәмін білуге» әлі талай уақыты болады, ал қазір басты мақсат – оның ішек микрофлорасын қорғау. Сіз «жаман келін» емессіз, Сіз «білімді анасыз».') WHERE id = '2049b273-04ed-4768-bc4b-392861691428';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің түнде ұйықтап жатып өздігінен етпетінен аунап кетуі Сізді қорқыта ма? Егер ол күндіз екі бағытқа да (шалқасынан етпетіне және етпетінен шалқасына) еркін аунай алса, түнде оны әр жолы қайта жатқызудың қажеті жоқ. Тек төсегінде жастық, көрпе және жұмсақ ойыншықтар жоқ екеніне көз жеткізіңіз (тұншығу қаупі болмауы үшін). Ол өзіне ыңғайлы қалыпты өзі таңдайды. Сіз де тыныш ұйықтаңыз.') WHERE id = '75eb58f4-2826-4a4a-8b58-b49e3d0b9d70';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы айда бөпенің шашы түсіп, орнына жаңасы өсе бастауы мүмкін («нәрестелік шашының» ауысуы). Кейде желкесінде «тақыр дақ» пайда болады – бұл жай ғана үйкелістен (көп жатқандықтан) туындайды және мүлде қалыпты жағдай. Ол отыра және көбірек қозғала бастағанда, шашы біркелкі өседі. Бұл дәрумен жетіспеушілігі емес, алаңдамаңыз.') WHERE id = 'f63f93ff-407c-4880-934c-4db268020afd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді ұсақ заттарды (мысалы, едендегі тозаңды немесе киіміндегі жіпті) байқап, саусақтарымен ұстауға тырысады. Көру қабілеті соншалықты жақсарғандықтан, ұсақ-түйекті ажырата алады. Бұл кезеңде қауіпсіздік – 1-нөмірлі қағида. Түймелерді, тиындарды, сырғаларды – бәрін оның қолы жетпейтін жерде сақтаңыз. Ол әлі де әлемді аузы арқылы танып-біледі және тапқан затының бәрін аузына салады.') WHERE id = '50867048-47ec-4339-857c-cdebcdc6c314';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Ходунок» (жүргіш) сатып алғыңыз келе ме? Тағы бір ойланыңыз. Көптеген дамыған елдерде (мысалы, Канадада) бұл құрылғыны сатуға тыйым салынған. Себебі: ол бөпенің аяқ ұшымен жүруіне (өкшесін жерге тигізбеуіне), омыртқасына ерте салмақ түсуіне және ең бастысы, қауіпті жерлерге (ыстық шәйнекке, баспалдаққа) тез жетуіне себеп болады. Дамуға арналған ең жақсы орта – еден. Еңбектеп, бұлшықеттерін нығайта берсін.') WHERE id = '700936b7-4cd2-492b-9509-98a14c16e71e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің аяқтарын зерттеуі жалғасып жатыр. Ол аяқ башпайларын аузына салып сорса, кедергі жасамаңыз. Бұл қимыл оның омыртқасының икемділігін арттырады, жамбас буындарын ашады және дене тепе-теңдігін табуға көмектеседі. Сонымен қатар осылайша ол өз денесінің шекараларын танып-біледі ("Аһа, мына башпай да менікі"). Шұлығын шешіп, аяқтарының "дәмін татып көрсін".') WHERE id = '0696d902-62ea-41fb-ac33-42f63be246d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің салмағы едәуір артты (шамамен 6-8 кг болуы мүмкін), сондықтан оны үнемі қолыңызға алып жүру омыртқаңызға айтарлықтай салмақ түсіреді. "Эргономикалық тасымалдау" ережелеріне назар аударыңыз: бөпеңізді жамбасынан демеп, салмағын біркелкі бөліңіз, бір жаққа салып (тек оң немесе сол жамбаста) көтеріп жүруден аулақ болыңыз, өйткені бұл сколиозға әкелуі мүмкін. Мүмкіндігінше еденде ойнауға басымдық беріңіз. Бөпеңізге күтім жасай алуыңыз үшін беліңіздің саулығы өте маңызды.') WHERE id = 'd400ec9f-412b-4ad6-988e-58b62c0416fd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз ойыншығын жерге тастайды, Сіз көтересіз, ал ол қайтадан тастап, күле ме? Бұл Сізді жалықтыруы мүмкін, бірақ ол үшін бұл — физикалық тәжірибе! Ол "Себеп-Салдар" байланысын үйреніп жатыр: "Мен мұны тастаймын (себеп), анам көтереді (салдар) немесе дыбыс шығады". Бұл ойын оған айналасындағы әлемге әсер ете алатынын сезіндіреді. Ашуланбаңыз, мұның дамуы үшін маңызды екенін есіңізге алып, ойынды сабырмен жалғастырыңыз (немесе жіппен байланған ойыншықтарды қолданыңыз).') WHERE id = 'fe5f82f2-00a9-4854-b3e5-0b8ebb578153';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің күндізгі ұйқысы біртіндеп реттеле бастайды ("Nap transition"). Бұрынғы ретсіз әрі қысқа ұйқылардың орнына күніне 3 рет (таңертең, түсте, кешкісін) ұзағырақ ұйықтауы мүмкін. Соңғы ұйқысы (кешкі мызғып алу) әдетте қысқа болады (30-40 мин) және түнгі ұйқыға ауысуды жеңілдетеді. Егер ол әлі де ретсіз ұйықтаса, "ұйқы терезесін" (ояу жүретін уақытын) бақылап, қатты шаршап кетпей тұрып ұйықтатуға тырысыңыз. Ұйқы ұйқыны шақырады.') WHERE id = '5d110284-d82d-4dbe-8144-2a516161ad7f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз аяқтарын аузына салып, "дәмін татып жатқандай" ма? Бұл көрініс өте күлкілі болуы мүмкін, бірақ шын мәнінде, бұл — оның омыртқасының икемділігі мен дене қимылдарының үйлесімді дамуын көрсететін тамаша жетістік. Ол денесінің төменгі бөлігін зерттеп жатыр. Оған кедергі жасамаңыз (ыңғайлы болуы үшін шұлығын шешіңіз). Бұл қимыл іштің кебуі мен газдан болатын түйілуді табиғи жолмен жеңілдетуге де көмектеседі.') WHERE id = '66fe21ca-05fd-4c48-95fa-5f031cadebb2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '5-айда бөпелер айқайлағанды, шыңғырғанды және даусын қатты шығарғанды ұнатады. Кейде бұл шу құлақ тұндыруы мүмкін, бірақ қорықпаңыз, ол Сізге ашуланып жатқан жоқ. Ол жай ғана дауыс желбезегін "сынап жүр": "Қаншалықты қатты айқайлай аламын екен?". Осылайша ол өз даусын басқаруды үйренеді. Оған сыбырлап жауап беріңіз; ол да Сізге еліктеп, даусын бәсеңдетуге тырысады. Бұл — тамаша ойын.') WHERE id = 'd03675dd-580b-4a83-a42a-a1376cb7a774';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қош келдің, 5-ай! Үйдегі кішкентай ғана "түйіншектің" орнын енді бәріне қызығатын, күлетін, айқайлайтын және қимылдайтын нағыз тұлға басты. Бұл айда оның дене дамуы одан әрі қарқын алады: аунау, заттарды бір қолынан екіншісіне ауыстыру және, мүмкін, еңбектеуге алғашқы талпыныстар... Сіз тек қауіпсіз орта жасаңыз (еденге кілем төсеңіз) да, сырттай бақылаңыз. Кейде араласпау — ең жақсы көмек.') WHERE id = 'ab2e9390-020b-4160-8af0-d640595e2268';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз ернін сүйірлеп, сілекейлі көпіршіктер шығарып "пырылдата" ма? Ол мұны тек үстін сулау немесе Сізді күлдіру үшін жасап жүрген жоқ! Бұл қимыл сөйлеу қабілетінің дамуы үшін аса маңызды тіл, ерін және жақ бұлшықеттерін жаттықтырады. Сонымен қатар ол дыбыстың қалай пайда болатынын зерттейді: "Ернімді осылай қозғасам, мынадай дыбыс шығады". Оған "Ұят болады" демеңіз, керісінше, өзіңіз де қосылып пырылдатыңыз. Бұл "диалог" ол үшін әлемдегі ең қызықты ойын.') WHERE id = 'ea92481c-f89e-4020-bcda-f62d11c6d1f3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің қолдары бұрынғыдан ептірек. Ол ойыншықты бір қолымен ұстап, кейін екінші қолына ауыстыра ала ма? Бұл "ортаңғы сызықты кесіп өту" (crossing the midline) дағдысы ми сыңарлары арасындағы байланыстың нығайып келе жатқанын көрсетеді. Осы дағдысын дамыту үшін оған екі түрлі ойыншық беріңіз: біреуін оң қолына, екіншісін сол қолына. Содан кейін үшінші ойыншықты ұсыныңыз. Қолындағы ойыншықтардың бірін тастап, үшіншісін ала ма, бақылаңыз. Бұл — оның алғашқы "шешім қабылдау" сәті.') WHERE id = 'c16f8e30-0e77-4445-93ae-cd9830a7f241';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '5-айда бөпелер түстерді, әсіресе қызыл, көк және сары түсті өте анық көреді. Сонымен қатар тереңдікті сезіну қабілеті (3D көру) қалыптасады. Ол енді ойыншықтың қаншалықты алыс тұрғанын шамалап, қолын тура соған соза алады. Осы кезеңде оны айна алдына отырғызу немесе түрлі түсті доптармен ойнату көз бен қол үйлесімін жетілдіреді. Егер әлі де қылилық (көздерінің анда-санда бір-біріне қарай ауытқуы) байқалса, осы айда ол азаюы керек; жалғаса берсе, дәрігерге көрсеткен дұрыс.') WHERE id = '1f034b11-0fbb-48ea-bbf4-278ca6b86b2b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді басқа біреу (тіпті әжесі немесе нағашы әпкесі) қолына алғанда, ернін бүріп жылай ма? Аналар бұған жиі қысылып, "балам жатырқайды" деп уайымдайды. Бірақ шын мәнінде бұл — оның зердесінің дамып келе жатқанының белгісі! Ол енді "жақын адамдар" (Сіз бен әкесі) және "бөтен адамдар" (басқалар) ұғымдарын ажырата алады. Бұл "бөтен адамнан қорқу" (stranger anxiety) — қалыпты даму кезеңі. Оны басқа біреудің қолына күштеп бермеңіз. Алдымен Сіздің құшағыңызда отырып, сол адамға үйреніп, өзін қауіпсіз сезінсін.') WHERE id = 'c6a4085b-3a97-4e0b-b5f5-5b36782649fe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Бала тоймай жүр, түнде ояна береді, ботқа берейік" деген ұсыныстар көбейді ме? Есіңізде болсын, түнде оянудың себебі көбіне аштық емес, ұйқы циклдерінің өзгеруі, тісінің қышуы немесе жай ғана Сізді қалау болуы мүмкін. 5 айлық бөпенің ас қорыту жүйесі әлі толық қалыптаспаған (ферменттер жеткіліксіз). Қосымша тағамды ерте бастау аллергия қаупін арттырып, ана сүтінің азаюына әкелуі мүмкін. ДДСҰ ұсынысы өзгеріссіз: алғашқы 6 айда тек сүт. Асықпаңыз, қасық ұстауға әлі бүкіл ғұмыры алда.') WHERE id = 'c26a80c4-409b-4945-b7d2-51c416190946';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Айнаға қарағанда өзіңізді күтімсіз, шаршаңқы сезінесіз бе? Декреттік демалыс кейде «Суыр күніне» (бір күннің қайта-қайта қайталануына) ұқсайды. Бүгін бөпеңізді әкесіне немесе әжесіне қалдырып, үйден 1 сағатқа шығып қайтыңыз. Дүкенге барып келу, саябақта жалғыз серуендеу немесе шаш қиюдың өзі Сізге «оттегі маскасындай» әсер етеді. Сіз бақытты болсаңыз, бөпеңіз де бақытты болады.') WHERE id = '3c6e4f71-0ba2-4930-a133-04552c20e1dd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 5-ші айдың ортасына келдіңіз! Бөпеңіздің салмақ қосуы алғашқы айлардағыдай жылдам болмауы мүмкін (айына 1 kq орнына 400-500 qr). Бұл қалыпты жағдай, өйткені ол көбірек қимылдап, энергия жұмсайды. Дәрігер бақылауындағы «қисық сызық» жоғары қарай бағытталып тұрса, алаңдауға негіз жоқ. «Сүтім азайып, бөпем салмақ жоғалтты» деп уайымдамаңыз, оның белсенділігіне сүйсініңіз.') WHERE id = '77295e93-c83b-4ff4-8d09-da9b139b8a65';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сіз тамақ ішкенде бөпеңіз аузын ашып, Сізді мұқият бақылай ма немесе тәрелкеңізге қол соза ма? Бұл — «тағамға биологиялық қызығушылық». Ол Сізге еліктегісі келеді, бірақ бұл міндетті түрде оның қарны аш екенін білдірмейді. Қосымша тағамды бастау үшін қызығушылықтың өзі жеткіліксіз; бөпе басын тік ұстай алуы, тіреусіз (немесе аздаған тіреумен) отыруы және ең бастысы, «тілмен итеру рефлексінің» (тағамды тілімен кері итеруінің) жойылуы қажет. Әзірше оған бос қасық беріп, ойнай тұруына мүмкіндік жасаңыз, ал тағам беруге сәл шыдамдылық танытыңыз.') WHERE id = '7853d6dc-3fa1-4c99-9bee-ffadc85c9246';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз етпетінен жатқанда қолдары мен аяқтарын ауаға көтеріп, «Супермен» сияқты ұша ма? Бұл қимыл өте сүйкімді көрінгенімен, шын мәнінде күрделі жаттығу. Ол арқа, мойын және бөксе бұлшықеттерін ширықтырып, болашақта еңбектеу мен отыруға қажетті күш жинайды. Бұл кезде оған кедергі жасамаңыз, тек алдына қызықты ойыншық қойып, ынталандырыңыз.') WHERE id = 'ee5e432a-11cb-49f0-b780-4af770910a6e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '5-ші айда бөпелер кейде әдеттен тыс дыбыстар шығарады: сырылдайды, жөтелгендей болады немесе қатты айқайлайды. Сіз қорқып, дәрігерге баруға дайындалып жатқанда, ол Сізге күлімсіреуі мүмкін. Бұл — оның дауыс байламдарымен ойнап жасайтын «тәжірибесі». Ол қай қимылдан қандай дыбыс шығатынын зерттеп жүр. Егер дене қызуы көтерілмесе және аурудың басқа белгілері болмаса, осы «концерттен» ләззат алыңыз.') WHERE id = 'b8f6e7f4-fa6c-4da7-b344-5fdbda538ecd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз ұйықтағанда басын үнемі бір жағына бұратынын немесе желкесінің жалпайғанын байқасаңыз, ояу кезіндегі ойындардың бағытын өзгертіңіз. Егер әдетте оң жағынан жақындасаңыз, енді сол жағынан сөйлесіңіз. Жарыққа немесе Сізге қарау үшін басын екінші жаққа бұруға тура келетіндей, бесіктің орнын өзгертіңіз. Бұл қарапайым өзгеріс мойын бұлшықеттерінің біркелкі дамуына көмектеседі.') WHERE id = 'b66d2212-4a92-4a46-b745-aeb8c99cd2a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жару қарсаңында бөпенің иммунитеті сәл әлсіреуі мүмкін, бірақ «тіс қызуын» «вирустық инфекциямен» шатастырмаңыз. Тіс жарғанда дене қызуы әдетте 38 градустан жоғары көтерілмейді және мұрыннан су ағу, жөтел сияқты белгілер болмайды. Егер дене қызуы жоғарылап, бөпе әлсіз болса, мұны тек тіске байланысты деп алаңсыз жүрмей, міндетті түрде дәрігеріне хабарлаңыз.') WHERE id = 'ec752558-6d74-4751-872c-b47b29cef0cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Осы кезеңде аналардың етеккір циклі қалпына келуі мүмкін (кейбірінде ертерек, кейбірінде кешірек). «Емізетін ананың етеккірі келмейді» деген пікір — миф. Етеккір басталғанда сүттің мөлшері сәл азаюы немесе дәмі өзгеруі мүмкін (гормондарға байланысты), сондықтан бөпе емуден бас тартуы ықтимал. Бірақ сүттің сапасы нашарламайды және ол «уланбайды». Емізуді жалғастырыңыз, бұл — уақытша жағдай.') WHERE id = 'ad62d3cf-28a5-411d-86f8-d16d19e156b2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз қолындағы ойыншығын жерге ұрып, үстелге соққылағанды ұната ма? Бұл бұзықтық емес, оның «дыбыс инженериясы»! Ол қатты заттың қатты бетке тигенде қандай дыбыс шығаратынын зерттеп жүр. Оған кедергі келтірмей, әртүрлі дыбыс шығаратын заттарды (ағаш қасық, пластик ыдыс, жұмсақ ойыншық) беріңіз. «Қарашы, мынау тарсылдайды, ал мынау дыбыс шығармайды» деп, айырмашылығын түсіндіріңіз.') WHERE id = '62ce75ea-f714-4996-ae9c-54a3b27495ac';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Үйдегі қауіпсіздік шараларын («Babyproofing») күшейтетін дәл уақыт келді. Бөпе әлі еңбектемесе де, аунап немесе бауырлап жүріп, электр розеткаларына, салбырап тұрған сымдарға немесе дастарқанның шетіне жетуі мүмкін. Оның деңгейіне түсіп (еденге жатып), үйге оның көзімен қараңыз: еденде не қауіпті көрінеді? Қауіп төндіретін барлық затты алып тастаңыз, өйткені жазатайым жағдай алдын ала ескертпейді.') WHERE id = 'aff088aa-a1cd-4138-acbc-e2c0688efeb6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің терісінде құрғақ дақтар немесе қызару (атопиялық дерматит/экзема) пайда болса, бірден жеген тағамдарыңызды (диетаңызды) кінәламаңыз. Көбіне себеп тағам емес, қоршаған орта болады: құрғақ ауа, синтетикалық киім, кір жуғыш ұнтақ немесе тым ыстық суға шомылдыру. Бөлменің ылғалдылығын арттырыңыз, бөпенің терісіне ылғалдандырғыш кремдерді (эмоленттерді) жеңіл уқалап жағыңыз және шомылдырғаннан кейін терісін ысқыламай, ақырын басып құрғатыңыз.') WHERE id = '572d9eb0-1241-494b-9f36-13d0ee848f80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бөпеңіз 5 айға толды! Жарты жасқа (6 ай) толуына да аз қалды. Бұл ай — ол үшін үлкен өтпелі кезең; енді ол сезімдерін анығырақ білдіреді, қуанғанда айқайлайды, қаламаған нәрсесін итереді. Сіз де осы 5 ай ішінде таңғажайып жолдан өттіңіз. Ұйқысыз түндер мен шаршауға қарамастан, Сіз оның әлемінің орталығысыз. Өзіңізге «рақмет» айтып, бұл күнді жылы жымиыспен атап өтіңіз!') WHERE id = '7802c1ee-5da4-41a5-a0b7-633ee14ee9a9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6-айдың алғашқы күніне қош келдіңіз! Енді үйдегі ең өзекті тақырып — "қосымша тамақ". Әжелер асықтыруы мүмкін, бірақ Сіз ДДСҰ-ның алтын қағидасын есте сақтаңыз: 6 ай толғанға дейін тек ана сүті (немесе сүт қоспасы). Дегенмен дайындықты бастай беруге болады! Бөпеңіздің бұған дайын екенін тексеріңіз: ол тіреусіз отыра ала ма? Басын тік ұстай ма? Сіз тамақ ішкенде, аузын жыбырлатып, қызығушылық таныта ма? Егер жауаптарыңыз "иә" болса, жаңа кезең жақындап қалды.') WHERE id = 'c07d39a8-4230-4141-b911-a428b18acb0f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз емізіп отырғанда Сізді тістей ме? Бұл қызыл иегінің қышып жүргенін немесе тойып алып, ойнағысы келетінін білдіруі мүмкін. Айқайлап, оны қорқытып алмаңыз, әйтпесе ол емшектен бас тартуы мүмкін. Сабырмен "жоқ" деп, емшекті аузынан шығарыңыз (шынашағыңызды аузының шетіне кіргізіп, вакуумды босатыңыз). Егер ол тістегенде емізу тоқтайтынын түсінсе, мұны қайталамайды. Салқындатылған тіс қаситын ойыншықтар бұл кезде Сіздің ең жақсы көмекшіңіз болады.') WHERE id = '1c9ac763-40c0-4c2c-9037-aa4d0926c708';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізді отырғызу үшін "жастықтан қамал" жасауға асықпаңыз. Егер ол өздігінен отыруға талпынбаса және арқасын бүгіп, "C" әрпі тәрізді отырса (бүкірейген қалып), бұлшықеттері әлі дайын емес деген сөз. Күштеп отырғызу омыртқасына зиян келтіруі мүмкін. Еденде көбірек уақыт өткізуіне мүмкіндік беріңіз, сонда ол өзі "Tripod" қалпына (қолдарын алдына тіреп отыруға) келеді. Табиғи даму әрқашан ең қауіпсіз жол.') WHERE id = '026af185-68d2-497b-b2e5-6cbcde3b4230';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жаруға арналған гельді (gel) қолданғанда өте абай болыңыз. Құрамында "Лидокаин" немесе "Бензокаин" бар гельдер бөпелер үшін елеулі қауіп төндіруі мүмкін (жұтынудың қиындауы және жүрек ырғағының бұзылу қаупі). FDA (АҚШ-тың Азық-түлік және дәрі-дәрмек басқармасы) бұл заттарды бөпелерге қолдануға кеңес бермейді. Оның орнына табиғи құрамды гельдерді немесе жай ғана салқындатылған резеңке ойыншықтарды қолдану, қызыл иегін дымқыл дәкемен уқалау қауіпсіз әрі тиімдірек.') WHERE id = 'd57483e9-dfea-4122-86d2-ac70acfdcbfd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз етпетінен жатқанда қолдарымен еденді итеріп, артқа қарай ("шаян сияқты") жылжи бастады ма? Бұл — еңбектеудің алғашқы кезеңі! Ол алға жылжығысы келеді, бірақ қолдары аяқтарынан күштірек болғандықтан, артқа қарай кетеді. Бұл оның ашуын келтіруі мүмкін. Көмектесу үшін алға қарай итеріле алатындай, табандарына қолыңызбен тірек жасаңыз. Сабыр сақтаңыз, көп ұзамай ол бүкіл үйді бағындырады.') WHERE id = '1cfdff71-da32-4931-b5cb-94e1a37d4db0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бұл айда бөпеңіздің ұйқысы қайта бұзылуы мүмкін, бірақ бұл жолы оған "ажырау мазасыздығы" (separation anxiety) себеп болуы ықтимал. Сіздің бөлмеден шыққаныңызды ол "мені тастап кетті" деп қабылдайды. Ұйықтатқанда жанында сәл ұзағырақ қалып, оны сипаңыз, бірақ бірден қолыңызға алып, тербетіп жүруге асықпаңыз (әйтпесе әдетке айналуы мүмкін). Онымен "Ку-ку" (жасырынбақ) ойынын ойнап, анасының кетсе де, қайта оралатынын үйретіңіз. Бұл қорқыныш уақытша, ал сенім сезімі әрдайым қалады.') WHERE id = 'bda07f09-37eb-4be3-a16a-4bf2694b38b8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Жер суық, баланы ауыртып аласың" дейтін үлкендердің сөзіне еріп, бөпеңізді диванға немесе бесікке қамап қоймаңыз. Таза кілем немесе арнайы ойын төсеніші (пазл-төсеніш) — бөпеңіз үшін ең жақсы спортзал. Суықтан қорықсаңыз, киімін соған сай таңдаңыз (шұлық немесе мақта шалбар кигізіңіз). Ол еденде неғұрлым көп аунап, еңбектеуге талпынып, қимылдаса, бұлшықеттері соғұрлым тез шынығады. Қимылсыздық — дамуды тежейтін ең үлкен жау.') WHERE id = '5ed49a9c-59aa-4f08-b836-cd7056d33992';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңізбен бірге кітап оқу үшін оның сөйлей бастағанын күтпеңіз. Дәл қазір қолмен ұстап сезінуге болатын (touch and feel) немесе сыбдырлайтын кітаптарды сатып алатын уақыт. Ол кітап беттерін аударуға тырысады (бұл ұсақ моторикаға арналған тамаша жаттығу), суреттерді қолымен ұрады, тіпті кітапты кеміруі де мүмкін. Бұл — "кітапқа деген сүйіспеншіліктің" бастауы. Оған жануарларды көрсетіп, дыбыстарын салыңыз ("Сиыр қалай мөңірейді? Мө-ө-ө!"). Бұл қарапайым ойын оның пассив сөздік қорын байытады.') WHERE id = 'a556f86c-ce31-4428-944f-44af737aa8ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз отыруға талпынғанда, қолдарын алдына тіреп (үшбұрыш/tripod қалпында) тепе-теңдігін сақтауға тырыса ма? Бұл — өте жақсы белгі! Бірақ оны әлі қараусыз қалдырмаңыз, өйткені ол кенеттен шалқасынан немесе бір жағына құлап кетуі мүмкін. Айналасына (арты мен екі жанына) жастықтар қойып, "қауіпсіздік шеңберін" жасаңыз. Алайда оны жастықтардың арасына қысып, қимылсыз қалдырмаңыз; тепе-теңдігін табу үшін денесін өзі басқаруды үйренсін.') WHERE id = '75dd1faa-e49b-4521-a298-8ff13485c3cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Неліктен қосымша тамақты дәл 6 айдан бастаймыз? Себеп тек асқазанда емес, қанда да жатыр. Бөпенің ана құрсағында жинаған темір қоры (ферритин) шамамен 6-шы айда азая бастайды, ал ана сүтіндегі темір оның өсіп келе жатқан қажеттілігін енді толық өтей алмайды. Сондықтан алғашқы тағам ретінде әдетте темірге бай өнімдер (ет, темірмен байытылған ботқалар) таңдалады. Бұл жай ғана "тою" мәселесі емес, физиологиялық қажеттілік.') WHERE id = 'd0ee725f-9b61-4b89-bc59-14a2829f8036';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтандыруға арналған орындықтағы (бөпе орындығы) "қауіпсіздік белдігін" елемеуге болмайды. "Менің балам әлі қозғалмайды, қайда барады дейсіз?" деп ойлау — ең үлкен қателік. Бөпелер бір секундтың ішінде төмен сырғып кетуі немесе орнынан тұруға талпынуы мүмкін. Сондай-ақ орындықта "аяқ тірегі" (footrest) болуы керек. Аяғы салбырап тұрған балаға жұтыну қиын болуы мүмкін (қақалу қаупі артады). Аяқтары тірекке тірелгенде, денесі тұрақтырақ болып, жұтыну қауіпсіз өтеді.') WHERE id = '625e4f6a-1f8a-44b3-838c-95a927b0b1a5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Анам кетіп қалды!" деген қорқыныш (Separation Anxiety) осы кезеңде күшеюі мүмкін. Бөлмеден шыққаныңызда жыласа, есіктің ар жағынан онымен сөйлесуді жалғастырыңыз: "Мен осындамын, сені естіп тұрмын, қазір келемін". Даусыңыз оны жұбатады. Сондай-ақ "Ку-ку" (Pee-ka-boo) ойынын жиі ойнаңыз. Бұл ойын оған адамдар көрінбей қалса да (бетін жапса да), міндетті түрде қайта оралатынын үйретеді. Бұл — психологиялық жаттығу.') WHERE id = '422035de-73c2-492a-bbec-313984910971';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Суды қашан бере бастау керек?» деген сұрақ өзекті бола түседі. Қосымша тағамды (қатты тағамды) бастаған күні су беруді де бастауыңыз керек. Әзірге (егер әлі қатты тағам бермесеңіз) су қажет емес, ана сүті/жасанды қоспа жеткілікті. Қазірден-ақ кішкентай, су төгілмейтін «су ішетін ыдыс» (сиппи-стақан/поильник) сатып алып, бөпеңізді онымен таныстыра аласыз (ішіне су құймай-ақ). Қолына ұстап, аузына апарып, ойыншық сияқты ойнасын. Осылайша уақыты келгенде ол ыдысты жатсынбайды.') WHERE id = 'ff09c584-fe70-41cf-951d-eb545f630c39';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің жөргегін ауыстыру күрес сайысына ұқсап кетті ме? Ол бір орында жатпайды, бұрылып, қашуға тырысады. Бұл оның еркін қимылдаудан ләззат алып жүргенін білдіреді. Ашуланбаңыз, тек айла қолданыңыз: жөргегін ауыстырғанда қолына қызықты, бұрын көрмеген бір затты (мысалы, таза крем құтысын) беріңіз немесе ән айтып, назарын басқаға аударыңыз. Кейде жөргегін тік тұрған немесе еңбектеп жүрген кезінде ауыстыруға тура келуі мүмкін – бұл нағыз аналық шеберлік!') WHERE id = '5c0bcce8-2d98-4e33-ab73-d613b0c76c24';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз «Ба-ба», «Да-да», «Ма-ма» деген буындарды қайталай ма? Әкелер әдетте «Әке деді!» деп қуанады, бірақ әзірге бұл саналы түрде айтылған сөз емес, жай ғана дыбыстарды жаттықтыру (былдырлау). Дегенмен Сіз оған мағына беріңіз: «Иә, бұл – Әке!», «Иә, мен – Анаңмын!». Сіздің осы сөздерді заттармен немесе адамдармен байланыстыруыңыз оның миындағы сөздік қорды қалыптастырады. Көп ұзамай ол бұл сөздерді мақсатты түрде қолдана бастайды.') WHERE id = 'ea83f521-c253-469b-809a-6bfb8bc161b2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6 айға (жарты жасқа) толуына небәрі 20 күн қалды! Қосымша тағам беруге арналған «тамақтандыру орындығын» таңдап қойдыңыз ба? Орындық таңдаудағы ең маңызды талап: бөпенің арқасы тік болуы және аяқтары міндетті түрде тіреуішке (аяқ қойғышқа) тірелуі керек. Аяғы салбырап тұрған бала мазасызданып, тамаққа назарын аудара алмайды. Оның қымбат бренд болуы міндетті емес, эргономикалық әрі оңай тазаланатын болса (өйткені қатты былғанады!), жеткілікті.') WHERE id = '5376c7fc-e6df-4f63-941d-2e00e5209d33';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тағамға дайындық үшін керек-жарақ сатып ала бастадыңыз ба? Ең алдымен, бөпеге арналған арнайы қасықты дұрыс таңдау маңызды. Металл қасықтар оның сезімтал таңдайын жарақаттауы және жылуды тез өткізіп, тілін күйдіруі мүмкін. Ең жақсы таңдау – ұшы жұмсақ силиконнан жасалған, көлемі шағын әрі сабы ұзын қасықтар. «Үлкен қасықпен берсем, тез тояды» деген ой қате; қасық неғұрлым кішкентай болса, оның жұту рефлексі соғұрлым оңай бейімделеді. Түрлі түсті қасықтар оның тағамға деген қызығушылығын арттырады.') WHERE id = '1d96ab29-9c6c-4bb8-ba1f-f5f3f11a1dbb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз түнде кенет жылап оянып, әрең тыныштала ма? 6-айға жақындағанда қызыл иектегі қысым түнде (жатқан кезде басқа қан көбірек баратындықтан) қаттырақ сезіледі. Оған ашуланбаңыз, оның жай ғана жаны ауырып жатыр. Ұйықтар алдында қызыл иегін таза саусағыңызбен немесе арнайы силикон щеткамен жеңіл уқалау қан айналымын жақсартып, жайсыздықты азайтады. Сабырлы болыңыз, кішкентай «інжулер» көрінгенде ұйқысыз түндердің бәрі ұмытылады.') WHERE id = '4bb38a42-9207-48cc-87a0-6e8506859c1d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тамақ бере бастағанда су беру де маңызды болады. Бөпеңізді қазірден бастап "Су ішетін стақанмен" (Sippy cup немесе кәдімгі шағын стақан) таныстырыңыз. Ішіне өте аз мөлшерде (бір жұтым) су құйыңыз немесе бос күйінде беріңіз. Ол стақанды ұстауды, аузына апаруды және оны "көлбеу" ұстауды (басын артқа шалқайтуды) үйренсін. Емізігі бар бөтелкеден өзгеше, стақаннан ішу ауыз бен тілдің мүлде басқа үйлесімді қимылын қажет етеді.') WHERE id = '276120aa-1546-4b32-a95c-f7c80f3724d7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сенесіз бе? Жарты жасқа (6 айға) небәрі 10 күн қалды! Бұл — дамудың үлкен кезеңі. Бөпеңіз енді "үлкен бала" болуға дайындалып жатыр деуге болады. Осы күндері оны суретке түсіріп, видеоларға жазып жүріңіз. Алғашқы айлардағы бүрісіп жататын тыныш бөпені қазіргі белсенді зерттеушімен салыстырыңыз. Сіз оған тек сүт қана емес, сенім, сүйіспеншілік пен батылдық та сыйладыңыз. Соңғы 10 күннің әр сәтінен ләззат алыңыз, өйткені алда "дақ болған алжапқыштар" мен "қасық шайқастары" кезеңі келе жатыр!') WHERE id = 'eeef4f12-67b6-4638-9c3f-cfa2a5c6b644';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6-шы айдың соңғы онкүндігіне қош келдіңіз! Қосымша тамаққа дайындық асүйде қызу жүріп жатыр. Алғашқы тағам ретінде көкөніс езбелері (мысалы, кәді, гүлді қырыққабат) немесе күріш/қарақұмық ботқалары әдетте ең қауіпсіз таңдау саналады. Маңызды қағида: Әр жаңа тағамды бір-бірден беріп, 3 күн күту ережесін ұстаныңыз. Бұл бөпеңіздің сол тағамға аллергиясы бар-жоғын анықтаудың бірден-бір жолы. Асықпаңыз, алғашқы күндері мақсат — тойдыру емес, тек жаңа дәмдермен таныстыру.') WHERE id = 'f895f071-f97f-4fb0-9772-e32eeffab324';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді тіреусіз отыруға бір қадам жақындады. Оны еденге отырғызғанда, қолдарын екі жағына тіреп, тепе-теңдігін сақтайтынын байқауыңыз мүмкін. Бұл кезеңде айналасына жұмсақ төсеніштер немесе жастықтар қойған маңызды, өйткені бір сәт көзден таса қалса, шалқасынан "қап сияқты" құлап кетуі мүмкін. Бірақ оны жастықтардың арасына "көміп" тастамаңыз, өз бұлшықеттерімен тепе-теңдік сақтауды үйренсін. Арқа мен іш бұлшықеттері неғұрлым көп жұмыс істесе, соғұрлым тез тік отырады.') WHERE id = '5a9ac2d0-eaf0-4588-afbc-9d21af03e70a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тамаққа көшу кезінде "қақалып қалу" қорқынышы — әр ананың үрейлі түсі. Бөпелерде "Gag reflex" (лоқсу рефлексі) тілдің алдыңғы бөлігіне жақынырақ орналасатынын білгеніңіз жөн; яғни бала лоқсыса, бұл оның қақалып қалғанын емес, тағамды кері итеріп жатқанын білдіреді. Шын мәнінде қақалып қалған кезде бала дыбыс шығара алмайды және өңі өзгереді. Ал лоқсу кезінде ол жай ғана жөтеліп, тағамды аузынан шығарады. Бұл рефлексті ажырата білу Сізді тыныштандырып, бөпеңіздің тамақтануды үйренуіне батылдық береді.') WHERE id = '70a66a9a-563a-4960-829c-3c543e77de0b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді заттарды бір қолынан екіншісіне емін-еркін ауыстырады. Бұл ми сыңарларының үйлесімді жұмыс істейтінін көрсетеді. Осы дағдыны дамытатын ойындар ойнаңыз: Оған бір ойыншық беріңіз, оны ұстағаннан кейін екінші қолына тағы бір ойыншық ұсыныңыз. Біріншісін тастай ма, әлде екінші қолына ауыстыра ма, бақылап көріңіз. Бұл қарапайым ойын оның ұсақ моторикасын да, мәселені шешу қабілетін де дамытады.') WHERE id = 'ae843217-76c1-4871-8e0d-ffc6c753bdec';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6-айда бөпелердің есте сақтау қабілеті айтарлықтай күшейеді. Ол енді күнделікті рәсімдерді таниды. Мысалы, алжапқышын (слюнявчик) таққанда тамақ ішетінін, ал сүлгіні көргенде шомылатынын түсінеді. Осындай тұрақтылық оған сенімділік береді. Сондықтан қалыптасқан рәсімдерді бұзбауға тырысыңыз. «Қазір не істейміз?» деп онымен сөйлесіп, әр әрекетіңізді түсіндіріңіз. Сіздің даусыңыз бен осы реттілік оның әлемін қауіпсіз әрі түсінікті етеді.') WHERE id = '024b161c-2539-4cac-976f-5bf08fd88827';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Алғашқы тістері әлі шықпаса, алаңдамаңыз; кейбір балаларда тіс шығу үдерісі 1 жасқа дейін созылуы мүмкін. Дегенмен қызыл иегі ісініп, ауыруы ықтимал. Бөпенің қызыл иегін таза, дымқыл әрі салқын дәкемен уқалау оны едәуір тыныштандырады. Сондай-ақ осы айларда сілекейдің көп бөлінуі теріні тітіркендірмеуі үшін ауыз айналасын құрғақ ұстаңыз және қорғаныш кремдерін қолданыңыз.') WHERE id = '5905275f-db82-478c-ba85-c28c03e494ac';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тамақ бере бастағанда бөпенің нәжісінің (жөргек ішіндегінің) түсі, иісі мен қоюлығы күрт өзгереді. Бұдан қорықпаңыз! Ішегі алғаш рет сүттен басқа тағамды қорытуға тырысып жатыр. Кейде көкөністер қорытылмай, сол күйінде шығуы мүмкін, бұл да қалыпты жағдай. Ең бастысы, бөпеде іштің қатты ауыруы немесе іш қату болмасын. Егер осындай жағдай байқалса, берген тағамыңызды бірнеше күнге тоқтатып, сүтке басымдық беріңіз.') WHERE id = '2175d91f-594f-42b1-b5ca-5375fe51dcff';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпенің «ұсақ моторикасын» бақылаңыз: ол енді заттарды алақанымен емес, саусақтарымен ұстауға тырысады (әлі толық «қысқыш» әдісімен ұстай алмаса да). Ұстауы үшін оған пішіндері әртүрлі қауіпсіз ойыншықтар беріңіз. Осы кезеңде резеңке, мата және ағаш материалдардың айырмашылығын сезіну оның сенсорлық дамуы үшін өте маңызды. Ұмытпаңыз, ол әлі де бәрін «аузына салып тексереді», сондықтан ойыншықтардың тазалығына және ұсақ бөлшектерінің болмауына назар аударыңыз.') WHERE id = 'ad5ab394-baf9-4d75-b342-9b228c2343bc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ертең бөпеңізге тура жарты жыл (6 ай) толады! Бүгін қосымша тамаққа қажет заттардың бәрін (буға пісіргішті, блендерді немесе жай ғана елеуішті, пластик ыдыстарды) соңғы рет тексеріңіз. Бірақ ең маңыздысы – психологиялық дайындық. Бөпе алғашқы қасықтағы тамақты түкіріп тастауы, үсті-басын былғауы немесе мүлде жегісі келмеуі мүмкін. Ашуланбаңыз және мәжбүрлемеңіз. Алғашқы айдағы мақсат – тойдыру емес, жаңа дәмдермен таныстыру. Сіздің сабырыңыз – бұл істің ең маңызды құрамдас бөлігі.') WHERE id = '99a11b8e-07bd-49f3-b3dd-d51a0720e2b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, ғажайып Ана! Бүгін бөпеңіз 6 айға толды! Сіз жолдың жартысын (алғашқы жылдың жартысын) сәтті еңсердіңіз. Бөпеңіздің салмағы туған кездегімен салыстырғанда шамамен екі есе артты және ол қоршаған әлемге толық бейімделді. Бүгін онымен бірге алғашқы ресми «тамақ мерекесін» атап өтіңіз. Бірнеше қасық езбеден басталатын бұл қызықты сапар – оның өсуіндегі жаңа кезең. Өзіңізді мақтан тұтыңыз: ұйқысыз түндеріңіз бен тынымсыз еңбегіңіздің жемісін бүгін оның Сізге қарап күлімдеген сүйкімді жүзінен көре аласыз!') WHERE id = '6314b77b-4ba8-4969-86b0-43b2ae2976dd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '7-ші айға қош келдіңіз! Қосымша тағам беру кезеңі ресми түрде басталды. Алғашқы күндері бөпеңіздің тағамды тілімен кері итеріп шығарғанын байқасаңыз, алаңдамаңыз; бұл — оның бірнеше ай бойы үйренген ему рефлексінен туындайтын табиғи реакция. Оған бар болғаны 1-2 шай қасық езбе ұсыныңыз және мәжбүрлемеңіз. Бұл кезеңдегі мақсатымыз — бөпені тойдыру емес, оны әртүрлі дәмдермен және тағам құрылымдарымен таныстыру. Ана сүті немесе сүт қоспасы әлі де оның негізгі қуат көзі болып қала береді.') WHERE id = '359c78b7-5eb4-4ddd-8230-6dac6d1fbced';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Алғашқы көкөністерді бергеннен кейін бөпеңіздің нәжісінің түсі мен иісінің өзгеруі — қалыпты жағдай. Егер жөргектен езбенің қорытылмаған күйінде шыққанын байқасаңыз, қорықпаңыз; бөпеңіздің ас қорыту жүйесі жаңа тағамдарға бейімделуге тырысып жатыр. Ең бастысы, теріде кенеттен қызару, бөртпе немесе іштің қатты кебуі бар-жоғына назар аударыңыз. Мұндай белгілер болмаса, бәрі дұрыс!') WHERE id = 'e2b1e9c6-06ca-442f-a823-59969208dc77';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тағам бере бастаған күннен бастап бөпеңізге су ұсыныңыз. Бөпеңіздің күнделікті суға қажеттілігі әзірге көп емес, бірақ тамақтан кейін бірнеше жұтым су ішу ауыз қуысын тазартып қана қоймай, болашаққа пайдалы әдет қалыптастырады. Суды емізігі бар бөтелкемен емес, кішкентай кесемен немесе арнайы су ішетін ыдыспен (sipper cup) беруге тырысыңыз. Бұл оның төменгі жақ бұлшықеттерінің басқаша дамуына көмектеседі.') WHERE id = '0368b56f-7108-4cef-9b22-96d46e080b4f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '3 күн күту қағидасын ұстанып жүрсіз бе? Ағзаның реакциясын бақылай алу үшін әрбір жаңа көкөністі немесе жемісті жеке-жеке беріңіз. Мысалы, бүгін асқабақ езбесін ұсынсаңыз, келесі 2 күн ішінде басқа ешбір жаңа тағам қоспаңыз. Бұл аллергия пайда болған жағдайда, оған "кінәлі" өнімді бірден анықтауға көмектеседі. Сабырлы болыңыз, бөпеңіздің дәм рецепторлары қазір зертхана секілді жұмыс істеп жатыр!') WHERE id = '6a73b0da-2d2c-48e8-a871-941a5e9014db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз тамақтану кезінде қасықты қолыңыздан алуға немесе қолын езбеге салуға тырыса ма? Оған кедергі жасамаңыз! Бөпелер тағамды дәмін татып қана емес, қолымен ұстап та танып-біледі. Айналаның аздап былғануы қалыпты жағдай; бұл "былғаныш" оның сенсорлық дамуы мен өз бетінше тамақтану дағдысы үшін маңызды. Тағамның құрылымын сезінуіне мүмкіндік беріңіз, бұл болашақта тағам талғау мәселесінің алдын алудың ең жақсы тәсілі.') WHERE id = '81644d16-8ba2-4b27-83e5-5d3f50deae69';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тағам беру кезеңінде іш қатуы мүмкін. Бөпеңіздің ішегі сүттен басқа тағамдарды қорытуға бейімделіп жатыр. Егер бөпеңіз қатты күшеніп, нәжісі тым қатты болса, езбеге аздап зәйтүн майын қосу немесе қара өрік езбесін беру пайдалы болуы мүмкін. Жеткілікті су беруді ұмытпаңыз. Мәселе ұзаққа созылса, міндетті түрде педиатрмен кеңесіңіз, алайда алғашқы күндері мұндай өзгерістердің болуы қалыпты жағдай.') WHERE id = '467b7c20-7f80-4ea7-b9c0-93bd0e277a7e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '6 айдан кейін бөпенің есте сақтау қабілеті мен зейіні айтарлықтай жақсарады. Ол енді заттардың атауларын сол заттармен байланыстыра бастайды. Мысалы, «доп қайда?» деп сұрасаңыз, оны көзімен іздейді. Онымен осындай сұрақ-жауап ойындарын ойнаңыз. Сіз ол үшін «дыбыстар кітапханасы» іспеттісіз. Неғұрлым көп сөз естісе, миындағы сөздік қоры соғұрлым тез толығады. Оны ересек адамдай мұқият тыңдап, әр дыбысына мағыналы жауап беріңіз.') WHERE id = '5b5665e4-15b0-42d4-8279-20912bd71937';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөбеңіз енді тіреусіз отыруға сенімдірек талпынып жүр ме? Жамбас пен арқа бұлшықеттерін нығайту үшін «еденде уақыт өткізу» — ең жақсы жаттығу. Оны етпетінен жатқызып, алдына сәл алысырақ жерге қызықты ойыншық қойыңыз. Ол ойыншыққа жету үшін денесін бұруға, тіпті еңбектеуге талпынуы мүмкін. Бұл қимылдар дене үйлесімділігінің дамуы үшін өте маңызды. Есіңізде болсын, әр құлау — үйренудің бір бөлігі, тек айналасының қауіпсіз екеніне көз жеткізіңіз.') WHERE id = '85f7b4d5-b074-40cb-b8e7-126bfcb368b7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнде қайта-қайта оянуы жиілесе, бұл тіс жаруымен немесе дене белсенділігінің артуымен байланысты болуы мүмкін. Бөпе күндіз үйренген қимылдарын (мысалы, аунау немесе еңбектеу) тіпті ұйқысында да «қайталайды». Егер жыламаса, оны бірден қолыңызға алуға асықпаңыз; өздігінен тынышталып, қайта ұйықтауға тырысып көрсін. Кейде оған қасында екеніңізді сездірудің өзі (қолыңызды арқасына қою) жеткілікті болуы мүмкін.') WHERE id = 'aa9eef25-9e2b-4d46-bc09-aebaa1272eaa';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Міне, ресми түрде 7-ші айға да аяқ бастық! Бөпенің салмағы туған кездегі салмағынан шамамен екі есе болуы тиіс (бұл орташа көрсеткіш). Егер тістері әлі көрінбесе, алаңдамаңыз: сүйектерінің дамуы қалыпты болса, тістері кез келген сәтте «сәлем» деуі мүмкін. Бүгін оған дайындаған көкөніс езбесіне өте аз мөлшерде (бірнеше тамшы) жоғары сапалы суық сығымдалған зәйтүн майын қосып көріңіз; бұл ас қорытуды жақсартып қана қоймай, пайдалы май қышқылдарымен миын да қоректендіреді.') WHERE id = 'd3b9ca7e-7233-4280-976e-e11828d20cca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Егер көкөністермен танысып үлгерсеңіздер, енді біртіндеп ақуыздар әлеміне көшуге болады. Етпен алғаш таныстыру үшін майсыз бұзау еті, күркетауық немесе қоян еті — ең жақсы таңдау. Етті әбден пісіріп, біркелкі езбе күйіне дейін ұнтақтап, көкөніс езбесіне қосыңыз. Ет — бөпенің тез азайып бара жатқан темір қорын толықтыруға қажетті ең маңызды тағамдардың бірі. Алғашқы күндері бір шай қасық ет езбесі жеткілікті.') WHERE id = 'd543dbe5-6df1-4d22-a7ce-cbb22da34fc3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөбеңіз ойыншықты бір қолынан екіншісіне ауыстырып, екі қолымен бір мезгілде әрекет жасай ала ма? Бұл — ми сыңарларының үйлесімді дамуының белгісі. Онымен «ұста-жібер» ойындарын ойнаңыз. Мысалы, бір қолына ойыншық беріңіз, содан кейін сол қолына екінші ойыншықты ұсыныңыз; біріншісін екінші қолына ауыстырып, жаңасын ала ма, байқап көріңіз. Бұл қарапайым жаттығу оның ұсақ моторикасын да, мәселені шешу дағдысын да жетілдіреді.') WHERE id = 'a8158232-7247-4508-af89-b5e8c2455782';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жұмыртқаның сарыуызымен танысатын уақыт келді! Жұмыртқаны әбден пісіріп, сарыуызынан небәрі бұршақтай бөлігін ана сүтіне немесе езбеге араластырып беріңіз. Жұмыртқаның сарыуызы мидың дамуына қажетті холин мен май қышқылдарына бай. Мұқият болыңыз: жұмыртқаның ағы (ақуыз) күшті аллерген болғандықтан, 1 жасқа дейін ұсынылмайды. Сарыуыз мөлшерін әр жолы аздап арттырып, бөпеңіздің реакциясын бақылаңыз.') WHERE id = '348776a6-90b7-44de-bed5-439f8ce3ea57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз еңбектеуге дайындалып, "старт" қалпына келе ме? Ол алақаны мен тізесіне сүйеніп, алға-артқа тербелуі мүмкін. Бұл "тербелу" арқылы ол тепе-теңдігін сақтап, бұлшықет күшін сынап жүр. Мұны көргенде оны мақтап, ынталандырыңыз. Еңбектей бастауы үшін еденнің тайғақ болмауын қадағалаңыз (кілем немесе төсеніш өте қолайлы). Көп ұзамай ол үйдің әр бұрышына жететін болады!') WHERE id = '075eebcf-bf5d-40ba-b7ae-a5f38e71818b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тамақ беру кезеңінде су ішу енді таңдау емес, қажеттілік. Бөпеңіздің бүйрегі жаңа тағамдарды қорытып, өңдеген кезде көбірек суды қажет етеді. Егер бөпеңіз су ішуден бас тартса, әртүрлі тұмсықты стақандармен (sipper cup) немесе кішкентай түрлі түсті стақандармен қызықтырып көріңіз. Суды тамақтан кейін бірден және күні бойы жиі ұсыныңыз. Есіңізде болсын, шырындар мен компоттар суды алмастырмайды; таза су — ең пайдалы таңдау.') WHERE id = '5ed536ec-a0b5-4447-9d9a-377e3e5da4a3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Ажырасу мазасыздығы" (Separation anxiety) осы күндері айқынырақ байқалуы мүмкін. Сіз бөлмеден шыға салысымен бөпеңіздің қатты жылауы оның "мінезі жаман" екенін білдірмейді, бұл — Сізді жоғалтып алудан қорқуы. Бөлмеден шыққанда оған міндетті түрде дауыстап айтыңыз: "Анаң асүйде, қазір келеді". Даусыңыздың алыстан естілуі оған сенімділік береді. "Ку-ку" ойынын күрделірек етіп ойнаңыз; тығылып, басқа жерден шыға келу оның осы қорқынышын жеңуіне көмектеседі.') WHERE id = '9d97a34c-0a55-4e17-9a40-0912d5c81137';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің терісінде, әсіресе аузының айналасында немесе денесінде кенеттен қызару байқасаңыз, соңғы 3 күнде берген жаңа тағамдарыңызды еске түсіріңіз. Қандай да бір аллергиялық реакцияға күмәндансаңыз, сол тағамды беруді дереу тоқтатып, 1-2 аптадан кейін қайтадан (аз мөлшерде) байқап көріңіз. Кейде ағза тағамның құрылымына ғана реакция білдіреді, ал кейде бұл нағыз аллергия болуы мүмкін. Күмән туындаған жағдайда педиатрмен кеңескен дұрыс.') WHERE id = 'c73b10f1-26e8-49f8-a842-9fc9eb05c61a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Үйдегі қауіпсіздік деңгейін тағы бір рет тексеріңіз. Бөпеңіз енді заттарға қол созып, тартып, дәмін татып көреді. Электр розеткаларына қорғаныш қақпақтарын орнатып, өткір бұрыштарды жұмсартыңыз. Ең бастысы: еденде немесе кілем үстінде ешқандай ұсақ зат (түйме, моншақ, батарея) қалмауы керек. Бөпеңіздің көру қабілеті соншалықты жақсы, тіпті Сіз байқамаған кішкентай жіпті де тауып алып, аузына салуы мүмкін.') WHERE id = 'cb68fae9-cc1f-40fd-8358-d8d8262537c7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқысы қайтадан бұзылуы мүмкін. Бұған көбіне «қимыл-қозғалыс дамуы» себеп болады. Бөпе күндіз үйренген қимылдарын (мысалы, тізерлеп тұруды) ұйықтап жатып та қайталағысы келеді. Егер түнде тізерлеп тұрып, тербеле бастаса, оны бірден қолыңызға алмаңыз. Ақырын жатқызып, арқасынан сипаңыз. Өздігінен тынышталуды үйренуі үшін оған мүмкіндік беріңіз.') WHERE id = 'e9e1b950-57d8-4d65-82e5-7c7681ec6159';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бөпеңіздің 200 күні толды! Бұл — үлкен белес. Енді Сіз «жаңа босанған ана» емес, тәжірибесі мол ата-анасыз. Бөпеңіз Сізге қарап күлімсіреп, құшақтауға талпынғанда, бар еңбегіңіздің ақталғанын сезесіз. Бүгін оған арнап ерекше «дәмдер фестивалін» ұйымдастырыңыз: сүйікті көкөністері мен еттен дәмді езбе дайындаңыз. Сіз кереметсіз, Ана!') WHERE id = '8ef38899-1def-4d57-bd7d-f28245d50ca5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '200 күндік үлкен белесті артта қалдырдық, енді мәзірді аздап түрлендірейік! Егер бөпеңіз көкөніс пен ет езбелеріне үйреніп қалса, ас үлесіне жемістерді қосудың дәл уақыты келді. Алдымен алма, алмұрт немесе бананнан бастаңыз. Жемістерді буға пісіріп, езбе жасау (немесе шыны үккіштен өткізу) ас қорытуды жеңілдетеді. Абай болыңыз: жемістердің тәтті дәмі бөпеге қатты ұнауы мүмкін. Сондықтан көкөністерден бас тартпауы үшін жемісті көбіне күннің екінші жартысында десерт ретінде ұсынған дұрыс.') WHERE id = '52048f39-dc3c-4433-994b-496425ac059d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің отыру дағдысы енді «үштаған» қалпынан (қолдарын жерге тіреп отырудан) өтіп, денесін тік ұстап, еркін отыруға ұласуы тиіс. Ол енді қолдарын жерден көтеріп, ойыншықпен ойнай алады. Егер әлі де бір жағына жиі құлай берсе, алаңдамаңыз. Арқа бұлшықеттерін нығайту үшін еденде көбірек уақыт өткізуіне жағдай жасаңыз. Артына жұмсақ жастықтар қойыңыз, бірақ тепе-теңдікті өзі табуына мүмкіндік беріңіз. Өздігінен отыру бөпеңізге әлемді мүлде басқа қырынан көруге жол ашады.') WHERE id = '9d5fc99c-ca1a-4324-a7ea-7d36c4768a6e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сүт өнімдерімен танысатын уақыт келді! Егер дәрігер қарсы көрсетілім бар екенін айтпаса, үйде дайындалған табиғи йогурт немесе сүзбе ұсына аласыз. Йогурт кальцийге бай әрі ішек микрофлорасына пайдалы пробиотиктерге толы. Алғаш бергенде бір шай қасықтан бастап, терісіндегі өзгерістерді бақылаңыз. Ұмытпаңыз: дүкендерде сатылатын жеміс пен қант қосылған «балалар йогурттарынан» аулақ болыңыз. Ең пайдалысы — үйде өзіңіз дайындаған қоспасыз табиғи йогурт.') WHERE id = '8027ff1e-e9f7-4f2e-9aa6-3293659f2fb7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз заттарды бір-біріне соғып, дыбыс шығарғанды ұната ма? Осылайша ол «себеп-салдар» байланысын тереңірек түсініп жүр: «Егер мына екі ойыншықты бір-біріне соқсам (себеп), дыбыс шығады (салдар)». Дыбыстар мен жанасу сезімдерінің айырмашылығын түсінуі үшін оған әртүрлі материалдардан (ағаш, пластик, мата) жасалған ойыншықтар беріңіз. Бұл қарапайым ойын оның есту қабілетін де, қимыл-қозғалысын да дамытады. Асүйдегі пластик ыдыстар мен ағаш қасықтар кейде ең қымбат ойыншықтан да қызығырақ болуы мүмкін!') WHERE id = '580f2e78-b4ac-4e71-a08f-98de51b2b255';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Ма-ма", "Ба-ба", "Да-да" сияқты буындарды қайталауы енді ырғақты әрі ұзақ бола бастайды (қайталама былдыр). Бөпеңіз енді Сіздің дауыс ырғағыңызға еліктеуге тырысады. Сіз онымен сөйлескенде, ол да Сізге "жауап" береді. Осындай диалогтерді ұзартыңыз! Ол дыбыс шығарғанда мұқият тыңдап, содан кейін: "Иә, рас па? Содан кейін не болды?" – деп жауап беріңіз. Бұл оның қарым-қатынас жасауға деген ынтасын арттырып, сөйлеу орталығын белсендіреді. Сіз – оның ең жақсы тілдесу серігісіз.') WHERE id = 'cfd5a392-f80a-4d2d-a1a6-3083e4ec4e6d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қосымша тағам мәзіріне дәнді дақылдарды (ботқаларды) белсендірек енгізіңіз. Егер әлі бастамаған болсаңыз, күріш, қарақұмық және жүгері ұнынан жасалған ботқалардан бастаған дұрыс, өйткені олардың құрамында глютен жоқ. Ботқаны тым қою етпеңіз, бастапқыда оны ана сүтімен немесе жасанды қоспамен сұйылтып беріңіз. Дәнді дақылдар бөпеге ұзақ уақытқа жететін қуат береді және түнгі ұйқысының үзіліссіз болуына көмектесуі мүмкін (әрине, егер оянуының себебі аштық болса).') WHERE id = 'a9b193a4-5558-4e20-a84e-1718f45d9ce1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз заттарды алақанымен емес, саусақтарымен ұстай бастады ма ("қысқыш тәрізді ұстауға" дайындық)? Бұл – оның ұсақ моторикасының дамуындағы үлкен серпіліс. Оған қауіпсіз, тым ұсақ емес, бірақ саусақтарымен ұстай алатын ойыншықтар беріңіз. Мұқият болыңыз: бұл дағды оның еденнен көрген ең кішкентай жіпті немесе шаң түйірін де ұстап алып, аузына сала алатынын білдіреді. Үйдің таза болуы және еденде ұсақ бөлшектердің жатпауы қазір бұрынғыдан да маңызды.') WHERE id = 'f62f3f3e-4b0d-4001-8523-9219c3da8c5d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Дербестік" кезеңі басталады! Тамақтану кезінде оған өз қасығын ұстауға мүмкіндік беріңіз. Иә, айналаның бәрі былғанып, езбе бөпеңіздің шашына да, Сіздің бетіңізге де жағылуы мүмкін, бірақ бұл өз бетінше тамақтану дағдыларын дамыту үшін өте маңызды. Бір қасық оның қолында болсын, ал екінші қасықпен Сіз тамақтандырыңыз. Осылайша ол өзін тамақтану үдерісінің белсенді қатысушысы ретінде сезінеді. Бұл болашақта "тамақ жегім келмейді" деген қыңырлықтың алдын алудың ең жақсы тәсілдерінің бірі.') WHERE id = '60871d42-5c1c-446f-a627-a65d4f2f7fcb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Егер тіс жару үдерісі әлі жалғасып жатса, бөпеңіздің тәбеті төмендеуі мүмкін. Қызыл иегі ауырған кезде қатты немесе ыстық тағам жеу оған жағымсыз болуы ықтимал. Мұндай күндері оны мәжбүрлемеңіз, ана сүтін көбірек беріңіз немесе тағамды бөлме температурасынан сәл салқындау етіп ұсыныңыз. Салқын жеміс езбелері қызыл иегін тыныштандыруы мүмкін. Сабыр сақтаңыз, бұл жайсыздық уақытша. Ең бастысы – оның тамақтан жағымсыз әсер алмауы.') WHERE id = 'd3067cbe-ce54-41b6-9dd3-9072dfcf2c69';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 7-айдың соңына да жеттіңіздер! Бөпеңіз енді өз есімін жақсы таниды және шақырған кезде Сізге қарай бұрылады. Ол эмоцияларын да анық көрсете бастады: қуанғанда айқайлайды, ойыншығын қолынан алғанда наразылығын білдіреді. Бұл – оның тұлғасының қалыптасуы. Бүгін онымен бірге еденге жатып, жай ғана ойнаңыз – ол үшін Сіздің назарыңыз бәрінен де қымбат. Сіз керемет жолдан өттіңіз, анашым!') WHERE id = 'bd6cd20e-2a94-483e-b4a1-ed0a0a344bf5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '8-айға қош келдіңіз! Бұл айда бөпеңіз «дербес зерттеуші» мәртебесіне ие болады. Ол енді еңбектеп, бөлменің бір бұрышынан екіншісіне тез жете алады. Егер бөпеңіз әлі еңбектемесе, алаңдамаңыз: кейбір балалар еңбектеу кезеңін өткізіп жіберіп, бірден орнынан тұруға және жүруге талпынады. Оны ынталандыру үшін сүйікті ойыншығын сәл алысырақ қойып, оған жетуге әрекеттенуіне мүмкіндік беріңіз. Оның әрбір кішкентай ілгерілеуі — үлкен жеңіс!') WHERE id = 'ecb494cd-7c29-44d1-ad94-78d5bacf0eb8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді езбелердің құрылымын біртіндеп өзгертетін уақыт келді. Тағамды блендерден өткізудің орнына, шанышқымен езе бастаңыз. Бөпеңіздің тістері әлі шықпаса да, ол жұмсақ түйірлерді қызыл иегімен езуді үйренуі керек. Бұл шайнау бұлшықеттерін дамытып, болашақта сөйлеу қабілетіне оң әсер етеді. Алғашқы кезде лоқсу рефлексі (gag reflex) болуы мүмкін, бұл қалыпты жағдай; тек жанында болып, жігерлендіріңіз.') WHERE id = '2727a145-103d-40b1-93bd-853efdc6e639';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз заттарға сүйеніп, орнынан тұруға әрекеттене ме? Диванның шеті, орындықтар, тіпті Сіздің аяқтарыңыз да оған тірек болады. Осы кезеңде үйдегі жиһаздардың орнықты екеніне назар аударыңыз. Жеңіл орындықтар немесе бұрыштық жиһаздар құлап кетуі мүмкін. Жиһаздың өткір бұрыштарына арнайы жұмсақ қорғаныштар орнататын кез келді, өйткені орнынан тұруға талпыну кезінде бөпе жиі құлап қалады.') WHERE id = '2b052f0a-26d0-4470-a503-c5a76302b58f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің ас мәзіріне балық қосуды ойлап жүрсіз бе? Егер отбасыңызда балыққа ауыр аллергия болмаса, ақ етті балықтар (мысалы, теңіз алабұғасы немесе сүйексіз ақ балық) — Омега-3 май қышқылдарының тамаша көзі. Балықты буға пісіріп, ішінде титтей де сүйек қалмағанына көз жеткізу үшін қолыңызбен мұқият тексеріңіз. Балық мидың дамуы мен көру қабілеті үшін өте пайдалы. Аптасына бір рет шағын порциядан бастауға болады.') WHERE id = '1d9818aa-0e5b-4ba9-aefe-a8e9678137db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Жоқ» сөзімен танысу! Бөпеңіз енді даусыңыздың ырғағындағы өзгерісті түсінеді. Ол қауіпті нәрсеге қол созғанда, байсалды әрі қатаң дауыспен «Жоқ» немесе «Болмайды» десеңіз, тоқтап, Сізге қарауы мүмкін. Алайда бұл сөздерді тым жиі қолданбаңыз, әйтпесе олар әсерін жоғалтады. Оларды тек шынайы қауіп төнгенде (мысалы, розеткаға қол тигізгенде) қолданыңыз. Басқа жағдайларда оның назарын өзге қызықты ойыншыққа аудару тиімдірек.') WHERE id = 'f3741479-5e2c-4a17-a78f-8627ec0b11aa';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің «қысқыш тәрізді ұстау» қабілеті (pincer grasp) одан әрі жетіліп келеді. Ол енді бас бармағы мен сұқ саусағының көмегімен ұсақ түйірлерді ұстай алады. Осы дағдыны дамытатын «қолмен жейтін тағамдарды» (finger foods) ұсыныңыз: әбден пісірілген жұмсақ сәбіз тілімдері, банан бөліктері немесе піскен асқабақ. Бұл оның қимыл-қозғалыс дағдыларын дамытып қана қоймай, өздігінен тамақтануды үйренуіне де жол ашады. Әрдайым бақылауда ұстаңыз!') WHERE id = '832beb7b-28cb-4a32-9588-55e7154e59b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Байқадыңыз ба, бөпеңіз ойыншықты лақтырғаннан кейін оның қайда түскеніне қарайды? Бұл «нысан тұрақтылығының» (object permanence) толық қалыптасқанын көрсетеді. Ол ойыншық көз алдынан жоғалса да, мүлде жоқ болып кетпегенін, тек жерге түскенін біледі. Сондықтан Сіздің бөлмеден шығып кеткеніңізге бұрынғыдан қаттырақ реакция білдіруі мүмкін. Оған кететініңізді және міндетті түрде қайтып келетініңізді сездіретін қысқа «қоштасу» рәсімдерін қалыптастырыңыз.') WHERE id = '2f260480-889e-4da7-8269-7ccb344f483a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің ұйқы режимі өзгеруі мүмкін. 8-ші айда кейбір бөпелер күндізгі 3-ші ұйқыдан (түстен кейінгі мызғып алудан) бас тарта бастайды. Бұл — қалыпты жағдай. Егер ол күндіз 2 рет ұзағырақ ұйықтап, кешке уақытында ұйқыға жатса, демек жаңа режимге ауысып жатырсыздар. Енді оның сергек жүретін уақыты 2.5 - 3 сағатқа дейін ұзаруы мүмкін. Шаршау белгілерін (құлағын қасу, көзін уқалау) бақылауды жалғастырыңыз.') WHERE id = '0800d9fe-eb08-4a4c-84c3-d676b21556f0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіл дамуының жаңа кезеңі: бөпеңіздің енді «өз тілінде» ұзақ сөйлемдер құрайтынын байқадыңыз ба? Бұл — «жаргон» кезеңі. Ол ересектердің сөйлеу мәнерін қайталап, сұрақ қойғандай дауысын көтереді немесе бір нәрсені түсіндіргендей қолын қимылдатады. Оны мұқият тыңдап, «Рас па? Өте қызық екен!» деп жауап беріңіз. Бұл оның қарым-қатынас жасауға деген ынтасын ерекше арттырады.') WHERE id = '71cabae0-25d9-4b76-b251-aaf1f4412278';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 8-ші айдың алғашқы он күні аяқталды! Бөпеңіз енді эмоцияларын күрделірек білдіреді: еркелейді, қарсылық көрсетеді немесе Сізді көргенде қуанып, қол шапалақтайды. Бүгін онымен еденде доп ойнаңыз: допты оған қарай домалатыңыз, ал ол допты ұстап алуға немесе Сізге қарай қайта итеруге тырыссын. Бұл қарапайым ойын араларыңыздағы физикалық әрі әлеуметтік байланысты нығайтады. Сіз — керемет жол көрсетушісіз, Анашым!') WHERE id = '9fdaa957-189e-4f2e-b893-b9625e6dd277';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сүт өнімдерімен танысуды жалғастырамыз! Егер әлі бастамаған болсаңыз, ас мәзіріне үйде дайындалған сүзбе (творог) қосатын уақыт келді. Сүзбе кальций мен ақуызға бай, бөпенің сүйектері мен тістерінің дамуы үшін өте маңызды. Оны жеміс езбесімен араластырып, дәмдірек ете аласыз. Есіңізде болсын, сүзбені дүкеннен сатып алсаңыз, міндетті түрде қантсыз, қоспасыз және балаларға арналған түрін таңдаңыз.') WHERE id = 'ae94f7bd-20c4-400d-a0b5-4fc94f6e2927';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді өз дене мүшелерін тани бастайды. Оған «мұрның қайда?», «көздерің қайда?» деген сұрақтар қойып, өзіңізден көрсетіңіз. Бұл қарапайым ойын оның сөздік қорын молайтып қана қоймай, өзін жеке тұлға ретінде тануына да көмектеседі. Айна алдында тұрып, оның қолдары мен аяқтарын көрсету бұл үдерісті одан да қызықты етеді. Ол айнадағы бейненің мәнін түсінуге жақын қалды.') WHERE id = 'c515c840-71f3-41f7-b139-398b94946105';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сүйеніп жүруге алғашқы талпыныстар! Бөпеңіз диваннан немесе орындықтан ұстап, жанымен адымдай бастауы мүмкін. Мұны "cruising" деп атайды. Бұл кезеңде оған аяқ киім кигізуге асықпаңыз; үйде жалаңаяқ (немесе табаны таймайтын шұлықпен) жүру аяқ бұлшықеттерінің дұрыс қалыптасуы мен тепе-теңдікті сезінуі үшін ең тиімді. Аяқ саусақтарымен еденді сезіну оның миына көбірек ақпарат жеткізеді.') WHERE id = '0028192c-1744-4eba-bb7a-f5c3b5d11c54';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің "ұсақ моторикасын" бақылаңыз: ол ойыншықты бір қолынан екінші қолына еркін ауыстырып, бас бармағын басқа саусақтарына қарама-қарсы қоя алады. Осы кезеңде оған пішіні мен түсі әртүрлі "пирамида" ойыншықтарын немесе бірінің ішіне бірі салынатын ыдыстар беріңіз. Ол сақиналарды әлі дұрыс ретімен орналастыра алмаса да, оларды бөлшектеп, қайта жинау кеңістікті қабылдауы мен қимыл үйлесімін айтарлықтай дамытады.') WHERE id = 'b139a999-0910-43e1-b5bf-dc2f0d783db4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Мәзірді түрлендіріңіз: егер әлі беріп көрмесеңіз, бұршақ тұқымдастарды (мысалы, қызыл жасымықты) ұсына бастауға болады. Жасымық — өсімдік тектес ақуыз бен темірдің көзі. Алайда абай болыңыз: бұршақ тұқымдастар іштің кебуіне себеп болуы мүмкін. Сондықтан жасымықты алдын ала жібітіп, көкөніс сорпасына өте аз мөлшерде қосыңыз. Бөпеңіздің ас қорыту жүйесі қалай қабылдайтынын бақылаңыз; бәрі жақсы болса, бұл оған өте тойымды түскі ас болады.') WHERE id = '071fb8f4-fce6-4526-aae9-c60d8797b1ea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылар: бөпеңіз енді "сау бол" (қол бұлғау) немесе "жарайсың" (қол шапалақтау) қимылдарын қайталай алады. Сіз қол шапалақтағанда ол да қайталаса, бұл оның еліктеу қабілетінің жақсы дамып келе жатқанын көрсетеді. Бұл қимылдарды ойынға айналдырыңыз. Еліктеу — үйренудің ең қысқа жолы. Әр сәтті қимылынан кейін оны қуана мақтаңыз, бұл оның өзіне деген сенімін арттырады.') WHERE id = '5cd6ae76-cf22-4b82-a5b7-ee78e7b002f5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздік ескертуі: бөпеңіз енді биікке өрмелеуге бейім. Шкафтың тартпаларын баспалдақ ретінде пайдалануы мүмкін. Тартпаларға арналған арнайы құлыптарды орнататын уақыт келді. Сондай-ақ ауыр жиһаздардың (кітап сөресі, комод) қабырғаға мықтап бекітілгеніне көз жеткізіңіз. Бөпеңіз оларды тартып қалып, үстіне құлатып алуы мүмкін. Қауіпсіз үй — еркін зерттеуге мүмкіндік береді.') WHERE id = 'a8f4ab5e-3832-4512-afc4-44fcec1c8a18';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Су ішу әдеті: бөпеңіздің бүйрегі қосымша тағамдарды өңдеген сайын суға деген қажеттілігі артады. Егер бөпеңіз су ішуден бас тартса, оны әртүрлі қызықты тәсілдермен ұсыныңыз. Мысалы, өзіңіз су ішкенде оған да ұсыныңыз, өйткені ол Сізге қарап үйренеді. Суды әрдайым оның қолы жететін жерде ұстаңыз. Таза су ас қорытуды реттеп, іш қату қаупін азайтады.') WHERE id = '73e0efe7-8cf6-4415-b315-772133307918';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз Сізге еліктеп, телефонмен сөйлескендей кейіп таныта ма немесе шашын тарауға тырыса ма? Бұл — "функционалдық ойын" кезеңі. Ол заттардың не үшін қолданылатынын түсіне бастайды. Оған қауіпсіз тұрмыстық заттарды (пластик тарақ, ойыншық телефон, ағаш қасық) беріп, еліктеу қабілетін қолдаңыз. Еліктеу — бөпенің әлеуметтік және зияткерлік дамуына ықпал ететін ең күшті құралдардың бірі.') WHERE id = '186aab21-e01b-4cb3-9b1b-f1b7cf5f3b0c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тағам құрылымын өзгерту: Егер әлі де тағамды толық езбе түрінде беріп жүрсеңіз, бүгіннен бастап ұсақ түйіршіктердің мөлшерін көбейтіңіз. Тағамды әбден езбей, ішінде кішкентай жұмсақ кесектер қалдырыңыз. Бұл бөпенің шайнау дағдысын дамытып, қызыл иегін нығайтады. Егер бөпе кесектерді түкіріп тастаса, оны мәжбүрлемеңіз, бірақ әр тамақтану кезінде бірнеше кесек ұсынып көре беріңіз. Сабырлы болсаңыз, ол жақын арада отбасы дастарқанындағы тағамдарға толық бейімделеді.') WHERE id = '0b1ada17-b48a-4258-81e3-556f2db2a842';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік қарым-қатынас: Бөпеңіз "сау бол" деп қол бұлғауды немесе "жарайсың" дегенде қол шапалақтауды үйренді ме? Бұл қимылдар — оның сөйлеуге дейінгі қарым-қатынас түрлері. Сіз қол бұлғағанда ол да қайталаса, бұл оның Сізге бауыр басқанын және назар аударып тұрғанын көрсетеді. Осы қимылдарды әндермен үйлестіріп, ойынды қызықты етіңіз. Қарым-қатынас жасауға деген ынтасы артуы үшін оның әрбір қимылына қуана жауап беріңіз.') WHERE id = '88a30222-647e-4598-aa2c-f27d2f68a4e6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздіктің жаңа кезеңі: Бөпеңіз енді барлық жерге өрмелегісі келеді. Аласа үстелдер мен диванның шеттері ол үшін "шың" саналады. Үйдегі барлық ауыр заттар мен жиһаздардың орнықты тұрғанын тексеріңіз. Әсіресе электр сымдарын (кабельдерді) жасырыңыз, өйткені оларды тарту оның ең қызықты ермегіне айналуы мүмкін. Үйдің қауіпсіздігі Сізге тыныштық сыйласа, оған айналаны еркін зерттеуге мүмкіндік береді.') WHERE id = '42e1e998-0acc-4253-963b-1927f727ffd8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы және "ажырау мазасыздығы": Бөпеңіз түнде оянғанда Сізді көрмесе, қатты жылауы мүмкін. Бұл кезеңде оған өзін қауіпсіз сезінуге көмектесу маңызды. Жанына келгенде жарықты жақпай, жай дауыспен "анашың осында, ұйықтай ғой" деп айтып, сипаңыз. Оны бірден қолыңызға алып, бөлмеден алып шығуға асықпаңыз. Сіздің жанында болғаныңыз бен даусыңыздың өзі оған қайта ұйықтап кету үшін жеткілікті сенім береді.') WHERE id = 'cab92102-e3a5-49d4-bbd8-bdc2525ea7fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, толық 8 айды артқа тастадық! Бөпеңіздің салмағы туған кездегі салмағынан шамамен үш есе артты (бұл орташа көрсеткіш). Ол қазір өте белсенді, дыбыстарды ажыратады және отбасы мүшелерін таниды. Бүгін онымен еденде "доп-доп" ойынын ойнаңыз: допты оған қарай домалатыңыз, ал ол ұстап алуға тырыссын. Бұл ойын көз бен қол үйлесімін де, кезек күтуді (әлеуметтік ережені) де дамытады. Сіз керемет жолдан өттіңіз, Ана!') WHERE id = 'eeeb250d-7860-4dbd-adfd-8f04383dcc0f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнде оянуы жалғаса берсе, оған «ажырау мазасыздығымен» қатар тіс жаруы да себеп болуы мүмкін. Әдетте 8-9 айда үстіңгі күрек тістер «сәлем» береді. Қызыл иегі ісініп, сезімтал болуы мүмкін. Ұйықтар алдында таза саусағыңызбен қызыл иегін ақырын уқаласаңыз, бөпеңіз тынышталады. Сабырлы болыңыз, бұл жайсыздық уақытша, ал Сіздің қолдауыңыз ол үшін әрдайым маңызды.') WHERE id = 'a7e2adf7-fa7d-49f9-b9df-6cb36632b7da';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 230 күнді артқа тастадық! Бөпеңіз енді Сіздің көңіл күйіңізді өте жақсы сезеді. Сіз күлсеңіз, ол да қуанады, ал байсалды үнмен сөйлесеңіз, тоқтап, Сізге қарайды. Бүгін онымен бірге еденге жатып, жай ғана «қытық-қытық» ойынын ойнаңыз. Оның сыңғырлаған күлкісі бар шаршауыңызды басады. Сіз бөпеңізбен керемет байланыс орнаттыңыз, Анашым!') WHERE id = 'd3c12132-2a39-444c-81a2-79aa27f8b6cc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді ас мәзіріне әртүрлі дәнді дақылдарды (сұлы, арпа) қосуға болады. Егер отбасында глютенге аллергия болмаса, сұлы (oat) ботқасы бөпеңіз үшін әрі тойымды, әрі талшыққа бай таңғы ас болады. Талшыққа бай тағамдар бөпеңіздің ішек жұмысын реттеп, іш қатуды жеңілдетеді. Ботқаға аздап езілген банан немесе алма езбесін қосып, дәмін тартымды ете аласыз.') WHERE id = 'f8aaab74-ed0b-4ea9-b26f-011f00ca98cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз заттарды бірінің ішіне бірін салуға немесе бірінің үстіне бірін жинауға тырыса ма? Бұл — «кеңістікті қабылдау» қабілетінің дамуы. Оған әртүрлі көлемдегі пластик стақандарды немесе бірінің ішіне бірі салынатын ыдыстарды беріңіз. Үлкен ыдыстың ішіне кішкентай ыдыс сыятынын байқағанда, оның миында жаңа нейрондық байланыстар түзіледі. Әзірге мұнара құрастыру қиын болуы мүмкін, бірақ Сіз құрастырған мұнараны бұзу оның ең сүйікті ісіне айналады!') WHERE id = '51ca7794-c77c-4014-b77a-c79e37d35c43';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Денесін танып-білу: Бөпеңіз енді «мұрын», «көз», «ауыз» дегенде оларды көрсете алады немесе Сіз көрсеткенде жымиып жауап береді. Бұл — оның өзін-өзі тануының маңызды бөлігі. Шомылдырғанда немесе киіндіргенде: «Енді оң қолыңа киеміз», «Енді сол аяғыңды жуамыз», — деп дене мүшелерін атап отырыңыз. Бұл оның тілінің дамуына да, дене сызбасын қалыптастыруына да көмектеседі.') WHERE id = '7184c458-15f9-4675-8f4b-a012153962e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Саусақпен жейтін тағамдар» (finger foods) кезеңіндегі шеберлік: Бөпеңіз енді тағамның кішкентай бөліктерін (мысалы, піскен сәбіз тілімін немесе асбұршақты) саусақтарымен ұстап, бірден аузына салуға ептірек болды. Бұл дағды оның өздігінен тамақтануын және тойғанын сезіну қабілетін дамытады. Үстеліне қауіпсіз әрі жұмсақ тағамдар қойып, өз бетінше жеуіне мүмкіндік беріңіз. Айналаның былғануы қалыпты жағдай, ең бастысы — оның осы дағдыны меңгеруі. Әрдайым жанында болып, қадағалаңыз.') WHERE id = 'b13c96d3-3ebb-4786-a1ba-dda465e426a2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '9-айға қош келдіңіз! Бұл ай — бөпеңіздің «саналы қарым-қатынас» кезеңі. Енді ол «Ма-ма» немесе «Ба-ба» дегенде жай ғана дыбыстарды қайталамай, тікелей Сізге немесе әкесіне тіл қатады. Сізге қарап осы сөздерді айтқанда, қуана жауап беріп, оны құшақтаңыз. Сіздің мұндай жағымды реакцияңыз оған сөздердің күші мен мағынасын түсінуге көмектеседі. Енді ол өз қалауы мен сүйіспеншілігін тіл арқылы жеткізе алатынын түсінеді.') WHERE id = 'c35ed773-5541-46b9-a100-13e031ebc738';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бауырымен жорғалаудан төрттағандап еңбектеуге толық көшу кезеңі! Бөпеңіз енді қарнын жерден көтеріп, төрттағандап жылдам қозғалады. Бұл қимыл оның ми сыңарлары арасындағы айқаспалы үйлесімді жетілдіреді. Еңбектеу болашақта оқу мен жазуға қажет көру-қимыл үйлесімінің де негізін қалайды. Үйдің барлық жерін еркін зерттей берсін, тек оның жүретін жолдары қауіпсіз екеніне көз жеткізіңіз.') WHERE id = 'eef05a4c-d9ba-43c9-8340-a35c1089e87f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тағам түрлерін көбейту: Енді бөпеңіздің ас мәзіріне бұршақ тұқымдастарды (жасыл жасымық, үрмебұршақ езбесі) және сүзбемен араластырылған түрлі маусымдық жемістерді батылырақ қоса аласыз. Осы кезеңде бөпеңіздің темір қорын сақтау үшін қызыл етті немесе жұмыртқаның сарысын жасыл көкөністермен бірге беруге тырысыңыз. C дәрумені (мысалы, көкөніске сығылған бірнеше тамшы лимон шырыны) темірдің сіңуін жақсартады.') WHERE id = 'c2e87fad-ec56-47c4-9f57-fc56aefe9e8a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қысқыш тәрізді ұстау» (pincer grasp) енді нағыз шеберлікке айналып келеді. Бөпеңіз еденнен көрген ең кішкентай қиқымды да екі саусағымен ұстап алады. Бұл дағдыны дамыту үшін оған жұмсақ пісірілген асбұршақ дәндерін немесе сүзбенің кішкентай түйірлерін ұсыныңыз. Өз бетінше тамақтану оның өзіне деген сенімін арттырады. Алайда абай болыңыз: бұл дағды оның түйме, моншақ сияқты қауіпті ұсақ заттарды да аузына оңай сала алатынын білдіреді.') WHERE id = 'afe941be-e174-4b07-9f32-16d62d4cfe8e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді «Жоқ» сөзінің мағынасын толық түсінеді. Қауіпті әрекет жасап жатқанда «Жоқ» десеңіз, ол тоқтап, Сізге қарауы немесе тіпті қарсылық білдіріп жылауы мүмкін. Бұл — оның шекараларды үйренуінің бастамасы. Дегенмен үйдің іші түгел «Жоқ» деген тыйымдарға толып кетпеуіне тырысыңыз. Қауіпті заттарды алып тастап, оған «Иә» деуге болатын ойындармен еркін айналысуға мүмкіндік беріңіз. Шектеулерді тек шынымен маңызды жағдайларда қойыңыз.') WHERE id = 'a85e4f35-e664-455a-b825-3e51d17e5f0d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Заттың тұрақтылығы» ойыны: Бөпеңіз ойыншықты көрпенің астына жасырсаңыз да, оның жоғалып кетпейтінін енді біледі. Ойыншықты жартылай жасырып, оны тауып алуына мүмкіндік беріңіз. Бұл ойын оның есте сақтау қабілеті мен логикалық ойлауын дамытады. Сонымен қатар «жасырынбақ» ойыны ажырап қалудан қорқуын азайтуға көмектеседі: ол Сіз көзден таса болсаңыз да, міндетті түрде қайтып келетініңізді түсінеді.') WHERE id = '0a1f58ae-f05c-4b6b-aa75-6ff0b27beddc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тірекке сүйеніп тұру дағдысы: Бөпеңіз енді кез келген жерден – диванның шетінен, орындықтың аяғынан, тіпті Сіздің тізеңізден ұстап орнынан тұрады. Бірақ ол әлі қалай қайта отыру керегін білмей, тік тұрған күйі көмек сұрап жылауы мүмкін. Оған қалай отыру керегін көрсетіңіз: тізесін бүгіп, еденге ақырын түсіріңіз. Бұл оның денесін басқару қабілеті мен тепе-теңдік сезімін дамытады.') WHERE id = 'd5785d23-fd09-4663-8877-2740ab81ecbc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы кезіндегі "қимыл-қозғалыс оянулары": Бөпеңіз түнде кенеттен еңбектей бастауы немесе ұйқылы күйде орнынан тұруға тырысуы мүмкін. Оның миы күндіз үйренген қимылдарын түнде қайталайды. Егер ол жыламаса, тиіспеңіз, өзіне ыңғайлы қалып тауып, қайта ұйықтауына мүмкіндік беріңіз. Ал жыласа, жанына тыныш қана барып, жарықты жақпастан қайта жатқызыңыз және жұбатар сөздер айтыңыз. Бұл кезең уақытша.') WHERE id = '3ee50fc0-987b-4449-9a9a-aeac43eacebb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жару және тамақтану: 9-шы айда көбіне үстіңгі немесе астыңғы бүйір күрек тістер жарып шығады. Бұл кезеңде бөпеңіздің қызыл иегі ауыратындықтан, ол қатты тағамнан бас тартуы мүмкін. Оны мәжбүрлемеңіз, бірнеше күн бойы жұмсағырақ әрі салқын тағамдар (мысалы, салқын жеміс езбесі немесе йогурт) беріңіз. Тіс жару үдерісі аяқталған соң, тәбеті қайта қалпына келеді. Сіздің сабырыңыз бен мейіріміңіз – ол үшін ең жақсы ем.') WHERE id = '5c734779-7b9a-4eb8-a3df-dadd22df3bb2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 250 күндік үлкен жолды артта қалдырдық! Бөпеңіз енді Сіздің бет әлпетіңізді өте дәл түсінеді. Сіз қуансаңыз, ол да күледі, ал байсалды үнмен сөйлесеңіз, тоқтап, Сізді бақылайды. Бүгін онымен еденде отырып, "кітап қарау" уақытын өткізіңіз. Үлкен суреттері бар кітаптан жануарларды көрсетіп, олардың дыбыстарын салыңыз. Ол Сізге еліктеуге тырысады. Сіз – оның әлемді танып-білуіне көмектесетін ең сенімді жолбасшысысыз, анашым!') WHERE id = '4168c3b6-34fd-49a6-b076-88e5415caa27';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сіздер 9-шы айдың дәл ортасына жеттіңіздер! Бөпеңіз енді заттарға сүйеніп, орнынан тұруды жақсы меңгеріп келеді. Алайда ең маңызды дағды әлі алда: тұрған жерінен еденге қауіпсіз отыру. Оған тізесін бүгіп, ақырын отыруды көрсетіңіз. Егер ол шалқасынан құлап қалса, айқайлап қорқытпаңыз; жай ғана жанына барып, қалай дұрыс қимылдау керегін қайта көрсетіңіз. Бұл оның дене үйлесімділігін нығайтады.') WHERE id = '8802254f-c7f7-4ff6-9b20-d9c01f14b494';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің ым-ишара арқылы қарым-қатынас жасауы енді мағыналы бола бастады. Ол қалаған ойыншығын саусағымен көрсетуі мүмкін (pointing). Бұл – танымдық дамуындағы үлкен серпіліс! Ол өз назарын Сізбен бөліскісі келеді. Бір нәрсені көрсеткенде, бірден оның атауын айтыңыз: "Иә, бұл доп! Сен допты қалайсың ба?". Бұл оның миында сөздер мен заттар арасындағы байланысты нығайтуға көмектеседі.') WHERE id = '425f3229-dceb-43c5-a7c7-021a098be008';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы алуандық пен жаңа құрылымдар: Енді езбені мүлде қойсаңыз болады. Тағамды шанышқымен езіп, бөпеңізге ұсыныңыз. Оның қызыл иегі жұмсақ піскен ет кесектерін немесе көкөністерді езуге жеткілікті түрде мықты. Шайнау қимылы ас қорыту үшін ғана емес, сөйлеуге қатысатын бұлшықеттердің дамуы үшін де қажет. Егер кейбір кесектерді түкіріп тастаса, алаңдамаңыз; ол жаңа сезімдерге үйреніп жүр.') WHERE id = '04975f3b-94a9-41da-8a0a-2994a09d6287';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Стақаннан су ішу дағдысын бекітіңіз. Бөпеңіз енді стақанды екі қолымен ұстауға талпына алады. Оған шағын пластик немесе силикон стақанмен су беріңіз. Алғашқы кезде судың жартысы үстіне төгілуі мүмкін, бұл — қалыпты жағдай. Ашық стақаннан ішу тіл мен жақтың дұрыс дамуы үшін емізігі бар бөтелкеден ішкенге қарағанда пайдалырақ. Бұл — оның дербестікке қарай жасаған келесі қадамы.') WHERE id = '2fd76c93-94cc-41aa-af0c-928b17fbd06d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ойындар: «Бер-ал» ойыны енді оның ең сүйікті ермегіне айналып келеді. Сіз одан ойыншықты сұрағанда, ол оны Сізге ұсынуы мүмкін (кейде қайта тартып алса да!). Бұл ойын кезек күтуді және бөлісуді түсінуінің негізін қалайды. Оған «Рақмет» деуді ұмытпаңыз. Сіздің жағымды реакцияңызды көргенде, ол осындай әлеуметтік әрекеттерді жиірек қайталауға ынталанады.') WHERE id = '7c3fd582-3962-47a8-9de8-b81ab68183e7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қысқыш тәрізді ұстау» (pincer grasp) дағдысы енді әбден жетілді. Бөпеңіз жердегі ең кішкентай шаң түйірін де ұстай алады. Бұл дағдысын дамыту үшін оған жақсы піскен бұршақ тұқымдастарды (мысалы, ноқат немесе жасымық) ұсына аласыз. Бұл оның зейінін шоғырландыруға да көмектеседі. Бірақ есіңізде болсын: ол тапқан кез келген ұсақ затты аузына салады, сондықтан еденде қауіпті ұсақ заттардың болмауын үнемі қадағалаңыз.') WHERE id = 'fda4720c-d3a0-4bf6-82ad-06eddb719108';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің есте сақтау қабілеті енді бірнеше күн бұрын болған оқиғаларды есте сақтай алатындай күшейді. Ол сүйікті ойыншығының қайда жасырылғанын есіне түсіре алады. Онымен күрделірек жасырынбақ ойындарын ойнаңыз. Мысалы, ойыншықты жамылғының астына жасырып, оны қалай табатынын бақылаңыз. Бұл оның логикалық ойлауын және заттардың жоғалып кетпей, жай ғана жасырылғанын түсінуін (объектінің тұрақтылығы) жетілдіреді.') WHERE id = '2c349583-ad28-47b1-aaec-34168c563082';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тірекке сүйеніп жүру (cruising) одан әрі жылдамдай түседі. Бөпеңіз диванды бойлай бір шетінен екінші шетіне тез жүріп өте алады. Бұл кезеңде оған аяқ киім кигізбеңіз. Жалаңаяқ немесе сырғанамайтын шұлықпен жүру табан мен башпайлардың дұрыс қалыптасуына өте қолайлы. Ол еденнің құрылымын сезінген сайын тепе-теңдігін жақсырақ сақтайды.') WHERE id = 'e21e8596-3f21-4200-9b5c-b7f1ca90251a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жару кезінде қызыл иектің қышуы мен ауыруы бөпенің түнгі ұйқысына әсер етуі мүмкін. Егер бөпеңіз ұйықтап жатып мазасызданса, қызыл иегін таза, дымқыл әрі салқын шүберекпен ақырын уқалаңыз. Тіс жару кезеңінде тәбеттің төмендеуі де қалыпты жағдай; оны тамақтануға мәжбүрлемей, сұйықтықты, ана сүтін немесе қоспаны жиірек ұсыныңыз. Сіздің мейіріміңіз — оның жанын тыныштандыратын ең жақсы ем.') WHERE id = 'c0bb1b1a-709a-4043-a236-fe5cfd9ea7eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 260 күн толды! Бөпеңіз енді өз есімін әрдайым танып, шақырған кезде бірден Сізге қарай бұрылады. Ол отбасы мүшелерін басқа адамдардан анық ажыратып, Сізге ерекше бауыр басқанын көрсетеді. Бүгін онымен бірге еденде отырып, "кітап оқу" уақытын өткізіңіз: ол суреттерді көрсетсін, ал Сіз олардың атауын айтыңыз. Сіз — оның ең сенімді ұстазы әрі қаһарманысыз, Анашым!') WHERE id = '122b28c9-a9e8-422e-9381-d9406e97f79b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді 9-шы айдың соңғы онкүндігіне аяқ бастық. Бөпеңіз тік тұрған кезде бір қолын диваннан босатып, екінші қолымен ойыншыққа созыла алады. Бұл оның тепе-теңдік сақтау қабілетінің қаншалықты дамығанын көрсетеді. Осы кезеңде айналасында ұстап тұруға болатын орнықты жиһаздардың бар екеніне көз жеткізіңіз. Ол қазір өз күшін сынап жүр және көп ұзамай өздігінен алғашқы қадамын жасауға батылдық жинайды.') WHERE id = '4ac0d7bc-e3ee-464a-a0d8-d71c88bce550';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің "ұсақ моторикасында" жаңа жетістік бар: енді ол екі затты бір-біріне соғып, дыбыс шығарғанды өте жақсы көреді. Бұл екі қолдың үйлесімді жұмыс істей бастағанын көрсетеді. Оған екі ағаш текше немесе пластик ыдыс беріп, оларды қалай тақылдататынын бақылаңыз. Бұл қарапайым әрекет оның есту қабілетін де, қимылды жоспарлауын да (motor planning) дамытады. Музыкалық ырғақтарды қосып, бұл ойынды одан әрі қызықты ете аласыз.') WHERE id = 'fddb995c-a311-44d6-a424-3f063a465828';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтануды түрлендіру: Егер әлі беріп көрмеген болсаңыз, ас мәзіріне сүзбе немесе йогуртпен бірге жұмсақ жемістердің кішкентай бөліктерін қосатын уақыт келді. Бөпеңіздің шайнау қимылдары енді біршама үйлесімді. Тағамды толық езіп бермей, кішкентай бөліктермен ұсыну қызыл иегінің нығаюына және болашақта отбасы дастарқанындағы тағамдарға толық бейімделуіне көмектеседі. Өздігінен тамақтануына мүмкіндік беріңіз, бұл оның өзіне деген сенімін арттырады.') WHERE id = 'b230cf28-523f-407d-9888-06b6c53bb3a6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік қарым-қатынастағы "еліктеу" кезеңі: Бөпеңіз енді Сіздің бет әлпетіңізді, шығарған дыбыстарыңызды, тіпті түшкіргеніңізді де қайталай алады. Ол Сізді мұқият бақылап, үйреніп жүр. Оның алдында әртүрлі қимылдар жасап көріңіз (мысалы, тіліңізді шығарыңыз немесе көзіңізді жыпылықтатыңыз), оның Сізді қайталайтынын бақылаңыз. Еліктеу дағдысы — оның әлеуметтік бейімделуі мен үйрену қабілетін дамытатын ең қуатты құралдардың бірі.') WHERE id = '671adb79-58b3-4617-94e4-bb4071a9a5ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Нысан тұрақтылығы" енді толық қалыптасты. Бөпеңіз ойыншықты қалтаңызға жасырсаңыз, оның жоғалып кетпегенін, жай ғана қалтаңызда тұрғанын біледі. Ол Сізді іздеп, қалтаңыздан тартады. Бұл есте сақтау жаттығуы оның логикалық ойлауын дамытады. Онымен жасырынбақ ойынының күрделірек түрлерін ойнаңыз; бұл оның ажырау мазасыздығын (separation anxiety) азайтуға да көмектеседі.') WHERE id = '6997dc99-18bc-4bdc-bae3-c34fc9c367dc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Стақаннан су ішу дағдысын нығайтыңыз. Бөпеңіз стақанды ұстап, аузына апаруға тырысқанда, су мөлшерін реттеуді үйреніп келеді. Алғашқы кезде судың жартысы киіміне төгілуі мүмкін, алаңдамаңыз. Ашық стақаннан ішу тіл мен ерін бұлшықеттерінің дұрыс дамуы үшін өте маңызды. Бұл дағды болашақта оның анық сөйлеуіне негіз болады. Сабырлы болыңыз, бұл — үйрену үдерісі.') WHERE id = '85d33873-230f-4ec2-aeb2-c03aab1bc8c9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тірекке сүйеніп жүру (cruising) айтарлықтай жылдамдады. Бөпеңіз диванды жағалай жүгіріп бара жатқандай қозғалады. Осы кезеңде үйдегі қауіпсіздік шараларын тағы бір рет тексеріңіз. Жиһаздың өткір бұрыштары, салбырап тұрған дастархандар немесе едендегі электр сымдары енді үлкен қауіп төндіреді. Бөпе бәрін тартып, өзіне қарай жақындатқысы келеді. Қауіпсіз орта оның зерттеуге деген құштарлығын шектемей дамуына мүмкіндік береді.') WHERE id = '6cb85c30-34e6-4f9c-a6d7-47b0e62b9c27';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіл дамуындағы "жаргон" кезеңі: бөпеңіз енді өз тілінде ұзақ "әңгімелер" айтады. Оның сөздерін түсінбесеңіз де, ол ересектердің сөйлеу мәнерін тамаша қайталайды. Оны мұқият тыңдап, сұрақтар қойыңыз және "Рас па? Содан кейін не болды?" деп жауап беріңіз. Бұл "диалог" оның өз ойын жеткізуге деген ынтасын арттырып, миындағы сөздік қорын байытады.') WHERE id = '56798677-523b-4029-94dd-1e80eef243c7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жару кезінде қызыл иектің қышуы мен ауыруы бөпеңіздің түнгі ұйқысына әсер етуі мүмкін. Егер бөпеңіз ұйқысында мазасыз болса, қызыл иегін таза, дымқыл әрі салқын шүберекпен ақырын уқалаңыз. Тіс жару кезеңінде тәбеттің төмендеуі де қалыпты; оны мәжбүрлемей, көбірек сұйықтық пен емшек сүтін/сүт қоспасын ұсыныңыз. Сіздің мейіріміңіз — оның ең күшті ауырсынуды басатын құралы.') WHERE id = '953f792e-f8bd-44cc-a2d0-c3b8471c1a51';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 9 айды аяқтадық! Бөпеңіз енді өз есімін әрдайым таниды және шақырған кезде бірден Сізге қарай бұрылады. Ол отбасы мүшелерін басқа адамдардан анық ажыратып, Сізге ерекше бауыр басқанын көрсетеді. Бүгін онымен еденде отырып, "кітап оқу" уақытын өткізіңіз; ол суреттерді көрсетсін, ал Сіз олардың атауларын айтыңыз. Сіз — оның ең сенімді ұстазы әрі қаһарманысыз, Ана!') WHERE id = 'b5fee624-3a8a-4073-bf22-e9bf23545a25';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '10-айға қош келдіңіз! Бұл айды бөпеңіздің «тәуелсіздік жариялайтын» кезеңі деуге болады. Ол енді заттардан ұстап, аяғында сенімдірек тұрады, тіпті бірнеше секунд бойы тірексіз тұрып көруге талпынады. Тепе-теңдікті сақтаған осындай қысқа сәттер — алғашқы қадамдардың жақындағанының белгісі. Оған кең әрі қауіпсіз орын дайындаңыз. Есіңізде болсын, әр құлаған сайын ол жердің тартылыс күшін сезініп, өз денесін басқаруды үйренеді. Тек жанында болып, жігерлендіріңіз.') WHERE id = '162ad9af-c711-43da-b203-5c312cf418b0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің тіліндегі «Ма-ма», «Ба-ба» немесе «Әт-тә» сияқты сөздер енді нақты мағынаға ие бола бастайды. Егер ол осы сөздерді айтқанда Сізге немесе әкесіне қараса, демек сөзді тиісті адаммен байланыстыра алады. Оған жауап бергенде қарапайым әрі түсінікті сөйлемдер қолданыңыз. Мысалы, ол «Доп» десе, «Иә, бұл қызыл доп» деп, сөздік қорын байытыңыз. Сіздің әрбір жауабыңыз оның миында жаңа тілдік байланыстар қалыптастырады.') WHERE id = 'be8f3e1a-5335-4ace-960c-562783ff9dcb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы жаңа кезең: «Қысқыш тәрізді ұстау» (pincer grasp) қабілеті жақсы дамығаны соншалық, бөпеңіз кішкентай асбұршақ дәнін немесе жұмсақ пісірілген сәбіз тілімін өзі ұстап, аузына апара алады. Оған өз бетінше тамақтануға көбірек мүмкіндік беріңіз. Бұл оның қимыл-қозғалыс дағдыларын дамытып қана қоймай, тойғанын өзі сезініп, тамақтануын реттеуіне көмектеседі. Айналаның былғануынан қорықпаңыз, мұндай «шығармашылық ретсіздік» оның дамуы үшін маңызды.') WHERE id = '58ffad0f-55f8-47af-b047-3975e8528016';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді Сізге еліктеуді жақсы меңгерді. Сіз телефонмен сөйлескенде, ол да қолына бір зат алып, құлағына тақайды, ал Сіз шашыңызды тарасаңыз, ол да соған ұқсас қимыл жасайды. Бұл — «функционалдық еліктеу» кезеңі. Оған қауіпсіз тұрмыстық заттарды (пластик тарақ, ойыншық телефон, ағаш қасық) беріп, осы қабілетін қолдаңыз. Ол қоршаған ортаны Сізге қарап үйренеді, сондықтан іс-әрекетіңізбен жақсы үлгі көрсетуге тырысыңыз.') WHERE id = 'a6c8ab18-10f6-4956-855e-8fca749308ef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Заттың тұрақтылығы» ойыны: Бөпеңіз ойыншықты ыдысқа салып, бетін жауып қойсаңыз да, оның жоғалып кетпейтінін біледі. Онымен күрделірек жасырынбақ ойындарын ойнаңыз. Мысалы, ойыншықты екі түрлі жамылғының бірінің астына жасырып, оны қалай табатынын бақылаңыз. Бұл оның есте сақтау қабілетін де, зейінін шоғырландыру дағдысын да дамытады. Тапсырманы орындаған кезде оны ерекше ықыласпен мақтаңыз.') WHERE id = '535f32b7-37dd-475b-9f52-55c5a1160920';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тірекке сүйеніп жүру (cruising) енді әбден автоматтанған. Бөпеңіз диваннан ұстап, бөлменің бір шетінен екінші шетіне жылдам жүріп өте алады. Осы кезеңде үйдің қауіпсіздігін қайта тексеріңіз: салбырап тұрған дастарқандар, едендегі электр сымдары мен өткір бұрыштар енді бұрынғыдан да үлкен қауіп төндіреді. Ол бәрін тартып, өзіне қарай сүйреп, жоғары өрмелеуге тырысады. Қауіпсіз орта оған айналаны еркін зерттеуге мүмкіндік береді.') WHERE id = 'd10583a3-e400-4339-b85b-3d395175b72a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы кезінде «ажырау мазасыздығы» қайтадан байқалуы мүмкін. Бөпеңіз оянғанда Сізді көрмесе, бірден жылап жіберуі ықтимал. Оған сенімділік беру үшін жанына барып, жарықты қоспай, жайлап сипаңыз да: «Анаң осында, ұйықтай ғой», — деп сыбырлаңыз. Оны бірден қолыңызға алып, бөлмеден алып шығуға асықпаңыз; Сіздің жаныңызда екеніңізді сезіп, өздігінен қайта ұйықтауға тырыссын. Сіздің сабырлылығыңыз бұл кезеңді жеңілірек өткізуге көмектеседі.') WHERE id = '807f6974-949a-4673-9e12-ca050a097e4d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 290 күнді артқа тастадық! Бөпеңіз енді жеке тұлға ретінде өз мінезін көрсете бастады: оған не ұнайды, неден қорқады, қандай тағамды жақсы көреді... Бүгін онымен бірге еденге жатып, ойынды басқаруды бөпеңізге тапсырыңыз. Ол Сізге не істеу керегін «көрсетсін», ойыншығын ұсынсын немесе Сізге еліктесін. Онымен бірге өткізген әр минутыңыз — оның болашақ бақытының іргетасы. Сіз керемет жолдан өттіңіз, Ана!') WHERE id = '2489cf6a-6c9a-4826-ac80-afae063dcb86';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '10-шы айдың соңғы онкүндігіне қош келдіңіз! Бөпеңіз бір қолынан ұстағанда сенімді қадам баса ма, әлде әлі де сүйенішсіз тұруға батылы жетпей жүр ме? Екі жағдай да қалыпты. Кейбір бөпелер 10-шы айда жүре бастайды, ал басқалары 15-16 айға дейін асықпайды. Аяқ бұлшықеттерін нығайту үшін еденде көбірек уақыт өткізуіне мүмкіндік беріңіз. Ол өз күшіне сенген сәтте алғашқы дербес қадамымен Сізді таңғалдырады!') WHERE id = '96dedeae-65fd-4082-8b02-077d47cad21d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің «объект тұрақтылығы» туралы түсінігі жақсы дамығаны сонша, ол бір затты қораптың ішіне салып, кейін қайта шығара беруден жалықпайды. Бұл «салу және шығару» ойыны оның кеңістікті қабылдауын да, ұсақ моторикасын да дамытады. Оған өлшемдері әртүрлі ыдыстар мен олардың ішіне салуға болатын қауіпсіз заттар беріңіз. Бұл қарапайым жаттығу — оның болашақта күрделі тапсырмаларды шешу қабілетінің негізі.') WHERE id = 'a8043f3c-dcb0-41ac-858a-58401aab3cc0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы жаңа серпіліс: Бөпеңіз кейбір сөздерді немесе дыбыстарды нақты оқиғалармен байланыстыра бастады. Мысалы, есік қоңырауы соғылғанда «әке» деуі немесе қарны ашқанда ерекше дыбыс шығаруы мүмкін. Бұл — саналы сөйлеудің бастамасы. Оның дыбыстап білдірген әрбір өтінішіне мұқият жауап беріңіз: «Иә, есік қағылды, келген — әкең!». Сіздің осындай «аудармаларыңыз» оның миында сөздердің мағынасын берік бекітеді.') WHERE id = '7f7f52b6-f75a-4125-9bb5-a72c5365ce29';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы әртүрлілік: Енді бөпеңіздің мәзіріне өте аз мөлшерде (және жақсылап пісірілген) тұтас дәнді дақылдар, жұмсақ макарон немесе нанның жұмсағын қосуға болады. Бұл оған тағамдардың әртүрлі құрылымын сезінуге және шайнау дағдысын жетілдіруге көмектеседі. Есіңізде болсын, әзірге тағамға тұз бен қант қоспаймыз. Табиғи дәмдер оның дәм сезу рецепторларының дұрыс қалыптасуы үшін ең қолайлы.') WHERE id = 'b9f43156-8bbe-4d46-a470-47337a11cf3a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтануда тағам құрылымын ауыстыру кезеңін аяқтаңыз. Енді езбе тағамдар кезеңі толығымен артта қалуы керек. Тағамды тек шанышқымен езіп немесе қолмен ұстап жеуге болатын кішкентай жұмсақ бөліктер (finger foods) түрінде ұсыныңыз. Бөпеңіздің қызыл иегі жұмсақ пісірілген етті немесе көкөністі езуге жеткілікті дәрежеде қатайған. Бұл шайнау дағдысын жетілдіріп, болашақта «тамақ таңдау» мәселесінің алдын алады. Сабырлы болыңыз, әрбір жаңа құрылым — жаңа үйрену тәжірибесі.') WHERE id = '25d3da74-5500-488e-93bc-4e022b9fdf57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ойындардағы «кезектесу» дағдысы: Бөпеңіз енді «маған бер», «саған берейін» ойынын жақсырақ түсінеді. Оған ойыншықты ұсынып, кейін «енді допты маған сен бер» деп қайтарып сұраңыз. Егер берсе, оны көтеріңкі көңілмен мақтаңыз. Бұл ойын оның бөлісу түсінігі мен өзара қарым-қатынас ережелерінің негізін қалайды. Сондай-ақ ол көз бен қол қимылының үйлесімін және затты еркін жіберу дағдысын жетілдіреді.') WHERE id = '639df12e-60c1-4322-9712-2375f1060042';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Санаттар»: Бөпеңіз енді ұқсас заттарды ажырата бастайды. Мысалы, пішіндері әртүрлі доптардың бәрі «доп» екенін түсінуге жақын. Оған түсі мен өлшемі әртүрлі доптарды немесе текшелерді көрсетіңіз. Бұл — абстрактілі ойлаудың алғашқы қадамдары. Онымен ойнағанда заттардың түсі мен пішінін дауыстап айтып отырыңыз: «Бұл үлкен мәшине, ал мынау кішкентай мәшине».') WHERE id = '4207275f-8c9b-455a-be42-c07fcdc66c91';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қысқыш тәрізді ұстау» (pincer grasp) дағдысы енді толық қалыптасқан. Бөпеңіз еденнен көрген ең кішкентай қиқымды да бас бармағы мен сұқ саусағының ұшымен ұстай алады. Бұл дағдыны одан әрі дамыту үшін оған жақсы піскен жасымық дәндерін немесе жұмсақ сүзбенің кішкентай түйірлерін беріңіз. Мұқият болыңыз: бұл дағды оның тауып алған кез келген қауіпті ұсақ затты (түйме, моншақ) дәл сондай ептілікпен аузына сала алатынын да білдіреді. Қазір үйдің тазалығы бұрынғыдан да маңызды.') WHERE id = 'd9053aab-2643-4a33-bd40-377294e7163f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тірекке сүйеніп жүру (cruising) қарқыны соншалықты артты, бөпеңіз диванның жиегін жағалап жүріп, жүгіргендей қозғалады. Бұл кезеңде үйдегі жиһаздардың орнықтылығын тағы бір рет тексеріңіз. Ол қолымен тартыла көтеріліп, бәріне өрмелегісі келеді. Салбырап тұрған дастархандарды алып тастаңыз, өйткені олардан ұстап тұруға тырысса, үстіндегі заттардың бәрін өзіне қарай аударып алуы мүмкін. Қауіпсіз орта оның өзіне деген сенімін арттырып, айналасын қорықпай зерттеуіне мүмкіндік береді.') WHERE id = '22ae7b1e-0f5e-4f2c-a0b9-f363eec03221';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өзін-өзі тану: Бөпеңіз енді айнадағы бейненің өзі екенін түсіне бастайды. Оның мұрнына кішкентай түсті дақ қойып, айнаға қаратсаңыз, ол өз бетіндегі дақты сүртуге тырысады (бұл «ерін далабы сынағы» деп аталады). Бұл — оның өзіндік санасының (self-awareness) дамуының белгісі. Онымен бірге айна алдында тұрып, «бұл сенің мұрның, ал бұл ананың мұрны» деп айырмашылықтарды көрсетіңіз. Бұл дене сызбасын қалыптастыруға арналған тамаша жаттығу.') WHERE id = 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік қарым-қатынастағы жаңа ишаралар: Бөпеңіз енді қалаған затын саусағымен көрсетеді. Бұл — танымдық дамуындағы үлкен серпіліс. Ол назарын Сізбен бөліскісі келеді. Бір нәрсені көрсеткенде, бірден оның атауын айтыңыз: "Иә, бұл құс! Қарашы, құс ұшып барады". Бұл оның сөздік қорын молайтып қана қоймай, Сізбен арадағы эмоциялық байланысын да нығайтады. Оның қызығушылығын елеусіз қалдырмау өте маңызды.') WHERE id = '1c394285-7074-4a0d-ac82-eab79473970a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Стақаннан су ішу дағдысын жетілдіріңіз. Бөпеңіз енді стақанды екі қолымен ұстап, тепе-теңдікті сақтауға бір қадам жақындады. Оған пластик немесе силиконнан жасалған шағын стақанға аздап су құйып беріңіз. Судың төгілуі — үйрену үдерісінің бір бөлігі. Ашық стақаннан ішу тіл мен ерін бұлшықеттерінің дұрыс дамуына емізігі бар бөтелкеге қарағанда пайдалырақ әрі болашақта анық сөйлеуіне көмектеседі.') WHERE id = '863feabb-ad16-4aad-8a94-087f99977902';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Егер тіс жару үдерісі жалғасып жатса, бөпеңіздің ұйқысы мен тәбеті қайтадан бұзылуы мүмкін. 10-шы айда әдетте үстіңгі немесе астыңғы бүйір күрек тістер жарып шығады. Қызыл иегі қатты қышыса, оған салқындатылған (бірақ мұздатылмаған) тіс қаситын ойыншық немесе салқын көкөніс тілімдерін (міндетті түрде бақылаумен) беріңіз. Осы кезеңде көбірек сұйықтық пен ана сүтін ұсыну оның ағзасын сұйықтықпен қамтамасыз етіп қана қоймай, тыныштандырады. Сіздің мейіріміңіз — ең жақсы ауырсынуды басатын дәрі.') WHERE id = '22dd56cb-e699-4f81-b502-66f9d54e2b23';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 280 күнді аяқтадық! Бөпеңіз енді өз атын атаған сайын танып, анық жауап береді. Ол сүйікті ойыншығын немесе адамын таңдай алады және өз "мінезін" көрсете бастады. Бүгін онымен бірге еденге жатып, жай ғана "еліктеу" ойынын ойнаңыз: ол дыбыс шығарсын, Сіз қайталаңыз; Сіз қол шапалақтаңыз, ол қайталасын. Сіз — оның әлемді танып-білетін ең сенімді айлағысыз, Ана!') WHERE id = '71654afe-3791-4e59-a41c-7da09d0ef29c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '10-шы айдың дәл ортасына да жеттіңіздер! Бөпеңіз енді заттарға сүйеніп орнынан тұруды шебер меңгерді, тіпті қолын бірнеше секундқа жіберіп, өздігінен тұруға тырысады. Бұл оның тепе-теңдік сақтау қабілеті мен аяқ бұлшықеттерінің қаншалықты нығайғанын көрсетеді. Өздігінен тұруға мәжбүрлемеңіз, бұл қадамды өзін дайын сезінгенде жасасын. Құлап қалудан қорықпауы үшін айналасына жұмсақ жастықтар қойылған қауіпсіз "алаң" жасап беріңіз.') WHERE id = '03d76f01-bcab-4644-9f10-2526c187201c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіздің сөйлеу дамуындағы жаңа кезең: "жаргонша" былдырлау! Ол Сізге бір нәрсені түсіндіріп жатқандай, интонациясы мен эмоциясы бар ұзақ "сөйлемдер" құрайды. Әзірге бірде-бір сөзін түсінбесеңіз де, бұл — оның болашақ сөйлеуінің негізі. Оны мұқият тыңдап, "Рас па? Өте қызық екен, сосын не болды?" деп жауап беріңіз. Осындай диалогтер оның өз ойын білдіруге деген ынтасын арттырып, миындағы сөздік қорын жылдам байытады.') WHERE id = 'e6d2e0ec-fef4-4fdf-bd36-60be17d3ab5e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзім!" кезеңі басталады. Тамақтану кезінде бөпеңіз қасықты қолыңыздан алуға немесе тамақты қолымен жеуге көбірек ұмтылады. Оның дербестікке деген ынтасын баспаңыз. Қолдары былғанып, беті пюреге боялса да, еркіне қойыңыз. Бұл үдеріс оның өзіне деген сенімін арттырып, тағаммен жағымды қарым-қатынас қалыптастыруына көмектеседі. Сіздің сабырлылығыңыз оның болашақта тәбеті жақсы әрі дербес бала болып өсуіне негіз қалайды.') WHERE id = 'b31abab7-200d-4d55-b197-62b606e68100';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылар: Бөпеңіз енді "сау бол" деп қол бұлғау немесе "сүйіс жіберу" сияқты қимылдарды қайталай алады. Бұл қимылдар — оның сөйлеуге дейінгі қарым-қатынас түрлері. Сіз қол бұлғағанда, ол да артыңыздан қайталаса, бұл оның Сізге деген жақындығы мен зейінін көрсетеді. Осы қимылдарды әндермен үйлестіріп, ойынды одан әрі қызықты етіңіз. Қарым-қатынас жасауға деген ынтасын арттыру үшін оның әрбір қимылына қуана жауап беріңіз.') WHERE id = 'db90e8f1-9d73-4d53-8169-2122571f4a13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздіктің жаңа деңгейі: Бөпеңіз енді биікке өрмелеуге әуес. Аласа үстелдер мен диванның шеттері ол үшін нағыз "шың". Үйдегі барлық ауыр заттар мен жиһаздардың орнықты тұрғанын тексеріңіз. Әсіресе электр сымдарын (кабельдерді) жасырыңыз, өйткені оларды тарту оның ең қызықты ермегіне айналуы мүмкін. Үйдің қауіпсіз болуы Сізге тыныштық сыйласа, оған айналаны еркін зерттеуге мүмкіндік береді.') WHERE id = 'cd4b7de4-c97d-44b4-ae4b-d87984914859';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы және танымдық даму: Бөпеңіз түнде оянғанда Сізді көрмесе, қатты жылауы мүмкін. Бұл кезеңде оған өзін қауіпсіз сезінуге көмектесу маңызды. Жанына келгенде жарықты жақпай, жай дауыспен "анаң осында, ұйықтай ғой" деп айтып, арқасынан сипаңыз. Оны бірден қолыңызға алып, бөлмеден шығуға асықпаңыз. Сіздің қасында болғаныңыз бен даусыңыздың өзі оған қайта ұйықтап кету үшін жеткілікті сенім береді. Бұл — "ажырау мазасыздығының" уақытша кезеңі.') WHERE id = 'd5f8c50f-64e6-4aba-ad9f-5604b24fb65b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ертең бөпеңіздің туғанына тура 300 күн толады! Осы 10 ай ішінде ол таңғаларлық жолдан өтті: көмексіз ештеңе істей алмайтын нәрестеден өзіндік мінезі, қалауы мен қабілеттері бар кішкентай адамға айналды. Сіз де осы уақыт ішінде мол тәжірибе жинадыңыз. Бүгін онымен бірге еденге жатып, жай ғана күлкісін тамашалаңыз. Сіздің махаббатыңыз — оның дамуының ең үлкен қозғаушы күші.') WHERE id = '2638511c-740a-477b-ab58-1fbe5fd5c94a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бөпеңіздің туғанына 300 күн толды! Бұл — бір жасқа толар жолдағы соңғы үлкен белес. Бөпеңіз енді атын атаған сайын өзіне айтылғанын түсінеді, эмоцияларын анық көрсетеді және алғашқы қадамдарын жасауға дайындалып жүрген де болар. Бұл күнді онымен бірге ерекше ойын ойнап немесе сүйікті жемісін беріп атап өтіңіз. Сіз керемет іс атқардыңыз, Ана! 300 күндік еңбегіңіздің жемісі — күн сайын Сізге қарайтын сол бақытты жанарларда.') WHERE id = '4dbc6d6a-ae47-4867-ba96-b66058f91a2f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ойындардың күрделене түсуі: Бөпеңіз енді «бер-ал» ойынын жаңа деңгейге көтеріп жүр. Ол ойыншықты Сізге беріп, бірден қайтаруды сұрауы немесе Сіз «бер» дегенде оны әдейі жасыруы мүмкін. Бұл — оның алғашқы «әзілдері». Оның әзілқойлығына күліп жауап беріңіз. Бірге күліп, көңіл көтеру араларыңыздағы эмоциялық байланысты керемет нығайтады.') WHERE id = '3451f734-1652-4c0f-97a4-7d508b0bb860';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұйқы режимі және сергек жүру уақыты: 11-ші айда бөпелер күндізгі 2 ұйқыдан 1 ұйқыға ауысу (ұйқы ауысымы) белгілерін көрсетуі мүмкін, бірақ әзірге асықпаңыз. Бөпелердің көпшілігіне 14-15 айға дейін күндіз 2 рет ұйықтау қажет. Егер таңғы ұйқыға жатуы қиындаса, сергек жүру уақытын сәл ұзартып көріңіз (шамамен 3 - 3.5 сағат). Жақсы тыныққан бөпе жаңа дағдыларды құлшыныспен үйренеді.') WHERE id = '852db72f-d9a2-475c-b994-d1ab8a6b4f97';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістікті қабылдау»: Бөпеңіз енді қораптардың ішіне қарағанды, қақпақтарды ашып-жапқанды және заттарды бірінің ішіне бірін салғанды ұнатады. Оған әртүрлі өлшемдегі пластик ыдыстар беріңіз. Кішкентай ыдыстың үлкен ыдыстың ішіне сыйатынын байқаған кезде, оның миында күрделі математикалық және логикалық байланыстар қалыптасады. Бұл қарапайым болып көрінгенімен, шын мәнінде үлкен жаңалық.') WHERE id = '114fd473-c44c-4c3b-b5d0-19ac5cbf17e6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 310 күнді аяқтадық! Бөпеңіз енді өз еркін көрсете бастады: киінгісі келмесе, аяқтарын тірейді, сүйікті асын көргенде алақанын соғады. Бұл «мінез» белгілері кейде Сізді шаршатса да, шын мәнінде оның психологиялық дамуы қалыпты екенін көрсетеді. Бүгін онымен бірге еденге отырып, тек өзі қалаған ойынды ойнаңыз. Сіздің назарыңыз — ол үшін әлемдегі ең үлкен сый.') WHERE id = '2a98f756-8ee8-4fcc-b117-1adb344f61bd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз қолын тіреуден бірнеше секундқа босатып, өздігінен тұра ала ма? Бұл — оның өзіне деген сенімі шарықтаған сәт. Ол әлі жүрмесе де, тепе-теңдік сақтаған осы сәттер оның миындағы тепе-теңдік орталығын (вестибулярлық аппаратты) жетілдіреді. Оны мақтап, құшағыңызды ашып, Сізге қарай бір қадам жасауға ынталандырыңыз. Әрбір кішкентай талпыныс — үлкен қадамның бастауы!') WHERE id = '94901ac5-33b9-4db0-bb43-734602fe969c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Жоқ» сөзін түсіну және сынап көру! Бөпеңіз енді «жоқ» дегеніңізде тоқтап, Сізге қарайды, бірақ кейде сол әрекетті әдейі қайталайды. Осылайша ол шекараларды және Сіздің реакцияңызды тексереді. Сабыр сақтап, шешіміңізден таймаңыз. Қауіпті жағдайларда себебін байсалды, бірақ нық үнмен түсіндіріңіз. Ол Сіздің бет әлпетіңіз бен дауыс ырғағыңызға қарап, әлеуметтік ережелерді үйренуді жалғастырады.') WHERE id = '996a8930-2fe4-4558-a5f9-55c594d11cb6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «жаргон» (өз тілінде былдырлау) енді күрделене түседі. Бөпеңіз сұрақ қойып тұрғандай дауысын көтереді немесе бір нәрсені түсіндіргендей қол қимылдарын жасайды. Бұл оның сөйлеу интонациясын (просодияны) үйреніп жатқанын көрсетеді. Оны мұқият тыңдап, «Иә, солай ма? Өте қызық!» деп диалогті жалғастырыңыз. Сіздің осындай қызығушылық танытуыңыз оның қарым-қатынас жасауға деген ынтасын айтарлықтай арттырады.') WHERE id = '79994c5e-b38e-4456-bddc-86c51746ecdb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Отбасылық дастарқанға бейімдеу: Енді бөпеңіз барлығын дерлік (тұзсыз әрі ащы дәмдеуіштерсіз болса) Сіздермен бірге жей алады. Оған өз қасығын және өзі еркін іше алатын стақан беріңіз. Өздігінен тамақтануына мүмкіндік беру қимыл-қозғалыс дағдыларын дамытып қана қоймай, ас ішуді жағымды әлеуметтік әрекетке айналдырады. Дастарқан басында бірге отыру — оның болашақтағы тамақтану әдеттері үшін ең жақсы үлгі.') WHERE id = '4a48790e-7f13-40fe-9b6e-dd306e1f2a08';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістіктік жады» және іздеу: Бөпеңіз сүйікті ойыншығының қайда жасырылғанын бірнеше минуттан кейін де есінде сақтай алады. Онымен күрделірек «жасырынбақ» ойындарын ойнаңыз. Мысалы, ойыншықты жамылғының астына жасырып, оны қалай тауып алатынын бақылаңыз. Бұл оның есте сақтау қабілетін де, зейінін шоғырландыру дағдысын да дамытады. Тапсырманы орындаған кезде оны қуана мақтаңыз.') WHERE id = 'f29f91f0-dc1e-44f0-842d-ac8ae1283e19';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылардағы «бөлісу» әрекеттері: Бөпеңіз қолындағы ойыншығын Сізге «беретіндей» созып, кейін қайта тартып алуы мүмкін. Бұл — оның алғашқы қалжыңдары мен әлеуметтік ықпал ету әрекеттері! Оның бұл «ойынына» күліп, қуана жауап беріңіз. Бірге күліп, көңіл көтеру араларыңыздағы эмоциялық байланысты айтарлықтай нығайтып, оның әзіл сезімінің негізін қалайды.') WHERE id = 'ffe2c8a7-1840-4df7-a9fa-47dc0268105b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қысқыш тәрізді ұстау» (pincer grasp) дағдысы енді толық жетілді. Ол жердегі ең жіңішке жіпті немесе кішкентай қиқымды да оңай іліп алады. Бұл дағдыны дамыту үшін оған жақсы піскен бұршақ дәндерін немесе сүзбенің ұсақ түйірлерін ұсыныңыз. Бірақ абай болыңыз: мұндай ептілік оның кез келген қауіпті ұсақ затты дәл сондай жылдамдықпен аузына сала алатынын да білдіреді. Қауіпсіздік әрдайым бақылауда болуы керек!') WHERE id = 'c1101eea-3caa-455b-a661-c216864cdeb4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Музыка және ырғақ: Бөпеңіз музыка естігенде денесін тербетіп немесе қол шапалақтай ма? Музыка ырғағын сезіну — оның есту қабілеті мен дене үйлесімділігінің дамып келе жатқанының белгісі. Онымен бірге билеп, қол шапалақтаңыз. Бұл оның дене белсенділігін арттырып қана қоймай, эстетикалық талғамы мен ырғақ сезімінің қалыптасуына көмектеседі. Ән сөздерін бірге қайталауға тырысыңыз.') WHERE id = '3a1cdf9f-7bc8-427f-b1e3-a23a8f78241b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '11-айға қош келдіңіз! Алғашқы туған күніне небәрі екі ай қалды. Бұл кезеңде бөпеңіз «мен» мен «сен» ұғымдарының айырмашылығын жақсырақ түсіне бастайды. Ол Сіздің бет әлпетіңізді қайталау арқылы эмоциялық интеллектін дамытады. Сіз мұңайғанда, ол да байсалды кейіп танытуы мүмкін, ал Сіз күлгенде, ол да қарқылдап күледі. Онымен сезімдеріңіз туралы сөйлесіңіз — бұл оның болашақта өз эмоцияларын басқара білуіне берік негіз қалайды.') WHERE id = '9a834d06-30b3-4c6c-92b2-859a3c7000f4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз бір қолынан ұстағанда сенімді жүре ме, әлде әлі де диванның жиегін жағалап қана жүр ме? Осы күндері ол тепе-теңдігін сақтау үшін қолдарын екі жаққа жайып, өздігінен бір-екі қадам жасауы мүмкін. Мұндай «тепе-теңдік» қимылдары оның миындағы тепе-теңдік орталығын (вестибулярлық аппаратты) жаттықтырады. Оны асықтырмаңыз, өзіне толық сенімді болғанша уақыт беріңіз.') WHERE id = 'a31576c9-38ba-4027-9aca-cbc63e6f334a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «қалауын білдіру»: Бөпеңіз енді не қалайтынын тек жылап қана емес, саусағымен көрсетіп, ерекше дыбыстар шығару арқылы да түсіндіре алады. Ол ойыншығын нұсқағанда: «Иә, сен мына қонжықты қалайсың ба?» — деп, қалауын сөзбен растаңыз. Бұл оның бойында «мені түсінеді» деген сезім қалыптастырып, болашақта өзін түсінбегеннен туындайтын агрессиялық әрекеттердің, соның ішінде жылаудың алдын алуға көмектеседі.') WHERE id = 'aa86788c-ff14-4450-8f10-2208ffcc316b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы дербестік: Бөпеңіз енді қасықты өзі ұстап, аузына апарғысы келеді. Иә, тамақтың көбі еденге және алжапқышқа төгіледі, бірақ бұл — ұсақ моторика мен қол-көз үйлесімін дамытатын аса маңызды жаттығу. Оған ұстауға ыңғайлы силикон қасық немесе сабы жуан қасық беріңіз. Сол уақытта Сіз басқа қасықпен тамақтануына көмектесе аласыз. Бұл нағыз «командалық жұмыс» сияқты!') WHERE id = '3159f58c-c8a2-418a-a8bd-3b961ca0266e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Жануарлардың дыбыстары» кезеңі! Бөпеңіз енді «ит қалай үреді?», «мысық қалай дыбыстайды?» деген сұрақтарға өз тілінде жауап бере бастауы мүмкін. Бұл — оның дыбыстарды қайталау қабілетінің шарықтау кезеңі. Жануарлардың суреттері бар кітаптарды бірге қарап, осы ойындарды жалғастырыңыз. Дыбыстарға еліктеу сөйлеу мүшелерін (тіл мен ерін бұлшықеттерін) болашақта күрделі сөздерді айтуға дайындайды.') WHERE id = '43246706-501b-4546-a51a-8e59351b53c5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Пинцеттік ұстау» (pincer grasp) қабілеті жетілгені сонша, бөпеңіз едендегі жіңішке жіпті немесе кішкентай қиқымды да оңай іліп алады. Бұл дағдысын жаттықтыру үшін оған жақсы піскен бұршақ тұқымдастарды (ноқат, жасымық) ұсына аласыз. Бірақ ұмытпаңыз: тапқан ұсақ заттың бәрін аузына салу әдеті де шегіне жеткен кезең. Үй еденінің таза болуы және ұсақ заттардың қолжетімсіз жерде сақталуы қауіпсіздіктің ең маңызды қағидасы болып қала береді.') WHERE id = '1053192f-a2a7-43d0-8335-34db00482590';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқыдағы "қимылдық оянулар": Бөпеңіз ұйықтап жатып кенет орнынан тұруы немесе ұйқылы күйде еңбектеуге тырысуы мүмкін. Оның миы күндіз үйренген қимылдарды түнде қайталайды. Егер жыламаса, оған тиіспеңіз, өзіне ыңғайлы қалып тауып, қайта ұйықтауына мүмкіндік беріңіз. Ал жыласа, жанына жайлап барып, жарықты жақпастан қайта жатқызыңыз да, жұбатар сөздер айтыңыз. Оның қайта ұйықтауы үшін Сіздің қасында болғаныңыз жеткілікті.') WHERE id = '8706f5e6-ca0d-4a1d-8941-e5de02cc1dad';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 320 күнді артқа тастадық! Алғашқы туған күніне небәрі 45 күн қалды. Бөпеңіз енді өз мінезін, қалауын және таңдауын батыл көрсете бастады. Бүгін онымен бірге еденге жатып, жай ғана "қайталау" ойынын ойнаңыз: ол дыбыс шығарсын, Сіз қайталаңыз; Сіз қол шапалақтаңыз, ол қайталасын. Ана, Сіз — оның әлемді танып-білу жолындағы ең сенімді панасы әрі ең жақын досысыз!') WHERE id = '6671dafc-f72e-46f2-8504-39bf2769162e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Енді 11-ші айдың соңғы онкүндігіне аяқ басып келеміз. Бөпеңіз бір қолынан ұстағанда сенімді жүре ме, әлде әлі де диванның жиегін жағалап қана жүр ме? Осы күндері ол тепе-теңдігін сақтау үшін қолдарын екі жаққа жайып, өздігінен бір-екі қадам жасауы мүмкін. Мұндай "тепе-теңдік" қимылдары оның миындағы тепе-теңдік орталығын (вестибулярлық аппаратты) жаттықтырады. Оны асықтырмаңыз, өзіне деген сенімі толық қалыптассын.') WHERE id = '223de2de-87c5-4289-96a9-08ae91456aa1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз заттардың не үшін қолданылатынын түсіне бастады (функционалдық ойын). Мысалы, тарақты басына апарады, телефонды құлағына ұстайды немесе кесені аузына апарып, "ішкендей" болады. Бұл — танымдық дамуындағы үлкен серпіліс! Оған қауіпсіз тұрмыстық заттар беріп, еліктеу дағдысын қолдаңыз. Ол әлемді Сізге қарап үйренеді, сондықтан іс-әрекетіңізбен жақсы үлгі көрсетуге тырысыңыз.') WHERE id = '1023ea09-5e35-4d01-b1e5-ee2d0049110b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Объектінің тұрақтылығы" ойыны: Бөпеңіз ойыншықты ыдыстың ішіне салып, бетін жапсаңыз да, оның жоғалып кетпейтінін енді біледі. Онымен күрделірек жасырынбақ ойындарын ойнаңыз. Мысалы, ойыншықты екі түрлі жапқыштың бірінің астына жасырып, қалай тауып алатынын бақылаңыз. Бұл оның есте сақтау қабілетін де, зейінін шоғырландыру дағдысын да дамытады. Тапсырманы орындағанда, оны зор ықыласпен мақтаңыз.') WHERE id = '8ef86f1c-b50a-4f76-b6a2-1deccffcaf49';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы дербестік: Бөпеңіз енді қасықты өзі ұстап, аузына апарғысы келеді. Иә, тамақтың көбі еден мен алжапқышқа төгілуі мүмкін, бірақ бұл — ұсақ моторика мен қол-көз үйлесімін дамытатын ең маңызды жаттығулардың бірі. Оған ұстауға ыңғайлы, силиконнан жасалған немесе сабы жуан қасық беріңіз. Сіз де дәл сол уақытта басқа қасықпен тамақтануына көмектесе аласыз. Бұл нағыз "командалық жұмыс" сияқты!') WHERE id = '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Жануарлардың дауысы» кезеңі! Бөпеңіз енді «ит қалай үреді?», «мысық қандай дыбыс шығарады?» деген сұрақтарға өз тілінде жауап бере бастауы мүмкін. Бұл — оның дыбыстарға еліктеу қабілетінің шарықтау кезеңі. Жануарлардың суреттері бар кітаптарды бірге қарап, осы ойындарды жалғастырыңыз. Дыбыстарға еліктеу сөйлеу мүшелерін (тіл мен ерін бұлшықеттерін) болашақта күрделі сөздерді айтуға дайындайды.') WHERE id = 'cdc84d0d-886f-4a27-bf41-fd9c5be5503c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Пинцеттік ұстау» (pincer grasp) дағдысының жетілгені сонша, бөпеңіз жердегі ең жіңішке жіпті немесе титтей қиқымды да оңай ұстай алады. Бұл дағдыны жаттықтыру үшін оған жақсы піскен бұршақ тұқымдастарды (ноқат, жасымық) ұсынуға болады. Бірақ ұмытпаңыз: тапқан ұсақ заттың бәрін аузына салуға деген әдеті де шарықтау шегіне жеткен. Үй еденінің таза болуы және айналада ұсақ заттардың болмауы әлі де ең маңызды қауіпсіздік қағидасы болып қала береді.') WHERE id = '03beae21-c620-431a-a745-a2cb5663e55d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ойындар күрделене түседі: бөпеңіз енді «бер-ал» ойынын жаңа деңгейге шығарады. Ол ойыншықты Сізге беріп, бірден қайтарып алғысы келуі немесе Сіз «бер» дегенде оны әдейі жасыруы мүмкін. Бұл — оның алғашқы «әзілдері». Оның әзілқойлығына күліп жауап беріңіз. Бірге күліп, көңіл көтеру араларыңыздағы эмоциялық байланысты керемет нығайтады.') WHERE id = '3339985d-3305-4eb1-9ee4-eac876362604';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұйқы режимі және сергек жүру уақыты: 11-айда бөпелер күндізгі 2 ұйқыдан 1 ұйқыға ауысу (күндізгі ұйқының ауысуы) белгілерін көрсетуі мүмкін, бірақ әзірге асықпаңыз. Бөпелердің көпшілігі 14-15 айға дейін күндіз 2 рет ұйықтауды қажет етеді. Егер таңертең ұйықтауы қиындаса, сергек жүру уақытын сәл ұзартып көріңіз (шамамен 3 - 3.5 сағат). Жақсы тыныққан бөпе жаңа дағдыларды құлшыныспен үйренеді.') WHERE id = 'db42c776-feed-4c94-906a-857e9999bca9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістікті қабылдау»: бөпеңіз енді қораптардың ішіне үңілгенді, қақпақтарды ашып-жапқанды және заттарды бірінің ішіне бірін салғанды ұнатады. Оған өлшемдері әртүрлі пластик ыдыстар беріңіз. Кішкентай ыдыстың үлкен ыдыстың ішіне сыятынын анықтаған кезде, оның миында күрделі математикалық және логикалық байланыстар қалыптасады. Бұл қарапайым болып көрінгенімен, шын мәнінде үлкен жаңалық.') WHERE id = 'c317d6dc-6305-468b-bef4-37407eacbfe2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 330 күнді аяқтадық! Алғашқы туған күніне небәрі бір ай қалды. Бөпеңіз енді өз еркін көрсете бастайды: киінгісі келмесе, аяқтарын тірейді, ал сүйікті тамағын көрсе, қол шапалақтайды. Осы «мінез» белгілері кейде Сізді шаршатса да, шын мәнінде оның психологиялық тұрғыдан сау дамып келе жатқанының белгісі. Сіз керемет жолдан өттіңіз, Анашым!') WHERE id = 'c209d7a9-28c5-4bcf-a9ab-ed5e68cd5e38';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '12-ші айға қош келдіңіз! Алғашқы туған күнге небәрі 30 күн қалды. Бөпеңіз қазір мүлде бөлек тұлғаға айналды. Ол енді Сіздің қимылдарыңызды жай ғана қайталап қоймай, олардың мағынасын да түсінеді. Осы айда өзіне деген сенімділігін арттыру үшін оған қарапайым таңдау ұсыныңыз. Мысалы: «Мына жейдені кигің келе ме, әлде ананы ма?». Бұл оның шешім қабылдау қабілетінің алғашқы негізін қалайды.') WHERE id = 'fd9ad5fc-02c4-489e-8c2f-e2ab1ee56a7e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Егер бөпеңіз тірексіз жүре бастаса, үйдегі қауіпсіздік шараларын «ең жоғары» деңгейге көтеріңіз. Ал әлі жүрмесе, алаңдамаңыз: дені сау көптеген бөпе 15 айға дейін жүрмейді. Қай жаста жүре бастауы зияткерлік дамудың көрсеткіші емес. Ең бастысы — оның аяғынан тік тұра алуы және айналасын зерттеуге ынтасының болуы.') WHERE id = 'e0fb9df8-7033-4ff7-a1b1-5c3d3e6afa83';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «саналы сөздер»: Бөпеңіз «су», «бер», «кел» сияқты қарапайым сөздерді орынды қолдана ма? Ол қалағанын бір сөзбен немесе ыммен Сізге түсіндіре алады. Оның бұл талпыныстарын толықтырып отырыңыз: «Иә, сен су ішкің келе ме? Мә, бұл сенің көк стақаның». Бұл оның миында сөздер арасындағы грамматикалық байланыстарды қалыптастыруға көмектеседі.') WHERE id = 'c5cc511f-2fea-4b22-b8e8-1b77f482261c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезінде отбасы дастарқанына толық қосылу. Бөпеңіз енді Сізбен бірге дастарқан басына отырып, барлығыңызбен бірдей дерлік тағамдарды жей алады. Бұл оның әлеуметтенуі үшін өте маңызды. Оған жеке ыдыс-аяқ беріп, өздігінен тамақтануына мүмкіндік жасаңыз. Тамақтану ол үшін міндет емес, қызықты әрі дәмді әрекет болуы керек.') WHERE id = '8b39909f-51d2-4504-9985-513b605dc042';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қысқыш тәрізді ұстау» (pincer grasp) дағдысы әбден жетілді, енді ұсақ моторикасы күрделірек ойындарды ойнауға мүмкіндік береді. Оған текшелерді бірінің үстіне бірін қоюды, үлкен моншақтарды жіпке тізуді (міндетті түрде бақылаумен!) немесе қарапайым пазлдарды (puzzle) құрастыруды көрсетіңіз. Бұл ойындар зейін қою қабілетін де, қол мен көз үйлесімін де керемет дамытады.') WHERE id = 'e3225412-1384-48a0-aa55-7ca8a5ef8659';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік қарым-қатынаста «эмпатияның» алғашқы белгілері байқалады. Сіз мұңайғанда немесе жылағанда, бөпеңіз жаныңызға келіп, Сізге қолын тигізуі немесе ойыншығын ұсынуы мүмкін. Бұл оның өзгелердің сезімдерін түсіне бастағанын көрсетеді. Оның осындай жанашыр әрекеттеріне сүйіспеншілікпен жауап беріңіз. Бұл болашақта оның эмоциялық тұрғыдан сау тұлға болып қалыптасуына көмектеседі.') WHERE id = '31745949-5ef4-444a-8a69-ec5929c0332b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылардағы "Қалжыңдар": Бөпеңіз ойыншықты Сізге әдейі беріп, артынша бірден тартып алып, оған күле ме? Бұл оның әзіл сезімі мен әлеуметтік ықпал ету дағдысы қалыптасып келе жатқанын көрсетеді. Оның бұл "ойынына" қуана қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты нығайтып, бөпеңіздің өзіне деген сенімін қалыптастырады.') WHERE id = 'f977f0c6-061a-4189-bf33-4e6656c97984';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтануда "Талғампаздық" басталуы мүмкін. Бөпеңіз кеше жеген тағамынан бүгін үзілді-кесілді бас тартуы ықтимал. Осылайша ол өз қалауын білдіре бастайды. Оны мәжбүрлемеңіз, бірақ ұнатпаған тағамын біраз уақыттан кейін басқа түрде қайта ұсыныңыз. Ең бастысы — дастарқан басында шиеленіс тумауы керек. Тамақтану уақыты ол үшін жағымды әдет болып қалсын.') WHERE id = 'eb15bd6a-93d6-4986-92eb-7294c9a935c2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Құрастыру" дағдысы: Бөпеңіз енді текшелерді бірінің үстіне бірін қойып, кішкентай "мұнаралар" жасауға тырысады. Әзірге мұнара тез құлап қалуы мүмкін, бірақ бұл оның қол-көз үйлесімін және зейінін шоғырландыру қабілетін дамытуға арналған тамаша жаттығу. Оған өлшемі мен түсі әртүрлі текшелер беріңіз. Құлаған мұнараға бірге күліп, "Кәне, тағы бір рет құрастырайық!" деп жігерлендіріңіз.') WHERE id = '7a4a5884-cfbe-4717-937f-7483274cf1dd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Кеңістікті қабылдау" және есте сақтау: Бөпеңіз енді сүйікті ойыншығының қайда жасырылғанын біледі және оны табу үшін кедергілерді (мысалы, жастықты) шетке ысырады. Бұл оның мәселені шешу қабілетінің дамып келе жатқанын көрсетеді. Онымен күрделірек "жасырынбақ" ойындарын ойнаңыз. Кедергілерден өту оның миындағы логикалық байланыстарды нығайтады.') WHERE id = '87a69c40-9317-47d9-89ca-fad250ba27cf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өзін-өзі тану және дербестік: Бөпеңіз киінген кезде Сізге "көмектесуге" тырыса ма? Мысалы, аяғын шұлыққа қарай созады немесе қолын жейденің жеңіне сұғады. Бұл әрекеттерін қолдап, мақтаңыз. "Қандай әдемі киіндің!" деуіңіз оның өзін жеке тұлға ретінде тануына және дербес болуға деген ұмтылысына үлкен үлес қосады.') WHERE id = '82ceaad9-caa0-45d0-ae94-6fb25e59d3dc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс шығару кезеңінің соңғы сатылары (алғашқы жыл үшін): 1 жасқа таяған бөпелердің көпшілігінде 4-8 тіс болады. Қызыл иегі қайтадан ісініп немесе ауыруы мүмкін. Шайнауы үшін салқын көкөніс тілімдерін (сәбіз, қияр – міндетті түрде бақылаумен!) беріңіз. Шайнау қызыл иекті уқалап қана қоймай, жақ бұлшықеттерін де нығайтады.') WHERE id = '3fe62d47-f929-4c62-b0de-6bc80e34943b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Стақаннан су ішу дағдысы енді толық қалыптасуы керек. Емізігі бар бөтелкеден біртіндеп бас тартатын уақыт келді. Бөтелкені ұзақ уақыт пайдалану тістердің орналасуына және сөйлеу қабілетінің дамуына кері әсер етуі мүмкін. Оған қызықты, түрлі түсті тұмсықты стақан немесе кәдімгі ашық стақан ұсыныңыз. Өздігінен су ішу оған үлкен дербестік сезімін сыйлайды.') WHERE id = '38eafb23-62e2-4538-a93f-213f32e35986';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістіктік жады» және реттілік: Бөпеңіз ойыншықтарының қайда тұратынын біледі. Ойын аяқталғаннан кейін оларды бірге жинаңыз. «Кел, қонжықты үйіне (қорапқа) салайық» деп, оны ынталандырыңыз. Бұл оның бойында жауапкершілік сезімін қалыптастырып қана қоймай, әр заттың өз орны бар екенін түсінуге де көмектеседі. Реттілік пен тәртіпке үйрену дәл осы айларда басталады.') WHERE id = 'c880f2e4-5f85-403c-b1f7-b1634ed3e06b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы және сергек жүру ұзақтығы: Бөпеңіз енді күндізгі ұйқысын сиретіп немесе бір ұйқысын қысқартуы мүмкін. Егер ол күндіз бір рет ұйықтап, өзін жақсы сезінсе, күн тәртібін соған сай реттеңіз. Алайда 1 жастағы балалардың көпшілігіне әлі де күндіз екі рет ұйықтау қажет. Оның шаршау белгілерін бақылауды жалғастырыңыз; жақсы тыныққан бала көңілдірек әрі үйренуге бейім болады.') WHERE id = '9898d949-3ccb-4708-a982-1de8127dfcfd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 340 күнді артқа тастадық! Алғашқы туған күніне небәрі 25 күн қалды. Бөпеңіз қазірдің өзінде жеке тұлға – оның өз талғамы, мінезі және сүйікті ойындары бар. Бүгін онымен бірге еденге жатып, өзі таңдаған ойынды ойнаңыз. Сіздің оның әлеміне енуіңіз – ол үшін ең үлкен сыйлық. Сіз керемет бір жыл өткіздіңіз, Ана!') WHERE id = 'c4c0444c-fad1-4344-8a31-c99f7a9878d9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Туған күніне небәрі 25 күн қалды! Егер бөпеңіз өздігінен бірнеше қадам жасап жүрсе, бұл оның тепе-теңдік орталығының толық қалыптасқанын көрсетеді. Ал әлі қадам баспаса, қолынан ұстап, жүруге мәжбүрлемеңіз. Бұл оның омыртқасына артық салмақ түсіруі мүмкін. Ең дұрысы – қарсы алдында тұрып, құшағыңызды ашып, өзіңізге қарай келуге ынталандыру. Сіздің сенімді көзқарасыңыз оған зор батылдық береді.') WHERE id = '8681364a-206a-4e87-acfa-4a44f4404ec8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «рецептивті тілдің» (түсіну қабілетінің) дамуы: Бөпеңіз қарапайым нұсқауларды түсінеді. «Допты маған бер», «Мұнда кел», «Бас киіміңді ал» дегенде, ол орындай ала ма? Ол әлі барлық сөзді айта алмаса да, миында үлкен сөздік қор жинақталып келеді. Онымен сөйлескенде әр әрекетіңізді сөзбен сипаттауды жалғастырыңыз. Бұл – оның болашақ сөйлеу қабілетінің берік іргетасы.') WHERE id = 'b0d73932-0d82-458c-b55b-ddc718662495';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Жоқ» сөзінің күші: Бөпеңіз енді Сіздің «Жоқ» дегеніңізге қарсылық білдіріп, тіпті жерге жатып алып жылауы мүмкін (алғашқы қырсығу ұстамалары). Бұл оның өз эмоцияларын басқаруды әлі білмеуінен болады. Сабыр сақтап, оның деңгейіне дейін еңкейіңіз де, сезімдерін атап беріңіз: «Ойыншықты бермегеніме ашуланып тұрсың, түсінемін». Сіздің осындай сабырлылығыңыз — оған эмоциялық тұрақтылықты үйрететін ең жақсы үлгі.') WHERE id = '627b69c9-1a97-4379-b790-7b2e4d39bfb2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 350 күнді артқа тастадық! Алғашқы туған күніне небәрі 15 күн қалды! Бүгін алғашқы айлардағы суреттеріне қарап, екеуіңіздің қаншама жолдан өткендеріңізді ой елегінен өткізіңіз. Сол дәрменсіз бөпе қазір өзіндік мінезі бар жеке тұлғаға айналды. Осы 15 күнді күйзеліске салынбай, жай ғана онымен бірге уақыт өткізіп, рақаттанып қарсы алыңыз. Сіз керемет бір жылды өткердіңіз, Ана!') WHERE id = '8417d81b-7389-4675-845a-7c49bcb07801';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Алғашқы туған күніне небәрі 10 күн қалды! Бөпеңіз кітап беттерін (әзірге бірнешеуін бірден) аудара ала ма? Бұл оның ұсақ моторикасының дамуын әрі кітапқа қызығушылығын көрсетеді. Оған үлкен әрі түрлі-түсті суреттері бар кітаптарды оқуды жалғастырыңыз. Суреттегі итке қарап, «Ау-ау қайда?» дегеніңізде, оны саусағымен көрсетуі — түсіну қабілетінің жоғары деңгейде дамып келе жатқанының белгісі.') WHERE id = '3e342e5d-4541-4b82-ae58-b2cc792f784b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз музыка естігенде денесін тербетіп, тізесін бүгіп-жазып «билей» ме? Музыканың ырғағын сезінуі оның есту қабілеті мен дене үйлесімділігінің жетіліп келе жатқанын көрсетеді. Онымен бірге қол шапалақтап, ырғақ ұстаңыз. Осындай көңілді сәттер оның миында бақыт гормондарының бөлінуін арттырып, Сізбен арасындағы байланысты одан әрі нығайтады.') WHERE id = '824b4580-ab45-4cbc-9104-e999a9e050cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпеңіз енді заттардың не үшін қолданылатынын толық түсінеді. Тарақты көрсе, басына апарады, аяқ киімін көрсе, аяғына қарай созады. Ол заттардың жай ғана ойыншық емес екенін, әрқайсысының белгілі бір қызметі барын түсіне бастады. Оған қауіпсіз тұрмыстық заттармен (пластик ыдыстар, таза щеткалар) ойнауға рұқсат беріңіз. Бұл оның күнделікті өмірге бейімделуін жылдамдатады.') WHERE id = '40fb0a95-63d4-4ada-888b-1faf14ddd19d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «қайталау» кезеңі. Бөпеңіз Сіз айтқан сөздердің соңғы буындарын қайталауға тырысуы мүмкін. Мысалы, Сіз «алма» десеңіз, ол «ма» деуі мүмкін. Осылайша оның сөйлеу аппараты белсенді түрде жаттығады. Онымен әрдайым анық әрі дұрыс дыбыстап сөйлесіңіз. «Бала тілінде» (пипи, мяу-мяу және т.б.) сөйлеудің орнына заттардың нақты атауларын айту оның сөздік қорының дұрыс қалыптасуына көмектеседі.') WHERE id = '40321163-794d-42e6-bcde-127caef60c13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '2 жасқа қош келдіңіздер! Алғашқы туған күннің толқынысы артта қалды, бірақ нағыз қызық енді басталады. Бөпеңіз енді ресми түрде "жүре бастаған бала" (тоддлер) кезеңіне өтті. Осы айдан бастап ол әлемді тік тұрып көбірек зерттегісі келеді. Қимыл-қозғалысы артқан сайын, энергияға деген қажеттілігі де өзгереді. Бірақ ана сүті немесе сүт қоспасы әлі де оның тамақтану рационының маңызды бөлігі болып қала алатынын ұмытпаңыз.') WHERE id = '165b6f1d-3374-4097-b9a4-8e514ea4fdd0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жүру дағдысы нығая түседі! Егер бөпеңіз өздігінен жүре бастаса, оның қадамы әлі де сәл "теңселген" әрі алшақ екенін байқайсыз. Бұл — тепе-теңдікті сақтауға көмектесетін табиғи механизм. Үйде мүмкіндігінше жалаңаяқ жүруіне мүмкіндік беріңіз. Бұл табанының дұрыс қалыптасуына және миына еден бетінің құрылымы туралы көбірек ақпарат түсуіне көмектесетін ең жақсы тәсіл.') WHERE id = 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1 жастан кейін балалардың тәбеті кенет төмендеуі мүмкін. Бұл "физиологиялық анорексия" деп аталады. Оның себебі қарапайым: баланың өсу қарқыны алғашқы жылмен салыстырғанда баяулайды, сондықтан оған бұрынғыдай көп калория қажет емес. Оны күштеп тамақтандыруға тырыспаңыз. Ең бастысы — ұсынатын тағамдарыңыз сапалы әрі алуан түрлі болсын. Бала қанша тамақ жеу керектігін өзі реттеуді үйренуі тиіс.') WHERE id = 'dd5c13fb-e41c-4d49-a21d-c17c38691c1f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Бір сөздік сөйлемдер" кезеңі. Бөпеңіз енді бір ғана сөзбен тұтас ойын жеткізе алады. Мысалы, "Се-ру" деуі әрі "далаға шығайық", әрі "аяқкиімімді кигізші" дегенді білдіруі мүмкін. Сіз оның бір сөзден тұратын ойын кеңейтіп жауап беріңіз: "Иә, қазір аяқкиіміңді киіп, аулаға серуендеуге шығамыз". Бұл оның сөйлем құрау дағдысын тезірек дамытуға көмектеседі.') WHERE id = '4f614506-d560-4d40-bad9-c0ba7ee808d8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім!" кезеңі күшейе түседі. Бөпеңіз қолын жуғанда, баспалдақпен көтерілгенде немесе киінгенде Сіздің көмегіңізден бас тартуы мүмкін. Бұл қырсықтық емес, өз бетінше әрекет етуге талпыныс. Қауіпсіз жағдайлардың бәрінде оған "рұқсат етілген еркіндік" беріңіз. Өзінің бір нәрсені істей алатынын сезіну — оның өзіне деген сенімін қалыптастыратын ең маңызды факторлардың бірі.') WHERE id = '884b93ff-cafb-4926-88b8-45e9267f348c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылардағы "Қатар ойнау" кезеңі. Бөпеңізді құрдастарының ортасына апарсаңыз, оның басқа балалармен бірге емес, солардың жанында өз бетінше ойнайтынын көресіз. Бұл 1-2 жас аралығындағы балалар үшін мүлде қалыпты жағдай. Олар әлі бөлісуді және бірге ойнауды білмейді, бірақ бір-бірін бақылау арқылы көп нәрсе үйренеді. Әлеуметтенуі үшін оны саябақтарға және ойын топтарына апаруды жалғастырыңыз.') WHERE id = 'e23b48b6-63ac-4bcc-9b95-51974a62ac74';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моториканы меңгеру: Бөпеңіз енді қарындашты немесе қылқаламды (әзірге алақанымен) ұстап, қағазға шимай сала алады. Бұл — оның қол-көз үйлесімінің жаңа деңгейі. Оған үлкен қағаздар мен балаларға қауіпсіз түрлі түсті қарындаштар беріңіз. Бұл әрекет оның шығармашылық қиялының алғашқы дәндерін де себеді. Қабырғалар «өнер туындысына» айналып кетпеуі үшін оны үнемі қадағалаңыз!') WHERE id = '0b6473c4-31af-4b7f-87fd-2d01229d5be8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұйқы режимінің өзгеруі: 13-ші айда көптеген бала күндізгі екі ұйқыдан бір ұйқыға ауысуға дайын болады. Егер бөпеңіз таңертең ұйықтай алмай қиналса немесе түскі ұйқысы тым кеш басталса, режимді реттейтін уақыт келді. Бір реттік күндізгі ұйқыға көшу бірнеше аптаға созылуы мүмкін, осы өтпелі кезеңде кешкісін ол сәл мазасыз болуы ықтимал. Сабырлы болыңыз, жаңа режим екеуіңізге де қолайлы болады.') WHERE id = '04380a78-48ac-47f1-b32c-6d6f9bfeb4d4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздіктегі «биіктік» факторы. Бөпеңіз енді орындықтарға өрмелеп, үстелдің үстіне шығуға тырысады. Ол биіктіктің қауіптілігін және ықтимал қатерлерді әлі толық түсінбейді. Терезе бекіткіштерін тексеріп, биік жиһаздарды қабырғаға бекітіңіз. Оның еркін қозғалуын шектемей, айналаны құлап кетуден барынша қауіпсіз ету — Сіздің басты міндетіңіз.') WHERE id = '6948a89f-6493-4c6e-9adb-708a1f0063cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '13-ші айдың алғашқы он күнін аяқтадыңыз! Бөпеңіз енді қарапайым нұсқауларды («Ойыншығыңды қорапқа сал», «Мұнда кел») саналы түрде орындайды. Бұл — оның тілдік әрі әлеуметтік дамуының маңызды көрсеткіші. Бүгін онымен бірге кітап оқып, суреттегі заттарды тауып көрсетуін сұраңыз. Сізбен бірге өткізген әрбір сапалы минут — оның дамуына көрсетілетін ең үлкен қолдау.') WHERE id = '702b1e33-f64a-46f4-9e5d-44efebebe748';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз «Жоқ» сөзінің күшін енді түсінді! Бұл кезеңде ол бәріне қарсылық білдіріп, өз шекарасын тексереді. Бұл қырсықтық емес, оның дербес тұлға ретінде қалыптасуы. Сіз «Жоқ» дегенде, ол әдейі сол әрекетті жасап, реакцияңызды бақылауы мүмкін. Сабыр сақтауға тырысыңыз: Сіздің эмоциялық тұрақтылығыңыз — оған ережелерді үйрететін ең жақсы бағдар.') WHERE id = 'e0c32222-756f-4ca9-8533-fb5e6a6bf334';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жүру дағдысы жетілген сайын, бөпеңіз артқа қарай жүруге немесе жүріп бара жатып қолына ойыншық ұстап жүруге талпынады. Бұл оның дене күші артып, миының қимылдарды үйлестіру қабілеті дамып келе жатқанын көрсетеді. Оған сүйреп жүре алатын дөңгелекті ойыншықтар беріңіз. Мұндай ойындар аяқ бұлшықеттерін одан әрі нығайтады.') WHERE id = '49b402b9-bb72-400d-ac9d-7af091029dd1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы "талғампаздық" кезеңі жалғасуда. Бала кеше сүйсініп жеген тағамын бүгін жерге лақтырып жіберуі мүмкін. Бұл кезеңде "қанша жеу керектігін" баланың өзіне қалдырыңыз, ал Сіз оның "қашан және не жейтінін" анықтаңыз. Дастарқан басында мәжбүрлемей, жайлы көңіл күй қалыптастырыңыз. Оның асқазаны әлі де кішкентай екенін және бірнеше түйір тағамның өзі жеткілікті болуы мүмкін екенін ұмытпаңыз.') WHERE id = '853086ca-90b3-4556-bd83-70b66fd42f49';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы алғашқы "қарама-қарсы ұғымдар". Ол енді "үлкен-кіші", "ыстық-суық" сияқты айырмашылықтарды көру және қолмен ұстап сезу арқылы түсіне бастайды. Ойын кезінде "Қарашы, мынау үлкен доп, ал мынау кішкентай" деп салыстырып көрсетіңіз. Осындай қарапайым диалогтер оның абстрактілі ойлау қабілетін дамытып, сөздік қорын жылдам молайтады.') WHERE id = '8381dd6a-9188-4a53-b0c0-fe9e5722bee4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Ажырасудан қорқу" (Separation anxiety) осы айларда қайтадан толқын тәрізді пайда болуы мүмкін. Сіз бөлмеден шыққанда оның жылауы — Сізге мұқтаж екенінің белгісі. Кетер алдында әрдайым "Сау бол, мен жақында қайтып келемін" деп айтыңыз және білдіртпей кетіп қалмаңыз. Сіздің шынайылығыңыз оның бойында "анам көзден таса болса да, міндетті түрде қайтып келеді" деген сенімді нығайтады.') WHERE id = 'd51eadcf-ced3-43a7-a954-d65ad8f07d93';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы жаңа қадам: қақпақтарды ашу және жабу. Бос пластик ыдыстар мен олардың қақпақтары бала үшін ең қызықты "басқатырғышқа" айналуы мүмкін. Қақпақты орнына дұрыс салу үшін саусақ қимылдары мен зейінін үйлестіруі оның миында жаңа нейрондық байланыстар қалыптастырады. Оған осы қарапайым асүй заттарымен ойнауға рұқсат етіңіз.') WHERE id = '6e7fc713-da58-436a-956b-2725c7ebe15b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өз сезімдерін қимыл-қозғалыс арқылы көрсете алады: айқайлау, жерге жата кету немесе Сізді құшақтау. Бұл оның эмоцияларын реттеу қабілеті әлі толық дамымағанын білдіреді. Ол ашуланғанда жанына отырып, онымен бір деңгейде болыңыз да, "Сен қазір ашуланып тұрсың, түсінемін" деп сезімін атап айтыңыз. Бұл болашақта оның өз эмоцияларын басқара білуіне негіз қалайды.') WHERE id = '49f6d0be-6454-4212-a7b3-56294a93638b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тіс жару кезінде (әдетте осы кезеңде азу тістері шығуы мүмкін) сілекейдің көп бөлінуі және қызыл иектің ауыруы байқалуы ықтимал. Бұл оның ұйқысы мен тамақтану тәртібіне әсер етуі мүмкін. Оған тіс қаситын ойыншықтар немесе шайнауға болатын салқын жеміс тілімдерін беріңіз. Сіздің мейіріміңіз бен шыдамдылығыңыз оның осы ауыр кезеңді жеңілірек өткізуіне көмектеседі.') WHERE id = '48e458f5-c261-485d-bb67-d4e81e9a6931';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы кезінде "белсенді қимылдар" болуы мүмкін. Балаңыз ұйықтап жатып аунап, орнын ауыстыруы немесе кенеттен отырып қалуы мүмкін. Оның миы күндіз үйренген жаңа қимылдарының бәрін ұйқы кезінде "жаттықтырады". Егер жыламаса, араласпаңыз. Өзіне ыңғайлы қалып тауып, ұйқысын жалғастыра берсін.') WHERE id = '5ccc44b7-6be9-42e8-9051-5aba385dfbb3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 13-айдың ортасына жеттіңіз! Балаңыз қарапайым өтініштерді толық түсінеді, тіпті Сізге "көмектескісі" келеді (мысалы, ойыншықты қорапқа салу). Оның бұл ынтасын баспаңыз, әрбір кішкентай көмегін қуана мақтаңыз. Сіздің қолдауыңыз оның болашақта жауапкершілігі жоғары әрі өзіне сенімді адам болып қалыптасуына көмектеседі. Сіз керемет анасыз!') WHERE id = '2f2ae51c-beef-4df3-9d10-cb7325ea4331';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз қасықты бұрынғыдан да шебер қолдана бастады. Иә, тамақтың бір бөлігі әлі де жерге төгіледі, бірақ ол білек қимылдарын әлдеқайда жақсы басқарады. Оған өз бетінше тамақтануға көбірек мүмкіндік беріңіз. Тойғанын сезіп, тамақты әрі итеруі оның ағзасындағы ашығу мен тоқтық белгілеріне құлақ асатынын көрсетеді. Бұл болашақта дұрыс тамақтану әдеттерін қалыптастыру үшін өте маңызды.') WHERE id = '45554d06-2e09-4223-93a8-104614df2f0c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз енді саналы түрде "көмектесуге" тырысады. Мысалы, ойыншықтарын қорапқа жинайды немесе Сізге бір нәрсе ұсынады. Бұл — оның әлеуметтік жауапкершілік сезімінің алғашқы белгілері. Ол бір нәрсе әкелген сайын: "Көп рақмет, маған көп көмектестің", — деңіз. Мұндай мақтау оның өзін қажет әрі қабілетті сезінуіне көмектеседі.') WHERE id = '5614d8e1-6798-45a7-8bfd-239e88293a49';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жаңа қорқыныштардың пайда болуы: 13-14 айлық балалар кенеттен шаңсорғыштың дыбысынан, қараңғылықтан немесе бейтаныс адамдардан қорқа бастауы мүмкін. Бұл оның қиялының және қоршаған ортаны түсіну қабілетінің дамуымен байланысты. Оның қорқынышына күлмеңіз, "мұнда қорқатындай не бар?" демеңіз. Жай ғана жанында болып, құшақтап, қауіпсіз жерде екенін сездіріңіз. Уақыт өте келе бұл қорқыныштар басылады.') WHERE id = '320f797a-413e-4747-8432-a77c70f8f1ae';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Пинцеттік ұстау" қабілетінің дамығаны соншалық, балаңыз кітап беттерін (әзірге қалың беттерін) бір-бірлеп аудара алады. Бұл оның ұсақ моторикасын дамытып қана қоймай, кітапқа деген қызығушылығын да арттырады. Оған түрлі түсті, үлкен суреттері бар кітаптарды оқуды жалғастырыңыз. Суреттен көрген затын атауды сұрап, сөйлеу қабілетін ынталандырыңыз.') WHERE id = '3f0fc8bf-420a-4d0f-acf7-ab2d58fa2a4b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '14-айға қош келдіңіз! Бұл айда балаңыз физикалық жағынан да, эмоциялық тұрғыдан да көбірек "дербестікке" ұмтылады. Ол енді қайда барғысы келетінін және нені жегісі келмейтінін анық көрсетеді. Бұл — оның тұлғалық дамуының маңызды кезеңі. Күні бойы оған шағын таңдау мүмкіндігін беріңіз (мысалы, "алма жейсің бе, әлде алмұрт па?"). Таңдау мүмкіндігі оның қарсылығын азайтып, өзіне деген сенімін арттырады.') WHERE id = '05712130-29d6-4028-9cd7-1eeae1f8b5f6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз заттарды бірінің үстіне бірін қоюды (текшелерден мұнара құрауды) барған сайын ұқыпты орындайды. Бұл жай ғана ойын емес: ол тартылыс күшін, тепе-теңдікті және кеңістіктегі байланыстарды зерттеп жүр. Мұнара құлаған кезде, ол "себеп-салдар" байланысын түсінеді. Оған әртүрлі өлшемдегі және түстегі текшелер беріп, осы маңызды танымдық үдерісті қолдаңыз.') WHERE id = '0c30df46-8b8a-4974-a5d4-fa643bc0045f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сөздік серпіліске" дайын болыңыз! Балаңыз енді күн сайын жаңа дыбыстарды немесе сөздерді үйренеді. Ол айналасындағы заттарды саусағымен көрсетіп, Сіздің олардың атауын айтқаныңызды күтеді. Сіз әр заттың атауын айтқан сайын, оның пассив сөздік қоры (түсінетін сөздері) белсенді сөздік қорына (айтатын сөздеріне) қарағанда жылдамырақ өседі. Онымен үнемі сөйлесіңіз — бұл оның сөйлеуін дамытудың ең тиімді тәсілі.') WHERE id = '462a5499-02c0-46d8-9b87-781f37471081';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Менікі!" кезеңі басталады. Бала өз ойыншықтарын немесе заттарын басқаларға беруден бас тартуы мүмкін. Бұл — оның "меншік" ұғымын түсіне бастағанының алғашқы белгісі. Оған "бөлісуің керек" деп қысым жасамаңыз, өйткені ол бөлісудің не екенін әлі толық түсінбейді. Оның орнына кезекпен ойнауды ("қазір сенің кезегің, содан кейін әкеңнің кезегі") көрсетіп, әлеуметтік ережелерді үйретіңіз.') WHERE id = 'bf0454b9-f968-4795-a96d-a48966050e5d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігі: Балаңыз енді баспалдақпен көтерілуге талпынады (көбіне еңбектеп немесе Сіздің қолыңыздан ұстап). Бұл оның аяқ бұлшықеттерін де, қимыл үйлесімділігін де нығайтады. Баспалдақта әрдайым жанында болыңыз және қауіпсіздік қақпаларын пайдалануды ұмытпаңыз. Әр басқышқа көтерілуі ол үшін үлкен бір "жеңіс"!') WHERE id = '6d0b9b84-0a2e-4b5d-941c-44ac3c78711f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өздігінен тамақтанудағы келесі қадам: Балаңыз енді стақаннан суды төкпей дерлік іше алады. Ашық стақаннан ішу оның ерін және тіл бұлшықеттерін сөйлеуге дайындайды. Егер әлі де емізігі бар бөтелкені қолдансаңыз, одан толық бас тартатын уақыт келді. Бұл тістердің дұрыс қалыптасуы мен таңдай саулығы үшін өте маңызды.') WHERE id = '59bb00a9-cd0f-4293-859e-3a1c2a23e167';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «буындарды біріктіру»: Балаңыз енді әртүрлі буындарды біріктіріп, өз тілінде ұзақ «сөйлемдер» құрайды. Оның сөздерін толық түсінбесеңіз де, ол ересектердің сөйлеу мәнерін керемет қайталайды. Оны мұқият тыңдап, «Иә, солай ма? Содан кейін не болды?» деп жауап беріңіз. Мұндай «диалог» оның өз ойын жеткізуге деген ынтасын арттырып, миындағы сөздік қорын байытады.') WHERE id = '71d396d7-4d37-40f4-a3f7-9c1e6ac427ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы дербестік: Балаңыз енді балаларға арналған қауіпсіз шанышқыны өзі қолдануға талпынады. Жұмсақ жеміс немесе көкөніс бөліктерін шанышқыға шаншуға тырысу оның қол мен көз үйлесімін айтарлықтай дамытады. Үстел үсті сәл шашылып қалса да, оған осы мүмкіндікті беріңіз. Бұл оның қимыл-қозғалыс дағдыларының дамуына да, тамаққа деген оң көзқарасының қалыптасуына да ықпал етеді.') WHERE id = '333db3d2-14f1-4e63-a2dd-abc9df47ccf2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «санаттар»: Балаңыз енді түсі немесе түрі бірдей заттарды ажырата бастайды. Оған әртүрлі доптарды немесе мәшинелерді көрсетіп, «Басқа доп қайда?» деп сұраңыз. Ол ұқсастықтарды таба бастайды. Бұл — оның логикалық ойлауының негізі. Онымен бірге үйдегі заттарды түсіне немесе өлшеміне қарай топтастыру ойынын ойнаңыз.') WHERE id = 'e2b8df1f-c1e3-4ba1-a168-83dfc3901148';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік дағдылардағы «көмекшілдік»: Балаңыз Сізге еліктеп, бір нәрсені сүрткісі немесе әкелгісі келсе, оған шағын «тапсырмалар» беріңіз. Мысалы: «Маған мына майлықты бере қойшы». Ол Сізге көмектесіп жатқанын сезінгенде, өзін ересек әрі қажет тұлға ретінде қабылдайды. Бұл оның бойында болашақта жауапкершілік сезімі мен ынтымақтастық дағдысының қалыптасуы үшін өте маңызды.') WHERE id = 'dec6a9fe-e431-4948-b5e9-cde4811493c1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуы: Балаңыз енді бір орында секіруге немесе музыка әуенімен тізесін бүгіп билеуге талпынады. Бұл оның тепе-теңдік сезімін де, ірі моторикаға жауап беретін бұлшықеттерін де нығайтады. Онымен бірге билеп, қимылдарын қайталаңыз. Бұл әрі дене жаттығуы, әрі араларыңыздағы эмоциялық байланысты нығайтатын ең көңілді әрекет.') WHERE id = 'f2ba7880-c8a0-44c4-9683-adcae62249c7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістікті қабылдау» және конструкторлар: Балаңыз енді текшелерді жай ғана бірінің үстіне бірін қоймай, олардан «қабырғалар» немесе қарапайым пішіндер құрастыруға тырысады. Оған өлшемдері әртүрлі конструктор бөлшектерін беріңіз. Мұндай ойындар оның шығармашылығын да, мәселені шешу қабілетін де дамытады. Мұнара құлап қалғанда күліп, «Қане, тағы бір рет жасап көрейік!» деуіңіз оны сәтсіздіктен қорықпауға үйретеді.') WHERE id = '3bcda1a7-5185-49d5-9cff-a4657ec214ad';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз музыка естігенде денесін ырғаққа сай қимылдатып немесе қол шапалақтай бастады. Ырғақты сезіну мидың математика мен тілге жауап беретін орталықтарымен тығыз байланысты. Онымен бірге би билеп, қол шапалақтап, әртүрлі ырғақтарды қайталаңыз. Бұл әрі дене белсенділігі, әрі араларыңыздағы эмоциялық байланысты нығайтатын көңілді әрекет.') WHERE id = '22fc8a33-8e0b-4e79-86f9-460a94db933b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік қарым-қатынастағы "эмпатияның" алғашқы белгілері: Сіз мұңайып отырсаңыз немесе аяғыңызды бір жерге соғып алсаңыз, балаңыз жаныңызға келіп, Сізге қолын тигізуі, құшақтауы немесе өз ойыншығын ұсынуы мүмкін. Бұл оның өзге адамдардың сезімдерін түсіне бастағанын көрсетеді. Оның мұндай жанашыр әрекетіне "Көп рақмет, сен өте мейірімдісің" деп жауап беріңіз. Жанашырлық сезімінің негізі дәл осы жаста қаланады.') WHERE id = '993a5a5e-046b-489d-bd9d-9580428e1cdc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Кеңістіктік жады" және іздеу: Балаңыз енді сүйікті ойыншығының қайда жасырылғанын біледі. Онымен күрделірек "жасырынбақ" ойындарын ойнаңыз. Мысалы, ойыншықты қораптың ішіне салып, үстін орамалмен жабыңыз. Кедергілерден өтіп, ойыншықты табуы оның мәселені шешу қабілетін дамытады. Осындай кішкентай "жеңістер" оның өзіне деген сенімін арттырады.') WHERE id = '63dfa4ff-f8c9-4a30-bd0e-f8d086dd0898';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздік туралы ескерту: Балаңыз енді диванға, орындыққа, сөреге — кез келген жерге өрмелегісі келеді... Ол биіктік пен қауіп-қатерді әлі толық түсінбейді. Ауыр жиһаздардың қабырғаға мықтап бекітілгеніне және баспалдақтарда қорғаныш қақпалары орнатылғанына көз жеткізіңіз. Оның айналаны зерттеуге деген құштарлығын шектемей, қауіпсіз орта қалыптастыру маңызды.') WHERE id = 'cc4b37ce-4e2e-4d58-a313-414b2395c5eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "қайталау" кезеңі. Балаңыз Сіз айтқан сөздердің соңғы буындарын қайталауға тырысуы мүмкін. Мысалы, Сіз "су" десеңіз, ол "у" немесе "су" деуі мүмкін. Онымен әрдайым дұрыс әрі анық сөйлесіңіз. "Би-би", "ням-ням" сияқты сәбилерге тән сөздердің орнына заттардың нақты атауларын айту оның сөздік қорының дұрыс қалыптасуына көмектеседі.') WHERE id = 'd1034aae-153e-40ef-b35f-875a226037db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 13 айды аяқтадық! Балаңыз енді "toddler" (жүре бастаған бала) ретінде өз қалауын, мінезін және сүйіспеншілігін толық көрсете бастады. Бүгін онымен бірге еденге жайғасып, өзі таңдаған ойынды ойнап, уақыт өткізіңіз. Онымен өткізген әрбір сапалы сәтіңіз — оның болашақ бақытының негізі. Сіз керемет анасыз!') WHERE id = '4d58b019-ad51-4763-b775-1cff7a5c244e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «шимайлау» өнері! Балаңыз енді қарындашты ұстап, қағазға нық сызықтар сыза алады. Бұл — оның қол-көз үйлесімділігі мен жазуға дайындық дағдылары дамуының ең алғашқы кезеңі. Оған балаларға арналған жуан, қауіпсіз қарындаштар мен үлкен қағаздар беріңіз. Оның алғашқы «шығармашылық туындыларын» мақтаңыз, бұл өнерге деген қызығушылығын арттырады.') WHERE id = '32044af7-f666-4ab4-a029-c8309f8e7a1b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «еліктеу» енді күрделене түседі. Ол тек Сізге ғана емес, көрген басқа балаларға, тіпті теледидардағы кейіпкерлерге де еліктеуі мүмкін. Сіз үй жинағанда, ол да бір нәрсені сүрткісі келеді, ал тамақ дайындағанда, ол да араластырғысы келеді. Оған ойыншық сыпырғыш немесе пластик ыдыстар беріп, «үй шаруасына» қатыстырыңыз. Бұл оның бойында жауапкершілік сезімін қалыптастырады.') WHERE id = '0d48495d-8dfc-4d4f-a65f-4e2b54b5955c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқы кезінде «ұйқы регрессиясы» (ұйқының бұзылуы) болуы мүмкін. Бұған көбіне жаңа дене қимылдары (жылдамырақ жүру, өрмелеу) немесе Сізден бөлінуге байланысты мазасыздықтың күшеюі себеп болады. Егер балаңыз түнде оянып, Сізді шақырса, жанына жайлап барып, қолыңызға алмай-ақ тыныштандырыңыз және қайта ұйықтауына көмектесіңіз. Күн тәртібін тұрақты сақтау бұл уақытша кезеңді жеңілдетеді.') WHERE id = '15f626ab-5c76-4c8c-ba7f-675666d5bc7d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 400 күнді артқа тастадық! Бұл — таңғаларлық көрсеткіш. Балаңыз енді жай ғана «бөпе» емес, өз ойы, мінезі және күлкісі бар отбасыңыздың тең құқылы әрі ең белсенді мүшесі. Бүгін онымен бірге сүйікті саябағына серуендеуге шығып, әлемді зор қызығушылықпен танып-білуін бақылаңыз. Сіз оның осы жолдағы ең мықты тірегі әрі ең мейірімді ұстазысыз. Жарайсыз, ана!') WHERE id = 'cc5a3ed7-bfca-476b-b299-2377ba4200f3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Міне, 400 күндік үлкен белестен де өттік! Осы күндері балаңыз киімін (мысалы, бас киімін немесе шұлығын) өзі шешуге талпынуы мүмкін. Бұл — өзіне-өзі қызмет көрсету дағдыларының алғашқы қадамы. Егер ол бір нәрсені өзі кигісі немесе шешкісі келсе, асықтырмай, жеткілікті уақыт беріңіз. Бір нәрсені өз бетімен істей алғанын көру оның өзін-өзі бағалауын (self-esteem) бәрінен де көбірек арттырады.') WHERE id = 'c405a38b-5463-4f2f-a8fe-555b36296982';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз «функционалдық ойын» кезеңінен «символдық ойынның» алғашқы белгілеріне өте бастады. Ол ойыншық қонжығын «тамақтандыруы» немесе қуыршағын ұйықтатуы мүмкін. Бұл оның қиялы мен жанашырлық сезімі дамып келе жатқанын көрсетеді. Мұндай ойындарға Сіз де қосылыңыз: «Қонжықтың қарны ашты ма? Кел, оған аздап пюре берейік». Осындай ойындар оның әлеуметтік және танымдық дамуын жеделдетеді.') WHERE id = 'a392702d-a437-4a73-9212-0aa4a4ef5685';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Түнгі ұйқыдағы «регрессия» немесе қорқыныштар: 14-айда кейбір балалар қараңғылықтан немесе жалғыз қалудан қорқа бастауы мүмкін. Бұл оның танымдық дамуының және айналасындағы ортаны тереңірек түсіне бастауының нәтижесі. Ұйықтар алдындағы әдеттеріңізді (ертегі оқу, бесік жырын айту) өзгертпей сақтаңыз. Сіздің сабырлы әрі сенімді даусыңыз оған «бәрі жақсы, сен қауіпсіз жердесің» дегенді сездіреді.') WHERE id = 'eff64bbb-3777-4339-9e6a-476beebba20d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 410 күн артта қалды! Балаңыз енді күн сайын Сізге жаңа тосынсый жасайды: бірде жаңа сөз айтады, бірде жаңа қимыл үйренеді. Бүгін онымен бірге еденге жатып, өзі таңдаған ойынды ойнап уақыт өткізіңіз. Сіздің оның әлеміне енуіңіз — ол үшін ең үлкен бақыт. Сіз бұл жолды шыдамдылықпен және сүйіспеншілікпен жүріп келе жатқан керемет анасыз!') WHERE id = '21628582-4016-4734-a5cc-d731fc576c16';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз «Жануарлардың дауыстары» әлеміне толықтай еніп кетті. Оған «Ит қалай дыбыстайды?» немесе «Мысық қалай дыбыстайды?» деген сұрақтар қойыңыз. Бұл дыбыстарға еліктеу сөйлеу аппаратын (тіл мен ерін бұлшықеттерін) болашақта күрделі сөздерді айтуға дайындайды. Жануарлардың суреттері бар кітаптарды қарап отырып, осындай диалогтерді көбірек құрыңыз; суреттегі жануарды тауып, оның дауысын салуын сұраңыз.') WHERE id = '1ba32438-5f06-49eb-a326-d4e6c5037f1b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз өздігінен бұрынғыдан да сенімді жүре бастады. Енді ол тұрған жерінде бұрылуды, артқа қарай қадам басуды немесе жүріп келе жатып еңкейіп, жерден ойыншық алуды үйреніп жүр. Бұл — тепе-теңдікті сақтауға арналған күрделі жаттығу. Оған кедергілерден (жастықтар, кішкентай қораптар) өту тапсырмасын беріңіз. Мұндай физикалық кедергілер оның жалпы моторикасын да, мәселені шешу қабілетін де дамытады.') WHERE id = '67533bf8-42c4-4684-8990-79465e5ffca9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Атау» кезеңі: бала енді дене мүшелерін (мұрын, көз, ауыз) көрсете алады. Шомылдырғанда немесе киіндіргенде «Енді оң қолыңа киеміз», «Бұл — сенің кішкентай мұрның» деп, әр әрекетті дауыстап айтып отырыңыз. Бұл оған өз денесінің құрылымын түсінуге және сөздік қорындағы сөздерді көзбен көретін нысандармен сәйкестендіруге көмектеседі.') WHERE id = '616b6164-3d66-4e8e-8eaa-1c418d285de7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Себеп-салдар» байланысын көрсететін ойындарға басымдық беріңіз. Мысалы, түймесін басқанда дыбыс шығаратын ойыншықтар немесе қақпағын ашқанда ішінен бірдеңе шығатын қораптар. Бала өзінің бір әрекеті қоршаған ортада өзгеріс тудыратынын түсінеді. Бұл жаңалық оның бойында «әлемге ықпал ете аламын» деген сезім мен өзіне деген сенімді қалыптастырады.') WHERE id = '8d3ed7f3-9547-466c-ba26-2f33141101eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Баланың есте сақтау қабілеті енді оқиғаларды ұзақ уақыт бойы сақтай алады. Ол Сіз бірнеше сағат (тіпті бірнеше күн) бұрын жасырған ойыншықтың орнын есіне түсіріп, тауып алуы мүмкін. Онымен «жоғалған затты тап» ойынын ойнаңыз. Бұл оның есте сақтау қабілетін де, көзбен іздеу дағдысын да дамытады. Тапқан кезде жетістігіне қуана білуі үшін оны ықыласпен мақтаңыз.') WHERE id = '41a34496-6a48-46a1-9bab-58d653fd4147';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өз бетінше киінуге талпынысы арта түседі. Бала енді аяқкиімін киюге, басына баскиімін қоюға немесе шалбарының балағын тартуға тырысады. Мұндай талпыныстарына кедергі жасамаңыз және асықтырмаңыз. Тіпті киімін теріс киіп алса да, «Өзің киіндің, жарайсың!» деп айтыңыз. Бұл — оның дербестігінің алғашқы негізі.') WHERE id = '114533c6-2065-42b8-8349-baf02171f30b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «сөз тіркестерінің» бастапқы кезеңі: бала енді екі сөзді қатар айтуға талпынуы мүмкін (мысалы, «Әке, жүр» немесе «Су бер»). Егер ол әлі сөздерді біріктірмесе, оған үлгі көрсетіңіз. Ол «Мәшине» десе, Сіз «Иә, үлкен мәшине» деп сөзін толықтырыңыз. Бұл оның миында грамматикалық құрылымдардың қалыптасуына көмектеседі.') WHERE id = '66c20a78-018b-46e0-a413-b9d7d652fd0b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: бала қолына бір нәрсе ұстап жүре алатынына сенімді бола түседі. Ол бір мезетте жүріп, ойыншығын Сізге көрсете алады. Оған арнап «кедергілер жолағын» жасаңыз: едендегі жастықтарды айналып өту немесе аласа қораптан аттап өту. Бұл оның тепе-теңдігін де, өз денесін сезіну және басқару қабілетін де (проприоцепция) нығайтады.') WHERE id = '9f5b4f9d-6c12-455d-adaa-8991ef34a4ef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім таңдаймын!» кезеңі. Киім немесе тағам таңдағанда балаға қауіпсіз екі нұсқа ұсыныңыз. Мысалы: «Көк шұлығыңды кигің келе ме, әлде қызылын ба?». Бұл тәсіл балаға жағдайды өзі басқарып тұрғандай сезім береді және алдағы уақытта туындауы мүмкін «қырсығу ұстамаларының» алдын алуға көмектеседі. Таңдау жасау — шешім қабылдау дағдысының негізі.') WHERE id = '3e2f13ff-1204-4de3-91f9-ba0a61eced52';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моториканы дамытатын «Сұрыптау» ойындары. Бала енді текшелерді түсіне немесе өлшеміне қарай ажырата бастауы мүмкін. Оған әртүрлі түсті ыдыстар беріп, түсі бірдей ойыншықтарды тиісті ыдыстарға салуды көрсетіңіз. Бұл ойын оның логикалық ойлауын да, түстерді қабылдау қабілетін де жылдам дамытады.') WHERE id = '1833bec9-62a3-4273-aaa3-6cb2d5b43918';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезінде бала отбасы дастарқанындағы тағамдардың барлығын дерлік (тұзы аз әрі қоспасыз болса) жей алады. Оған өзінің кішкентай шанышқысы мен қасығын беріп, өз бетінше тамақтануына мүмкіндік беріңіз. Тағамды қолымен ұстап, құрылымын сезінуі оның ас талғампаздығын азайтады. Айналаның былғануы қалыпты жағдай, ең бастысы — баланың өздігінен тамақтану дағдысын қалыптастыруы.') WHERE id = '724fdd08-1982-44c9-81ad-e2e9e494133c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Тізу" дағдысы: Бала енді ірі моншақтарды жіпке тізуге (міндетті түрде бақылаумен!) немесе сақиналарды пирамидаға кигізуге тырысады. Бұл әрекеттер саусақ бұлшықеттерінің үйлесімділігін айтарлықтай дамытады. Оған түсі мен пішіні әртүрлі сақиналарды беріп, түстері мен өлшемдерін де (үлкен-кіші) дауыстап айтып отырыңыз.') WHERE id = '9a5df16b-402c-4293-a449-95f97975e102';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Еліктеу" енді саналырақ бола түседі. Сіз телефонмен сөйлескенде, ол да қолына бір зат алып, құлағына тақайды, ал Сіз шашыңызды тарағанда, ол да соған ұқсас әрекет жасайды. Бұл — баланың күнделікті өмірдегі әдеттерді үйрену тәсілі. Оған қауіпсіз тұрмыстық заттармен (пластик тарақ, ойыншық телефон) ойнауға рұқсат беріп, айналадағы әлемді танып-білуіне көмектесіңіз.') WHERE id = 'ffb2b034-66cc-4cea-967c-b8e6e4f363c4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Кітап оқу енді интерактивті әрекетке айналды. Бала парақтарды өзі аударғысы келеді және суреттен таныс заттарды көргенде қуанады. Одан "Мұнда мәшине қайда?" деп сұрағанда, саусағымен көрсетуі оның көру жады мен зейінінің қаншалықты дамығанын білдіреді. Күн сайын кешке бірнеше минут кітап оқуды әдетке айналдырыңыз.') WHERE id = 'c199a72c-c2fe-4afe-b5cc-41415b0a5808';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қауіпсіздік туралы ескерту: Бала қазір өрмелеуге өте әуес. Ол орындықтарды баспалдақ ретінде пайдаланып, үстелдің үстіне шығып кетуі мүмкін. Үйдегі барлық ауыр жиһаздың қабырғаға мықтап бекітілгеніне және өткір бұрыштардың қорғалғанына көз жеткізіңіз. Сіз де оны алаңдамай сырттай бақылай алуыңыз үшін баланың еркін қимылдауына қауіпсіз орта жасалуы керек.') WHERE id = '4ee9c2b3-c8ac-4ff5-98d9-426713c0d86e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дамудағы "Ерік-жігерді сынау": Бала қалағаны болмаған кезде жылап немесе жерге жата қалып, қарсылық білдіруі мүмкін. Бұл кезеңде онымен дауласпай, назарын басқа қызықты нәрсеге аудару тиімдірек. Сабырлы дауыспен "Сен қазір ашуланып тұрсың, бірақ ойыншықты қайтару керек" деп, оның сезімін атап беріңіз. Сіздің сабырлылығыңыз — ол үшін ең жақсы үлгі.') WHERE id = '3cd65486-2777-46ac-9963-b43596b260f8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта «эмпатия» арта түседі. Бала басқа баланың жылағанын көргенде алаңдауы немесе Сізге жақындап, құшақтауы мүмкін. Бұл оның өзгелердің сезімін түсіне бастағанын көрсетеді. «Иә, досың қазір сәл мұңайып тұр» деген сияқты сөйлемдермен оның осы сезімдерін атап отырыңыз. Сезімдерді тану — эмоциялық интеллектінің алғашқы баспалдағы.') WHERE id = 'da7ee871-54fe-4caf-9b11-def1fe5482db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезінде «құралдарды қолдану». Бала балаларға арналған шанышқыны (пластик/жұмсақ) тағамға шаншуды жақсырақ меңгере бастады. Оған шанышқымен шаншуға болатын жұмсақ банан немесе піскен сәбіз кесектерін беріңіз. Бұл әрекет қол қимылдарының үйлесімділігін дамытып қана қоймай, тамақтануды бала үшін қызықты «шеберлік сынағына» айналдырады.') WHERE id = '451ba512-8b9d-44f7-915a-a7f1ea152f7c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Pretend play» (кейіпке еніп ойнау). Бала бос кеседен «су ішкендей» әрекет жасауы немесе ойыншық мәшинесін жүргізіп, «вж-ж-ж» деп дыбыс шығаруы мүмкін. Оның ойынына қосылыңыз: «Мәшине қайда бара жатыр? Дүкенге ме?». Бұл оның шығармашылығын да, оқиғалар арасындағы логикалық байланысты түсінуін де дамытады.') WHERE id = '58538226-5b39-4731-8bc6-1e9881002e44';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ерік пен шекаралар: бала «Болмайды» деген сөзге жауап береді, бірақ кейде сол әрекетті әдейі жасап, Сізге қарап тұруы мүмкін. Осылайша ол Сіздің шыдамдылығыңызды және ережелердің өзгермейтінін тексереді. Сабырлы, бірақ нық болыңыз. Бірде «болмайды» деген нәрсеге басқа жолы рұқсат бермеңіз — сонда ережелер оның санасында анық қалыптасады.') WHERE id = 'ccb50bdf-5e11-4253-a1c0-79b7eb2fe4d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз артқа қарай жүруді немесе бір орында айналуды үйреніп алды. Бұл қимылдар оның тепе-теңдік сезімі мен дене үйлесімділігін жаңа деңгейге көтереді. Оған кедергісі жоқ кең жерде осы жаңа дағдыларын байқап көруге мүмкіндік беріңіз. Денесін басқару қабілеті артқан сайын, өзіне деген сенімі де нығая түседі.') WHERE id = '527b5771-2c14-44f3-9a1f-7d0335d59d5a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «ниет» сөздері: бала енді заттарды жай ғана атап қоймай, қалауын да бір сөзбен білдіреді. Мысалы, Сізге қарап «Есік» деуі «Сыртқа шыққым келеді» дегенді білдіруі мүмкін. Оның осындай өтініштеріне ойын кеңейте отырып жауап беріңіз: «Иә, сен есікті көрсетіп тұрсың ба? Жүр, аулаға (ад-да) барайық». Бұл оның қарым-қатынас жасауға деген ынтасын арттырады.') WHERE id = '1b9f532e-6857-454f-9361-0a20bbd28a5f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Баспалдақпен көтерілу енді оның ең қызықты ісіне айналды. Ол баспалдақпен еңбектеп немесе қолынан ұстап тұрғанда аяғымен көтеріле алады. Бұл қимыл ірі моторикасын нығайтып қана қоймай, биіктікті сезінуді де үйретеді. Баспалдақтың басында әрдайым жанында болыңыз және үйдегі қауіпсіздік қоршауларының жабық тұрғанына көз жеткізіңіз.') WHERE id = '74e3ddee-b891-4ccd-91d8-7ed95452703e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз қағазға "шимайлап" сурет салғанда, сызықтарды бұрынғыдан сенімдірек жүргізеді. Ол дөңгелек қимылдар жасап немесе түзу сызықтар салып көруі мүмкін. Оған үлкен қағаздар мен алақанына ұстауға ыңғайлы, жуан әрі уытсыз қарындаштар беріңіз. Бұл — болашақта жазу дағдысы мен қол-көз үйлесімін дамытудың аса маңызды негізі.') WHERE id = '4d091261-3f36-4fe5-bf63-cb391c17abb5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзім істеймін!" кезеңі: Балаңыз енді қолын жууға, тісін тазалауға (әзірге щетканы шайнаумен ғана) немесе үстелді сүртуге ұмтылады. Оның тазалық дағдыларына деген қызығушылығын қолдаңыз. Қолы жетуі үшін шағын басқыш (step stool) қойып, қимылдарыңызды қайталауына мүмкіндік беріңіз. Бұл оның өзіне-өзі қызмет көрсету дағдыларын қалыптастырады.') WHERE id = '1d418a62-b096-44ed-98d7-1fbf38ca6e83';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ойындардағы "Еліктеу" күрделене түседі. Сіз үй сыпырғанда, ол да бір нәрсені алып, сыпырғысы келеді. Оған балаға лайық шағын "тазалық құралдарын" беріңіз. Үй шаруасына осылай "көмектесуі" оның өзін отбасының пайдалы мүшесі ретінде сезінуіне мүмкіндік береді әрі жауапкершілік сезімін қалыптастырады.') WHERE id = '9c0e73ce-723f-4070-afbc-322de1ae0633';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Конструкторлар": Балаңыз енді 3-4 текшені (блокты) бірінің үстіне бірін қойып, "мұнара" тұрғыза алады. Бұл зейінді шоғырландыруды да, дәлдікті де қажет етеді. Мұнара құлаған кезде көңілді реакция білдіріңіз, сонда ол сәтсіздікті ойынның бір бөлігі ретінде қабылдайды. Бұл оның мәселе шешу қабілеті мен қайта талпынуға деген ынтасын арттырады.') WHERE id = '80068b19-aaa1-4996-ba9d-5b3777ebce0c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Музыка және ырғақ: Балаңыз енді әртүрлі ырғақтарға түрлі қимылмен жауап береді. Жылдам музыка қосылғанда белсендірек қимылдайды, ал баяу музыка кезінде тербеледі. Онымен бірге "ырғаққа ілесу" ойындарын ойнаңыз – қол шапалақтап, аяқтарыңызды еденге тарсылдатыңыз. Бұл оның есту қабілетін де, дене қимылдарының үйлесімділігін де керемет дамытады.') WHERE id = '83fcfed7-5b83-4a68-8d79-7654a496f70e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезінде балаңыз дербестікке көбірек ұмтылып, қасыққа тамақты өзі салуды жақсырақ меңгеріп келеді. Оған шанышқымен түйреуге ыңғайлы шағын кесектер ұсыныңыз. Өздігінен тамақтану оған тойғанын сезінуге және құрылымы әртүрлі тағамдарға қызығушылық танытуға көмектеседі.') WHERE id = '369e5ef8-dd84-4005-92a0-3547d1d81f03';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Балаңыз енді Сіз "жоқ" дегенде, реакцияңызды тексеру үшін сол әрекетті әдейі қайталауы мүмкін. Бұл кезеңде сабырлы әрі нық болу өте маңызды. Егер бір нәрсеге "болмайды" десеңіз, оны әр жолы бірдей үнмен және бірдей түрде қайталаңыз. Ережелердің тұрақтылығы балада қауіпсіздік пен тәртіп сезімін қалыптастырады.') WHERE id = '3b03f902-43dc-4352-9de9-99e2a04d004c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыздың жүрісі жылдамдап, кейде жүгіруге талпынады. Алайда тепе-теңдікті сақтау қабілеті әлі толық қалыптаспағандықтан, ол жиі құлап қалуы мүмкін. Оған айналаны зерттеу үшін тегіс әрі жұмсақ жерлерді (кілем, көгал) көбірек дайындаңыз. Жүгірген кезде қолдарын екі жаққа жайып, тепе-теңдігін сақтауға тырысуы — оның физикалық дамуының табиғи бөлігі.') WHERE id = 'd5bd999f-15a8-4225-95dc-a3e29ec9bb65';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Есте сақтау қабілетінің дамуы: Балаңыз енді заттардың қай жерде тұратынын есінде сақтайды. Мысалы, аяқкиімнің дәлізде, ал ойыншықтардың қорапта екенін біледі. Одан "Аяқкиімің қайда?" деп сұрағанда, сол жаққа қарауы немесе көрсетуі танымдық қабілетінің дамып келе жатқанын білдіреді. Ойын аяқталғаннан кейін ойыншықтарды бірге орнына жинап, оның бойында жинақылық пен тәртіп дағдысын қалыптастырыңыз.') WHERE id = '821949a4-99c0-456c-ba4e-1768b6ba56ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Жануарлар мен олардың дыбыстарын ажырату". Балаңыз енді суреттен көрген жануарды танып қана қоймай, Сіз сұрамай-ақ оның дыбысын сала алады. Кітап оқығанда: "Қарашы, бұл — сиыр. Сиыр қалай дыбыстайды?" деп, диалогті жалғастырыңыз. Бұл оның есту жадын дамытып, сөздік қорын жылдам байытады.') WHERE id = 'ca9adb43-fa2c-4743-a4c9-e39c4eb29777';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Үстіне қою және тізу". Балаңыз енді 5-6 текшені бірінің үстіне бірін қойып, биігірек мұнаралар құра алады. Сондай-ақ сақиналарды үлкенінен кішісіне қарай тізуге талпынуы кеңістікті қабылдау қабілетін дамытады. Оның мұнараны құлатудан қалай ләззат алатынын көріп жүрсіз бе? Бұл — оның "мен әлемді өзгерте аламын" деген себеп-салдар түсінігінің ең көңілді көрінісі.') WHERE id = 'c50f5774-0c5b-40a4-8f99-e817382c1b20';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды жай ғана жинап қоймай, оларды түсіне қарай топтастыра бастауы мүмкін. Оған екі түрлі түсті ыдыс беріп, түсі бірдей текшелерді сәйкес ыдыстарға салуды көрсетіңіз. Бұл ойын оның көру арқылы қабылдауын және логикалық ойлауын қарқынды дамытады. Әр дұрыс таңдау жасаған сайын оны мадақтап, жігерлендіріңіз.') WHERE id = 'c99fbd76-3509-452c-bb85-8931e45ac6e6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өз бетінше киінуге талпынысы мақсатты бола түседі. Бала шұлығын тартып шешуі немесе басына бас киімін киюге тырысуы мүмкін. Оған осындай «өзіне-өзі қызмет көрсету» жаттығуларына жеткілікті уақыт беріңіз. Асықтырмай, бір нәрсені өз бетінше орындауына мүмкіндік беру оның өзіне деген сенімін (self-esteem) бәрінен де жақсы арттырады.') WHERE id = '2ee741f0-6ac8-462c-a88b-0f41a8cfe7f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Өтірік емес, шын сияқты» (Pretend play) ойындары басталады. Бала бос ойыншық кеседен су ішкендей кейіп танытуы немесе қуыршағын «ұйықтатуы» мүмкін. Бұл — оның абстрактілі ойлауының алғашқы белгілері. Оның ойындарына қосылып, жаңа сұрақтармен (мысалы, «Қонжықтың қарны ашты ма?») қиялын ынталандырыңыз.') WHERE id = 'b84b66d1-b1ba-4c15-8fdd-579e274e0daa';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене ептілігі: Бала енді тұрған орнында секіруге талпынады. Әзірге екі аяғы бір уақытта жерден көтерілмеуі мүмкін, бірақ ол тізесін бүгіп-жазу арқылы осы қимылды қайталайды. Бұл — ірі моторикаға қатысатын бұлшықеттер мен тепе-теңдік сезімін нығайтуға арналған тамаша жаттығу. Онымен бірге ырғақты музыкаға билеңіз.') WHERE id = 'd53255ec-c9a7-49ab-9a79-7b2313a09598';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап» кезеңі. Бала енді «Бұл не?» деп (немесе өз тілінде соған ұқсас дыбыс шығарып) заттарды көрсетеді. Сіз бәрін асықпай атап отырыңыз: «Бұл — қызыл мәшине», «Бұл — үлкен ағаш». Оның қызығушылығын жауапсыз қалдырмау сөздік қорының белсенді түрде молаюына көмектеседі.') WHERE id = 'd7ddb1ff-3688-4df3-8111-1494d13b6470';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қарындаш ұстау» дағдысы. Бала енді қарындашты алақанымен емес, саусақтарымен ұстауға жақындайды. Қағаз бетіне сенімдірек шеңберлер немесе сызықтар салады. Оған балаларға арналған қауіпсіз, жуан түрлі түсті қарындаштар беріп, «шығармашылық» кеңістігін ұлғайтыңыз. Бұл — болашақта жазу дағдысын меңгерудің негізі.') WHERE id = '785f6c05-389d-4b59-bf24-09d238f78a91';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезінде «Менің стақаным». Бөпе ашық стақаннан суды төкпей ішуге аз қалды. Оған балаларға арналған, төңкеріліп қалмайтын (түбі ауыр) пластик стақандар беріңіз. Суды өздігінен ішу жақ бұлшықеттерін сөйлеуге дайындап, дербестік сезімін дамытады.') WHERE id = 'cdcb59ac-ce34-4644-9101-dd165efadbd4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен» және «Сен» ұғымдарының айырмашылығын түсіну. Бөпе айнадан өзін көргенде, енді «басқа бала» деп емес, дәл өзі екенін түсініп әрекет етеді. Мұрынына кішкентай түсті белгі салып, айнаға қаратсаңыз, ол өз мұрнындағы дақты сүртуге тырысады. Бұл — оның өзіндік санасы (self-awareness) дамығанын көрсететін ең маңызды сынақтардың бірі.') WHERE id = 'e44171a6-fe71-458b-9f01-6422077e41b3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Ынтымақтастық»: Бөпе енді Сізге бір нәрсе әкелгенді, асүйде жаныңызда тұрып «көмектескенді» ұнатады. Оған шағын әрі қауіпсіз тапсырмалар беріңіз: «Мына қағазды қоқыс жәшігіне тастай аласың ба?». Сізге көмектесіп жатқанын сезінгенде, ол өзін маңызды әрі құнды тұлға ретінде сезінеді.') WHERE id = 'd9f30f7c-bdc1-4054-b9fc-312496a93a19';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: Бөпе енді диваннан еденге өздігінен түсуді (артымен сырғып) үйрене алады. Оған мұны қалай қауіпсіз жасау керегін көрсетіңіз. Биіктен өздігінен түсуді үйрену денесін басқару және қауіп-қатерді бағалау қабілетін арттырады. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз.') WHERE id = '594432bd-57c7-413f-839d-cbac2143ecbe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дағдарыстар мен «тантрумдар». Бөпе бәрін өзі жасағысы келіп, қолынан келмей қалғанда кенет ашулануы мүмкін. Бұл — оның қалауы мен физикалық мүмкіндіктерінің әлі толық сәйкес келмеуінен туындайтын күйзеліс. Мұндай сәттерде оны құшақтап, сабырлы дауыспен: «Ойыншықты жөндей алмағандықтан ашуланып тұрсың, мен сені түсінемін», — деп, оның эмоциясын атап беріңіз.') WHERE id = '52ab2a35-efc6-4dfa-ae8e-dd8d45265cbf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сөзді қайталау». Бөпе енді Сіз айтқан әр сөзден кейін өз тілінде бір нәрсе айтуға тырысады. Бұл — тіл үйренудің ең белсенді кезеңі. Оның алдында қарапайым, қысқа әрі түсінікті сөйлемдер құрыңыз. Сіз — оның сөйлеу тілінің ең басты үлгісісіз. Бүгін онымен бірге сүйікті ертегісін оқып, суреттегі жасырын бөлшектерді тауып көруге тырысыңыз.') WHERE id = '36237c33-88c9-45f0-bb2f-74a99cfea0e7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің қиындығы». Бұл жаста «менікі» деген түсінік өте күшті болады. Бала ойыншығын басқа балаға бергісі келмесе, бұл өзімшілдік емес, дамудың қалыпты кезеңі. Оны бөлісуге мәжбүрлемеңіз, оның орнына «кезекпен ойнау» қағидасын көрсетіңіз. Уақыт өте келе ол осы әлеуметтік қағиданы меңгереді.') WHERE id = '634d745d-5157-4467-b6ab-326f97a6818e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы «Ас құралдарын қолдану». Бала балаларға арналған шанышқыны тағамға (мысалы, піскен сәбізге немесе картопқа) шаншып, аузына апаруды дәлірек орындай бастайды. Бұл дағды қол мен көз қимылының үйлесімділігін нығайтып қана қоймай, өзін дербес тұлға ретінде сезінуіне де мүмкіндік береді.') WHERE id = '3cb1db52-5d88-4edb-a3ab-0984a9450809';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістікті игеру»: Бала тар жерлерден өтуді, кедергілердің астымен еңбектеуді немесе үстінен аттауды үйреніп келеді. Үйде жастықтар мен қораптардан шағын «кедергілер жолағын» жасаңыз. Бұл оған өз денесінің көлемін сезінуге (проприоцептивтік сезімдер) және қимылдарын жоспарлауға көмектеседі.') WHERE id = '2b1c5f94-7b82-40ce-9f0d-d663053b5141';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жақындық: Бала Сізге деген сүйіспеншілігін енді анық қимылдармен көрсетеді – кенеттен келіп құшақтайды немесе басыңыздан сипайды. Сіз де оған дәл сондай мейіріммен жауап беріңіз. Бұл эмоциялық қарым-қатынас оның өзін қауіпсіз әрі бағалы сезінуі үшін ең маңызды рухани нәр болып табылады.') WHERE id = 'de41f735-eeb7-4ab7-ab3c-cfc2d80548ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '16-шы айға қадам басамыз! Балаңыз енді «Әке», «Ана» сөздерінен бөлек, 5-10 түрлі сөзді саналы түрде айта алады. Ол сөздерді әлі толық әрі дұрыс айтпаса да, әрқайсысының нақты мағынасы бар. Оның әрбір талпынысын қолдап, толық айтпаған сөзін толық сөйлеммен растаңыз. Мысалы, ол «Мә» десе, Сіз «Иә, бұл мәшине» деп жауап беріңіз.') WHERE id = 'd807a9a4-6329-44cd-97d5-dae1bf4a8ff6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс дамуындағы жаңа кезең: Бала қолынан ұстасаңыз, баспалдақпен тік тұрып көтеріле алады. Бұл қимыл оның сан және жамбас бұлшықеттерін нығайтады. Баспалдақта әрқашан жанында болып, қолдау көрсетіңіз. Үйдегі баспалдақтарға кіреберісте орнатылған қауіпсіздік қоршауларының (gate) жабық екеніне көз жеткізуді ұмытпаңыз.') WHERE id = '22600f5c-8f2a-4f8d-9f3c-76e5a5fcda2c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді қарапайым тапсырмаларды орындағанды ұнатады. «Допты маған әкелші» немесе «Бас киіміңді алшы» десеңіз, ол мұны орындай алады. Бұл оның айтылған сөзді түсіну қабілетінің қаншалықты дамығанын көрсетеді. Оған шағын әрі қызықты тапсырмалар беріп, сөйлеу қабілеті мен жауапкершілік сезімін қатар дамытыңыз.') WHERE id = '44a68c23-5478-40d4-a83c-2dc9f09d429d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Менікі!» деген түсінік айқындала түседі. Бала сүйікті ойыншығын басқаға бергісі келмегенде, өз дегенінен қайтпауы мүмкін. Бұл — оның жеке шекараларын тани бастағанының белгісі. Оны бөлісуге мәжбүрлемеңіз. Оның орнына ойыншықтарды кезекпен пайдалануды («қазір сенің кезегің, содан кейін әкеңнің кезегі») көрсетіп, әлеуметтік әділдік сезімін қалыптастырыңыз.') WHERE id = '3dc015ff-56bb-4a43-b76e-ffb3ffd6a8c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моториканы жетілдіру: бала енді конструктор бөлшектерін (текшелерді) тек бірінің үстіне бірін қойып қана қоймай, оларды қатарластырып, «пойыз» немесе «жол» жасауға тырысады. Бұл оның кеңістікті қабылдау қабілетінің күрделірек деңгейге өткенін көрсетеді. Оған әртүрлі пішіндегі конструкторларды беріп, шығармашылығын ынталандырыңыз.') WHERE id = '05f48dd1-b441-4a53-83ad-213693a97b1c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы «талғампаздық» кезеңі. Бала кенеттен кейбір тағамдардан бас тартуы мүмкін. Бұл оның дәм сезу рецепторларының дамуына және өз еркін білдіруге байланысты. Оны мәжбүрлемеңіз, бірақ бас тартқан тағамын бірнеше күннен кейін басқа түрде (мысалы, езбе емес, тілім түрінде) қайта ұсыныңыз. Дастарқан басында жағымды көңіл күйді сақтаңыз.') WHERE id = '01373d24-e28a-437e-998d-4ae78f2851c2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді қағазға шимай салғанда қолын кеңірек сермеп қимылдатады. Ол қарындашты сенімдірек ұстап, кейде түстерді ажыратуға тырысады. Оған балаларға қауіпсіз жуан түрлі түсті қарындаштар мен үлкен сурет қағаздарын беріңіз. Оның осы алғашқы «өнер туындылары» қол мен көз үйлесімін дамытуға және өзін білдіруге өте құнды.') WHERE id = '10f5c993-c3c9-44f8-a870-3ed80a4cfbed';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «еліктеу» енді күнделікті істерден де көрінеді. Сіз үй жинағанда, ол да бір нәрсені сүрткісі келеді, ал тамақ дайындағанда, ол да араластырғысы келеді. Оған кішкентай шаң сүртетін шүберек немесе ойыншық сыпырғыш беріңіз. Бұл баланың өзін отбасының маңызды мүшесі ретінде сезінуіне және пайдалы дағдыларды меңгеруіне көмектеседі.') WHERE id = 'd75c2f77-0a11-4bee-830a-88006d025c3c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тепе-теңдік және үйлесімділік: Бала енді бір орында секіруге талпынады. Әзірге екі аяғы бірдей жерден көтерілмеуі мүмкін, бірақ тізесін бүгіп, серпілуі — оның ірі моторикасының дамып келе жатқанының белгісі. Онымен бірге ырғақты музыкаға билеңіз. Бұл — әрі көңілді, әрі дене дамуына өте пайдалы жаттығу.') WHERE id = '47585bf0-21b2-4948-bcc0-cc0d44631bdd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дамудағы "Қалау мен мүмкіндік" қайшылығы. Бала бір нәрсе жасағысы келіп, қолынан шықпаса, айқайлап немесе ашулануы мүмкін. Мұндай сәттерде сабыр сақтап, оның сезімін атап айтыңыз: "Текшелер құлап қалғандықтан ашуланып тұрсың, сені түсінемін". Сіздің осылай түсіністік танытуыңыз оған эмоцияларын басқаруды және қиындықтарға тап болғанда еңсесін түсірмеуді үйретеді.') WHERE id = 'a0a20bce-4839-4117-9368-c41ef5150778';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала дене мүшелерін (қол, аяқ, іш) көрсетіп қана қоймай, олардың атауларын айтуға да талпынады. Киіндіріп жатқанда: "Сенің ішің қайда?" деп сұрап, жауап беруіне уақыт беріңіз. Бұл — оның өз денесін танып-білуіне және сөздік қорын белсенді қолдануына арналған тамаша жаттығу.') WHERE id = '9f429553-7b9f-4533-9a8c-fa277c16a3ea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дербестікке ұмтылысы киіну кезінде байқала бастайды. Бала шұлығын тартып шешуі немесе басына баскиімін киюге талпынуы мүмкін. Оның осындай "өзіне-өзі қызмет көрсету" әрекеттеріне кедергі жасамаңыз. Асықтырмай, бір нәрсені өз бетінше орындауына мүмкіндік беру оның өзіне деген сенімін (self-esteem) бәрінен де жақсы арттырады.') WHERE id = 'eb7b56da-4f69-416f-ae1f-039fef91ef94';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде "Сөз тіркестерінің" алғашқы белгілері пайда болады: Бала енді екі сөзді қатар айта алады (мысалы, "Әке, кел" немесе "Су бер"). Егер ол әлі сөздерді біріктірмесе, өзіңіз үлгі көрсетіңіз. Ол "Доп" десе, Сіз "Иә, үлкен доп" деп сөзін толықтырыңыз. Бұл оның миында грамматикалық құрылымдардың қалыптасуына көмектеседі.') WHERE id = '6753f0e0-f84e-40f2-a42e-a2fc56030ffe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторика және "Кітап беттері". Бала енді қалың картон беттерді бір-бірден аударуға машықтана түседі. Оған қолмен ұстап сезінуге болатын (touch-and-feel) элементтері бар интерактивті кітаптар ұсыныңыз. Кітап бетін өз бетінше аударуы оның дербестік сезімін қалыптастырып қана қоймай, саусақтарының ұсақ бұлшықеттерін жазуға дайындайды.') WHERE id = 'ed122971-473f-43f3-a24c-a44303a6f746';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтану кезіндегі «Ас құралдарын қолдану». Бала балаларға арналған шанышқыны тамаққа (мысалы, жұмсақ пісірілген көкөніске) шаншып, аузына дәлірек апара алады. Бұл дағды қол мен көз үйлесімін жақсартып қана қоймай, оның өзін дербес тұлға ретінде сезінуіне көмектеседі. Үстел үсті сәл шашылып қалса да, оған осы мүмкіндікті беріңіз.') WHERE id = '28156e7f-7e18-4b94-927c-a444469bee3e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістіктік жады» және іздеу: Бала бірнеше сағат бұрын ойыншықты қай жерге қойғаныңызды есіне түсіріп, оны таба алады. Онымен «жоғалған затты тап» ойынын ойнаңыз. Бұл оның көру жадын да, зейінін шоғырландыру қабілетін де жақсартады. Тапқан әрбір заты ол үшін кішкентай «зерттеушілік» жеңіс болады.') WHERE id = '15ff0052-98cf-4d44-8277-9931b5bbd7bd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта «эмпатия» арта түседі. Бала басқа адамның (немесе ойыншығының) «ауырғанын» көргенде, оны құшақтап не сипап жұбатуы мүмкін. Бұл оның өзгелердің сезімін түсіне бастағанын көрсетеді. «Иә, досың қазір сәл мұңайып тұр» деген сияқты сөйлемдермен осы сезімдерді атап, оның эмоциялық интеллектісін қолдаңыз.') WHERE id = '6c93684c-6781-4a11-bb15-1580d5f66d36';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарының үйлесімі: Бала тұрған орнында айналуды және артқа қадам басуды үйреніп келеді. Бұл — тепе-теңдікті сақтауға арналған күрделі жаттығу. Оған кең әрі кедергісіз жерде жаңа дағдыларын байқап көруге мүмкіндік беріңіз. Денесін басқару қабілеті артқан сайын, құлап қалудан қорқуы азайып, қозғалыс ауқымы кеңейеді.') WHERE id = '33b5778f-3fe2-440a-8f22-62f63b5a956d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Өтірік ойнау» (Pretend play) ойындары күрделене түседі. Бала ойыншық мәшинесінің «выр-выр» деген дыбысын салуы немесе бос тәрелкеден «тамақ жеп отырғандай» әрекет етуі мүмкін. Онымен бірге осы ойындарға қатысып, жаңа сұрақтар арқылы қиялын ынталандырыңыз. Бұл оның шығармашылығын да, логикалық байланыстар құру қабілетін де дамытады.') WHERE id = 'd2fca029-5edb-4176-b69f-5a506afd4a61';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды жай ғана жинап қоймай, оларды түсіне қарай топтастыруға тырысады. Оған екі түрлі түсті ыдыс беріп, түсі бірдей ойыншықтарды сәйкес ыдыстарға салуды көрсетіңіз. Бұл ойын оның көру арқылы қабылдауын және логикалық ойлауын қарқынды дамытады. Оқуға деген қызығушылығы артуы үшін әр дұрыс таңдауын мадақтап отырыңыз.') WHERE id = '7aebe8cd-a4e5-44f9-8f57-fc363b89129a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Артқа қадам". Бала енді артқа қарай жүруді үйренді. Бұл — тепе-теңдікті сақтауға арналған күрделі жаттығу әрі оның дене үйлесімділігінің қаншалықты дамығанын көрсетеді. Осы жаңа дағдысын кедергісіз әрі жұмсақ жерде байқап көруіне жағдай жасаңыз. Денесін басқару қабілеті артқан сайын, өзіне деген сенімі де нығая түседі.') WHERE id = '23d55f43-944e-41ff-a1f0-31e749c5ea5d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сұрақ пен қызығушылық". Бала енді заттарды көрсетіп, "Бұл не?" деп сұрайды (немесе өз тілінде соған ұқсас дыбыс шығарады). Сіз бәрін асықпай атап беріңіз: "Бұл қызыл мәшине", "Бұл үлкен ағаш". Оның қызығушылығын жауапсыз қалдырмау сөздік қорының әрі пассивті, әрі белсенді түрде молаюына көмектеседі.') WHERE id = '741cbef2-ffcd-4b10-9cdf-8e41aa164e28';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Әзілдер". Бала ойыншықты Сізге әдейі ұсынып, бірден қайта тартып алып, күле ме? Бұл оның әзіл сезімі мен әлеуметтік қарым-қатынас дағдысы қалыптасып келе жатқанын көрсетеді. Оның осы "ойынына" ықыласпен қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты нығайтып, баланың өзіне деген сенімін қалыптастырады.') WHERE id = '5a726b9c-27a1-4456-85ed-e5c0d76d2484';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Пирамида мен сақиналар". Бала енді сақиналарды үлкенінен кішісіне қарай (немесе керісінше) реттеп жинауға машықтанып келеді. Бұл әрекет оның көлем туралы түсінігін (үлкен-кіші) және қол-көз үйлесімділігін дамытады. Сақиналарды жинаған кезде түстерін де дауыстап айтып отырыңыз.') WHERE id = '51378f6a-c746-490d-b2e3-d4da3d093685';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім ішемін". Бала енді ашық стақаннан суды төкпей ішуге жақын қалды. Оған балаға лайық өлшемдегі, аударылмайтын (түбі ауыр) пластик стақандар беріңіз. Суды өз бетінше ішуі ерін мен тіл бұлшықеттерін сөйлеуге дайындап, дербестік сезімін дамытады.') WHERE id = '44c70121-397f-4987-8f6a-6aae583c01e5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялды дамыту: «Тамақ пісіру» ойыны. Бала ойыншық ыдыстармен бірдеңе «пісіріп жатқандай» ойнай алады. Оның ойынына қосылыңыз: «Маған да аздап тамақ бересің бе?». Бұл оның күнделікті тұрмыстағы әрекеттерді қаншалықты мұқият бақылайтынын және қиялының қалай дамып келе жатқанын көрсетеді.') WHERE id = '0303ebf1-df3e-4e81-bd4e-6f1dea97c188';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы батылдық: бала енді аласа баспалдақтарға немесе диванның шетіне өздігінен өрмелеуге тырысады. Биіктікті сезіну қабілеті дамып келе жатқанымен, ол қауіп-қатерді әлі толық түсінбейді. Әрдайым жанында болып, оны сақтандырыңыз және қауіпсіз түсу жолдарын (мысалы, артқа қарай түсу) көрсетіңіз.') WHERE id = '4a36804a-6409-441e-bfa1-5d47aa7ddf64';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Жануарлар мен олардың дыбыстарын ажырату». Бала енді суреттегі сиыр мен мысықты бір-бірінен ажыратып, сұрамасаңыз да олардың дыбыстарын сала алады. Кітап оқығанда «Мысық қайда?» деп сұрасаңыз, оны саусағымен көрсетуі көру жады мен зейінінің қаншалықты дамығанын білдіреді.') WHERE id = '48266b98-24f4-486a-8c86-5edb343f6455';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және «Жоқ». Бала бәрін өзі жасағысы келіп, қолынан келмей қалса, кенеттен ашулануы мүмкін. Мұндай сәттерде оны құшақтап, сабырлы дауыспен: «Аяқкиіміңді кие алмағандықтан ашуланып тұрсың, мен сені түсінемін», — деп оның сезімін атап беріңіз. Сіздің сабырлылығыңыз — оған эмоцияларын басқаруды үйрететін ең жақсы үлгі.') WHERE id = 'bd6e2ef7-be9f-49e8-9f5a-73c5aca2c6c7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өз талғамын көрсете бастайды. Ол кигісі келетін жейдесін немесе оқығысы келетін кітабын нық таңдай алады. Бұл кезеңде оған «шектеулі таңдау» мүмкіндігін беріңіз: «Бүгін қызыл жейдені кигің келе ме, әлде көкті ме?». Бұл оған жағдайды басқара алатынын сезіндіреді және алдағы қырсығу ұстамаларының алдын алады.') WHERE id = 'e2f29ee5-abb0-4ec5-8bfb-7fca6b238c4f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Жүгіру шеберлігі». Бала енді жүгіріп келе жатқанда тепе-теңдігін жақсырақ сақтап, кенеттен тоқтай алады. Бұл оның бұлшықет күші мен ми-бұлшықет үйлесімінің қаншалықты жетілгенін көрсетеді. Саябақтан немесе ауладан кедергісіз жүгіре алатын орын тауып, бойындағы энергиясын жұмсауына жағдай жасаңыз.') WHERE id = '85cc1293-16e0-49cd-904b-171804ae1853';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Эмпатия" белгілері. Бала Сіздің мұңайып тұрғаныңызды немесе бір жеріңізді соғып алғаныңызды көргенде, жаныңызға келіп, қолын тигізуі, тіпті құшақтауы мүмкін. Бұл оның өзгенің сезімін түсіне бастағанын көрсетеді. "Маған қолдау көрсеткенің үшін көп рақмет" деп, оның бұл сезімін атап айтыңыз. Бұл — эмоциялық интеллектінің негізі.') WHERE id = '3a9d7d72-ab6c-4777-b054-a56b8986ee74';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше тазалық сақтау". Бала Сізге еліктеп, қолын жууға, бетін сүртуге немесе тісін тазалауға (әзірге щетканы жай ғана шайнап) талпынады. Оның дербестікке деген ұмтылысын тежемеңіз. Қолы жетуі үшін басқыш (step stool) қойып, қимылдарыңызды қайталауына мүмкіндік беріңіз. Бұл оның өзіне-өзі күтім жасау дағдыларын қалыптастырады.') WHERE id = '090f40d7-6abc-46b1-8914-c34325dbcaa0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Есте сақтау және "Кеңістіктік жады". Бала ойыншығының қайда жасырылғанын енді ұзақ уақыт есте сақтай алады. Онымен үйде шағын "қазына іздеу" ойындарын ойнаңыз. Бір затты жамылғының астына жасырып, оны қалай табатынын бақылаңыз. Мұндай ойындар зейінін шоғырландыруға да, мәселенің шешімін табуға да үйретеді.') WHERE id = '0bfe8ad5-dcd4-46e4-af49-e5c2a87c763e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: "Өтірік ойын" (Pretend play). Бала енді бос кеседен "шай ішкендей" кейіп таныта алады немесе қуыршағына "тамақ бере" алады. Онымен бірге осындай ойындарға қатысыңыз. Мұндай ойындар баланың шығармашылығын дамытып қана қоймай, күнделікті өмірдегі әрекеттерді түсінуін де жылдамдатады.') WHERE id = '9a097c94-eb06-4b23-b839-a6859f4ee3f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: "Өрмелеу және түсу". Бала енді аласа баспалдақтарға немесе диванның шетіне өз бетінше өрмелеуге тырысады. Биіктікті сезіну қабілеті дамып келе жатқанымен, ол қауіп-қатерді әлі толық түсінбейді. Оған әрдайым арқасымен кері қарай түсудің қауіпсіздеу екенін көрсетіңіз. Сіздің бақылауыңызбен осындай жаттығулар жасауы оның денесін басқару қабілетін нығайтады.') WHERE id = '0f9b9189-8ffa-4276-919f-031f8673dbe8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және "Жоқ". Бала енді "Болмайды" деген сөзге жауап береді, бірақ кейде сол әрекетті әдейі жасап, Сізге қарап тұрады. Осылайша ол Сіздің шыдамыңызды және ережелердің өзгермейтінін тексереді. Сабырлы, бірақ нық болыңыз. Ережелердің тұрақтылығы балада қауіпсіздік пен тәртіп сезімін қалыптастырады.') WHERE id = '3fbc8bef-6814-4548-b448-0883b201e56d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды жай ғана жинап қоймай, оларды түсіне қарай топтастыруға да тырысады. Оған екі түрлі түсті ыдыс беріп, түсі бірдей ойыншықтарды сәйкес ыдыстарға салуды көрсетіңіз. Бұл ойын оның көру арқылы қабылдауын және логикалық ойлауын жылдам дамытады. Әр дұрыс таңдау жасаған сайын оны мадақтап, жігерлендіріңіз.') WHERE id = 'be0ade15-5544-47ec-9b0f-c9482045c9e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы "Артқа қадам". Бала енді артқа қарай жүруді үйреніп жүр. Бұл — тепе-теңдікті сақтауға арналған күрделі жаттығу әрі оның дене үйлесімділігінің қаншалықты дамығанын көрсетеді. Осы жаңа дағдысын кедергісіз әрі жұмсақ жерде байқап көруіне жағдай жасаңыз. Денесін басқару қабілеті артқан сайын, өзіне деген сенімі де нығаяды.') WHERE id = '4090fd14-b660-4e63-9f79-fd22a575576f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сұрақ пен қызығушылық". Бала енді заттарды көрсетіп, "Бұл не?" деп сұрайды немесе өз тілінде соған ұқсас дыбыс шығарады. Сіз бәрін шыдамдылықпен атап отырыңыз: "Бұл қызыл мәшине", "Бұл үлкен ағаш". Оның қызығушылығын жауапсыз қалдырмау сөздік қорының әрі пассивті, әрі белсенді түрде молаюына көмектеседі.') WHERE id = '4d85c160-6a89-4bf6-8f45-da46fe9e61c0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Қалжыңдар". Бала ойыншықты әдейі Сізге беретіндей болып, бірден кері тартып алып күле ме? Бұл оның әзіл сезімі мен әлеуметтік әрекеттесу дағдысының қалыптасып келе жатқанын көрсетеді. Оның осы "ойынына" қуана қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты нығайтып, баланың өзіне деген сенімін қалыптастырады.') WHERE id = '843dc844-89cf-4311-8b84-968a8aaa47d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Пирамида мен сақиналар". Бала енді сақиналарды үлкенінен кішісіне қарай немесе керісінше орналастыруға машықтанып келеді. Бұл әрекет оның өлшем туралы түсінігін (үлкен-кіші) және қол-көз үйлесімділігін дамытады. Сақиналарды орналастырған кезде олардың түстерін де дауыстап атаңыз.') WHERE id = 'da06e49e-5a35-41bf-9d03-b1f30db1e3f3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім ішемін". Бала енді ашық стақаннан суды төкпей ішуге жақын. Оған балаға лайық өлшемдегі, оңай аударылмайтын (түбі ауыр) пластик стақан беріңіз. Суды өз бетінше ішу ерін мен тіл бұлшықеттерін сөйлеуге дайындап, дербестік сезімін дамытады.') WHERE id = '7672591f-bef4-411a-94a3-365d4ae118a3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сөз тіркестері". Бала енді екі сөзді қатар қолданып, қарапайым сөйлемдер құрайды: "Әке, кел", "Алма бер". Егер ол сөздерді әлі тіркестірмесе, айтқан бір сөзін Сіз кеңейтіп қайталаңыз: "Иә, сен алма қалайсың ба? Мә, саған дәмді алма". Бұл оның миындағы грамматикалық құрылымдарды нығайтады.') WHERE id = '3ec1877f-e8dc-4ba3-893d-678bde1927b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Пазл" кезеңі. Бала енді 2-3 бөліктен тұратын қарапайым пазлдарды құрастыруды немесе пішіндерді сәйкес саңылауларға салуды үйренеді. Бұл ойын оның көру арқылы қабылдауын және мәселені шешу дағдысын айтарлықтай дамытады. Қолынан келмей жатса, оған сабырмен көмектесіп, жігерлендіріңіз.') WHERE id = 'b4b1a4bc-e49d-4497-b688-464c24f79875';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Қатар ойнау". Бала басқа балалармен бірге болғанда, олармен емес, олардың жанында өз бетінше ойнайды. Бұл 17-ші ай үшін мүлде қалыпты жағдай. Ол басқа балаларды бақылау арқылы көп нәрсе үйренеді. Әлеуметтік ортаға бейімделуі үшін оны құрдастарының ортасына апаруды жалғастырыңыз.') WHERE id = '0d8b6018-4d34-41fe-ad70-9143e9c2615f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім жуынамын". Шомылғанда немесе қолын жуғанда бала сабынды не жөкені алып, өзін жууға тырысады. Оның гигиеналық дағдыларға деген қызығушылығын қолдаңыз. Өз денесін "тазалауы" дене мүшелерін жақсырақ танып-білуіне және дербестік сезімін қалыптастыруына көмектеседі.') WHERE id = '3c2bb527-c368-4b69-94c1-76665087b2b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Есте сақтау қабілетінің нығаюы: "Жоғалған заттар". Бала Сіз жасырған ойыншықты табу үшін күрделірек әрекеттер жасайды – жамылғыны көтереді, қораптың ішіне қарайды. Бұл оның бойында "заттың тұрақтылығы" туралы түсініктің толық қалыптасқанын көрсетеді. Үйде онымен шағын "қазына іздеу" ойындарын ойнап, зейінін жаттықтырыңыз.') WHERE id = 'd0afa5e2-c732-43e9-af9d-2f3d19c36c4e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиял және "Үй шаруасы". Бала ойыншық телефонмен "сөйлеседі" немесе ойыншық сыпырғышпен еден сыпырады. Ол Сіздің әрбір әрекетіңізді қайталайды. Еліктеу – оның қоршаған ортаны танып-білу тәсілі. Оған өзінің шағын "жұмыс құралдарын" беріп, өзін маңызды сезінуіне мүмкіндік жасаңыз.') WHERE id = '9dfb3516-1999-4989-989e-9e6fdb3fb9e5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялды дамыту: "Ас пісіру" ойыны. Бала ойыншық ыдыстармен бірдеңе "пісіріп жатқандай" ойнай алады. Сіз де оның ойынына қосылыңыз: "Маған да аздап тамақ бересің бе?". Бұл оның күнделікті тұрмыс әрекеттерін қаншалықты мұқият бақылайтынын және қиялының қалай дамып келе жатқанын көрсетеді.') WHERE id = '54cd9ab8-e1d5-4a0e-ab3a-58d28bf66df0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: Бала енді аласа баспалдақтарға немесе диванның шетіне өздігінен өрмелеуге тырысады. Биіктікті сезіну қабілеті дамып келе жатса да, ол қауіп-қатерді әлі толық түсінбейді. Әрдайым жанында болып, қауіпсіздігін қамтамасыз етіңіз және оған қауіпсіз түсу жолдарын (мысалы, артымен түсу) көрсетіңіз.') WHERE id = 'b93116ed-f9b5-4701-8c1f-2fc127b8352c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Жануарлар мен олардың дыбыстарын ажырату". Бала суреттегі сиыр мен мысықты енді бір-бірінен ажыратып, сұрамасаңыз да олардың дыбыстарын сала алады. Кітап оқығанда "Мысық қайда?" деп сұрасаңыз, оны саусағымен көрсетуі көру жадының нығайып келе жатқанын білдіреді.') WHERE id = 'dcd3b6fa-3aa2-4a2f-98c6-4125a36e33d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және "Жоқ". Бала бәрін өзі жасағысы келіп, қолынан келмей қалса, кенеттен ашулануы мүмкін. Мұндай сәттерде оны құшақтап, сабырлы түрде: "Аяқкиіміңді кие алмағандықтан ашуланып тұрсың, мен түсінемін", — деп оның эмоциясын атап айта аласыз. Сіздің осындай сабырлылығыңыз — оған эмоцияларын басқаруды үйрететін ең жақсы үлгі.') WHERE id = '352efc53-2735-4313-8ef5-1cd93238bca8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '18-айға, яғни бір жарым жасқа қадам басамыз! Бала енді жүгіргенде тепе-теңдігін жақсырақ сақтап, қалаған сәтте тоқтай алады. Бұл — дене күшінің де, ми мен бұлшықет үйлесімінің де айтарлықтай дамуы. Саябақтан немесе ауладан кедергісіз жүгіретін орын тауып, оған күш-қуатын пайдалы жолмен жұмсауға мүмкіндік беріңіз.') WHERE id = '20741f1b-1447-4efb-94f4-6f3a4844a16e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сөз тіркестері" қарқынды дами бастайды. Бала енді екі сөзді біріктіріп, күрделірек өтініштерін білдіреді: "Әке, кел", "Алма бер", "Доп қайда?". Егер ол сөздерді әлі біріктірмесе, алаңдамаңыз; Сіз оның айтқан жеке сөздерін сөйлемге айналдырып жауап беріңіз: "Иә, допты қалайсың ба? Мә, сенің қызыл добың".') WHERE id = '81c4a684-a911-49c4-a9d7-1699f6fa7902';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: «Өрмелеу шеберлігі». Бала енді баспалдақпен өздігінен көтерілуге (әзірге еңбектеп немесе қолынан ұстап) қатты ұмтылады. Биіктікті сезінуі жақсарған сайын, оған төмен түсуді де үйрету қажет. Әрдайым баспалдақтан артымен түсу қауіпсіздеу екенін көрсетіңіз.') WHERE id = '15095e09-193b-4e26-bc2e-4f81de7c413d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 500 күнді аяқтадық! Балаңыз бөпелік кезеңнен толық өтіп, өз мінезі мен ерік-жігері бар кішкентай бүлдіршінге айналды. Бүгін онымен бірге өзі ұнататын іспен айналысып (мысалы, сурет салып немесе саябақта серуендеп), уақыт өткізіңіз. Сіздің шыдамдылығыңыз бен махаббатыңыз — оны осы кезеңге жеткізген ең үлкен күш. Жарайсыз, Ана!') WHERE id = '3427ae53-cf26-4b28-928a-b9787dc9cf32';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «Мен» ұғымын іс-әрекетімен көрсете бастайды. Киімін өзі таңдағысы немесе тамақты өзі жегісі келуі — дербестігінің белгісі. Оған осындай мүмкіндік беріңіз: «Қай жейдені кигің келеді?». Шағын таңдау ұсыну оның шешім қабылдау қабілетін дамытып қана қоймай, қырсығу ұстамаларын да азайтады.') WHERE id = '1f190c82-9146-4726-b79a-d4e22c530f6d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында — «Кедергілерден өту». Бала енді едендегі ойыншықтар мен жастықтардың үстінен аттап немесе оларды айналып өтуді үйреніп келеді. Бұл — кеңістікті қабылдаудың күрделі дағдысы. Үйде қауіпсіз кедергілер жасап, оның тепе-теңдігін және денесін басқару қабілетін жаттықтырыңыз.') WHERE id = '0762347b-3e67-4f92-a1cc-28fc730be874';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сөздердің мағынасы». Бала енді сөздерді жай ғана қайталамай, оларды нақты жағдайларға сай қолданады. Мысалы, Сіз аяқкиіміңізді киіп жатқанда, ол «Далаға» деуі мүмкін. Оның осындай сөздерін толықтырып айтыңыз: «Иә, қазір аяқкиімімізді киіп, саябаққа барамыз». Бұл оның миындағы оқиғалар мен сөздер арасындағы байланысты нығайтады.') WHERE id = '32725b0c-885a-420b-8b00-82ddb5c437d8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Жобалау және құрастыру». Бала енді текшелерді жай ғана бірінің үстіне бірін қоймай, олардан «пойыз» немесе «қоршау» сияқты көлденең пішіндер жасауға тырысады. Бұл оның кеңістіктік ойлауы жаңа кезеңге өткенін көрсетеді. Оған әртүрлі пішіндегі конструкторлар беріп, қиялын қолдаңыз.') WHERE id = 'd22bf585-b849-4796-8341-19d360ee9434';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Пазл" (жұмбақ) кезеңі. Бөпе енді 2-3 бөліктен тұратын қарапайым пазлдарды құрастыруды немесе геометриялық пішіндерді сәйкес ойықтарға салуды үйреніп келеді. Бұл ойын оның көру арқылы қабылдауын да, мәселені шешу қабілетін де жоғары деңгейге көтереді. Қолынан келмей жатса, сабырмен бағыт беріп, жігерлендіріңіз.') WHERE id = 'f29daf62-95a9-439b-9639-5474aad5c6b0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта "Қатар ойнау" әлі де басым. Басқа балалармен бірге болғанда, бөпе олармен бірлесіп емес, олардың жанында өз бетінше ойнайды. Бұл 18 айға дейінгі балалар үшін мүлде қалыпты жағдай. Ол басқа балаларды бақылау арқылы көп нәрсе үйренеді. Әлеуметтік ортаға бейімделуі үшін оны құрдастарымен кездестіруді жалғастырыңыз.') WHERE id = 'b30c9be9-ec87-4316-9f1a-0e4dee84bd75';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім жуынамын". Шомылғанда немесе қолын жуғанда, бөпе сабынды не ысқышты алып, денесін сүртуге және Сізге еліктеуге тырысады. Оның гигиеналық дағдыларға деген қызығушылығын қолдаңыз. Өз денесін "тазалауы" дене мүшелерін жақсырақ танып-білуіне де, дербестік сезімінің қалыптасуына да көп көмектеседі.') WHERE id = '4e8730af-51d2-460d-ac2a-1e5c1f18dbf2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Есте сақтау қабілетінің нығаюы: "Кеңістіктік жад". Бөпе Сіз жасырған ойыншықты табу үшін күрделі тәсілдерді қолданады – жамылғыны көтереді, қораптың ішіне қарайды, тіпті жастықтың астына қолын созады. Бұл оның бойында "нысанның тұрақтылығы" ұғымы толық қалыптасқанын көрсетеді. Үйде онымен шағын "қазына іздеу" ойындарын ойнап, зейінін жаттықтырыңыз.') WHERE id = '88dfd514-9103-49dd-80b3-7233dd30fb8c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиял және "Үй шаруасы". Бөпе ойыншық телефонмен "сөйлеседі" немесе ойыншық сыпырғышпен еден сыпырады. Ол Сіздің күнделікті әрбір әрекетіңізді қайталайды. Бұл еліктеу – оның қоршаған ортаны танып-білу тәсілі. Оған өзінің шағын "еңбек құралдарын" беріп, өзін маңызды сезінуіне мүмкіндік жасаңыз.') WHERE id = '86806a6e-92ce-48bc-8348-5f82c21f79d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: "Өрмелеу шеберлігі". Бөпе енді баспалдақпен өздігінен көтерілуге (әзірге қолынан ұстап немесе еңбектеп) қатты талпынады. Биіктікті сезінуі артқан сайын, оған төмен түсуді де үйрету қажет. Артқа қарап түсу қауіпсіздеу екенін үнемі көрсетіп, сақтандыру үшін әрдайым жанында болыңыз.') WHERE id = 'bdb8a9e0-fbd7-4c99-b8e8-bdcb234283e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Жануарлар мен олардың дыбыстарын ажырату». Бала суреттен көрген сиыр мен мысықты енді бір-бірінен анық ажыратып, сұрамасаңыз да олардың дыбыстарына еліктей алады. Кітап оқып отырғанда «Мысық қайда?» деп сұрасаңыз, оны саусағымен көрсетуі баланың көру жады мен зейінінің қаншалықты дамығанын білдіреді.') WHERE id = 'c66b2427-57b0-459e-a0a3-0cf6bedf7007';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және «Жоқ». Бала бәрін өзі жасағысы келіп, қолынан шықпай қалғанда кенеттен ашулануы мүмкін. Мұндай сәттерде оны құшақтап, сабырлы түрде: «Текшелер құлап қалғандықтан ашуланып тұрсың, мен сені түсінемін», — деп оның сезімін атап беріңіз. Сіздің осылай түсіністік танытуыңыз оған эмоцияларын басқаруды және қиындықтарға тап болғанда берілмеуді үйретеді.') WHERE id = 'a52afb36-cf2f-4e94-8f57-7e002290fbaf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды түсіне қарай топтастыруға тырысады. Оған екі түрлі түстегі ыдыс беріп, сол түстерге сәйкес ойыншықтарды тиісті ыдыстарға салуды көрсетіңіз. Бұл ойын оның көру арқылы қабылдауын және логикалық ойлауын жылдам дамытады. Оқуға деген қызығушылығы артуы үшін әр дұрыс таңдауында оны мақтап, ынталандырыңыз.') WHERE id = '59526637-405e-4f57-afc2-14b281d0bec6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Артқа қадам басу». Бала енді артқа қарай жүруді үйрене бастады. Бұл — тепе-теңдікті сақтауды қажет ететін күрделі жаттығу әрі оның дене қимылдарын үйлестіру қабілетінің қаншалықты дамығанын көрсетеді. Осы жаңа дағдысын кедергісіз әрі жұмсақ жерде байқап көруіне жағдай жасаңыз. Денесін басқару қабілеті артқан сайын, өзіне деген сенімі де нығая түседі.') WHERE id = '75475781-7679-4745-947b-4230a1dabd3f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ пен қызығушылық». Бала енді заттарды көрсетіп, «Бұл не?» деп сұрайды немесе өз тілінде осыған ұқсас дыбыс шығарады. Сіз әр нәрсенің атауын сабырмен айтыңыз: «Бұл — қызыл мәшине», «Бұл — үлкен ағаш». Оның қызығушылығын жауапсыз қалдырмау сөздік қорының әрі пассивті, әрі белсенді түрде молаюына көмектеседі.') WHERE id = '428ddabc-76ae-4dd9-8955-566bc3b0021c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қалжыңдар». Бала ойыншықты Сізге әдейі беріп, артынша дереу тартып алып күле ме? Бұл оның әзіл сезімі мен ойын арқылы әлеуметтік қарым-қатынас жасау қабілеті қалыптасып келе жатқанын көрсетеді. Оның бұл «ойынына» қуана қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты нығайтып, баланың өзіне деген оң сенімін қалыптастырады.') WHERE id = '6f7f5c96-a971-4edb-9629-1420d3e51d5d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала орнында тұрып секіруге талпынып жүр. Әзірге екі аяғы бірдей жерден көтерілмеуі мүмкін, бірақ тізесін бүгіп, серпілуі — оның жалпы моторикасының дамып келе жатқанының белгісі. Онымен бірге ырғақты музыкаға билеңіз. Бұл — әрі көңілді, әрі аяқ бұлшықеттерін нығайтатын өте пайдалы дене жаттығуы.') WHERE id = '11679c4b-f0ae-4e4b-8e36-e62ed51385bb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде «Менікі» сөзінің пайда болуы. Бала енді өз заттарын таниды және оларды «менікі» деп (немесе өз тіліндегі белгімен) қорғауға тырысады. Бұл өзімшілдік емес, оның жеке шекарасын түсіне бастауы. Оған өз заттарына иелік етуге мүмкіндік беріңіз. Бұл оның өзіне деген сенімін арттырып, меншік ұғымын қалыптастырады.') WHERE id = '76f2d8e6-3dab-4534-8a50-e8454558158c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Сұрыптау және логика». Бала заттарды тек түсіне қарай емес, көлеміне қарай да (үлкен-кіші) ажырата бастайды. Оған көлемі әртүрлі ыдыстар беріп, оларды бірінің ішіне бірін салуын сұраңыз. Бұл — оның болашақ математикалық ойлауының ең алғашқы негізі.') WHERE id = 'c34d1f9d-7805-4ebe-a5ef-2eba5d6e613a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дербестік: «Мен өзім киінемін». Бала шалбарын жоғары тартуға, шұлығын шешуге немесе оңай киілетін аяқкиімін аяғына киюге тырысады. Бұл үдерісте оған кедергі жасамаңыз және асықтырмаңыз. Бір нәрсені өз бетімен істей алғанын көру — ол үшін ең үлкен марапат. Кішкентай жетістіктері үшін оны әрдайым мақтаңыз.') WHERE id = 'e8325a98-332b-4719-b50a-32bc427f8a46';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Кезек күту». Бала ойыншықпен ойнау үшін біраз күту керек екенін түсіне бастайды. «Қазір менің кезегім, содан кейін сенікі» деген ойындар арқылы оған шыдамдылықты үйретіңіз. Бұл — оның балабақшаға немесе басқа әлеуметтік ортаға бейімделуі үшін ең маңызды дағдылардың бірі.') WHERE id = 'fb3f5f38-3ad4-4db7-9933-796ef621c2db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы «Қасықты өз бетінше қолдану шеберлігі». Бала қасыққа тамақ салып, оны аузына төгіп алмай дерлік жеткізуді үйреніп жүр. Оған йогурт немесе езбе сияқты қою тағамдармен жаттыққан оңайырақ. Үстелдің былғануынан қорықпаңыз: өз бетінше тамақтану оның қол мен көз үйлесімін дамытып қана қоймай, тойғанын сезінуіне де көмектеседі.') WHERE id = 'eb358b29-c8ba-43ce-9ec4-901370abee63';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пирамида мен сақиналар». Бала сақиналарды үлкенінен кішісіне қарай (немесе керісінше) реттеуге машықтанып келеді. Бұл әрекет оның өлшем туралы түсінігін (үлкен-кіші) және қол-көз үйлесімін дамытады. Сақиналарды реттеген кезде түстерін де атап отырыңыз.') WHERE id = '90eaad7f-688e-4fd5-ac4b-58ae26fd12fd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім ішемін». Бала ашық стақаннан суды төкпей ішуге аз қалды. Оған балаға лайық өлшемдегі, аударылып кетпейтін (түбі ауыр) пластик стақандар беріңіз. Суды өздігінен ішуі оның ерін және тіл бұлшықеттерін сөйлеуге дайындап, дербестік сезімін қалыптастырады.') WHERE id = 'ee6a42af-cce1-4d37-af51-df5adf60a403';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Тамақ пісіру» ойыны. Бала ойыншық ыдыстарымен бірдеңе «пісіріп жатқандай» ойнауы мүмкін. Сіз де оның ойынына қосылыңыз: «Маған да аздап тамақ бересің бе?». Бұл оның күнделікті тұрмыс әрекеттерін қаншалықты мұқият бақылайтынын және қиялының қалай дамып келе жатқанын көрсетеді.') WHERE id = 'f1803978-8c6d-4ba6-919b-9d07f71e4f23';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы батылдық: Бала аласа баспалдақтарға немесе диванның шетіне өздігінен өрмелеуге тырысады. Биіктікті сезінуі дамып келе жатса да, ол қауіптерді әлі толық түсінбейді. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз және оған қауіпсіз түсу жолдарын (мысалы, артымен түсуді) көрсетіңіз.') WHERE id = '992522f4-e329-4100-a785-ed11e118cc9d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде «Жануарлар мен олардың дыбыстарын ажырату». Бала суреттегі сиыр мен мысықты бір-бірінен ажыратып, сұрамасаңыз да олардың дыбыстарын сала алады. Кітап оқығанда «Мұнда мысық қайда?» деп сұрасаңыз, оның саусағымен көрсетуі көру арқылы есте сақтау қабілетінің нығайып келе жатқанын білдіреді.') WHERE id = 'a6dfa03f-81ed-42c6-9520-9c6097e0b191';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және «Жоқ». Бала бәрін өзі жасағысы келіп, қолынан келмей қалса, кенеттен ашулануы мүмкін. Мұндай сәттерде оны құшақтап, сабырлы дауыспен: «Аяқкиіміңді кие алмағандықтан ашуланып тұрсың, мен сені түсінемін», — деп оның эмоциясын атаңыз. Сіздің осындай сабырлылығыңыз — оған эмоцияларын басқаруды үйрететін ең жақсы үлгі.') WHERE id = 'fe5d769a-36f6-497a-abae-90604ca433b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Ойыншықтармен диалог». Балаңыз енді қуыршағымен немесе қонжығымен «сөйлеседі», оларды «ұйықтатады» немесе «тексереді». Бұл оның эмоциялық интеллектісі дамып, күнделікті әрекеттерді қаншалықты терең меңгергенін көрсетеді. Онымен бірге осындай рөлдік ойындарға қатысыңыз.') WHERE id = '966e6ab8-7afb-4514-ac61-ac17ed1b3363';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуы: «Доп тебу». Балаңыз енді тік тұрып, тепе-теңдігін жоғалтпай допты тебуге тырысады. Бұл — күрделі үйлесімділікті қажет ететін қимыл. Онымен үйде немесе аулада жеңіл доппен ойнаңыз. Допты Сізге беруін сұрап, кезектесіп ойнау дағдысын да дамытыңыз.') WHERE id = '074c6e28-5574-4dba-9c17-b0a8532eb39d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Неге?» кезеңінің алғашқы белгілері. Балаңыз әр нәрсені саусағымен көрсетіп, «Бұл?» деп, Сіздің түсіндіруіңізді күтеді. Әр заттың атауын және не үшін қолданылатынын қарапайым сөйлемдермен түсіндіріңіз. Сіздің түсіндірмелеріңіз оның санасында әлемнің картасын қалыптастырады. Оның қызығушылығын әрдайым қолдап отырыңыз.') WHERE id = '8bf76af3-3dd5-49ef-bbdd-da6f06260256';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 550 күнді артқа тастадық! Балаңыз ресми түрде 1.5 жасқа толды. Бұл — оның дамуындағы ең маңызды әрі қызықты кезеңдердің бірі. Ол енді қарапайым нұсқауларды толық түсінеді, эмоцияларын анық көрсетеді және әлемді танып-білуге дайын кішкентай «зерттеушіге» айналды. Бұл күнді онымен бірге ең сүйікті ойынын ойнап атап өтіңіз!') WHERE id = 'f706bcc8-1266-48d0-82ad-7920a5e14e37';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '19-шы айға қош келдіңіз! Балаңыз енді айнадан өзін толық таниды және ондағы бейнесін «басқа бала» емес, дәл өзі ретінде қабылдайды. Бұл — оның өзіндік санасының (self-awareness) дамуындағы үлкен қадам. Онымен бірге айна алдына тұрып: «Қарашы, мынау сенің көзің, ал мынау анаңның көзі», — деп, дене мүшелерін тереңірек үйретуді жалғастырыңыз.') WHERE id = '696f3d72-602f-4dc5-8009-bf57000cd9a2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Бүйірге қадам басу». Балаңыз енді тек алға және артқа ғана емес, бүйірімен де (crab walk) жүре алады. Бұл — тепе-теңдік пен қимыл үйлесімділігін дамытатын күрделі жаттығу. Оған музыка әуенімен әртүрлі бағытта қозғалуды көрсетіңіз. Бұл әрі көңілді би, әрі аяқ бұлшықеттерінің әртүрлі топтарын нығайтатын жаттығу.') WHERE id = '29558e25-5ccf-4193-9fb7-c0eb732293d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Нұсқауларды орындау»: Бала енді бірінен кейін бірі орындалатын екі қадамнан тұратын тапсырмаларды түсіне алады. Мысалы: «Допты ал да, қорапқа сал». Бұл оның тілді түсінуін де, жұмыс жадын да дамытады. Осындай қарапайым, екі кезеңді «тапсырмалар» беру арқылы оның зейінін жаттықтырыңыз.') WHERE id = 'b9afb514-aca9-4563-b096-907e76f4594a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Кітапқа деген сүйіспеншілік». Бала енді жұқа қағаз беттерін (Сіздің бақылауыңызбен) жыртпай аударуға тырысады. Ол сүйікті ертегілерін қайта-қайта тыңдағысы келуі мүмкін. Әр оқыған сайын суреттегі әртүрлі бөлшектерді көрсетіңіз: «Қарашы, мұнда кішкентай көбелек те бар». Бұл оның көру зейінін де, шыдамдылығын да арттырады.') WHERE id = 'dd8c337a-acae-4f9f-a64d-1a2e2dbf15fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тазалық сақтау». Бала енді қолын құрғатуға, бетін сүртуге немесе өзін ысқышпен «жууға» тырысады. Оның тазалық дағдыларына деген қызығушылығын қолдаңыз. Оған өзінің кішкентай сүлгісін беріңіз. Өзіне күтім жасай алу сезімі оның өзіне деген сенімін және өз денесіне құрметін қалыптастырады.') WHERE id = '31f5c493-87d9-45d8-950b-ce108414919b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Символдық бөлісу». Бала енді Сізге ойыншығының бір бөлігін немесе тамағының бір үзімін «ұсынуы» мүмкін. Тіпті оны шынымен бермесе де, бұл ишара бөлісу ұғымының негізін қалайды. Оның бұл әрекетін міндетті түрде «Көп рақмет, сен өте мейірімдісің» деп мақтаңыз.') WHERE id = '10acade6-6a92-4cf8-b728-f33648cdd314';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Геометриялық пішіндер». Бала енді шеңберді, шаршыны және үшбұрышты (пазлдардан немесе пішіндерді орналастыратын ойыншықтардан) ажырата бастайды. Оған осы пішіндердің атауларын айтыңыз. Әзірге атауларын айтпаса да, оларды көзбен бір-бірінен ажырата алуы — геометриялық ойлауының негізі.') WHERE id = '36dfa91f-6b4c-45f4-8057-bfc8dec4de87';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығы: «Төменге секіру». Бала енді аласа баспалдақтан (биіктігі небәрі бірнеше сантиметр) жерге секіруге талпынуы мүмкін. Қолынан ұстап, оған қолдау көрсетіңіз. Бұл қимыл оның тобықтарын нығайтып қана қоймай, биіктік пен қашықтықты іс жүзінде түсінуіне көмектеседі.') WHERE id = '20c66b93-4f9a-4106-b0f1-86263f239cfe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы «Талғампаздық» пен «Бақылау». Бала кейде жай ғана «бақылау өз қолында болсын» деп тамақтан бас тартуы мүмкін. Оны мәжбүрлемеңіз. Оның орнына дастарқанға пайдалы екі тағам қойып: «Брокколи жегің келе ме, әлде сәбіз бе?» деп сұраңыз. Таңдау мүмкіндігі оның қарсылығын азайтып, өз шешімдеріне құрметпен қарайтыныңызды сезіндіреді.') WHERE id = '597fce8a-7564-428a-aa97-6b8b166f2f7c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Кеңістікті қабылдау» және «Биіктік». Бала енді биіктіктің қауіпті екенін жақсырақ түсініп, аласа жерлерден түскенде абай болады. Оған диваннан немесе баспалдақтан артымен түсуді еске салып отырыңыз. Бұл оның дене қауіпсіздігі ережелерін меңгеруі үшін маңызды.') WHERE id = '42d59296-b192-45dd-b455-11502c8aeaec';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Еліктеу» енді эмоцияларға да ауысады. Сіз күлсеңіз, ол да күледі, ал Сіз байсалды болсаңыз, ол да үндемей қалады. Сіз — баланың эмоциялық айнасысыз. Онымен ойнағанда әртүрлі бет әлпетін көрсетіп, қайталауын сұраңыз. Бұл оның эмоциялық интеллекті мен өзгелерді түсіну қабілетінің дамуына көмектеседі.') WHERE id = 'c03e79b5-c416-4e9a-8cda-23ab824d2ea7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өздігінен жинау» дағдысы: Бала енді ойыншықтарын қорапқа жинауды «міндет» ретінде қабылдай алады. Ойын аяқталғаннан кейін: «Қане, мәшинелерді үйлеріне апарайық», — деп оны ынталандырыңыз. Бұл оның бойында ұқыптылықты және бастаған ісін аяқтау жауапкершілігін қалыптастырады. Әрдайым көмектесіп, мақтап отырыңыз.') WHERE id = '4be37208-93a9-4898-b72a-811ae2d7a051';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап» диалогі күрделене түседі. Ол «Бұл не?» деген сұрақты енді жауабын білмегендіктен ғана емес, Сізбен қарым-қатынасты жалғастыру үшін де қояды. Жауап бергенде сөйлемді сәл ұзартыңыз: «Бұл — қызыл алма, сен оны жақсы көресің». Бұл баланың сөздік қорын жылдам молайтады.') WHERE id = '59968193-d8d9-46a6-bcc6-77f1e1c44a81';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Доп тебу шеберлігі». Бала енді жүгіріп бара жатып, алдындағы допты тебе алады. Бұл қимыл мен тепе-теңдікті бір уақытта басқаруды талап етеді. Онымен үйде немесе аулада «футбол» ойнап, динамикалық тепе-теңдік дағдысын нығайтыңыз. Сізбен бірге қимылдау — ол үшін ең үлкен қуаныш.') WHERE id = '591884a7-b1fd-4edf-bb0d-3dca04af2ea4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімдерді білдіру». Бала қарны ашқанын, шаршағанын немесе бір нәрседен қорыққанын ерекше дыбыстармен не қарапайым сөздермен білдіре бастайды. Сіз оның бұл белгілерін сөзбен растаңыз: «Иә, сен шаршадың, кел, біраз демалайық». Бұл — болашақта өз эмоцияларын сөзбен жеткізіп, реттей білуіне көрсетілетін ең үлкен қолдау.') WHERE id = '402a1eb2-6224-49f3-92d8-6ebdc1c68d75';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Ойыншықтар жанданады». Бала ойыншық машиналарын жарыстырып немесе қуыршақтарын бір-бірімен «сөйлестіріп» ойнай бастайды. Бұл оның шығармашылығы мен күрделі ойлау қабілетінің дамып келе жатқанын көрсетеді. Сіз де осы рөлдік ойындарға қосылып, оқиғаны сәл кеңейтіңіз: «Машина жанармай құюға бара жатыр ма?».') WHERE id = '50b52b0c-f730-4500-a2ea-7d50f4678b25';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала қазір «Өзім істеймін!» кезеңінің шарықтау шегінде. Ол есікті өзі ашқысы, түймені өзі басқысы немесе баспалдақпен жалғыз көтерілгісі келеді. Бұл қырсықтық емес, ол өз мүмкіндіктерін сынап жүр. Қауіпсіз болған жағдайда оған әрекет жасап көруі үшін бірнеше секунд көбірек уақыт беріңіз. Бір нәрсені өзі істей алатынын көру — оның өзіне деген сенімін қалыптастыратын ең маңызды фактор.') WHERE id = '0424ded1-f254-419a-bacc-912b20a6465b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Допты нысанаға лақтыру». Бала енді допты жай ғана жерге тастамай, оны белгілі бір бағытқа немесе Сізге қарай лақтыруға тырысады. Бұл иық бұлшықеттері мен қол-көз үйлесімінің айтарлықтай дамығанын көрсетеді. Онымен «допты себетке лақтыр» ойынын ойнап, дәлдігін жетілдіріңіз.') WHERE id = 'd62bdbf3-d7fd-43c8-9cef-8ef0c95e0352';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сын есімдерді танып-білу». Бала енді заттарды жай ғана атап қоймай, олардың қасиеттерін де түсіне бастайды: «ыстық», «суық», «үлкен», «кішкентай». Тамақтанғанда немесе шомылғанда осы сөздерді жиі қолданыңыз: «Қарашы, мына су жылы». Бұл оған қоршаған ортаны егжей-тегжейлі сипаттауға және абстрактілі ойлауын дамытуға көмектеседі.') WHERE id = 'f549d4ea-b5e9-4a79-81eb-61a06771145c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Тізу және кіргізу». Бала моншақтарды жіпке тізуге (ірі моншақтарды және ересектердің бақылауымен) немесе кілтті құлыпқа салуға әрекеттенуі мүмкін. Бұл қимылдар саусақ бұлшықеттерінің аса дәл үйлесімін талап етеді. Мұндай жаттығулар болашақта қалам ұстау және жазу дағдыларының маңызды негізін қалайды.') WHERE id = '499eb64f-17b7-4928-a28f-32d77bae69bd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді ажыратып қана қоймай, олардың атауларын айтуға да тырысады. Оған "Көк мәшинені маған берші" дегенде дұрыс түсті таңдаса, бұл оның көру жады мен сөйлеуді түсіну қабілетінің үлкен жетістігі. Бұл білімі бекіуі үшін күнделікті киімдері мен ойыншықтарының түстерін жиі атап отырыңыз.') WHERE id = '1ab53f62-49d6-486d-9a52-ff092cc01b9c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы батылдық: Бала енді бір орында секіруге (екі аяғын бір мезгілде жерден көтеруге) көбірек талпынады. Бұл аяқ бұлшықеттері мен тепе-теңдік сезімінің үйлесімді жұмысын талап етеді. Жұмсақ кілемнің үстінде онымен "кім көбірек секіреді" ойынын ойнап, бойындағы күш-қуатын шығаруға мүмкіндік беріңіз.') WHERE id = 'fac02d76-edc4-45d2-ac23-faa60bad4132';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Орынды білдіретін сөздер". Бала енді "үстінде", "астында", "ішінде" сияқты сөздердің мағынасын іс жүзінде түсінеді. Оған "Допты орындықтың астына қой" деп айтып, тексеріп көріңіз. Мұндай тапсырмалар оның тілдік және кеңістікте бағдарлау дағдыларын дамытады. Осы ұғымдарды ойындарға қосу арқылы оның логикалық ойлауын жетілдіріңіз.') WHERE id = '30c8f80f-c5ad-42c7-a784-1930afcd9e96';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше таңдау" және ерік-жігер. Бала енді не киетіні немесе қай ыдыстан тамақ ішетіні туралы нақты пікірін білдіре алады. Оған "Бүгін көк ыдыстан тамақ ішкің келе ме, әлде жасыл ыдыстан ба?" деген сияқты таңдау мүмкіндігін беру өзін жеке тұлға ретінде сезінуіне көмектеседі және орынсыз қырсықтықтың алдын алады.') WHERE id = '6f9d4056-a417-4319-83b2-043809df814a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Дизайн және құрастыру". Бала енді 6-8 текшені (блокты) бірінің үстіне бірін қойып, биік мұнара құра алады. Бұл зейінін шоғырландыруды және қол қимылдарының дәлдігін талап етеді. Мұнара құлап қалғанда оны көңілді қабылдаңыз, сонда бала сәтсіздіктен қорықпай, қайтадан байқап көруге ынталы болады.') WHERE id = '17f5c5df-ea05-4d59-8a28-32ffc0cbb3e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Қамқорлық". Бала енді ойыншық қонжығын "тамақтандырып", оны "төсегіне жатқызып" немесе жылаған кезде "жұбата" алады. Бұл — символдық ойындардың дамуы. Сіздің балаға көрсеткен мейіріміңіз енді оның ойындарынан көрініс табады.') WHERE id = 'bc61e4f6-e294-4033-b040-474d57e5f13b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы «Суды өз бетінше ішу». Бала ашық стақаннан суды төгіп алмай дерлік, сенімді түрде іше алады. Бұл ерін мен жақ бұлшықеттерінің сөйлеуге қаншалықты дайын екенін көрсетеді. Осы дағдыны толық меңгеруі үшін оған балаға лайық, ұстауға ыңғайлы стақандар беруді жалғастырыңыз.') WHERE id = 'f0007c08-4f82-470d-976e-b690d945c125';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жаңа қорқыныштар: Бала кенеттен қараңғылықтан, қатты дыбыстардан немесе бетперде киген кейіпкерлерден қорқа бастауы мүмкін. Бұл оның қиялы мен қоршаған ортаны түсіну қабілетінің дамуымен байланысты. Оның қорқынышына күлмеңіз, жай ғана жанында болып, құшақтап, қауіпсіз жерде екенін сездіріңіз. Уақыт өте келе бұл қорқыныштардың орнын қызығушылық басады.') WHERE id = 'c56b4f54-c6b4-4285-a227-6cdf7c49e75e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Алғашқы күрделі сөйлемдер». Бала енді «Әкем келді», «Мен су іштім» сияқты өткен шақтағы қарапайым тіркестерді қолдана алады. Оның бұл талпыныстарын дұрыс грамматикамен қайталап, қолдау білдіріңіз. Сіздің сөйлеуіңіз — ол үшін ең басты үлгі. Онымен әрдайым анық әрі шынайы сөйлесіңіз.') WHERE id = 'ec0cb279-7627-42fd-8c4b-82e97e640420';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Артқа қарай жүру шеберлігі». Бала енді артына қарамай-ақ бірнеше қадам артқа жүре алады. Бұл оның денесінің кеңістіктегі орнын сезінуі (проприоцептивтік сезім) үшін маңызды. «Шаян сияқты жүрейік» деп, бұл қимылды ойынға айналдырыңыз. Сізбен бірге қимылдау — ол үшін әлемдегі ең қызықты ермек.') WHERE id = '891890ba-7797-463a-90b9-18dda87b2142';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '20-айға қадам басып келеміз! Баланың өзіне тән «талғамы» қалыптаса бастады. Ол кигісі келетін аяқкиімді немесе жегісі келетін тағамды қасарыса таңдауы мүмкін. Бұл оның ерік-жігерінің нығайып келе жатқанын білдіреді. Оған қауіпсіз екі нұсқаның бірін таңдауға мүмкіндік беріңіз: «Бүгін алма жейсің бе, әлде алмұрт па?». Бұл оның өзіне деген сенімін арттырып қана қоймай, қырсығу ұстамаларын да азайтады.') WHERE id = '9857fafb-dba1-41f5-bd34-455d5b939f6f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестірудегі «Динамикалық тепе-теңдік». Бала енді еңкейіп, жерден бір нәрсені алған кезде құламай қайта тұра алады. Бұл арқа және аяқ бұлшықеттерінің айтарлықтай нығайғанын көрсетеді. Ол үшін еденге әртүрлі биіктікте ойыншықтар қойып, оларды бір қорапқа жинауын сұраңыз. Бұл әрекет оның денесін басқару қабілетін жетілдіреді.') WHERE id = '21286f36-7532-41d3-a58d-4d4ecfb6df25';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Физикалық батылдық: «Өрмелеу және түсу». Бала баспалдақпен енді жылдамырақ әрі аяғын кезек-кезек басып (қолынан ұстасаңыз) көтеріле алады. Биіктікті сезінуі жақсарған сайын, оған қауіпсіз түсу жолын (артымен түсу) қайта-қайта көрсетіңіз. Қауіпсіздік қоршауларының әлі де орнында және жабық тұрғанына көз жеткізіңіз.') WHERE id = '3dfce46e-871b-4ff0-b52c-ef4021fb63e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Бала енді «Болмайды» деген сөзге жауап береді, бірақ кейде Сіздің реакцияңызды тексеру үшін ережелерді әдейі бұзуы мүмкін. Сабырлы, бірақ табанды болу — ең маңызды шарт. Егер бір нәрсеге «жоқ» десеңіз, оны әр жолы бірдей мәнерде қайталаңыз. Ережелердің тұрақтылығы баланың бойында ішкі тәртіп пен қауіпсіздік сезімін қалыптастырады.') WHERE id = '3d5db953-53d5-41ac-96c7-0de1abf8d13a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді ажыратып қана қоймай, оларды сәйкестендіре де алады. «Көк допты көк қорапқа сал» дегенде оны дұрыс орындаса, бұл — оның көріп қабылдау логикасындағы үлкен жетістік. Күнделікті өмірде «қызыл алма», «жасыл жапырақ» сияқты түске мән беретін сөз тіркестерін қолданып, осы білімін бекітіңіз.') WHERE id = '7bf7487b-3d3e-49a7-9bc5-a3a917c3fbbf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы жаңа дағды — «Бір орында секіру». Бала енді екі аяғын бір мезетте жерден көтеруге, яғни секіруге талпынады. Бұл аяқ бұлшықеттерінің күшін және тепе-теңдікті сақтауға қажетті күрделі үйлесімділікті талап етеді. Онымен бірге «Қоян сияқты секірейік» ойынын ойнаңыз. Бұл әрі көңілді, әрі дене дамуына өте пайдалы.') WHERE id = '37a6e358-9a9e-40cc-aab7-74b540fd0681';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу тілінде сын есімдер көбейеді. Бала енді заттардың атауын ғана емес, олардың қасиеттерін де (ыстық, суық, үлкен, кішкентай, жұмсақ, қатты) түсінеді. Тамақ ішіп отырғанда «Бұл езбе ыстық» немесе ойыншығын ұстағанда «Бұл қонжық жұмсақ» деп айтып, оның сезім мен қасиеттерді білдіретін сөздік қорын байытыңыз. Бұл балаға айналасындағы дүниені егжей-тегжейлі сипаттауға көмектеседі.') WHERE id = 'e5f3d411-7714-4b52-b440-c00913f921c9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Қарындаш ұстау» дағдысы жетіле түседі. Бала енді қарындашты алақанымен емес, саусақтарына жақындатып ұстауға тырысады. Қағаз бетіне сенімдірек шеңберлер немесе ретсіз болса да, анық әрі батыл сызықтар салады. Оған түрлі түсті қарындаштар мен үлкен қағаздар беріп, «шығармашылық» кеңістігін кеңейтіңіз.') WHERE id = '286d8a77-5c51-4a8f-96ae-733178c15fb0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дербестік: "Мен өзім киінемін". Балаңыз енді шұлығын шешуге, басына бас киімін киюге немесе оңай киілетін аяқкиімін аяғына сұғуға бұрынғыдан да табандырақ ұмтылады. Оған бұл әрекеттерді орындау үшін бірнеше минут артық уақыт беріңіз. Асықтырмай, өз бетінше бір нәрсе жасауына мүмкіндік беру оның өзіне деген сенімділігі мен дербестік сезімін қалыптастырады.') WHERE id = '947a00f0-f695-4c17-b833-1f7ad19529e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Кезек күту". Балаңыз енді саябақта әткеншек тебу немесе ойыншықпен ойнау үшін біраз күту керектігін түсінеді. "Қазір менің кезегім, содан кейін сенікі" деген ойындар арқылы оны сабырмен күтуге үйретіңіз. Бұл дағды — оның болашақта балабақша мен мектеп ортасына бейімделуіне қажетті ең маңызды әлеуметтік негіздердің бірі.') WHERE id = 'f555abb8-3ed3-4f14-968a-d2f98f543e71';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Тамақтанудағы "Шанышқы мен қасықты меңгеру". Балаңыз енді қасыққа тамақ салып, оны аузына төкпей дерлік жеткізуді үйреніп келеді. Оған шанышқымен түйреуге ыңғайлы (fork-friendly) көкөністер мен жемістердің кішкентай бөліктерін ұсыныңыз. Өз бетінше тамақтану оған тойғанын сезінуді үйренуге және құрылымы әртүрлі тағамдарға қызығушылық танытуға көмектеседі.') WHERE id = 'a925547f-11ed-45ce-9474-cab706a5ddda';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: "Ойыншықтармен диалог". Балаңыз енді қуыршағымен немесе қонжығымен "сөйлеседі", оларды "тамақтандырады" немесе "ұйықтатады". Бұл оның эмоциялық интеллекті дамып, күнделікті әрекеттерді қаншалықты терең меңгеріп келе жатқанын көрсетеді. Осы рөлдік ойындарға бірге қатысып, оқиғаны сәл кеңейтіңіз.') WHERE id = 'a151a89a-61af-4831-b10f-8a215a565721';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуы: "Доп тебу". Балаңыз енді тік тұрып, тепе-теңдігін жоғалтпай, алдындағы допты тебуге тырысады. Бұл — күрделі үйлесімділікті және бір аяқпен бір сәт тепе-теңдік сақтауды қажет ететін қимыл. Үйде немесе аулада онымен жеңіл доп ойнап, қимыл шапшаңдығы мен дәлдігін дамытуға көмектесіңіз.') WHERE id = 'deb4ac24-b3c7-4d6b-a7be-c36edea03c4e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 600 күнді аяқтадық! Балаңыз 20 айлық кезеңнің жартысына жетті. Ол енді қарапайым нұсқауларды толық түсінеді, эмоцияларын анық көрсетеді және әлемді бағындыруға дайын кішкентай "зерттеушіге" айналды. Бұл күнді онымен бірге сүйікті саябағында немесе ойын бөлмесінде уақыт өткізіп атап өтіңіз. Сіз керемет анасыз!') WHERE id = '1f1a3784-4c01-4fba-825d-ca3fcac15f79';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде "Сөз тіркестерін" қолдану қарқын алады. Бала енді өз қалауын екі-үш сөзбен жеткізеді: "Әке, допты бер", "Анашым, су іш". Ол сөйлеген кезде әрбір сөзін мұқият тыңдап, көзіне қараңыз. Сөздік қоры одан әрі молаюы үшін оның сөйлемдерін сәл кеңейтіп жауап беріңіз.') WHERE id = '4a36674f-0b66-41a0-beba-daa82b8d9f0b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — "Пазлдар мен басқатырғыштар". Бала енді 3-4 бөліктен тұратын қарапайым пазлдарды құрастыруды немесе пішіндерді сәйкес ойықтарға салуды жылдамырақ орындайды. Бұл оның кеңістікті қабылдауын да, көріп талдау қабілетін де дамытады. Тапсырма қиын болған кезде қызығушылығы жоғалмауы үшін оған шағын кеңестер беріңіз.') WHERE id = 'cce26ca5-c2df-4a63-a452-8753ade9a3fe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Символдық бөлісу". Бала енді өз ойыншығының бір бөлігін Сізге "ұсынуы" мүмкін (немесе оны бірден қайтарып алуы мүмкін). Бұл — бөлісу ұғымының алғашқы нышандары. Оның бұл әрекетін міндетті түрде мақтаңыз: "Ойыншығыңды маған көрсеткеніңе көп рақмет". Бұл оның бойында жағымды әлеуметтік дағдылардың негізін қалайды.') WHERE id = '35b68ddd-9074-4a9a-97b7-0fddbf831df1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім тазалаймын". Бала Сізге еліктеп, қолын құрғатуға, бетін сүртуге немесе дастарқанды ойыншық шүберекпен тазалауға талпынады. Оның дербестікке деген ынтасын баспаңыз. Оған өзінің кішкентай сүлгісін немесе щеткасын беріп, "үй шаруасына" қатыстырыңыз. Бұл оның бойында жауапкершілік сезімін қалыптастырады.') WHERE id = '37a69b03-aa17-4bad-982a-11091970591b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Жад, әсіресе "Кеңістіктік жад", жоғары деңгейде дамып келеді. Бала енді Сіз жасырған ойыншықтың орнын бірнеше сағаттан кейін де есіне түсіре алады. Онымен үйде "қазына іздеу" ойынын ойнаңыз. Бір ойыншықты жастықтың астына қойып, оны қалай тауып алатынын бақылаңыз. Бұл ойын оның зейінін шоғырландыруына да, мәселені шешу дағдысына да оң әсер етеді.') WHERE id = '105285fc-eb7a-4111-ad71-74ef8c1d89b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: "Ойыншықтармен диалог". Бала қуыршағымен немесе ойыншық қонжығымен "сөйлеседі", оларға тамақ береді немесе ұйықтатады. Бұл — эмоциялық интеллектінің дамуы мен күнделікті рәсімдерді меңгеруінің белгісі. Онымен бірге осы рөлдік ойындарға қосылыңыз: "Қонжық қазір қайда бара жатыр?". Бұл оның шығармашылық ойлауын қарқынды дамытады.') WHERE id = '1d1a3072-a955-4f0c-b97e-45be9ab5c292';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Сәйкестендіру" (Matching). Бала енді бір жануардың немесе заттың екі түрлі суретін бір-бірімен сәйкестендіре алады. Онымен қарапайым карточкаларды пайдаланып, "Дәл сондайын тап" ойынын ойнаңыз. Бұл оның көру зейіні мен есте сақтау қабілетін керемет дамытады. Дұрыс тапқан кезде қуана қолдау көрсетіңіз, сонда оның қызығушылығы жоғалмайды.') WHERE id = '45e380ad-6559-467d-84f4-eced81427f7d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: "Баспалдақтан бір-бір қадамдап түсу". Қолынан ұстасаңыз, бала енді баспалдақтан сенімдірек, бір-бір қадамдап түсуге тырысады. Төмен түсу жоғары көтерілуден қиынырақ әрі тепе-теңдікті көбірек сақтауды талап етеді. Қауіпсіздігі үшін әрдайым жанында болыңыз және баспалдақтың тұтқасынан ұстауына мүмкіндік беріңіз.') WHERE id = '9b3b0e2c-c4cd-4d64-a63f-e74713052b56';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы "Сезімдерді атау". Бала ашуланғанда, қуанғанда немесе ұялғанда, оның сезімдерін сөзбен жеткізіңіз: "Сен қазір қатты қуанып тұрсың!", "Ойыншығың құлап кеткендіктен, көңілің сәл түсіп кетті ме?". Сезімдерді атау балаға болашақта "tantrum" (ашу ұстамалары) кезінде өзін оңайырақ басқаруға көмектеседі.') WHERE id = 'da0fa9b2-9fec-47fb-a56d-5e0c384540ea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: "Қиялдан туған ойындар". Бала енді бір затты екіншісінің орнына қолдана алады. Мысалы, текшені "телефон" деп елестетіп, құлағына ұстауы мүмкін. Бұл — баланың абстрактілі ойлауы мен шығармашылығының жарқын көрінісі. Онымен бірге осындай ойындарды ойнап, қиялын қолдаңыз.') WHERE id = 'f71a9e64-80ca-4672-869a-4b4e2012c4b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді "Мен" және "Менікі" деген сөздерді жиірек қолданады. Бұл оның жеке шекарасы мен дербес тұлғасын түсіне бастағанының белгісі. Сүйікті ойыншығын құшақтап, "Менікі!" деуі қалыпты. Оған өз заттарына иелік етуге мүмкіндік беріңіз. Бұл — болашақта басқалардың да жеке шекарасын құрметтеуіне негіз болатын маңызды қадам.') WHERE id = 'b7d51937-c7a2-4d6d-b732-4b494fc952b3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы "Артқа жүру шеберлігі". Бала енді артына қарамай және тепе-теңдігін жоғалтпай, бірнеше қадам артқа жүре алады. Бұл оның өз денесінің кеңістіктегі орнын сезінуін (проприоцептивті сезім) дамытуға арналған тамаша жаттығу. Онымен "Шаян сияқты жүрейік" ойынын ойнаңыз. Бұл әрі көңілді әрекет, әрі аяқ бұлшықеттерін өзгеше жұмыс істетеді.') WHERE id = '513f1229-f55a-4c5d-a40b-fc0fd9f8ae37';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «сын есімдерді тіркестіру». Бала енді заттарды жай ғана атамай, олардың түсін немесе көлемін де қосып айтады: «Үлкен доп», «Қызыл мәшине». Оның бұл талпыныстарын қолдап, сөйлемін сәл кеңейтіңіз: «Иә, бұл сенің үлкен әрі жұмсақ добың».') WHERE id = 'b2c7d131-58dd-486b-9609-a0affe8ae4df';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «тік және көлденең сызықтар». Бала енді қарындашты сенімдірек ұстап, қағазға мақсатты түрде түзу сызықтар салуға тырысады. Оған жуан түсті қарындаштар мен үлкен сурет қағаздарын беріңіз. Ол салған әрбір сызық қол мен көз үйлесімділігін жақсартып, болашақ жазу дағдыларын нығайтады.') WHERE id = 'cc6fb892-8f1f-42d8-95a3-eba0a72b0349';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше таңдау» және киім. Бала енді қандай шұлық немесе баскиім кигісі келетіні жөнінде нақты пікірін білдіреді. Оған қауіпсіз екі нұсқа ұсыныңыз: «Бүгін жасыл баскиіміңді киесің бе, әлде көгін бе?». Осындай шағын шешімдер балаға өзін маңызды сезінуге көмектесіп, қырсығу ұстамаларын барынша азайтады.') WHERE id = '38af9059-ae27-4644-b4e5-977b53c68250';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «ынтымақтастық»: бала енді ойыншықтарын бірге жинаудан қуаныш алады. «Кел, мәшинелерді бірге орнына қояйық» десеңіз, ол Сізге көмектеседі. Бұл әрі ұқыптылық дағдысын қалыптастырады, әрі бірлескен әрекеттен қуаныш сыйлайды. Әр көмегінен кейін оны мақтауды ұмытпаңыз.') WHERE id = '49ba697d-2e60-439d-966b-ca621530805d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «бөліктерді біріктіру». Бала енді екі немесе үш бөліктен тұратын қарапайым пазлдарды (басқатырғыштарды) өз бетінше құрастыра алады. Сурет бөліктерін біріктіріп, толық бейнені көру оның көрнекі-кеңістіктік ойлауын дамытады. Қолынан келмей жатса, сабырмен бағыт беріңіз: «Қарашы, иттің құйрығы осында». Бұл оның мәселені шешуге деген табандылығын арттырады.') WHERE id = '1bcc9149-af08-4bbd-bac4-e8848b1380ea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «доп тебу және жүгіру». Бала енді жүгіріп келе жатып, алдындағы допты тебе алады. Бұл қимыл жылдамдығы мен динамикалық тепе-теңдікті бір уақытта басқаруды білдіреді. Онымен үйде немесе саябақта «футбол» ойнап, қимыл дәлдігін жетілдіріңіз.') WHERE id = '56be9450-be4f-4da2-bbc6-79d6b2c42f94';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '20-айдың соңғы онкүндігіне аяқ басамыз. Бала енді дене мүшелерін жай ғана көрсетіп қоймай, олардың не үшін қажет екенін де түсіне бастайды. «Аяқтарыңмен не істейсің?» деп сұрасаңыз, ол жүгіруді немесе аяғымен тарсылдатуды көрсетуі мүмкін. Онымен «Бұл не үшін керек?» ойынын ойнаңыз. Бұл оның сөздік қорын да, функционалдық ойлауын да дамытады.') WHERE id = 'dee4db38-d5ad-4ab8-80a6-e91df1c6234f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс дағдыларындағы «Кедергілердің астынан өту». Бала енді тік тұрумен қатар, еңкейіп үстелдің немесе орындықтың астынан өтуді және кеңістікте өз денесінің өлшемін бағалауды үйренеді. Бұл оның өз денесін сезінуін (body awareness) арттырады. Үйде жастықтар мен орындықтардан «туннельдер» жасап, осы дағдысын жаттықтырыңыз.') WHERE id = '4db05b48-52f1-4673-a7b9-28436103d6d9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есімдіктердің алғашқы белгілері». Бала енді өзі туралы «Мен», ал Сізге «Сен» деп айтуға (немесе өз тілінде оларды басқа дыбыстармен білдіруге) тырысады. Бұл оның өзін қоршаған ортадан бөлек, жеке тұлға ретінде сезіне бастағанын көрсетеді. Ол өз атын атағанда: «Иә, сен, (атын атаңыз), осындасың», — деп, оның өзіндік «мен» сезімін нығайтыңыз.') WHERE id = '15ef8b0a-68af-41c5-881d-ef1aaddc31ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрандалы қақпақты ашу». Бала енді бөтелкенің қақпағын бұрап ашуға немесе жабуға тырысады. Бұл қимыл білек бұлшықеттерінің айналмалы қозғалысын жаттықтыруға өте пайдалы. Оған әртүрлі өлшемдегі қауіпсіз ыдыстар беріп, осы жаңа «дағдысын» сынап көруге мүмкіндік беріңіз.') WHERE id = 'eca36160-9ece-4da0-80c8-687ec7c51745';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Көмектесуге ұмтылу». Бала енді азық-түлік салынған сөмкеден бірдеңе шығаруға немесе Сізге бір нәрсе әкелуге құлшынады. Оған «Өтінемін, мына жөргекті маған берші» деген сияқты шағын тапсырмалар беріңіз. Тапсырманы орындағанда: «Маған көп көмектестің, рақмет», — деп айтыңыз. Бұл оның бойында әлеуметтік жауапкершілік пен өзін пайдалы сезіну сезімін қалыптастырады.') WHERE id = 'ee7370f4-6eb2-48da-aebb-00ccc3c2ad1b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Тісті өз бетінше тазалау». Бала енді Сізге еліктеп, тіс щеткасын аузына салып, қозғалтады. Әзірге бұл жай ғана ойын, тістерін әлі де Сіз тазалауыңыз керек. Дегенмен оның осы әдетке қызығушылығын қолдаңыз. Өз тіс щеткасының болуы және тісін өзі тазалауға талпынуы гигиеналық әдеттердің қалыптасуына жақсы негіз қалайды.') WHERE id = '183dc3b9-e225-46b4-b630-b164f5414528';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Неге?» деген сұрақтың алғашқы белгілері. Бала әр нәрсені көрсетіп, «Бұл?» деп Сіздің түсіндіруіңізді күтеді. Әр заттың атауын және не үшін қолданылатынын қарапайым сөйлемдермен түсіндіріңіз. Мысалы: «Бұл — тіс щеткасы, онымен тісімізді тазалаймыз». Сіздің жауаптарыңыз оның санасында қоршаған әлемді жүйелі түрде топтастыруға көмектеседі.') WHERE id = 'cd8ca16e-d97a-4620-91cf-5f294687b3b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дамудағы «Өзін-өзі басқаруға талпыныстар». Бала ашуланғанда Сізге қарап, реакцияңызды күтуі мүмкін. Мұндай сәттерде сабыр сақтап: «Ойыншықты құрастыра алмағандықтан, сен қазір ашуланып тұрсың», — деп оның сезімін атаңыз. Сіздің сабырлылығыңыз — бала үшін эмоцияларын реттеудің ең жақсы үлгісі. Сіз керемет анасыз!') WHERE id = '10a65a4a-b905-4a99-8c90-141b7917fa27';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз қасық пен шанышқыны бұрынғыдан да шебер қолданады. Ол тамақтың көп бөлігін төкпей, аузына жеткізе алады. Бұл ұсақ моторика мен қол-көз үйлесімінің жоғары деңгейде дамығанын көрсетеді. Оған құрылымы әртүрлі тағамдарды өздігінен жеуге мүмкіндік беріңіз. Мұндай дербестік баланың тойғанын жақсырақ сезінуіне көмектеседі.') WHERE id = 'cd235f0e-55bc-496a-a89f-89523cd7e8fe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Физикалық дамудағы «Өрмелеу және түсу». Бала диванға немесе аласа баспалдақтарға өздігінен көтеріле алады. Оған биіктен әрдайым артқа қарай, алдымен аяғын түсіріп түсу керектігін еске салыңыз. Бұл — дене қауіпсіздігі ережелерін меңгеруге және қауіп-қатерді көзбен бағалауға көмектесетін маңызды дағды.') WHERE id = 'b1b72a87-fa8e-4ffe-811e-9806f2ea1d7c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Қимылды білдіретін сөздер». Бала «кет», «кел», «ұйықта», «же» сияқты етістіктерді тиісті жағдайларда қолдана бастайды. Оның сөзін кеңейтіп жауап беріңіз: «Иә, қазір біз саябаққа барамыз». Бұл баланың сөйлеуінде грамматикалық құрылымдардың қалыптасуын жеделдетеді.') WHERE id = '275f2048-2ec2-445d-b693-5c34e41e7b83';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Тізу және құрастыру». Бала 8-10 текшені бірінің үстіне бірін қойып, құламайтын мұнаралар құрастыра алады. Бұл зейінді шоғырландыруды да, саусақ ұштарының дәлдігін де талап етеді. Мұнара құлағанда, оны қуана қабылдаңыз, сонда бала қайтадан байқап көруге ынталы болады. Бұл оның мәселені шешудегі табандылығын арттырады.') WHERE id = '97370ca6-2fbc-4894-81aa-9ab979d2d27e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Символдық қамқорлық". Бала ойыншық қонжыққа "су ішкізіп", оны көрпемен жауып немесе жылаған кезде сипап жұбатуы мүмкін. Бұл оның эмоциялық интеллектісі мен өзгенің сезімдерін түсіну қабілетінің дамып келе жатқанын көрсетеді. Оның осындай мейірімді әрекеттерін мақтауды ұмытпаңыз.') WHERE id = '4c44b890-83ea-41cb-99e6-72cdc0b1bf1f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше жинау" дағдысы: Бала енді ойыншықтарын қорапқа жинауды ойынның аяқталуы ретінде қабылдай бастайды. "Кел, мәшинелерді жатын орнына қояйық" деп, бұл үдерісті қызықты етіңіз. Бұл оның бойында тәртіп пен жауапкершілік сезімін қалыптастырады. Сізге көмектескенде, ол өзін ересек әрі пайдалы адам ретінде сезінеді.') WHERE id = 'a363f89b-584e-494b-8c74-513903336560';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Бірдей және әртүрлі" ұғымдары. Бала енді түсі немесе түрі бірдей заттарды топтастыра алады. Оған "Барлық қызыл заттарды осында жинайық" деп айтып, байқап көріңіз. Мұндай ойындар оның логикалық ойлауы мен көріп талдау қабілетінің негізін қалайды.') WHERE id = 'f0afc0a3-b89f-4803-b20f-1fd14e1c84af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: "Төбеден төмен жүру". Көлбеу жерлерде (шағын төбешіктерде) жүру баладан тепе-теңдікті жаңаша сақтауды талап етеді. Бұл оның тобықтарын және денесінің ауырлық орталығын басқару қабілетін нығайтады. Саябақта серуендегенде, осындай шағын дене жаттығуларын орындауына мүмкіндік жасаңыз.') WHERE id = 'c7f6bf36-ec3f-4dad-b529-a2a1c67afd8f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Есім мен есімдік байланысы". Бала енді өзін атымен атаудан "Мен" деуге ауыса бастауы мүмкін. Сіз одан бір нәрсе сұрағанда, ол "Мен" немесе "Менікі" десе, бұл оның өзін жеке тұлға ретінде сезінуі қалыптасып келе жатқанын көрсетеді. Онымен осы тақырыпта диалог құрыңыз: "Бұл кімнің добы? Менікі!".') WHERE id = 'da725a7e-8a5a-4880-b76d-f59275696659';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: "Күрделі еліктеу". Бала енді бірнеше қадамнан тұратын әрекеттерді қайталай алады. Мысалы, "базарға барады", "азық-түлік сатып алады" және "тамақ пісіреді". Бұл оның есте сақтау қабілетін де, оқиғалар арасындағы логикалық байланысты қаншалықты терең байқайтынын да көрсетеді.') WHERE id = '385dd8e9-365e-4aee-b063-18466c68a303';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Пазл және логика». Бала енді 4-5 бөліктен тұратын қарапайым пазлдарды өз бетінше құрастыруға талпынады. Сурет бөліктерін көзбен сәйкестендіру оның зейінін шоғырландыру және мәселені шешу қабілеттерін дамытады. Қолынан келмей жатса, сабырмен бағыт көрсетіңіз, бірақ орнына жасап бермеңіз. Осындай шағын «жеңістер» оның танымдық қабілетін нығайтады.') WHERE id = '39e90e4b-782c-46d9-9e9f-4cff4dfc1e98';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Артқа қарай жүру». Бала енді артқа қарай бірнеше қадамды сенімді жасай алады. Бұл — тепе-теңдікті сақтаудың күрделі түрі әрі дененің кеңістіктегі қимылын үйлестіруді талап етеді. Онымен бірге «Шаян сияқты жүрейік» ойынын ойнаңыз. Бұл әртүрлі бұлшықет топтарын іске қосып қана қоймай, көңілді әрі күлкіге толы сәттер сыйлайды.') WHERE id = 'f9c866fa-1063-46f8-bd49-769efa10ff9a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап» диалогі күрделене түседі. Ол «Бұл не?» деген сұрақты заттың атауын білу үшін ғана емес, Сізбен әңгімені жалғастыру үшін де қоюы мүмкін. Жауап бергенде заттың не үшін қолданылатынын да айтыңыз: «Бұл — тарақ, онымен шашымызды тараймыз». Сіздің кеңірек түсіндіруіңіз оның дүниетанымын жылдам кеңейтеді.') WHERE id = 'b9cee91c-b40d-4bad-a4d5-c04129fdcf20';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар және «Жоқ». Бала бәрін өзі жасағысы келгенде немесе қалауы бірден орындалмағанда ашулануы мүмкін. Мұндай сәттерде сабыр сақтап, «Сен қазір қатты ашуланып тұрсың, бірақ (ережені айтыңыз) жасауға болмайды» деп, оның сезімін атап беріңіз. Сіздің бірізділігіңіз бен сабырлы үнмен түсіндіруіңіз — оған эмоцияларын басқаруды үйрететін ең жақсы үлгі.') WHERE id = '4c29e86c-55c8-4844-9903-13a58d0c9468';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді екі кезеңнен тұратын тапсырмаларды оңай орындайды. Мысалы: «Ойыншықты ал да, сөреге қой». Бұл оның жұмыс жады мен тілді түсіну қабілетінің жаңа деңгейге жеткенін көрсетеді. Күні бойы осындай шағын «міндеттер» беру арқылы оның жауапкершілік сезімі мен зейінін қатар дамытыңыз.') WHERE id = '63b64ef1-0e7a-45db-8f97-702657621c76';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Баспалдақпен көтерілу шеберлігі». Бала енді бір қолынан ұстаған кезде баспалдақпен әр сатыға бір аяғын қойып көтерілуге талпынуы мүмкін. Бұл сан мен жамбас бұлшықеттерінің нығайғанын білдіреді. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз және әр жетістігін қошеметтеңіз.') WHERE id = '4d704d6f-6be2-478b-b2bb-0363d0dde71b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала 22-айының ортасына келді, оның сөздік қорындағы «сөз жарылысы» әлі де жалғасып жатыр. Ол енді заттарды ғана емес, күрделі сезімдер мен әрекеттерді де атауға тырысады. Онымен сөйлескенде сөйлемдеріңізді сәл күрделендіріңіз: «Кел, қызыл баскиіміңді киіп, далаға шығайық». Бұл оның есту жадын және грамматиканы түсінуін жақсартады.') WHERE id = '9ec78a78-6722-4c40-af92-d0238d028cd3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Бір орында секіру шеберлігі». Бала енді екі аяғын бір мезетте жерден көтеріп секіруді сенімдірек орындайды. Бұл қимыл оның балтыр бұлшықеттерін нығайтып, тепе-теңдік сақтау қабілетін дамытады. Онымен бірге музыка әуенімен секіруден жарыс ұйымдастырыңыз. Бұл — бойындағы энергияны шығарудың ең көңілді жолы.') WHERE id = '43c73105-af4e-4d3a-b15d-a50b903d4d3e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу тіліндегі «Сын есімдердің көбеюі». Бала енді заттардың қасиеттерін (түсін, пішінін, дәмін) жақсырақ ажыратады. «Қышқыл лимон», «тәтті алма», «салқын су» сияқты тіркестерді оның күнделікті өміріне енгізіңіз. Бұл оған сезім арқылы қабылдағанын сөздермен байланыстырып, айналасындағы әлемді алуан түрлі етіп сипаттауға көмектеседі.') WHERE id = '39e55b53-a529-49e6-9321-ad14c32b7c7c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрандалы қақпақтарды ашу». Бала енді өлшемі әртүрлі бөтелке қақпақтарын немесе ыдыстарды бұрап ашуға қызығушылық танытады. Бұл қимыл білек бұлшықеттерінің айналмалы қозғалысын жаттықтыруға өте пайдалы. Оған қауіпсіз, бос пластик ыдыстар беріп, осы «механикалық» қызығушылығын қолдаңыз.') WHERE id = 'be39779f-3011-4da7-aa56-861a48e906e9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім киінемін» деген қырсықтығы шегіне жетті. Бала енді оңай киілетін шалбарды тартып киюге немесе аяқкиімін аяғына сұғуға тырысады. Бұл үдеріске оған бірнеше минут артық уақыт беріңіз. Асықтырмай, өз бетімен бір нәрсені істей алуына мүмкіндік беру оның өзін-өзі бағалауын (self-esteem) бәрінен де жақсы арттырады. Сіздің сабырлылығыңыз — оның дербестігіне қосқан ең үлкен үлесіңіз.') WHERE id = 'f0ed327b-3dc6-4a59-97ba-d4b77cc256ae';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің алғашқы сабақтары». Бала енді ойыншықты басқа біреуге біраз уақытқа беру одан біржола айырылу емес екенін түсінеді. Алайда «бұл менікі» деген сезімі әлі де өте күшті. Оны бөлісуге мәжбүрлемеңіз, оның орнына «кезекпен ойнау» ұғымын іс жүзінде көрсетіңіз. Бұл оның әлеуметтік ортаға бейімделуін жеңілдетеді.') WHERE id = 'ea8bf74e-874e-47bc-9e0f-7dc3094dfe1c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «себеп-салдар» тіркестері. Бала енді «Өйткені» деп (немесе соған ұқсас дыбыспен) айтуға тырысып, неліктен бір нәрсені қалайтынын түсіндіре алады. Сіз де оған себептерін түсіндіріңіз: «Қазір балмұздақ жемейміз, өйткені күн суық». Бұл — оның логикалық ойлауы мен өз ойын дәлелдеу қабілетінің негізі.') WHERE id = 'f2f8883c-9f63-473e-95a0-d34bd2a07048';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрау және айналдыру». Бала енді бөтелкелердің қақпақтарын, ойыншық бұрандаларын сенімді бұрап ашып-жаба алады. Бұл — білек бұлшықеттерінің айналмалы қимылын жаттықтырудың ең жақсы тәсілі. Оған әртүрлі көлемдегі пластик ыдыстар беріп, осы механикалық әрекеттерге деген қызығушылығын қолдаңыз. Бұл дағды болашақта қалам ұстау сияқты күрделі әрекеттер үшін маңызды.') WHERE id = '691bb5ce-e086-4aaa-85cf-679930593155';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім жуынамын». Шомылған кезде бала сабынды немесе жөкеліні алып, денесін ысқылап, Сізге еліктеуге тырысады. Оның тазалық дағдыларына деген қызығушылығын баспаңыз. Өзінің «тазалануына» мүмкіндік беру дене мүшелерін жақсырақ танып-білуіне және жеке бас гигиенасына жауапкершілікті ерте жастан үйренуіне көмектеседі.') WHERE id = 'd4a78241-9e41-44ca-8bb9-8ed66f07c05f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің қиындығы». Бұл жаста «Менікі!» деп айқайлау — қалыпты жағдай. Бала өзіне тиесілі заттарды қорғауды үйреніп жүр. Оны бөлісуге мәжбүрлемеңіз, оның орнына «Кезекпен ойнайық» қағидасын қолданыңыз. Бұл балаға қауіпсіздік сезімін береді: ол ойыншығын қайта алатынын біледі. Сіздің осындай сабырлылығыңыз оның әлеуметтік зердесін қалыптастырады.') WHERE id = '6ff62ac3-5f68-4753-ac59-118eb1c39c2b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сәйкестендіру» (Matching). Бала енді бір жануардың әртүрлі суреттерін немесе түсі бірдей заттарды өзара сәйкестендіре алады. Онымен қарапайым карточкаларды қолданып, «Дәл сондайын тап» ойынын ойнаңыз. Бұл оның көру зейінін де, санаттар бойынша ойлау қабілетін де қарқынды дамытады.') WHERE id = '63ba4843-04a1-423b-8338-e5d3a90cedb9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты алысқа лақтыру». Бала енді допты жай ғана жерге тастамай, оны иықтан асыра (overhand) алға қарай лақтыруға тырысады. Бұл қимыл бүкіл дене қозғалысын үйлестіруді талап етеді. Онымен саябақта немесе кең алаңда «Кім допты алысырақ лақтырады?» ойынын ойнаңыз. Бұл оның қолдарын нығайтып қана қоймай, қашықтықты қабылдау қабілетін де жетілдіреді.') WHERE id = '972bc93a-ef8b-4efd-af66-730802aaa073';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «өтініш білдіру» дағдысы. Бала енді бірдеңе қалағанда саусағымен жай ғана көрсетпей, «Берші» немесе «Өтінемін» (не соған ұқсас сөз) деп айта алады. Оған әрдайым сыпайы сөйлеудің үлгісін көрсетіңіз. Сізден «Рақмет» немесе «Өтінемін» деген сөздерді естуі оның болашақ қарым-қатынас мәдениетінің негізін қалайды.') WHERE id = '0ffa5444-e49f-4507-b5e7-cc95f08b1d36';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Рөлдік ойындар күрделене түседі». Бала енді жай ғана тамақ пісірмейді, ойыншықтарын қонаққа шақырады, оларды «емдейді» немесе «көлікке отырғызып, жұмысқа апарады». Бұл оның жадында сақталған оқиғаларды қалай байланыстыратынын көрсетеді. Онымен бірге осы рөлдік ойындарға қатысыңыз, бұл оның шығармашылығын одан әрі дамытады.') WHERE id = '24d4307d-0d0c-428b-a2fb-db25c78400d8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді танып қана қоймай, оларды сәйкестендіруді де жақсы меңгере бастайды. Оған «Қызыл шұлығыңның сыңарын тап» дегенде дұрыс тапса, бұл оның көрнекі ойлау қабілетінің дамып келе жатқанын білдіреді. Күнделікті киінген кезде түстерді жиі атап отырыңыз: «Бүгін жасыл жейдеңді киеміз бе?». Бұл оның сөздік қорындағы сын есімдерді бекітуге көмектеседі.') WHERE id = '179a1147-4671-4989-8a35-24a67964487b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Бір аяқпен тепе-теңдік сақтау» дағдысы. Бала бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл — дененің ауырлық орталығын басқаруды қажет ететін күрделі үйлесімді қимыл. Онымен бірге «Ләйлек» ойынын ойнаңыз. Бұл әрі көңілді, әрі дене дамуына өте пайдалы.') WHERE id = '6a2ac5db-ce06-4c8b-b0f1-21122d14d9a3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт ұғымының алғашқы белгілері». Бала «қазір», «кейін» сияқты сөздердің айырмашылығын түсіне бастайды. Оған «Алдымен тамақ ішеміз, содан кейін саябаққа барамыз» дегенде күте алса, бұл — үлкен жетістік. Шыдамдылық дағдысы қалыптасуы үшін іс-әрекеттердің ретін түсіндіруді жалғастырыңыз.') WHERE id = '91b2f1d2-b8e0-4586-beb2-1ed7668e668d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пазл құрастыру шеберлігі». Бала енді 5-6 бөліктен тұратын қарапайым пазлдарды өз бетінше құрастыра алады. Сурет бөліктерін көзбен сәйкестендіру оның зейінін шоғырландыру және мәселені шешу қабілеттерін дамытады. Қолынан келмей жатса, сабырмен бағыт көрсетіңіз, бірақ оның орнына орындамаңыз. Осындай шағын «жеңістер» оның танымдық қабілетін нығайтады.') WHERE id = 'feada4a3-1665-4491-8ec1-8dc39ef9224c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Жыл мезгілдері мен ауа райы». Бала даладағы ауа райының өзгеруін (жаңбыр, күн, жел) байқап, оған жауап бере бастайды. Терезеден қарап, «Жаңбыр жауып тұр» деп құбылыстарды атап отырыңыз. Бұл оның қоршаған ортамен байланысын нығайтып, сөздік қорын табиғатқа қатысты жаңа сөздермен толықтырады.') WHERE id = 'e5dc7560-975f-4493-9ff3-ea6744e46ec0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс үйлесімі: «Допты нысанаға тебу». Бала енді алдындағы допты жай ғана теппей, оны белгілі бір бағытқа (мысалы, қақпаға) бағыттауға тырысады. Бұл — көру зейіні мен қимыл үйлесімінің бірлесуі. Үйде онымен жұмсақ доппен шағын «футбол» ойынын ойнаңыз.') WHERE id = 'f701f5d4-0488-45fc-bf57-a9b74d61b0af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Есте сақтау және ертегілер». Бала сүйікті ертегісін жақсы білетіні соншалық, Сіз сөйлемді аяқтамай тоқтасаңыз, ол жалғастырып айта алады. Ертегі оқығанда кідіріс жасап, оның жалғастыруын күтіңіз. Бұл оның есте сақтау қабілетін де, оқиғалардың ретін түсіну дағдысын да керемет дамытады.') WHERE id = 'c61438a5-bdff-4ed0-b914-6e977fdb2bc1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дайындық: 2 жасқа толуына санаулы күндер қалды! Бала енді өз сезімдерін күрделірек түрде білдіреді. Ол кенеттен құшақтағысы келуі немесе дербестігін көрсету үшін жүгіріп барып жасырынуы мүмкін. Осы кезеңде онымен сабырлы сөйлесіп, әр қадамында жанында екеніңізді сезіндіру — оның эмоциялық қауіпсіздігі үшін ең маңызды қадам.') WHERE id = 'bcd3ac04-2293-413d-8bfd-ba0e21e03fe2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өз талғамы мен таңдауын батыл көрсетеді. Ол қай кітапты оқитыныңызды немесе қай ойыншықпен ойнайтыныңызды өзі шешкісі келеді. Оған осындай шағын көшбасшылық мүмкіндіктерді беріңіз. Бұл оның шешім қабылдау қабілетін дамытып қана қоймай, өзін құнды тұлға ретінде сезінуіне де көмектеседі.') WHERE id = 'b41a09b6-e8fc-4b09-b81c-400b678af920';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Динамикалық тепе-теңдік». Бала енді бір сызықтың бойымен жүруге немесе аласа жиекпен (қолынан ұстағанда) қадам басуға тырысады. Бұл — дененің ауырлық орталығын басқаруға арналған тамаша жаттығу. Саябақта серуендегенде жерге сызылған сызықтардың бойымен жүру ойынын ойнап, оның қимыл үйлесімін нығайтыңыз.') WHERE id = '5d42a805-244d-4112-9107-40ebc50ef785';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім ішемін". Бала енді ашық стақаннан суды төкпей дерлік, сенімді түрде іше алады. Бұл оның ерін және жақ бұлшықеттерінің сөйлеуге қаншалықты дайын екенін көрсетеді. Осы дағдыны толық меңгеруі үшін оған балаға арналған, ұстауға ыңғайлы стақандарды беруді жалғастырыңыз.') WHERE id = '20e5b03d-5d16-4142-97b2-3cffec7b0034';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Әзіл сезімі". Бала әдейі бір нәрсені "дұрыс емес" жасап (мысалы, баскиімін аяғына киіп), Сізге қарап күлуі мүмкін. Бұл оның әзілді түсіне бастағанын және әлеуметтік ықпал ету қабілетінің қалыптасып келе жатқанын көрсетеді. Оның осы "ойынына" ықыласпен қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты одан әрі нығайтады.') WHERE id = '0f7fea0c-bb47-4b7d-9391-ab4589f33670';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Биіктік пен арақашықтық". Бала енді баспалдақтан немесе диваннан түскенде арақашықтықты жақсырақ бағалай алады. Оған әрдайым абай болуды және қауіпсіз түсу тәсілдерін (артпен түсу) еске салып отырыңыз. Бұл — оның дене қауіпсіздігі ережелерін меңгеруіндегі маңызды кезең.') WHERE id = '6dd30633-3c9b-4455-9878-c9a89b329928';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: "Секіру кезіндегі бағытты өзгерту". Бала енді бір орында ғана секірмей, секіру кезінде бағытын өзгертуге тырысады. Бұл ірі моторикаға жауапты бұлшықеттердің жақсы үйлесімді жұмыс істейтінін көрсетеді. Онымен бірге жұмсақ кілемнің үстінде қимылды ойындар ойнаңыз. Бұл оған әрі энергиясын шығаруға, әрі денесін жақсырақ басқаруға көмектеседі.') WHERE id = '85fd0d24-866e-4847-be35-912d99da58df';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы "Жануарлар және олардың төлдері". Бала жануарлардың атауларын біледі, енді олардың төлдерін (мысалы, мысық пен марғауды) ажыратуға қызығушылық танытуы мүмкін. Кітап оқығанда осы ерекшеліктерге назар аударыңыз. Бұл оның санаттар бойынша ойлау қабілетін дамытып, табиғатқа деген қызығушылығын арттырады.') WHERE id = 'ce938ec0-b1a1-418d-9c79-f5996a2ee822';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дамудағы "Ерік пен шекаралар". Бала енді "Жоқ" сөзінің күшін толық түсінеді және оны жиі қолданады. Мұндай сәттерде сабыр сақтап, оған таңдау мүмкіндігін беру арқылы "жоқты" "иәға" айналдыруға тырысыңыз. Сіздің табандылығыңыз бен жұмсақ қарым-қатынасыңыз — оған ережелер аясында еркін болуды үйрететін ең жақсы сабақ.') WHERE id = '699f4641-31b9-4174-a887-f0cb838a43e4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '23-айдың соңғы онкүндігіне аяқ бастық! Бала енді «Мен» есімдігінің мағынасын толық түсініп, қолдана бастайды. «Мен келдім», «Мен тамақ жедім» деген сөйлемдер оның өзін айналасындағы адамдардан бөлек жеке тұлға ретінде қабылдайтынын көрсетеді. Оның дербес сөйлеуге деген талпынысын қолдап, диалогті кеңейтіңіз: «Иә, сен дәмді тамағыңды жедің, жарайсың!».') WHERE id = '7aacd700-e4fe-464f-89ef-4b8e3945aa5a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Жүгіріп келе жатып бағыт өзгерту». Бала енді жылдам жүгіріп келе жатып, бағытын кенет өзгерте немесе кедергілерді айналып өте алады. Бұл бұлшықет күшінің де, жылдам шешім қабылдау қабілетінің де көрсеткіші. Саябақта онымен «мені ұстап ал» ойынын ойнап, ептілігін арттырыңыз.') WHERE id = 'a492f1d5-4125-4356-ab32-a3a06c3ae006';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Көптік ұғымы». Бала енді «бір» мен «көптің» айырмашылығын түсіне бастайды. Оған ойыншықтарын көрсетіп, «Мұнда көп мәшине бар» деп, санау дағдысының алғашқы негізін қалаңыз. Әзірге сандарды ретімен айта алмаса да, заттар санының айырмашылығын көзбен байқауы — оның математикалық ойлауының бастауы.') WHERE id = '6541c63d-d78c-444c-93ac-32836d55b462';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Өнер туындылары». Бала енді қарындашты дәлірек ұстап, «тұйық сызықтар» (шеңберге ұқсас пішіндер) салуға тырысады. Оған түрлі түсті қарындаштар беріп, салған әр пішінін бір затқа ұқсатып, ынталандырыңыз: «Қарашы, мынау допқа ұқсайды!».') WHERE id = 'de8e6a20-ca58-4eb3-bdc2-7db3ed5bcda2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім көмектесемін». Бала Сізге үй шаруасында көмектескенді қатты ұнатады. Оған «Киімдерді себетке салуға көмектесші» деген сияқты нақты тапсырмалар беріңіз. Бұл оның қимыл-қозғалыс дағдыларын да, отбасындағы жауапкершілік сезімін де дамытады. Көмектескеннен кейін оған: «Сен менің ең үлкен көмекшімсің», — деп айтыңыз.') WHERE id = 'f2819b1a-b1cb-4ed8-b546-aae23641438e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әдептілік ережелері». Бала енді «Рақмет» және «Өтінемін» сөздерін орынды қолдана бастауы мүмкін. Әрине, бұл Сіздің қандай үлгі көрсететініңізге байланысты. Оған бір нәрсе бергенде немесе одан бірдеңе алғанда, осы сөздерді өзіңіз қолданып, үлгі көрсетіңіз. Бұл — оның болашақ қарым-қатынас мәдениетінің ең берік негізі.') WHERE id = 'eb0307cc-cb5a-49a5-b989-e572cad76794';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Үш сөзден тұратын сөйлемдер». Бала енді «Анашым, су берші», «Әке, саябаққа барайық» сияқты күрделірек сөйлемдер құрайды. Ол өз қажеттіліктерін толық жеткізе алады. Сіз оның айтқанын растап, сөйлемін сәл кеңейтіңіз: «Иә, қазір кел, су ішейік, содан кейін саябаққа барамыз». Бұл оның грамматиканы түсіну қабілетін жетілдіреді.') WHERE id = '8ba75ebe-7968-4c36-9120-369b2e5d0ec2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Пазл құрастыру шеберлігі» артады. Бала енді 6-8 бөліктен тұратын қарапайым пазлдарды өз бетінше құрастыра алады. Бұл көру арқылы талдауды да, саусақ қимылдарының дәлдігін де қажет етеді. Суретті әр аяқтаған сайын оның қуанышына ортақтасыңыз, сонда күрделі тапсырмаларға қызығушылығы артады.') WHERE id = '527f78da-7fbc-42ab-a36c-6bee3afe966e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім жинаймын». Ойыншықтарды орнына жинау енді ол үшін жай ғана тапсырма емес, жауапкершілікке айналады. Сіз «Кәне, мәшинелерді жататын орнына қояйық» дегенде ол көмектессе, бұл тәртіптіліктің негізі. Бұл дағды болашақта оның жинақылығы үшін өте маңызды.') WHERE id = '4cae5197-2921-4caa-b98c-16f64a7694c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісу және кезек күту». Бала енді «қазір сенің кезегің» дегенде біраз күту керектігін түсінеді. Сабыр сақтауды үйрену — бұл жас үшін үлкен жетістік. Кезекпен ойнайтын ойындарда (мысалы, допты бір-біріңізге беру) оған қолдау көрсетіңіз. Сіздің сабырлы қарым-қатынасыңыз оның ортаға бейімделуін жеңілдетеді.') WHERE id = 'e3e7be7f-e682-47f1-bdf9-05213d301d28';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Бірдей және әртүрлі». Бала енді бір санаттағы заттарды (мысалы, барлық жануарларды бір жерге, барлық мәшинелерді басқа жерге) топтастыра алады. Оған «Мұнда қай ойыншық өзгеше?» деген сияқты сұрақтар қойып, көріп талдау логикасын байқап көріңіз. Санаттар бойынша ойлау оның танымдық қабілетін жаңа деңгейге көтереді.') WHERE id = '9960803a-4e47-4edd-b50d-dc62d848c875';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарының үйлесімі: «Бір орында секіру және айналу». Бала енді жай ғана секірмей, секірген кезде денесін бұруға тырысады. Бұл — ірі моторикаға қатысатын бұлшықеттер қимылының жоғары деңгейде үйлесуі. Онымен бірге музыка әуенімен қимылдайтын көңілді «би» сағаттарын ұйымдастырыңыз. Бұл әрі қызықты, әрі дене икемділігіне арналған тамаша жаттығу.') WHERE id = 'b8a638df-098e-4767-9ebb-0f4df5304a5e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім киінемін» кезеңі күрделене түседі. Бала енді сыдырманы ілгеннен кейін өзі тартуға немесе үлкен түймелерді ағытуға тырысады. Бұл үдерісте оған кедергі жасамаңыз және асықтырмаңыз. Бір нәрсені өз бетінше істей алатынын көру — оның өзіне деген сенімінің ең үлкен көзі. Кішкентай жетістіктері үшін оны міндетті түрде жігерлендіріңіз.') WHERE id = 'f6d69242-03a3-4cc8-a444-aac7bbd07185';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта «эмпатия» арта түседі. Бала Сіздің немесе басқа баланың көңілсіз екенін көргенде, жаныңызға келіп, ойыншығын ұсынуы немесе құшақтауы мүмкін. Бұл — оның эмоциялық интеллектісінің (EQ) жақсы дамып келе жатқанының белгісі. Оның осындай қамқорлығын «Маған қолдау көрсеткеніңе рақмет» деп бағалаңыз.') WHERE id = '98c8accf-ca7d-4901-b417-a3bce7f325f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Пішін және өлшем». Бала енді бір пішіннің (мысалы, шеңбердің) үлкен және кіші нұсқаларын ажырата алады. Оған өлшемдері әртүрлі ыдыстарды бірінің ішіне бірін салуды көрсетіңіз. Бұл оның болашақ математикалық ойлауының негізі саналатын «реттеу» дағдысын дамытады.') WHERE id = 'bfdb17de-cc0d-437c-870c-13801051e507';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты тебу және нысанаға бағыттау». Бала енді допты жай ғана теппей, оны белгілі бір бағытқа бағыттауға тырысады. Бұл — көру зейіні мен қимыл үйлесімділігінің бірлесуі. Үйде немесе саябақта онымен бірге «шағын қақпа» жасап, допты соған тебу ойынын ойнаңыз. Бұл оның аяқ бұлшықеттерін нығайтып, дәлдігін арттырады.') WHERE id = 'a17dc9b7-c84f-4802-8431-7aad7b966067';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме айтуға талпыныс». Бала күн ішінде көрген қызықты нәрсесін (мысалы, «Үлкен ит көрдім») Сізге айтып беруге асығады. Оның әңгімесін соңына дейін тыңдап, сұрақтар арқылы толықтырыңыз: «Иттің түсі қандай болды?». Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да нығайтады.') WHERE id = 'daff24e3-d7cd-46e0-9c7d-75e6a3417d53';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: бала енді «Мен қаламаймын» деп, өз қалауын батыл білдіруі мүмкін. Мұндай сәттерде қасарысудың орнына, оған таңдау мүмкіндігін беріп, назарын басқаға аударыңыз. Сіздің сабырлылығыңыз бен тұрақты ережелеріңіз баланың бойында қауіпсіздік сезімін қалыптастырады. 2 жасқа небәрі 40 күн қалды — Сіз керемет еңбек етіп жүрсіз!') WHERE id = '30c55932-1036-4bc0-a31f-1b927f46a841';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есте сақтау және оқиғалар». Бөпе күні бойы болған қарапайым бір оқиғаны (мысалы, «Саябақта ит көрдім») есіне түсіріп, Сізге айтып бере алады. Оның әңгімелерін мұқият тыңдап, «Содан кейін не болды?» деп, оқиғаларды ретімен баяндауына көмектесіңіз. Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да дамытады.') WHERE id = '9fdcc45e-2b1e-4d3c-95a7-d7f5adca9ccb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дайындық: 2 жасқа толуына небәрі 50 күн қалды! Бөпе енді өз сезімдерін тереңірек білдіреді. Ол Сізге деген сүйіспеншілігін кенеттен құшақтап немесе сүйіп көрсетуі мүмкін. Сіз де оған дәл сондай мейіріммен жауап беріңіз. Мұндай эмоциялық байланыс оның өзін қауіпсіз сезінуіне және ең бастысы, «сүйікті жан» екенін түсінуіне көмектеседі.') WHERE id = '78317024-ad5b-4a00-86b5-ab43a417337b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпе енді түстерді ажыратып қана қоймай, олардың көбінің атауын дұрыс айтады. «Көк машинаны әкел» дегенде қателеспесе, бұл оның көру және сөздік жадының үйлесімді жұмыс істейтінін көрсетеді. Күнделікті серуен кезінде «Жасыл жапырақ», «Сары күн» сияқты сипаттамаларды қолданып, оның әлемін бояулармен байыта беріңіз.') WHERE id = '85496aa4-c911-4bb2-8f2e-3e5a32779858';